INSERT INTO public.chapters VALUES ('8ad12a2c-96d6-4c4c-a3c6-4eaf2086d296', '8f6bd2fb-dfb8-4769-9b3e-189aba58931a', 'البداية', '', '', 1, '2026-07-15 15:07:23.254', '2026-07-15 15:07:23.254');
INSERT INTO public.chapters VALUES ('bf9417d3-af0c-49ae-8bb7-e48d2b85ebe0', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 1: بذرة الحرب في أقاصي الشمال', '— --------------------------------------- تصاعد صليل السيوف في الساحة المفتوحة، صوت معدن يرتطم بمعدن، رتيب وموحش. ثورفين، الطفل ذو السنوات الست، كان يتنقل بين أقدام المحاربين كقطة ضالة، عيناه تلاحقان والده ثورس. ثورس لم يكن يقاتل كبقية رجال القرية؛ لم تكن حركاته صاخبة أو مبهرجة، بل كان يتفادى الضربات بخطوات محسوبة، وكأنه يقرأ نوايا الخصم قبل أن تتبلور في عضلاته. سقط الخصم أرضاً، لاهثاً، بينما وقف ثورس ساكناً كالجبل، يمسح العرق عن جبينه. اقترب ثورفين من والده، ممسكاً بطرف قميصه الخشن: «أريد سيفاً، أريد أن أقتل الغرباء الذين يداهمون السواحل». نظر إليه ثورس، لم يبتسم، بل وضع يده الثقيلة على كتف الصغير، وقال بصوت منخفض خلت منه نبرة التهديد: «اسمعني جيداً يا بني، ليس لأي إنسان أعداء. لا يوجد أحد في هذا العالم يستحق أن تقتله». سحب ثورفين كتفه بعيداً، تعبير وجهه تحول إلى قناع من التمرد الصامت. في تلك اللحظة، رسا زورق غريب على الشاطئ الصخري، وخرج منه رجل غريب الملامح، يرتدي دروعاً مهترئة تفوح منها رائحة الملح والدم القديم. كان ذلك الرجل هو أسكلاد، الذي لم يأتِ لزيارة ودية، بل لجلب رسالة مغلفة بالوعيد. دخل أسكلاد القرية بخطوات واثقة، تتخللها سخرية مبطنة في نظراته الملتوية. توجه مباشرة نحو ثورس، وقال بصوت أجش يحمل نبرة تهكمية: «تارل القائد يرسل تحياته، يا بطل يومسفيكنغ الهارب. لقد انتهت سنوات عزلتك بين هؤلاء المزارعين. الحرب تطلب سيفك مجدداً، أو ستحرق هذه القرية حتى لا يتبقى فيها حجر على حجر». اشتد الصمت في المكان، وتحجرت ملامح ثورس، بينما كان ثورفين يراقب الحوار من خلف كومة من الخشب، أصابعه تغرس في التراب، وقلبه يخفق بعنف، لا خوفاً، بل برغبة ملحة في الانقضاض على ذلك الغريب الذي أفسد سلام منزله. كان الهواء يتلبد بتوتر لم يعهده أهل القرية من قبل، وتلاشت خيالات السلام التي كان ثورس يحاول زرعها في عقل ابنه، ليحل محلها نذير صراع لا مفر منه.', '', 1, '2026-07-15 15:17:34.067', '2026-07-15 15:17:34.067');
INSERT INTO public.chapters VALUES ('8974a954-8e80-4de0-a194-c51eae20863e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 2: خلف أسوار الملح والذكريات', '— --------------------------------------- توقف ثورفين عن مطاردة الفراشات في الحقول المجاورة لمنزلهم، والتفت بحدة حين سمع صوت ارتطام المعدن بالخشب القادم من جهة الباب الخارجي. لم يكن والده، ثورس، من النوع الذي يغلق الأبواب بقوة. اقترب الصبي بخطوات هادئة، يراقب والده وهو يتفحص درعاً قديماً تراكم عليه الصدأ في زاوية الغرفة. كانت ملامح ثورس جامدة، لكن انقباضة خفيفة في عضلات فكه كانت كافية لتشي بما يخفيه عن عائلته. سأل ثورفين بصوت متهدج: «هل ستعود للحرب؟». لم يلتفت ثورس، بل استمر في مسح الغبار عن نصل سيفه، ثم أجاب بصوت رخيم وثابت: «هناك نداء لا يمكن تجاهله يا بني، حتى وإن كان في أعماق البحار». كانت الأم، هيلغا، تقف عند عتبة المطبخ، ممسكة بقطعة قماش بكلتا يديها، تضغط عليها حتى ابيضت مفاصل أصابعها. لم تكن بحاجة لسؤال، فالتاريخ الذي هرب منه زوجها لم يكن ليتركه وشأنه أبداً. في تلك الليلة، لم ينم ثورفين؛ كان يسترق السمع إلى حوارات مشحونة بين ثورس ورجال القرية الذين توافدوا في الظلام. كان أحد الرجال يصرخ بحماس محموماً عن المجد والغنائم، بينما كان ثورس ينظر إليه بهدوء، ثم قال بكلمات ثقيلة: «المجد ليس في الدماء التي تسفكها، بل في الحياة التي تحميها. اخرجوا من منزلي، فلا حاجة لي بسيوفكم هنا». تراجع الرجال، مذهولين من حدة نبرته التي لم تكن تحمل غضباً، بل صرامة جبلية لا تزحزح. نهض ثورفين من فراشه، متسللاً نحو مخزن الأسلحة في القبو، حيث كان والده قد خبأ سيفه منذ سنوات. دفع الغطاء الخشبي الثقيل، وانسل إلى الداخل، حيث كان بريق النصل يلمع تحت ضوء القمر الخافت المتسرب من شقوق السقف. لمس ثورفين مقبض السيف الخشن، وشعر ببرودة المعدن تسري في جسده. حين فتح الباب، وجد والده يقف أمامه، ساكناً كالتمثال. لم يوبخه ثورس، بل وضع يده الكبيرة على كتف الصبي وقال بنبرة خالية من الزيف: «أردت لك حياة أبعد من ساحات القتال، لكن يبدو أن الأقدار لا تستشيرنا في خياراتنا». غادر ثورس البيت في الفجر التالي، تاركاً خلفه ابناً يغلي في صدره خليط من الغضب والولاء، وعائلة تعلم أن العودة من هذه الرحلة ليست وعداً، بل أمنية بعيدة المنال.', '', 2, '2026-07-15 15:17:34.289', '2026-07-15 15:17:34.289');
INSERT INTO public.chapters VALUES ('6ca0cd67-00bb-4daa-a3dc-3dbf75921055', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 3: خلف أسوار الجليد: مواجهة لا مفر منها', '— --------------------------------------- انزلق النصل الفولاذي ليقطع الهواء بصرير مكتوم، بينما توقف ثورس وسط الساحة، نظراته لا تبرح وجوه الرجال الذين أحاطوا بمنزله. لم تكن في عينيه دهشة، بل هدوء مريب جعل القائد يتردد للحظة قبل أن يرفع سيفه. ثورفين، الطفل الذي لم يتجاوز العاشرة، كان يقف خلف والده، قبضتاه الصغيرتان ترتجفان من ضغط الغضب، وعيناه تلاحقان تحركات المهاجمين بتركيز وحشي. التفت ثورس إلى ابنه، ملقياً بنظرة واحدة كانت كافية لترويع أي طفل، لكنها هنا كانت أمراً صامتاً بالتراجع. لم يتكلم ثورس، بل اتخذ وضعية دفاعية صلبة، باسطاً قدميه على الأرض المغطاة بالصقيع. اندفع أحد المرتزقة نحو ثورس، صائحاً بكلمات بذيئة، لكن ثورس لم يتحرك إلا في اللحظة الحاسمة؛ حركة جانبية خاطفة جعلت المهاجم يتخبط في فراغ الساحة، قبل أن يتلقى ضربة بظهر يد ثورس القوية على عنقه، أفقدته وعيه في الحال. ساد صمت مطبق. نظر أسكلاد، الذي كان يراقب من بعيد، بابتسامة باهتة التوت على شفتيه، ممسكاً بمقبض سيفه ببرود. اقترب أسكلاد خطوة، صوته كان هادئاً وخالياً من الانفعال وهو يخاطب ثورس: أنت لا تزال تحتفظ بمهارة الرجل الذي نسيته ساحات المعارك، لكنك تدافع عن شيء انتهى زمنه. لم يلتفت ثورس لأسكلاد، بل كانت عيناه معلقتين بطفله الذي بدأ يخرج خنجراً من خلف ظهره، محاولاً الانضمام للمواجهة. تنهد ثورس، ونبرته حين تحدث كانت جافة وحازمة: يا ثورفين، القوة لا تقاس بما تزهق من أرواح، بل بما تحمي. تراجع الصبي، لكن عينيه ظلتا مشتعلتين برغبة عارمة في القتال. حين اندفع المرتزقة في آن واحد، لم يعد ثورس ذلك الرجل السلمي؛ لقد تحركت عضلاته كزنبرك مشدود، متفادياً نصلين كانا كفيلين بإنهاء حياته، وموجهاً ضربات دقيقة، مدروسة، وغير قاتلة، وكأنه يتلاعب بخصومه كدمى خشبية. كان الغبار يرتفع تحت أقدامهم، وصرخات المرتزقة تزداد حدة مع توالي سقوطهم الواحد تلو الآخر. أسكلاد، الذي لاحظ مهارة ثورس الاستثنائية، أدرك أن الأمر لن ينتهي بمجرد محاصرة، فبدأ يخطط لخطوته التالية، عينان تراقب، وعقل يزن الفرص. لم يكن ثورس يقاتل ليربح، كان يقاتل لينهي العبث، وفي أعماقه، كان يدرك أن قدره بدأ ينسج خيوطه حوله، وأن هدوء حياته قد ولى للأبد.', '', 3, '2026-07-15 15:17:34.464', '2026-07-15 15:17:34.464');
INSERT INTO public.chapters VALUES ('06846a28-f203-4082-9802-1eddd373ef47', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 4: نصل الخديعة', '— --------------------------------------- ارتطم نصل السيف بمعدن الترس محدثاً رنيناً معدنياً حاداً اخترق صمت المعسكر. وقف أسكلاد وسط رجاله، عيناه الزرقاوان تلمعان ببريق مريب وهو يحدق في ثورس الذي لم يبرح مكانه، جسده ثابت كصخرة وسط تيار جارف. بصق أسكلاد جانباً، ثم أشار بيده لرجاله ببطء، قائلاً بنبرة ساخرة تقطر مكرًا: يا له من مشهد رائع، بطل آيسلندا يقف أمامنا وكأنه في عرض عسكري. ألقِ سيفك يا ثورس، فدماء رجالك ستراق قبل أن تلمس قدماك الأرض. لم يجب ثورس، بل ضيق عينيه، وتصلبت عضلات فكيه. كان ثورفين يراقب من خلف والده، يده تقبض على مقبض خنجره حتى ابيضت مفاصل أصابعه، أنفاسه متسارعة تخرج من بين شفتيه كزفير حيوان حبيس. التفت ثورس إلى ابنه، لم تكن عيناه تعبران عن خوف أو تردد، بل عن هدوء مثقل بالمسؤولية. قال ثورس بصوت منخفض، خافت لكنه نافذ: عد إلى السفينة يا ثورفين، لا تلتفت خلفك مهما سمعت. صرخ ثورفين، وقد طفح به الكيل: لن أتركك تواجه هؤلاء الحثالة وحدك! سأقاتل بجانبك! لم يلتفت ثورس، بل رفع يده وأشار باتجاه البحر، موضحاً بلهجة لا تقبل الجدل: هذه ليست معركة شرف، إنها مذبحة. اذهب. انطلق أسكلاد في ضحكة مكتومة، متهكماً وهو يخطو خطوة نحو ثورس: انظروا إلى الأب يلقن ابنه دروس البطولة قبل الوداع. أسكلاد أومأ برأسه لرجاله، فتقدم رامي سهام من الخلف، انشد الوتر حتى أوشك على التمزق. استدار ثورس بجسده استدارة كاملة، وفي حركة خاطفة كسرق البرق، اندفع نحو المهاجمين. لم يكن يقاتل لقتلهم، بل كان يزيحهم كالأغصان الجافة في طريقه، حركاته اقتصادية، دقيقة، وقاتلة في آن. صمتت ضحكات أسكلاد، واستقرت ملامح وجهه على الجدية المطلقة. كان يعلم الآن أن الرجل الذي أمامه لا يجاريه أحد في المهارة. وبينما كان ثورس يطيح بالرجال يميناً ويساراً، ارتجفت يد رامي السهام، فطلقت السهم ليس نحو ثورس، بل نحو صدره العاري. توقف ثورس للحظة، اخترق السهم كتفه، تبعه سهم آخر في فخذه. سقط ثورس على ركبتيه، لم يصرخ، ولم يئن، بل رفع رأسه إلى السماء، نظراته تتجاوز أسكلاد ورجاله إلى أفق بعيد لا يراه غيره. ساد سكون ثقيل، وتوقفت المعركة وكأن الزمان قد تجمد. اقترب أسكلاد، سيفه يستند إلى كتفه، ونظر إلى ثورس من علٍ قائلاً: انتهى عرضك يا بطل. في تلك اللحظة، لم يعد هناك قتال، بل كانت نهاية فصل وبداية جرح لن يندمل في روح الصبي الذي يراقب من بعيد، عاجزاً عن الحراك، غارقاً في صمته المطبق.', '', 4, '2026-07-15 15:17:34.653', '2026-07-15 15:17:34.653');
INSERT INTO public.chapters VALUES ('b2c07722-5500-45aa-81fe-28b2ef0148ef', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 5: نذير الخيانة في عرض المحيط', '— --------------------------------------- ارتطم جسد ثورفين بخشبات سطح السفينة الصلبة، زفراته المكتومة تمتزج بصوت تلاطم الأمواج ضد الجوانب الخشبية. لم يكن هناك وقت للراحة؛ فقد كان والده ثورس يقف عند الدفة، جسده الضخم يمتص اهتزازات السفينة بثبات صخري. على بعد أمتار قليلة، جلس أسكلاد، يراقب ثورس بنظرات لا تهدأ، وكأنما يحاول فك شفرة رجل لم يعتد على الخضوع. اندلع صوت أسكلاد ساخراً ومخترقاً ضجيج الرياح: أهذا هو ثورس العظيم؟ بطل يوتلاند الذي هجر ميادين الدماء ليمارس دور الملاح؟ رد ثورس دون أن يلتفت، كانت نبرته كصوت الحديد حين يصطدم بالحديد: لست بطلاً يا أسكلاد، أنا رجل يبحث عن وجهته، ولست مهتماً بمعارك الصغار. تحرك ثورفين، قبضت يداه على حافة السفينة حتى ابيضت مفاصله، كان يراقب أسكلاد بحقد صافٍ، عيناه تلمعان كخنجر غير مصقول. اقترب أسكلاد ببطء، يخطو بخفة قط مفترس، وتحدث بصوت منخفض ومتهكم: المجد لا يترك أصحابه يا ثورس، حتى وإن حاولوا هم هجره. ثورس التفت ببطء، لم تكن في عينيه ذرة خوف أو توتر، بل هدوء قاتل جعل جنود أسكلاد يتراجعون خطوة للوراء غريزياً. قال ثورس: المجد وهم يغذيه نهم الرجال، وأنا تجاوزت هذا النهم. ساد صمت مطبق، لم يقطعه سوى صرير الأخشاب المجهدة. كان أسكلاد يبتسم، لكن عينيه كانتا تقيسان المسافة والضعف، يبحث عن شرخ في درع ثورس النفسي. التفت أسكلاد نحو ثورفين، ورمقه بنظرة ازدراء باردة: وأنت يا صغير، هل ستظل تتبع هذا الأب التائب حتى تصل إلى حتفك؟ زمجر ثورفين، تشنجت عضلات رقبته، واندفع بكلماته حادة كالسياط: والدي ليس تائباً، هو أشرف منك ومن كل قطاع الطرق الذين تقتاتون على دماء الأبرياء. ضحك أسكلاد، ضحكة خالية من المرح، وركل حجراً صغيراً على السطح بعيداً: الشرف عملة لا قيمة لها في عرض البحر يا صغير، حين يداهمكم الموت، لن يسألكم عن شرفكم. وفي تلك اللحظة، اتسعت حدقتا ثورس، ليس خوفاً، بل إدراكاً حاداً لتغير في إيقاع الأمواج ومسار السفينة القادم. استدار ثورس نحو الأفق، وضع يده على مقبض سيفه، وقال بصوت منخفض، ليس موجهاً لأحد: القادم ليس شرفاً، إنه واقع لا مفر منه. لم تكن هناك حاجة للمزيد من الكلمات، فالتوتر الذي تصاعد في الهواء كان أبلغ من أي حوار. عاد الصمت ليغلف السفينة، لكنه لم يعد صمت سلام، بل كان صمت ما قبل العاصفة، حيث تتربص الأقدار بالرجال الذين يعتقدون أنهم اختاروا طريقهم.', '', 5, '2026-07-15 15:17:34.869', '2026-07-15 15:17:34.869');
INSERT INTO public.chapters VALUES ('51deed92-10c5-406f-9f07-47314f51f4a9', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 6: رصانة المحارب في وجه العاصفة', '— --------------------------------------- تصاعدت وتيرة حركة الأشرعة الجلدية وهي تصطدم بحدة مع الصواري الخشبية تحت وطأة الريح الهائجة. في قلب السفينة، وقف ثورس ممسكاً بدفة القيادة، ملامحه لم تتحرك قيد أنملة، عيناه كانتا ترصدان الأفق الملبد بضباب رمادي كثيف، بينما كان ثورفين الصغير يقبع في زاوية ضيقة، أصابعه تشد بقوة على حافة خشبية حتى ابيضت مفاصلها. لم يتفوه ثورفين بكلمة، لكن أنفاسه المتقطعة كانت تخون توتره. التفت ثورس نحوه ببطء، صوته اخترق صخب الأمواج بنبرة هادئة وثقيلة: لا تبتعد عن ناظري، ثورفين. البقاء بجانبي هو أمانك الوحيد الآن. سحب ثورفين خنجره الصغير، وبريق معدنه يلمع في إضاءة السفينة الخافتة، محدقاً في والده بتحدٍ صامت، قبل أن يهز رأسه إيجاباً. كان الوضع في البحر يزداد حرجاً، إذ ظهرت من خلف ستار الضباب سفن القراصنة، سوداء كأنها نذر شؤم تقتحم الهدوء المريب. أسكلاد، الذي كان يقف على متن سفينته الأم، مسح على ذقنه ببرود، وعيناه تلاحقان سفينة ثورس بدقة المفترس الذي لا يستعجل فريسته. قال أسكلاد بصوت منخفض لمساعده: إنه هو، الترويض لن يكون سهلاً، لكن الدم الذي يسيل هنا سيكون ثمناً بخساً للمجد الذي سأجنيه. على سفينة ثورس، اشتدت القبضة على الدفة، انحنى ثورس بجسده الضخم مع حركة السفينة العنيفة، مستعداً للمواجهة القادمة. لم يكن ثورس ينظر إلى القراصنة كأعداء يستحقون الكراهية، بل كقدرٍ وجب التعامل معه بمهارة المحارب القديم. صاح ثورس برجاله، صوته كان قوياً كدوي الرعد: احموا ظهوركم، ولا تندفعوا للقتل. ابقوا على متن السفينة، ولا تسمحوا لهم بالاقتراب أكثر مما ينبغي. كانت الأوامر واضحة، حازمة، وخالية من أي ذعر. التفت ثورفين نحو القراصنة، كانت عيناه تشتعلان بغضب طفولي لا يعرف التهدئة، صرخ ثورفين بصوت مخنوق بالاندفاع: سأقتلهم! سأقطع رؤوسهم جميعاً! نظر إليه ثورس للحظة، لم تكن نظرة توبيخ، بل نظرة إدراك عميق لمصير ابنه، وضع يده القوية على كتف ثورفين، وضغط عليها بقوة كأنه يثبت كيانه في عالم يتأرجح. لا حاجة للقتل يا بني، القوة ليست في سلب الحياة، بل في الحفاظ عليها حين يحيط بك الموت من كل جانب. سكت ثورفين، لكن قبضته على الخنجر لم ترتخِ، بينما كانت سفن القراصنة تقترب، وصوت ارتطام أجسادهم الخشبية بسفينة ثورس يعلن بداية الصدام الموعود.', '', 6, '2026-07-15 15:17:35.051', '2026-07-15 15:17:35.051');
INSERT INTO public.chapters VALUES ('4ad42cb3-6117-464d-a3d7-ebace4505f18', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 7: خديجة الفولاذ والدم', '— --------------------------------------- التفت أسكلاد نحو ثورفين، ملامحه هادئة ببرود يثير الريبة. قال بصوت منخفض، خلت نبرته من أي تعاطف: «تظن أنك مقاتل يا صغير؟ الشجاعة وحدها لا تملأ جوفاً، ولا تبني مجداً إذا كانت تفتقر إلى البصيرة. أنت لست سوى مخلبٍ صدئ في يد رجل يتقن تحريك الدمى». استشاط ثورفين، قبضت يداه على مقبض خنجره حتى ابيضت مفاصل أصابعه، واندفع نحو أسكلاد بصرخة مكتومة. لم يتحرك أسكلاد، بل اكتفى بميل رأسه يسيراً، لتمر طعنة ثورفين في الهواء، ثم دفع كتفه بحدة ليفقد الصبي توازنه. سقط ثورفين على الأرض الموحلة، لكنه نهض في أجزاء من الثانية، أنفاسه متلاحقة، وعيناه تقدحان شرراً. صاح ثورفين: «سأقتلك! سأنتزع رأسك بنفسي!» ضحك أسكلاد، ضحكة جافة لا تصل إلى عينيه الماكرتين. قال وهو يمسح غباراً خيالياً عن كتفه: «الكل يكرر هذه الجملة، وفي النهاية، لا يتركون خلفهم سوى أجساد باردة. فكر جيداً يا ثورفين، هل تريد أن تكون بطلاً في أساطير الفاشلين، أم تريد أن تعيش لترى نهاية من دمر حياتك؟». توقف ثورفين عن الحركة، ارتجفت عضلات فكيه، واتسعت عيناه بتوتر. كان أسكلاد يقرأ في ملامحه، يعرف نقطة ضعفه، يعرف أن رغبة الصبي في الانتقام هي قيده الوحيد. اقترب أسكلاد منه، همس في أذنه بلهجة ساخرة: «أنت غاضب لأنك تعلم أنني محق. عد إلى مكانك، واشحذ سكينك، فربما يأتي اليوم الذي أسمح فيه ليدك بالوصول إلى عنقي. أما الآن، فالساحة تطلب دماءً لا تهمها كرامتك». انصرف أسكلاد بخطوات واثقة، مخلفاً وراءه ثورفين الذي تجمد في مكانه، صمته يطبق على أنفاسه، بينما كانت أصوات رجال العصابة في الخلفية تتعالى بالضحك الفظ والحديث عن الغنائم. لم يلتفت ثورفين، لم ينطق بكلمة، كان فقط يحدق في بقعة من الطين، وكأنها مرآة تعكس انكساره وتصميمه المظلم الذي لا يزال يشق طريقه ببطء في صدره الغض.', '', 7, '2026-07-15 15:17:35.232', '2026-07-15 15:17:35.232');
INSERT INTO public.chapters VALUES ('e0798ccf-8138-4205-b173-7437d02e7450', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 8: خديعة النيران ومواجهة الذئب', '— --------------------------------------- انتصبت خيالة أسكلاد فوق التلة، محاطة بضباب الصباح الذي بدأ يتبدد تحت وطأة شمس شاحبة. لم تكن ثمة نداءات للحرب، بل صمت ثقيل تقطعه حركة الخيول المضطربة. نظر أسكلاد نحو ثورس، كان وجهه بلا تعابير، لكن عينيه تتحركان كصقر يرصد فريسة. سأل أسكلاد بصوت متهكم خالٍ من أي عاطفة: هل قررت يا بطل الفايكنج؟ هل ستموت هنا لأجل حفنة من الفلاحين، أم ستختار النجاة؟ لم يرد ثورس، بل ثبت نظره على ثورفين الذي كان يتنفس بسرعة، يداه تقبضان على مقبض خنجره حتى ابيضت مفاصل أصابعه. ألقى ثورس درعه جانباً، لم تكن حركة استسلام، بل حركة توطئة لما سيأتي. ساد هرج بين جنود أسكلاد، تعالت أصواتهم المتوعدة، لكن أسكلاد رفع يده بإشارة واحدة، فخمد الضجيج. أخرج ثورس سيفه، لم يرفعه مهدداً، بل ألقاه في الوحل، ثم اتخذ وضعية القتال بيدين عاريتين. صرخ أحد المرتزقة متهكماً: هل فقدت عقلك؟ أنت تواجه مائة رجل بيدين عاريتين! تقدم أسكلاد خطوة، وقال بنبرة باردة كالفولاذ: اقتلوه، لكن لا تلمسوا الصبي. اندفع المرتزقة كالسيل الجارف، صرخاتهم تمزق سكون المكان. استقبلهم ثورس بحركة خاطفة؛ قبضة دقيقة أطاحت بأول المهاجمين، بينما كانت حركته تلتف كالإعصار. لم يكن يقاتل كمن يريد القتل، بل كمن يصد قدراً. ضربة في العنق، ركلة في الصدر، كان ثورس يتحرك بين الجنود وكأنه في رقصة موزونة وسط الفوضى. توقف المرتزقة للحظة، مذهولين من قوة هذا الرجل. تنفس ثورس بعمق، ونظر مباشرة إلى أسكلاد. قال أسكلاد بابتسامة صفراء: أنت مثير للإعجاب يا ثورس، لكنك تفتقر للذكاء. أشار أسكلاد بيده نحو الغابة خلف التلة، حيث ظهر رماة السهام، ووتر أقواسهم مشدود نحو الصدر العاري لثورس. تجمد ثورفين في مكانه، اتسعت حدقتا عينيه، وتراجع بضع خطوات للوراء بينما ارتجفت شفتاه دون أن ينطق بكلمة. أدرك الجميع في تلك اللحظة أن القوة البدنية مهما بلغت، لا تقف في وجه الغدر المحكم. نظر ثورس إلى رماة السهام، ثم التفت إلى ابنه، ملامحه لم تهتز، بل انحنى قليلاً كأنه يودع المكان الذي يقف عليه. صاح أسكلاد: ألقِ سلاحك أو سيصبح الصبي نخالة في هذه الأرض. توقف ثورس عن القتال تماماً، أنزل يديه، وتلاقت عيناه بعيني ابنه في صمت لم يكسره سوى طنين الريح الباردة التي عصفت فجأة بالمكان.', '', 8, '2026-07-15 15:17:35.405', '2026-07-15 15:17:35.405');
INSERT INTO public.chapters VALUES ('1daeea41-1d26-4722-92cf-209145b407de', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 9: خديعة المحارب في جحيم الجليد', '— --------------------------------------- انتصبت خيالات السفن كأنها شواهد قبور وسط ضباب الدنمارك الكثيف. توقف ثورفين عن حك نصل خنجره الصدئ حين سمع وقع أقدام مألوفة، صوت لا يشبه وقع أقدام المرتزقة الأجلاف. كان أسكلاد يتقدم بخطوات واثقة، يبتسم ابتسامة باهتة لا تصل إلى عينيه الماكرتين. نظر أسكلاد إلى الفتى الذي يرتجف غيظاً، وقال بنبرة متهكمة: لا تزال تشحذ خنجرك وكأنك تستعد لقص أظافر والدك، ثورفين. الصبر حرفة لا يتقنها الصغار. رمقه ثورفين بنظرة حادة، انقبضت كفه حول مقبض الخنجر حتى ابيضت مفاصله، وأجاب بصوت مبحوح: سأقتلك، حتى لو استغرق الأمر عمراً كاملاً. ضحك أسكلاد ضحكة قصيرة مقتضبة، ثم أشار بيده نحو الأفق حيث تلوح قوارب الأعداء: وفر حقدك لما هو قادم، فالرجال الذين يصرخون كثيراً هم أول من يبتلعهم بحر الشمال. في تلك اللحظة، كان ثورس يراقب الوضع من بعيد، ملامحه كأنها منحوتة من صخر لا تلين. تقدم نحوه أحد رجاله، وجهه شاحب والتعرق يغطي جبينه رغم البرد، هامساً: إنهم يطوقوننا، ثورس. لم يلتفت ثورس، بل ضيق عينيه وهو يمسح بنظره خطوط انتشار العدو. قال بصوت منخفض، هادئ كوقع المطر: القتال ليس مجرد اندفاع بالسيوف، إنه اتخاذ قرار عندما لا يتبقى خيار آخر. لم يضف كلمة أخرى، بل وضع يده على مقبض سيفه، حركة بسيطة لكنها جعلت المحيطين به يتراجعون خطوة للوراء تلقائياً. اندلعت الفوضى حين بدأت السهام تمزق سكون الضباب. سقط أحد المرتزقة بصرخة مكتومة، بينما اندفع ثورفين نحو ساحة المعركة، متجاهلاً نداءات أسكلاد الذي ظل يراقب المشهد من موقعه المرتفع، عيناه تحللان كل حركة، كل ثغرة، منتظراً اللحظة التي تنقلب فيها الموازين. كانت صرخات المحاربين تتردد في الخلاء، مختلطة بصليل المعدن الذي يرتطم بالدروع، بينما وقف ثورس في المركز، جسده كالسد المنيع، ينتظر بوعي تام تلك اللحظة التي سيتعين عليه فيها الاختيار بين القتال للبقاء أو القتال لإنهاء كل شيء.', '', 9, '2026-07-15 15:17:35.593', '2026-07-15 15:17:35.593');
INSERT INTO public.chapters VALUES ('4d1f1daa-5f92-4bcf-8b3f-4f3559705adf', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 10: بقايا العهد', '— --------------------------------------- انتصبت خيمة أسكلاد وسط أرض الميدان القاحلة، يمزق سكونها صوت تقليب الحطب الجاف. كان أسكلاد يحدق في النيران، بينما جلس ثورفين في زاوية مظلمة، يمسح نصل خنجره بقطعة قماش خشنة حتى كادت يده تدمى. دخل بيورن، بضخامته المعتادة، راميًا سيفه الملطخ بالوحل على الأرض، وقال بصوت أجش: خسرنا ربع الرجال في المناوشة الأخيرة. لا طعام، ولا غنائم تذكر. أطلق أسكلاد ضحكة خافتة، متهكمة، وقال دون أن يلتفت: الحرب لا تطعم الجياع يا بيورن، الحرب تستهلكهم فقط. التفت ثورفين بسرعة، وبريق غضب غامض في عينيه، وقال مقتضبًا: لا أهتم بالرجال. متى ستواجهني؟ توقف أسكلاد عن العبث بالنار، رفع نظره ببطء، وتلاقت عيناهما. لم يكن في عين أسكلاد ذرة حقد، بل برود كأنه ينظر إلى حشرة عالقة في شبكته. قال بنبرة هادئة ومستفزة: النزال الذي تطلبه يحتاج إلى نضج، يا صغيري. أنت لا تزال مجرد طفل يظن أن الغضب يقطع الحديد. صك ثورفين على أسنانه، وتصلبت عضلات فكه حتى برزت عروق عنقه. لم يقل شيئاً، لكن يده انقبضت على مقبض خنجره لدرجة ابيضاض مفاصله. في الخارج، كانت الرياح تعوي بين الخيام، حاملة معها نذر شتاء قارس. وقف أسكلاد، نفض الغبار عن ردائه، وأضاف ببرود: غداً سنزحف نحو الساحل. إذا بقيت حياً، ربما أفكر في منحك فرصة لتضييع حياتك على يدي. غادر الخيمة بخطوات ثابتة، تاركاً ثورفين في صمت خانق. لم يكن الصمت هنا ضعفاً، بل كان وقوداً يتجمع في أعماق صدر الصبي، صمتاً يسبق عاصفة لا ترحم.', '', 10, '2026-07-15 15:17:35.788', '2026-07-15 15:17:35.788');
INSERT INTO public.chapters VALUES ('e072e9dc-9984-4a82-bb51-f6fcb4819f27', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 11: خديعة الغبار', '— --------------------------------------- انتصبت خيالة أسكلاد كالأشباح وسط الضباب الخفيف الذي يلف سهول الدنمارك. استل أسكلاد سيفه ببطء، ولم يكن رنين المعدن سوى إيذانٍ ببدء الفوضى. نظر ثورفين إلى الأفق، كانت عيناه تشتعلان برغبة محمومة في النزال، لكن جسده الصغير كان يرتجف من وطأة الترقب لا الخوف. سأله ثورفين بصوت متحشرج: هل نهاجم الآن؟ لم يلتفت أسكلاد نحوه، بل اكتفى بابتسامة باهتة رسمت خطوط المكر على وجهه المحروق بالشمس، وقال بصوت منخفض: الصبر يا صغيري، المحارب الحق لا يرمي سهمه إلا حين يرى بياض عين عدوه. في هذه الأثناء، كان ثورس يقف على الجانب الآخر، كتلة صلبة من العضلات والهدوء، يراقب تحركات المهاجمين. لم يبتلع ريقه، ولم يطرف له جفن؛ كان يقرأ تضاريس الأرض كخريطة مفتوحة. اقترب منه أحد رجاله مذعوراً، يده ترتجف فوق مقبض فأسِه، وهمس: سيدي، عددهم يفوقنا بثلاثة أضعاف، إنهم يطوقوننا من الشمال. التفت ثورس ببطء، وتلاقت عيناه بعيني الرجل، فاستقرت أنفاس الأخير فجأة. قال ثورس بنبرة هادئة خالية من أي توتر: القوة ليست في العدد، بل في المكان الذي تضع فيه قدمك. تحركت الخيالة فجأة، وانطلق صهيل الخيول يمزق صمت المكان. اندفع ثورفين كالسهم المنطلق من قوس، متجاوزاً خطوط الدفاع، لكنه توقف فجأة حين رأى والده يقف في طريقه، لا كخصم، بل كجبل لا يتزحزح. لم تكن هناك كلمات، فقط اصطدام الأجساد الذي تلاشت معه كل الأصوات الجانبية. حاول ثورفين توجيه طعنة غادرة، لكن يد ثورس الأبوية القوية قبضت على رسغه بقسوة، لا لتؤذيه، بل لتوقفه عند حده. زمجر ثورفين: اتركني! أنا لست طفلاً! أجابه ثورس بصوت عميق: أنت لا تقاتل يا ثورفين، أنت تتنفس غضباً، والغضب أعمى. في تلك اللحظة، استغل أسكلاد انشغال الجميع بالمناوشات، وأمر رجاله بإشعال النيران في الأعشاب الجافة المحيطة. تصاعد الدخان الأسود ليحجب الرؤية، وتحولت ساحة المعركة إلى جحيم من الغبار والرماد. تراجع ثورس خطوة إلى الخلف، ماسحاً وجهه من غبار المعركة، بينما كانت عينا أسكلاد تلمعان ببريق الانتصار الرخيص. كانت الخديعة قد بدأت، وبدأ معها فصل جديد من النزاع الذي لا يرحم.', '', 11, '2026-07-15 15:17:35.982', '2026-07-15 15:17:35.982');
INSERT INTO public.chapters VALUES ('30939abc-d09e-4dcc-af92-1058e4b8de2a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 12: خيوط المصيدة', '— --------------------------------------- انتصب أسكلاد واقفاً فوق صخور الساحل الوعرة، يراقب الأفق حيث تتراقص سفن الفايكنج كأنها بقع سوداء على صفحة الماء الفضي. خلفه، كان رجاله يتهامسون بحدة، أصواتهم مزيج من الترقب والرهبة. التفت نحوهم بابتسامة باردة لم تصل إلى عينيه الماكرتين. قال بصوت منخفض ومتهكم: لا تعجلوا بالموت، فالصيد الثمين يحتاج إلى صبر الصياد، وليس إلى حماقة الذئاب الجائعة. لم يتحرك ثورفين، كان مسماراً في الأرض، يحدق في اتجاه قدوم ثورس، أنفاسه متسارعة، يده اليمنى تقبض على مقبض خنجره حتى ابيضت مفاصل أصابعه. رأى ثورفين والده يترجل من سفينته بخطوات ثابتة، واثقة، وكأنه يمشي في مرجٍ آمن لا في ساحة حرب وشيكة. لم يكن ثورس يحمل درعاً، ولا حتى خوذة؛ كان يكتفي بحضوره الطاغي الذي جعل المحاربين المحيطين به يتراجعون خطوة للوراء، غريزياً، دون أن يدركوا السبب. نادى أسكلاد بصوت جهوري مشوب بالسخرية: يا بطل الفايكنج، ألم تخبرني يوماً أن المحارب الحقيقي لا يقتل بلا سبب؟ ماذا تسمي وجودك هنا إذن؟ توقف ثورس، التفت ببطء، وعيناه الزرقاوان الحادتان مسحتا المكان، محصيتين كل مكمن، وكل مقاتل، وكل فجوة في التشكيل الدفاعي الذي نصبه أسكلاد. قال ثورس بصوت عميق وهادئ، كقرع الطبول البعيدة: جئت لأعيد ابني، لا لأحصد الرؤوس. نظر ثورفين إلى والده، تجمعت في عينيه ذكريات البيت، والدفء، ورفض العنف، لكن واقعه الآن كان ملطخاً بالدم والوعد بالانتقام. صرخ ثورفين محاولاً استعادة توازنه النفسي: لا تلتفت إليه يا أبي! إنه كاذب، إنه يجرنا إلى الفخ! ضحك أسكلاد، ضحكة قصيرة خالية من المرح، ثم أشار لرجاله بيده. تحرك المحاربون، أطبقوا الحصار في حلقة ضيقة. لم يتغير تعبير وجه ثورس، بل زادت استقامته. وقف وحيداً في مواجهة عشرات السيوف المشرعة، لكن الهواء من حوله بدا وكأنه يتجمد. لم يكن ثورس يرى أعداءً، بل كان يرى رجالاً تائهين في دوامة المجد الزائف والذهب الملطخ بالدماء. انقبضت عضلات ساقي أسكلاد استعداداً للوثوب، وقال بنبرة خافتة تكاد لا تُسمع: لنرى الآن، يا صاحب السيرة العطرة، كيف ينجو الشرف من نصل الخيانة.', '', 12, '2026-07-15 15:17:36.18', '2026-07-15 15:17:36.18');
INSERT INTO public.chapters VALUES ('68e4d873-2654-4158-af44-6c18d9fe3db3', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 13: خديجة الفولاذ والدم', '— --------------------------------------- انتصبت خيمة أسكلاد وسط المعسكر كأنها ندبة في جسد الأرض. الداخل غارق في قتامة دخانية، بينما كان أسكلاد يحدق في خريطة مهترئة، أصابعه الطويلة تتلمس المسارات الملتوية لقرى الدنمارك. دخل ثورفين دون استئذان، خطواته ثقيلة، ونظراته الموجهة نحو قائد المرتزقة تحمل كل ضغينة سنواته العجاف. لم يلتفت أسكلاد، بل اكتفى بابتسامة خافتة ارتسمت على زوايا فمه. قال أسكلاد بصوت رخيم ومتهكم: هل أتيت لتطالب بمبارزة جديدة يا صبي؟ دماء والدك لا تزال تلطخ ذكرياتك، أليس كذلك؟ قبض ثورفين على مقبض خنجره، انقبضت مفاصل أصابعه حتى ابيضت، وزفر هواءً حاراً من منخريه. زمجر ثورفين: سأقتلك. لن يمنعني شيء هذه المرة، لا قواعدك ولا مراوغاتك. ضحك أسكلاد، ضحكة جافة خالية من أي دفيء، ثم استدار ببطء ليواجه الفتى، عيناه تلمعان ببريق ثعلبي. اقترب خطوة، مخترقاً مساحة ثورفين الشخصية، وقال بنبرة واثقة: الموت ليس في حد النصل، بل في كيفية استخدام عقلك لتصل إلى ذلك النصل. أنت تندفع كالثور الأعمى. في تلك اللحظة، اقتحم الخيمة أحد رجال أسكلاد، وجهه شاحب والاضطراب يرتسم في تفاصيل حركاته. ألقى نظرة سريعة على ثورفين قبل أن يهمس لزعيمه: لقد تحركت القوات، الخطة بدأت تأخذ مجراها. تبدلت ملامح أسكلاد في لحظة، تلاشت السخرية وحلت مكانها حدة استراتيجية باردة. نظر إلى ثورفين نظرة عابرة، كأنه ينظر إلى أداة لا تزال بحاجة إلى صقل، ثم أشار بيده نحو المخرج. صمت ثورفين، لكن عينيه ظلتا تلاحقان كل حركة لأسكلاد. كان يعلم أن الوقت لم يحن بعد، وأن غضبه، مهما اشتد، ليس سوى وقود لمخططات هذا الرجل الماكر. خرج ثورفين إلى ضجيج المعسكر، حيث كانت السيوف تُشحذ والرجال يتبادلون الشتائم. لم يكن يرى شيئاً سوى ظهر أسكلاد، ولم يكن يسمع شيئاً سوى دقات قلبه المتسارعة، التي كانت تدق إيقاعاً واحداً فقط: القصاص.', '', 13, '2026-07-15 15:17:36.365', '2026-07-15 15:17:36.365');
INSERT INTO public.chapters VALUES ('6116d1a7-4b22-4e4e-90cf-0a7017cbb030', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 14: خيوط المصير في مأدبة القراصنة', '— --------------------------------------- انزاح الستار عن خيمة أسكلاد المترعة برائحة اللحم المشوي والشراب الرخيص، حيث كان الضجيج يملأ المكان، وضحكات القراصنة السكارى تصطدم بجدران الجلود البالية. جلس أسكلاد في صدر المجلس، يراقب المشهد بعينين ثعلبيتين، بينما كان ثورفين يتربص في الزاوية، يحدق في وجهه بحدة، يداه تقبضان على مقابض خنجريه تحت ردائه حتى ابيضت مفاصله. لم يكن ثورفين ينتظر فرصة للحديث، بل كان ينتظر فرصة للقتل. لاحظ أسكلاد نظرة الصبي، فرفع كأسه بابتسامة صفراء لا تصل إلى عينيه. قال أسكلاد بصوت متهكم اخترق لغط الجنود: يا بني، الغضب لا يسمن ولا يغني من جوع، ألم تتعلم بعد أن السيف الذي يخرج من غمده دون تفكير هو أول ما ينكسر؟ ارتد ثورفين إلى الخلف خطوة، فكه مشدود وعضلات عنقه بارزة، وأجاب بصوت مقتضب وحاد: سأنتزع رأسك من فوق كتفيك، لا يهمني كيف. ضحك أسكلاد بصوت أجش، ثم استدار نحو رجاله الذين توقفوا عن الصخب بانتظار أمر جديد. كانت التوترات تتصاعد تحت السطح، حيث تعالت أصوات المرتزقة المطالبين بمهمة تلوح في الأفق، مهمة تضمن الغنائم والدم. في تلك اللحظة، دخلت شخصية عابرة لتشير إلى تحركات عسكرية في الأفق، مما دفع أسكلاد للنهوض ببطء، ماسحاً أثر الشراب عن ذقنه بظهر يده، وبدت نبرته أكثر جدية وصرامة: استعدوا، فالمناجل لن تنتظر الحصاد. خرج الجميع إلى الخارج حيث كانت الرياح تصفع وجوههم، لكن ثورفين بقي في مكانه للحظة، ينظر إلى ظهر أسكلاد، يغلي من الداخل ببركان من الكره المكتوم، قبل أن يلحق بهم بخطوات سريعة وصامتة. لم تكن الكلمات هي التي تحرك هذا العالم، بل التوقيت، والسكين المخبأة في الظلام، والوعود التي يقطعها الصبية للقتلى.', '', 14, '2026-07-15 15:17:36.56', '2026-07-15 15:17:36.56');
INSERT INTO public.chapters VALUES ('fa38a529-18b8-47a9-af1e-f35b35256559', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 15: خديعة في مضيق الضباب', '— --------------------------------------- انزلق خنجر ثورفين من بين أصابعه ليستقر في كفه، محدثاً رنيناً مكتوماً. كان أسكلاد يراقبه من مقعده الخشبي، عيناه الضيقتان تلمعان ببريق مراوغ وهو يتفحص بقعة الدم المتيبسة على ذراع الصبي. قال أسكلاد بنبرة متهكمة: أهذا كل ما تملكه يا ابن ثورس؟ طعنة طائشة في ممر ضيق بينما تنزف كأرنب مذبوح؟ لم يجب ثورفين؛ انقبضت عضلات فكه حتى برزت عروق عنقه، وتصلب جسده النحيل كوتر قوس مشدود. في الخارج، كان صخب رجال أسكلاد يملأ أرجاء المعسكر، أصوات الضحكات الخشنة وقرع الكؤوس الخشبية تختلط بوقع أقدامهم الثقيلة على الأرض الموحلة. تقدم أسكلاد خطوة، خفف من حدة سخرية نبرته لتصبح أكثر دقة، أشبه بلسع سوط، متمتماً: لولا تدخل ثورس في ذلك اليوم، لكانت جثتك قد طعمت سمك بحر الشمال منذ زمن طويل. رمقه ثورفين بنظرة حادة، بؤبؤا عينيه متسعتان، وأنفاسه تتسارع في صدره المحتقن. لم يكن الصبي يرى سوى وجه أبيه الراحل، ولم يكن يسمع سوى صدى وعيده القديم الذي يطارده في يقظته ومنامه. سأله أسكلاد بصوت منخفض ومخادع: ما الذي يجعلك تظن أنك ستنجح اليوم؟ هل هو الحقد؟ أم أنك فقط أصبحت تعشق رائحة الموت التي تلاحقني؟ صمت ثورفين، وشلّت لغة جسده أي رد فعل دفاعي، فكل حرف ينطقه أسكلاد كان يغرس نصله في جرحه الغائر. في تلك اللحظة، دخل أحد الرجال، جسده الضخم يحجب ضوء المشعل المعلق عند المدخل، وقال بصوت خشن ومبتور: هناك سفينة تلوح في الأفق، تبدو كأنها من السفن الملكية. تغيرت ملامح أسكلاد في لحظة؛ تلاشت السخرية وحلت محلها برودة استراتيجية حادة. التفت نحو ثورفين، وضع يده على مقبض سيفه، وقال بلهجة آمرة: اخرج واستعد، فإذا أردت قتلي، فعليك أولاً أن تبقى حياً في هذه الفوضى التي بدأت للتو. لم ينتظر الصبي أمراً ثانياً؛ اندفع خارجاً نحو الساحة الملبدة بالضباب، حيث كان الهواء مشبعاً برائحة الملح والحديد، وعقله لا يزال يغلي بصورة أسكلاد وهو يقهقه باحتقار.', '', 15, '2026-07-15 15:17:36.735', '2026-07-15 15:17:36.735');
INSERT INTO public.chapters VALUES ('291a5e22-eee4-45aa-a55b-442f0527d40a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 16: رصانة الحديد في وجه العاصفة', '— --------------------------------------- توقفت حركة السفينة فجأة، كأنما اصطدمت بكيان صلب مخفي تحت صفحة الماء. على سطح السفينة، تصلبت أكتاف ثورس، واتسعت عيناه لتستوعب المشهد الذي لم يكن يلوح في الأفق قبل لحظات. السفن التي تحيط بهم لم تكن مجرد سفن تجارية عابرة، بل كانت تشكيلات قتالية مصطفة بإحكام غريب، ترفع أعلاماً عرفها ثورس جيداً. ساد صمت مطبق، لم يقطعه سوى أنين الخشب الذي يئن تحت وطأة الأمواج المترددة. التفت ثورس إلى ثورفين، قبض على كتفه بقوة كادت تغرس أصابعه في ثيابه، ثم بلهجة آمرة لا تقبل الجدال قال: اذهب إلى قاع السفينة، لا تخرج مهما سمعت. أراد ثورفين أن يحتج، أن يصرخ برغبته في القتال، لكن نظرة واحدة من أبيه كانت كافية لتجميد الدماء في عروقه. كانت نظرة ثورس تحمل ثقلاً لم يعهده من قبل، مزيجاً من التحذير والوداع الخفي. نزل ثورفين درجات السلم المظلمة، يضرب بقبضتيه الخشبيات، بينما كان في الأعلى يشتد صوت حوافر الخيل على ظهر سفنهم، صوت غريب ومقلق في وسط البحر. وقف ثورس على منصة القيادة، يراقب أسكلاد وهو يخطو بخيلاء نحو مقدمة السفينة، واضعاً يده على مقبض سيفه ببرود مستفز. نادى أسكلاد بصوت متهكم حمل نبرة التحدي: يا له من شرف عظيم أن نجد بطل الفايكنج الأسطوري يضحي بنفسه لأجل طاقمه. لم يجب ثورس، بل وقف كالجبل الأشم، عيناه تلاحقان تحركات رجال أسكلاد الذين بدأوا في الإحاطة بهم كأنهم ذئاب تحاصر ضبعاً جريحاً. كان الهواء مشحوناً برائحة الملح والترقب القاتل. تحرك أسكلاد ببطء، موازناً خطواته مع تمايل السفينة، ثم تابع بابتسامة باهتة لا تصل إلى عينيه: لا داعي للموت اليوم، ثورس، سلم نفسك وسنرى ما يمكن فعله. شد ثورس على لحيته، وتلاشت ملامح التردد من وجهه، ليحل محلها ثبات صخري. أجابه بصوت عميق ورخيم: لا أريد قتالكم، ولا أريد دماءكم على يدي. لكن إن كان هذا هو الطريق الذي اخترتموه للوصول إلي، فإني لا أخشى الموت. في القاع، كان ثورفين يضع أذنه على الخشب، يسمع وقع أقدام الأعداء فوق رأسه مباشرة، يضغط بأسنانة على شفته حتى يكاد يدميها، بينما كانت يداه ترتجفان بانتظار إشارة المعركة التي بدأت نيرانها تتصاعد في عيني ثورس وهو يسحب سيفه، معلناً بداية نهاية لا مفر منها.', '', 16, '2026-07-15 15:17:37.037', '2026-07-15 15:17:37.037');
INSERT INTO public.chapters VALUES ('8054d266-e0da-4980-b1a3-a1ed4078be4a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 17: خيوط القدر الملطخة', '— --------------------------------------- انتصبت خيمة أسكلاد كبقعة داكنة وسط اضطراب المعسكر، كان الجو داخلها ثقيلاً برائحة التبغ الرخيص والجلد المعتق. رمى أسكلاد خنجره على الطاولة الخشبية المتهالكة، محدثاً رنيناً معدنياً حاداً شق صمت المكان. استدار ثورفين، عيناه الغائرتان تقدحان شراً، ويداه المضرجتان بالدماء ترتجفان بحدة لا إرادية. قال أسكلاد وهو يمسح وجهه بكفه الخشنة: لا تظن أن هذا النصر يجعلك محارباً، يا صبي، إنه مجرد وسيلة لتبقى حياً لليوم التالي. زفر ثورفين هواءً ساخناً، وشد على مقبض خنجره حتى ابيضت مفاصل أصابعه: لا يهمني النصر، أريد رأسك، سأنتزعها بيدي في المبارزة القادمة. انحنى أسكلاد نحو الفتى، وتلاشت ابتسامته الماكرة ليحل محلها برود حاد يبعث القشعريرة: المبارزة القادمة؟ أنت تظن أنك تملك ترف الوقت؟ انظر حولك، الرجال الذين تقاتل بجانبهم هم ذئاب جائعة، لا يبحثون عن المجد بل عن الخبز والذهب، وأنت لا تعدو كونك أشبالاً تائهاً في قطيعهم. لم يرد ثورفين، بل تراجعت حدقتاه للوراء وتصلب جسده النحيل، وكأن كلمات أسكلاد كانت سياطاً تنهش ما تبقى من كبريائه. خرج الفتى من الخيمة بخطوات متعثرة، تاركاً خلفه ضحكات أسكلاد المكتومة التي كانت تشبه وقع الحصى على جدار صلب. في الخارج، كان صخب المعسكر قد خفت، لكن حدة التوتر كانت لا تزال تسري في الهواء. توقف ثورفين عند حافة النهر، غسل يديه بماء مثلج، محاولاً محو أثر المعركة، لكن رؤية انعكاس وجهه في الماء المحتقن بالدماء جعلته يطبق قبضته على وجه السطح، محطماً صورته المنعكسة في حركة غاضبة. كان يدرك في أعماقه، رغم إنكاره المرير، أن أسكلاد لا يكذب. كان الفتى يركض في حلقة مفرغة، يطارد ظلاً يزداد طولاً مع كل شروق شمس، بينما كانت حياته تتآكل في صراعات لا تعني له شيئاً سوى طريق واحد، مسدود ومظلم، يقوده نحو هاوية لم يعد يرى نهايتها.', '', 17, '2026-07-15 15:17:37.22', '2026-07-15 15:17:37.22');
INSERT INTO public.chapters VALUES ('44bfac12-44c8-41ad-afe5-98f7193c694b', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 18: نذير العاصفة', '— --------------------------------------- انتصبت خيام الغزاة تحت سماء تلبدت بغيوم رمادية ثقيلة، بينما كانت أصوات صليل السيوف وشحذ النصال تقطع صمت المعسكر الرتيب. جلس أسكلاد على جذع شجرة متهالك، يراقب ثورفين وهو يتدرب بحدة، حركات الصبي كانت سريعة لكنها تفتقر إلى التوازن، طعنات طائشة يملؤها الغضب المحض. قال أسكلاد بصوت متهكم دون أن ينظر إليه: «أنت تحاول قتل الشبح الذي يلاحقك، يا ثورفين، لكنك لا تدرك أن الشبح هو من يتحكم في حركة يدك». توقف ثورفين عن الحركة، صدره يعلو ويهبط بعنف، ونظر إلى أسكلاد بعينين تقدحان غيظاً مكتوماً. رد ثورفين بكلمات مقتضبة: «أنت تتحدث كثيراً عن التحكم، لكنك لا تملك الجرأة لمواجهتي وجهاً لوجه». ارتسمت على شفتي أسكلاد ابتسامة باردة، وتجاهل تحدي الصبي، ثم أشار بيده نحو الأفق حيث تلوح أشرعة السفن في عرض البحر. في خيمة القيادة، كان القادة يتبادلون نظرات الترقب والرهبة، فالأخبار الواردة من الحدود تشير إلى تحرك قوات غير متوقعة. لم تكن مجرد غارة عادية، بل حملة منظمة تهدف إلى محاصرة المعسكر. وقف أسكلاد نهض وترك الجذع خلفه، ومسح نصل خنجره بقطعة جلد ببطء شديد، ثم التفت إلى رجاله وقال بنبرة آمرة وهادئة: «استعدوا، فالذئاب التي كنا نطاردها قررت أخيراً أن تتحول إلى صيادين». ساد صمت مطبق في أرجاء المعسكر، تخلله فقط صوت احتكاك المعادن، بينما كان ثورفين يشد قبضته على مقبض خنجره، مفاصل أصابعه مبيضة من شدة الضغط، وعيناه لا تفارقان الأفق حيث بدأت تلوح ملامح السفن القادمة.', '', 18, '2026-07-15 15:17:37.535', '2026-07-15 15:17:37.535');
INSERT INTO public.chapters VALUES ('e0828e5a-af49-4bc9-bca8-26a9f808fbca', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 19: خلف أسوار الجليد', '— --------------------------------------- انتصب سور القلعة الدنماركية شاهقاً، تتساقط فوق حجارته المتآكلة ثلوج خفيفة لا تكاد تُرى، بينما كانت نظرات ثورفين معلقة ببرود نحو الداخل. لم يكن ثمة صوت سوى تكتكة خنجره وهو يرتطم بخاصرته كلما تحركت قدماه. كان أسكلاد يراقبه بابتسامة باهتة لا تصل إلى عينيه، يمسح بيده على مقبض سيفه كأنما يتهيأ لرقصة مألوفة. قال أسكلاد بصوت منخفض تكاد تخفيه هبات الريح: لا تظن أن الغضب سيفتح لك هذه البوابات يا صبي، الغضب أعمى، والعيون العمياء لا ترى مفاصل السور. انقبضت كف ثورفين على نصل خنجره، وسأل بصوت أجش ومختصر: متى نقتحم؟ لم يجب أسكلاد، بل أشار بيده نحو الحراس المتجمدين فوق البرج، كانت أنفاسهم تخرج بخاراً كثيفاً في الهواء القارس. لم تكن القلعة مجرد حجارة؛ كانت سجناً لمعلوماتٍ قد تغير مسار رحلتهم نحو الجنوب. اندفع ثورفين من مكانه دون استئذان، جسده الصغير ينسل بين الظلال كأنه أثر من أشباح الغابات. اتسعت بؤبؤة عين أسكلاد للحظة، لم تكن دهشة، بل كانت إعجاباً بمتهورٍ لا يخشى الموت، بل يطالبه. سحب أسكلاد سيفه ببطء، صليل المعدن كان النداء الأخير قبل أن تتحول الصمت المطبق في محيط القلعة إلى فوضى حركية. قفز ثورفين متجاوزاً كومة من جذوع الخشب، ساقاه تندفعان بقوة نحو الجدار بينما كانت عيناه ترصدان تحركات الحارس الذي غفل لثوانٍ. في تلك اللحظة، لم يكن هناك وجود لأي فلسفة، لم يكن هناك وجود للماضي؛ كان هناك فقط المسافة الفاصلة بين خنجره وعنق الحارس. سقط الجسد دون صوت يذكر، واستقرت قدما ثورفين على الحافة العلوية. التفت إلى أسكلاد الذي كان يقف أدناه، ملوحاً له بيده بحركة مقتضبة تدعو للصعود. لم تكن معركة، بل كانت عملية اقتحام صامتة، دقيقة، كأنها خياطة جرح في جسد القلعة. سار ثورفين فوق الأسطح الخشبية، خطواته خفيفة لا تترك أثراً، وكلما اقترب من غرف الجنود، زاد تيقظه الحسي. كان يعلم أن أي خطأ يعني النهاية، لكنه لم يفكر في ذلك؛ فكر فقط في الضربة القادمة، وفي ذلك الرجل الذي يقف في الأسفل، ينتظر منه أن يثبت أنه ليس مجرد تابع، بل مقاتل يقتلع النصر من فم المستحيل.', '', 19, '2026-07-15 15:17:37.711', '2026-07-15 15:17:37.711');
INSERT INTO public.chapters VALUES ('4181f4fa-f1d8-4304-915c-1cee2754078e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 20: خلف أسوار الجليد', '— --------------------------------------- توقف ثورفين عن الحركة. كانت خناجره ما تزال عالقة في جلد الحصان الميت، ونصله الذي يرتجف يقطع هواء الميدان الساكن. في الجهة المقابلة، وقف أسكلاد، يمسح سيفه بقطعة قماش خشنة، وعيناه تراقبانه بهدوء مفترس. لم يكن هناك صراخ، بل فقط أنفاس متلاحقة تخرج من صدور المحاربين المنهكين. نظر أسكلاد إلى الفتى، ثم ألقى قطعة القماش جانباً وقال بنبرة متهكمة: ألا تزال تأمل في أن يمنحك الغضب نصراً؟ أنت لا تقاتل يا فتى، أنت فقط تعبر عن حنق طفل فقد لعبته. انقبضت كف ثورفين على مقبض خنجره حتى ابيضت مفاصله، واندفع نحوه بجسد متصلب، لكن حركة أسكلاد كانت كزئبق ينساب من بين أصابع الفشل. تفادى الضربة بخطوة جانبية بسيطة، وركل ثورفين في صدره، مما أدى لارتطامه بجذع شجرة عتيق. سقط ثورفين، وسعل دماً. تقدم أسكلاد بخطوات وئيدة، ووقف فوقه، ظله يغطي جسد الفتى الصغير. قال بصوت منخفض وعميق: الموت لا ينتظر المحاربين المتسرعين. اذهب، اجمع قواك، فالمعركة التي تطلبها لم تأتِ بعد. التفت أسكلاد نحو رجاله الذين كانوا يراقبون المشهد بصمت مطبق، وأشار بيده إشارة مقتضبة للتحرك. نهض ثورفين بصعوبة، يمسح الدم عن شفته، عيناه لا تزالان معلقتين بظهر خصمه الذي يبتعد. لم يقل ثورفين شيئاً، لكن ارتجاف كتفيه كان كافياً ليعبر عن صمتِ بركانٍ يؤجل انفجاره. في زاوية أخرى، كان بيورن يراقب المشهد بملل، ثم بصق على الأرض وقال بصوت أجش: فتى عنيد، يظن أن العالم يدور حول انتقامه. هز الآخرون رؤوسهم بلامبالاة، وبدأوا في ركوب خيولهم، تاركين ثورفين وحده في الساحة الموحشة. وحين تلاشى صدى حوافر الخيول، لم يتبقَ سوى صوت الريح الخفيفة التي تحرك خصلات شعر ثورفين الملطخ بالوحل. أغمض عينيه للحظة، مستحضراً ملامح وجه والده، ثم قبض على خناجره بقوة أشد، وأقسم في أعماق نفسه أن السقوط اليوم ليس سوى استراحة لمحارب لن يعرف الهدوء قبل أن يقتلع روح عدوه.', '', 20, '2026-07-15 15:17:37.887', '2026-07-15 15:17:37.887');
INSERT INTO public.chapters VALUES ('d65a3b45-e2cb-409a-a568-d60719cb07c9', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 54: خريف الاحتمالات القاتلة', '— --------------------------------------- توقف ثورفين عن الحركة. كانت حدقة عينيه تتركز بصلابة على أسكلاد الذي كان يجلس ببرود، يمسح سيفه بقطعة قماش خشنة. لم تكن هناك رياح، فقط صوت اشتعال الأخشاب في الموقد يتداخل مع تنفس الرجال المنتظم في الخيمة. رمى أسكلاد القماش أرضاً، ونظر إلى ثورفين بابتسامة خفيفة، تلك التي لا تصل إلى عينيه. قال أسكلاد بنبرة هادئة ومستفزة: «ما زلتَ تحلم بالانتقام يا فتى؟ إنها فكرة مرهقة للأعصاب في هذا العمر». لم يجب ثورفين، بل قبض على مقبض خنجره حتى ابيضت مفاصل أصابعه، وارتفع صدره بهدوء مريب. كان يعلم أن أي حركة متهورة تعني نهايته، لكن الاندفاع كان يغلي في عروقه كسم بطيء. تدخل أحد الجنود بضحكة خشنة، مقاطعاً الصمت: «اتركه يا قائد، الصغير يحتاج لسنوات أخرى ليتمكن من خدش درعك». تجاهل أسكلاد الضحكة، واقترب ببطء من ثورفين، محدقاً فيه بحدة جعلت الهواء يثقل بينهما. همس أسكلاد ببرود: «المحارب الحقيقي لا يقتل لأنه يكره، بل لأنه يمتلك غاية أسمى، غاية لا تجدها في قلب طفلٍ يحمل سكيناً». ارتعدت عضلات وجه ثورفين، وأطلق زفيراً حاداً من أنفه، ثم تراجع خطوة إلى الوراء، مفلتاً مقبض خنجره قليلاً. كان يعلم أن أسكلاد لا يلقي الكلمات عبثاً؛ إنه يغرزها ليرى رد فعله. خرج ثورفين من الخيمة دون كلمة واحدة، تاركاً خلفه ثقلاً من التوتر. خارجاً، كانت السماء قد بدأت تتلون بلون الرماد، وأدرك ثورفين أن الشتاء القادم لن يكون مجرد برد، بل اختباراً جديداً لصبره الذي بدأ ينفد تحت وطأة سخرية الرجل الذي قتل أباه.', '', 54, '2026-07-15 15:17:44.519', '2026-07-15 15:17:44.519');
INSERT INTO public.chapters VALUES ('b93073c4-0ef6-46e2-b06b-7f6a4c93c6f3', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 21: خلف أسوار الجليد', '— --------------------------------------- توقف وقع أقدام ثورفين على الأرض المكسوة بالصقيع. كانت أنفاسه تخرج في هيئة سحب رمادية متقطعة، بينما تركز نظره على نصل خنجره الذي يلمع تحت ضوء الشفق الباهت. أمام الكوخ الصغير، توقف أسكلاد، ملقياً بنظرة جانبية فاحصة نحو الصبي، تلك النظرة التي لا تخلو من سخرية مريرة. قال أسكلاد بصوت أجش ونبرة مستفزة: هل تعتقد حقاً أن الغضب وحده سيشحذ نصلك؟ يا لك من ساذج. لم يجب ثورفين، بل انقبضت كفه حول مقبض الخنجر حتى ابيضت مفاصل أصابعه. في تلك اللحظة، خرج أحد المقاتلين من بين الظلال، يده ترتجف قليلاً وهو يبلغ أسكلاد بوصول الإمدادات الموعودة. لم يلتفت أسكلاد، بل استمر في مراقبة ثورفين، كأنه يتأمل آلة صممت خصيصاً لتنفيذ إرادته. زمجر ثورفين، مقتضباً، وقد برقت عيناه بوعيد صامت: سأقتلك، هذه المرة لن أخطئ. ضحك أسكلاد ضحكة قصيرة، جافة، خلت من أي مرح، ثم أردف بنبرة متعالية: التوقيت هو كل شيء يا ثورفين. القوة الخام بلا حكمة هي مجرد ضجيج في ساحة المعركة. في تلك الأثناء، كانت القوافل تتحرك في الأفق، تتناغم أصوات عجلات الخشب مع قسوة الرياح. تحرك ثورفين خطوة للأمام، لكن أسكلاد أشار بيده نحو السفن الراسية في الميناء القريب، قائلاً بلهجة آمرة: اترك الأحقاد الشخصية للوقت المناسب، فالمعركة التي تنتظرنا تتطلب أكثر من مجرد الرغبة في الانتقام. تجمدت ملامح ثورفين، واتسعت حدقتا عينيه وهو يرى مدى اتساع المهمة المطلوبة منه. لم تكن الكلمات بحاجة للاسترسال، فالمكان كان يعج بحركة الرجال الذين يستعدون للرحيل، ورائحة الزيت والجلود المحروقة تفوح في الأجواء، مما جعل الانقسام بين نيران الغضب في صدر ثورفين وبرودة الواقع من حوله يزداد حدة. استدار أسكلاد مغادراً، تاركاً ثورفين في صمته المطبق، بينما كان الأخير يراقب تحركات العدو من بعيد، مدركاً أن طريقه للخلاص ما زال محفوفاً بالدماء والمزيد من التضحيات التي لا يملك خياراً سوى دفعها.', '', 21, '2026-07-15 15:17:38.104', '2026-07-15 15:17:38.104');
INSERT INTO public.chapters VALUES ('89916e8a-f699-4dd9-8df2-3604b0c1147e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 22: خيوط المصير المشتبكة', '— --------------------------------------- انتصبت خيام أسكلاد كبقعة داكنة وسط السهول الواسعة، بينما كانت النيران تخبو مخلفة دخاناً يلتف حول الأجساد المنهكة. ثورفين، بملامحه المتصلبة كحجر منحوت في غيظ دائم، كان يحدق في النصل الذي يمسكه بيده، يقشطه بقطعة قماش خشنة. لم يلتفت عندما اقترب أسكلاد، بل اكتفى بتقلص عضلات كتفيه. توقف أسكلاد على مسافة بضع خطوات، ينفث دخان غليونه بهدوء، وعيناه تراقب الأفق بعيداً. قال أسكلاد بصوت أجش خفيض: ليس القتل فنًا يا صبي، إنه مجرد حتمية لمن لا يملك وسيلة أخرى للعيش. رمقه ثورفين بنظرة خاطفة، ثم بصق على الأرض وقال بنبرة مقتضبة: أنت تتحدث كثيراً عن الحتمية، بينما أنت تحكم قبضتك على كل شيء. ابتسم أسكلاد، وهي ابتسامة لم تصل لعينيه، وأردف قائلاً: الحرب لا تحتاج إلى فلاسفة، بل تحتاج إلى رجال يدركون متى يسحبون السيف ومتى يغمدونه. في تلك الأثناء، كان الجنود يتبادلون أحاديث صاخبة حول الغنائم والمسارات القادمة، أصواتهم تملأ الفضاء بنبرات خشنة خالية من أي رقة. كان ثورفين يراقب تحركاتهم، يحلل المسافات، يخطط في صمته المطبق لخطوته القادمة. لم يكن يكترث بكلمات أسكلاد، بل كان يرى في ظهره هدفاً متحركاً لا ينفك يراوغه. اقترب أحد المحاربين، واضعاً يده الثقيلة على كتف ثورفين، محاولاً استفزازه بضحكة مكتومة، فانتفض ثورفين بجسده، متجنباً اللمسة بخفة قطة برية، وقذف نظرة جعلت الرجل يتراجع خطوة للخلف بوجل غير مفسر. عاد أسكلاد ليلتفت نحو النار، متمتماً لنفسه: الصمت الذي يسبق العاصفة هو الشيء الوحيد الذي لا يمكنني التلاعب به. وبينما كانت النجوم تبدأ بالظهور، ساد صمت غريب، ثقيل ومحمل بالترقب، حيث لم يكن هناك مكان للكلمات العذبة أو الفلسفات الواهية؛ فقط صراع الغرائز، وبريق المعادن، وعزيمة ثورفين التي لا تنثني.', '', 22, '2026-07-15 15:17:38.282', '2026-07-15 15:17:38.282');
INSERT INTO public.chapters VALUES ('e633c583-96fe-4205-97a4-d4e53d324049', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 23: خيوط الغدر المنسوجة بدم النبلاء', '— --------------------------------------- انزاح الستار عن ليلةٍ طبعت سكونها أصوات تقارع الكؤوس في خيمة الأمير كانوت. كان أسكلاد يرقب المشهد من زاوية مظلمة، عينان تقدحان بمكر الثعالب بينما ترتشف يده نبيذاً مرّاً. اقترب منه أحد رجاله بهمسٍ خافت، ليرد أسكلاد بابتسامة باردة لا تبلغ عينيه: «الجميع يغرق في أوهام العظمة، والملك يظن أن الخيوط بيده، لكنه يجهل أن النسيج قد تهالك». في الخارج، كان ثورفين يحدق في الظلام، ملامحه متصلبة كصخر الجبل، ويده تقبض على مقبض خنجره حتى ابيضت مفاصل أصابعه. لم يكن ثورفين هنا للسياسة، بل كان ينتظر اللحظة التي يرى فيها رأس أسكلاد يتدحرج على الأرض. اقترب أسكلاد من المكان الذي يقف فيه ثورفين، نظر إليه بنظرة ساخرة وقال بصوت متهكم: «ما زلتَ هنا يا صغير؟ الاندفاع لا يقتل أعداءك، بل يقصر عمرك. تعلم كيف تنتظر، فالموت يتطلب صبراً أكثر من الحياة». استشاط ثورفين غضباً، واندفع نحوه بحركة سريعة، لكن أسكلاد بلمحة بصر أزاح جسده بخفة، ليوجه ركلة دقيقة أسقطت ثورفين أرضاً. لم تكن في عيون أسكلاد شفقة، بل كانت هناك برودة حسابية، بينما نهض ثورفين بصمت، أنفاسه متسارعة، وصمتُ المكان يضخم دقات قلبه. انفض الجمع، وأدرك الجميع أن ليلة الغدر قد بدأت، وأن الوجوه التي تبتسم الآن ستكون أول من يغرس نصاله في الظهر حين يميل ميزان القوى. لم تكن السياسة بالنسبة لأسكلاد سوى رقعة شطرنج من دماء، وكان يرى كل شخصية حوله مجرد بيدق ينتظر حتفه، بينما ظل هو يخطط ليجعل من سقوط الملوك سلماً يرتقي عليه.', '', 23, '2026-07-15 15:17:38.507', '2026-07-15 15:17:38.507');
INSERT INTO public.chapters VALUES ('d1838e4e-cb78-442e-ae67-679c15d3fd76', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 24: خلف أسوار الجليد', '— --------------------------------------- انتصبت خيام الغزاة تحت سماء رمادية خانقة، حيث تتصاعد خيوط الدخان من بقايا نيرانٍ لم تعد تُدفئ أحداً. كان أسكلاد يحدق في رقعة الشطرنج الخشبية بين يديه، أصابعه تعبث بقطعة الحصان ببطء مستفز، بينما كانت أنظاره تراقب ثورفين الذي جلس في الزاوية، يحدق في فراغِ خيمته، نصل خنجره الصغير يلمع بضوء خافت وهو يغرزه في الأرضية الترابية بانتظام رتيب. صمت الرجلين لم يكن هدوءاً، بل كان ضغطاً جوياً يسبق العاصفة. قطع أسكلاد الصمت بنبرة متهكمة باردة: هل تظن أن الانتقام سيُعيد لك رائحة الموقد في منزلك؟ ثورفين لم يرفع رأسه، بل ضغط على مقبض خنجره حتى ابيضت مفاصل أصابعه، وزمجر بصوت مخنوق: اصمت. لا تذكر بيتي. ابتسم أسكلاد نصف ابتسامة، وهو يضع قطعة الشطرنج في مكانها، معلقاً بهدوء: الغضب يا صغيري هو القيد الوحيد الذي يمنعك من رؤية ما أراه. أنت تتبعني ككلب مخلص، ليس لأنك تريد قتلي، بل لأنك لا تملك وجهة أخرى. انقبضت عضلات فك ثورفين، واندفع واقفاً، ليصبح وجهه على بعد بوصات من أسكلاد، تنفسه مسموع ومضطرب. صرخ ثورفين: سأقتلك، سأنتزع رأسك حين لا تتوقع ذلك، هذا هو وعدي الوحيد! قهقه أسكلاد، وقام بمسح الغبار عن سترته بلامبالاة قاتلة، ثم اتجه نحو مخرج الخيمة، ملتفاً ليقول بلهجة ساخرة: أحضر لي طعاماً إذن، القاتل الجائع لا يجيد تنفيذ تهديداته. خرج أسكلاد تاركاً ثورفين في عزلته المحمومة. في الخارج، كانت الحركة دؤوبة؛ رجال يسنّون سيوفهم، وآخرون يصلحون جلود دروعهم. اقترب أتور، أحد رجال العصابة، من ثورفين بخطوات ثقيلة، وألقى بقطعة لحم جافة على الأرض أمامه: زعيمك يطلبك. ثورفين لم يجب، بل اكتفى بوضع خنجره في غمده، وتحرك نحو الخارج، عيناه لا تغادران ظهر أسكلاد الذي كان يقف وسط الساحة، يراقب الأفق بعينين خبيرتين كمن يقرأ خريطة العالم في حركة السحب. لم تكن هناك رحمة في تلك النظرات، ولا حنين، فقط حسابات باردة لغدٍ لا يهم فيه من يعيش ومن يسقط.', '', 24, '2026-07-15 15:17:38.691', '2026-07-15 15:17:38.691');
INSERT INTO public.chapters VALUES ('c736de2e-8b15-406c-b02f-0ce5824b75c1', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 138: خلف أسوار الترقب', '— --------------------------------------- توقف إينار عن الجذف، اصطدمت مقدمة القارب الخشبي برمال الشاطئ الهادئة في أرض فينلاند التي وعدوا بها. قفز ثورفين إلى اليابسة، غاصت قدماه في التربة الرطبة، لم يلتفت للخلف، بل اتجه ببصره نحو الأفق حيث تبدأ الغابات العذراء. تبعه إينار، ممسكاً ببعض المؤن، أنفاسه متسارعة، وصدره يعلو ويهبط بانتظام. سأل إينار بصوت متهدج: أهذه هي الأرض التي حلمنا بها حقاً؟ توقف ثورفين، لم يجب على الفور، بل مد يده ليلمس لحاء شجرة قريبة، ملمس الخشب كان خشناً وبارداً تحت أصابعه. التفت ثورفين نحو رفيقه، كانت عيناه تحملان هدوءاً غير مألوف، وقال بنبرة قاطعة: الأرض لا تكترث لمن يمتلكها، بل لمن يعمرها. في تلك الأثناء، كان ليف إريكسون يقف على ظهر السفينة يراقب المشهد، واضعاً يده على مقبض سيفه، وجوه البحارة كانت مشدودة، تترقب أي حركة غير طبيعية في الأحراش الكثيفة. لم تكن هناك طيور تغرد، فقط صوت تكسر الأمواج ووقع خطواتهم على الأرض البكر. فجأة، توقفت حركة ثورفين، انقبضت عضلات رقبته، وألقى نظرة سريعة نحو الأدغال. لم تكن صدفة، بل إدراكاً فطرياً لخطر يتربص في الظل. سحب إينار فأسه ببطء، صليل المعدن كان الصوت الوحيد الذي خرق سكون المكان. همس ثورفين دون أن يغير اتجاه نظره: ابقَ خلفي، لا تتحرك. كانت لحظة مشحونة بالترقب، حيث يمتزج حلم البداية بمرارة الواقع الذي يرفض أن يتركهم في سلام. لم تكن هذه مجرد أرض للزراعة، بل كانت اختباراً جديداً لإرادتهم، ومعركة صامتة بدأت ملامحها تتشكل بين الأشجار المتشابكة.', '', 137, '2026-07-15 15:18:01.734', '2026-07-15 15:18:01.734');
INSERT INTO public.chapters VALUES ('040772b0-ba91-4cf0-9b14-d1fdb1f32e61', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 25: خلف أسوار الغدر', '— --------------------------------------- انتصبت الخيام فوق الهضبة الجافة، تاركةً خلفها غباراً عالقاً يغطي مخيم أسكلاد. كانت الأصوات ترتفع وتخفت، أصوات الرجال الذين يبيتون ليلتهم على ترقب. في زاوية منعزلة، كان أسكلاد يحدق في نيران مشتعلة، يمسح نصل سيفه بخرقة خشنة. اقترب منه أحد رجاله، ملامحه توحي بتوتر مكتوم. قال الرجل بصوت أجش: سيدي، الأمور لا تبدو مطمئنة، ثورفين لا يزال يطارد سرابه. رمقه أسكلاد بنظرة باردة، ثم ابتسم ابتسامة باهتة لا تصل إلى عينيه. قال أسكلاد بهدوء: دعه يطارد، فالحقد وقود يحرق صاحبه قبل خصمه. أما نحن، فالميدان لا ينتظر المترددين. في تلك الأثناء، كان ثورفين يتربص في الظلال، عيناه لا تغادران خيمة قائده، أصابعه تقبض على مقبض خنجره حتى ابيضت مفاصله. لم تكن في عقله استراتيجية ولا تفكير في عواقب، بل كان صوت والده يتردد في أذنه كصدى بعيد، ذاك الصوت الذي يحثه على القوة، لكنه يقف الآن حائراً أمام غيظه المتأجج. دخل ثورفين الخيمة بخطوات صامتة، كان الهواء داخلها ثقيلاً، مشبعاً برائحة الجلد الرطب. وجد أسكلاد يقرأ خريطة بتركيز، لم يلتفت إليه فور دخوله، بل قال بصوت ساخر: أهذا أنت يا صغيري؟ جئت لتنهي مهمتك العبثية؟ لم يرد ثورفين، بل تقدم خطوة، دافعاً بجسده نحو الأمام في وضعية استعداد للهجوم. توقف أسكلاد عن القراءة، ورفع بصره ليواجه الفتى، لم تكن في عينيه ذرة خوف. أضاف أسكلاد بنبرة هادئة ومستفزة: القتل ليس مهارة تمارسها في الظلام، إنه فن يحتاج إلى عقل لا يغمره الغضب. إذا أردت رأسي، فاصعد للميدان غداً، وافعلها أمام الجميع، لا أن تتسلل كجرذ جائع. انقبضت عضلات وجه ثورفين، وتسارعت أنفاسه، لكنه لم يندفع. أدرك في تلك اللحظة أن خصمه لا يملك سلاحاً يواجهه به فحسب، بل يملك برودة أعصاب تفقده توازنه. غادر ثورفين الخيمة مسرعاً، ليصطدم بالهواء الطلق وبرودة الليل التي لسعت وجهه، تاركاً أسكلاد يبتسم وحيداً وسط خيمته، مدركاً أن الفتى لم ينضج بعد، وأنه لا يزال رهينة لغضبه الذي يسهل التحكم فيه.', '', 25, '2026-07-15 15:17:38.888', '2026-07-15 15:17:38.888');
INSERT INTO public.chapters VALUES ('8348de80-a557-48d7-aa61-fab12022fe61', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 26: بقايا العهد', '— --------------------------------------- تصلبت ملامح ثورفين وهو يحدق في تلك الأنقاض التي كانت يوماً تمثل وطناً، لم يدرك صمته إلا حين تحطم غصن جاف تحت ثقله. كان أسكلاد يقف على مقربة، يرقب المكان بعينين ذابلتين لا ترحمان، يضع يده على مقبض سيفه ببرود غريب. التفت أسكلاد نحو ثورفين، ارتسمت على زوايا فمه ابتسامة صفراء لا تعبر عن سرور، بل عن سخرية واهنة. قال أسكلاد بصوت أجش: أتظن أن الأشباح التي تطاردك ستغادر هذه الأرض بمجرد وصولنا؟ إنها عالقة هنا، تماماً كما أنت عالق في غضبك الصغير. قبض ثورفين على خنجره، انقبضت مفاصل أصابعه حتى اصفرّ لونها، لم يرد بكلمة، بل اتجهت أنظاره نحو هيكل سفينة مهشم نصفه مغمور في الطين، كان ذلك المشهد يختزل كل شيء؛ الرحلة التي لم تكتمل، والوعود التي ذرتها الرياح قبل أوانها. تقدم أسكلاد خطوة أخرى، غرز حذاءه في الوحل، ثم أردف بنبرة تهكمية: الحقيقة يا ثورفين ليست في الانتقام، إنها في القدرة على رؤية ما وراء هذا الدمار. ثورفين لم يلتفت، كانت أنفاسه متسارعة، وصدره يعلو ويهبط بوتيرة حادة، دقات قلبه كانت تطن في أذنيه كصوت مطرقة على سندان، لكنه في لحظة خاطفة، استدار ونظر في عيني أسكلاد مباشرة. في تلك النظرة، لم يكن هناك خوف، بل شيء أكثر قتامة، شيء يشبه اليأس الذي تحول إلى حجر صلد. لم يعلق أسكلاد، بل اكتفى بإمالة رأسه ببطء، وكأنه يختبر صمود هذا الصبي الذي أقسم على قتله. كان الصمت الذي لف المكان أشد وطأة من صراخ المعارك، صمت يحمل في طياته ثقل السنوات التي ضاعت في مطاردة سراب الانتقام، بينما كانت الشمس تتوارى خلف الأفق، تاركة ظلالاً طويلة وموحشة تلتف حول بقايا سفينة خشبية باتت ذكرى لشيء لم يعد له وجود.', '', 26, '2026-07-15 15:17:39.061', '2026-07-15 15:17:39.061');
INSERT INTO public.chapters VALUES ('171dda80-0be5-45d2-ac64-bc62197a97d9', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 27: في قلب العاصفة القابعة في الأعماق', '— --------------------------------------- انتصبت قامته وسط الفوضى، لم يكن يقاتل كمن يطارد فريسة، بل كمن يفك طلاسم معادلة مستحيلة. أسكلاد، الذي اعتادت يداه على غمس النصل في الدماء، كان يراقب ثورفين. الصبي ذو العينين اللتين لم تعودا تعرفان سوى الوهج المحموم، اندفع كالسهم المخضب بالغل، يقطع المسافة نحو خصمه في تتابع حركي لا يمنح الخصم فرصة لالتقاط الأنفاس. لم تكن صرخات المحاربين من حولهما سوى ضجيج خلفي؛ العالم بالنسبة لثورفين كان يتقلص ليصبح مجرد مساحة ضيقة تفصله عن رقبة الرجل الذي سلب حياته. قال أسكلاد بصوت منخفض، متهكم، وهو يتفادى طعنة خاطفة بحركة انسيابية كأنه يرقص على حافة الهاوية: «لا تزال تندفع كالكلب المسعور، يا فتى. الغضب لا يمنحك قوة، بل يمنحني هدفاً أسهل». لم يرد ثورفين، بل انقبضت عضلات فكه حتى برزت عروق عنقه، وازدادت وتيرة ضرباته وحشية. كان الخنجر ينهال كالمطر، والصدى المعدني لارتطام السيوف يملأ الفضاء. أسكلاد، بمكره المعهود، كان يستدرجه، يجعله يستنزف كل ذرة طاقة في جسده النحيل، مراهناً على لحظة التراخي التي لا بد أن تأتي. في تلك اللحظة، وسط غبار المعركة، بدت ملامح ثورفين كقناع من حجر، لا يعلوه سوى ذلك الوهج القاتل. قال أسكلاد بسخرية وهو يدفع الصبي بعيداً بقدمه: «انظر حولك، الجميع يموتون من أجل لا شيء، وأنت تموت من أجل سراب. ما الذي ستفعله إن قتلتني؟ هل ستجد في دمي ما يطفئ ظمأك؟». لم يتردد ثورفين، بل استجمع جسده المنهك واستعد للوثبة التالية، متجاهلاً جراحه، متجاهلاً صراخ الجنود الساقطين، ومصمماً على تحويل اللقاء إلى مسرحية دموية لا تنتهي إلا بكسر ذلك القناع الساخر الذي يرتديه أسكلاد. كانت النظرة في عين أسكلاد قد تغيرت قليلاً؛ لم تعد تهكماً محضاً، بل مسحة من حذر خفي، ذاك الحذر الذي لا ينمو إلا في قلب ذئب عجوز يدرك أن الجرو الصغير قد بدأ يسن أنيابه حقاً.', '', 27, '2026-07-15 15:17:39.279', '2026-07-15 15:17:39.279');
INSERT INTO public.chapters VALUES ('97730910-bde5-4c5c-ba85-29bed703e7ff', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 28: خيوط المصير في مأدبة الغدر', '— --------------------------------------- انغرزت نصل خنجر أسكلاد في الطاولة الخشبية بقوة، لتنغلق أصابعه على مقبضه وتبرز عروق ساعده. نظر إلى ثورفين الذي كان يجلس بجمود، وعيناه المحتقنتان بالدم لا تفارقان وجهه. قال أسكلاد بنبرة ساخرة تقطر مكرًا: هل أنت جاد يا فتى؟ تريد مبارزة أخرى بعد أن تذوقت مرارة الهزيمة مرارًا؟ ضحك ثورفين بمرارة ونهض، كانت حركاته توحي بقطة متوثبة، صوته كان مقتضبًا وباردًا: المرة القادمة، لن أخطئ. أسكلاد أرجع ظهره للخلف، وأشعل غليونه، دخان التبغ يتصاعد ليخفي ملامحه التي لم تعد مبالية: الفرص لا تمنح للأموات يا ثورفين. في الخارج، كان جيش الدنماركيين يتحرك في صمت مريب، خيولهم تصهل بضجر، ورجال أسكلاد يتبادلون كلمات نابية حول التركة التي سيغتنمونها من هذه الحملة. دخل أحد قادة الكتيبة مسرعًا، وجهه شاحب، انفاسه متقطعة: إنهم قادمون. اقترب أسكلاد من النافذة، نظر إلى الأفق حيث تتراءى رايات الأعداء تخترق ضباب الصباح. ألقى نظرة خاطفة على ثورفين الذي بدأ يتفقد حدة خنجريه. لم يقل أسكلاد شيئاً، لكن يده اتجهت ببطء نحو مقبض سيفه، معلنةً حالة تأهب صامتة. لم تكن هناك حاجة لخطابات ملهمة، ففي هذا العالم، الكلمات رخيصة والحديد هو الذي يحدد قيمته. التفت أسكلاد إلى رجاله، صوته الآن صارم، حاد كشفرة: لا تتركوا أحداً يتنفس، غنائم اليوم ستُدفع بدمائهم. ثورفين لم ينتظر الإشارة، انطلق كالسهم خارج الخيمة، تاركاً أسكلاد خلفه وهو يبتسم ابتسامة مريبة لا تحمل في طياتها إلا نذير شؤم. كان الجو مشحوناً بتوتر يسبق العاصفة، وكل خطوة يقدم عليها ثورفين كانت تقربه أكثر من حافة هاوية لا يرى قاعها، هاوية لا ترحم.', '', 28, '2026-07-15 15:17:39.477', '2026-07-15 15:17:39.477');
INSERT INTO public.chapters VALUES ('9985ba51-2c87-4289-bca0-4c6f2298cd80', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 29: وليمة الذئاب في غابات الدنمارك', '— --------------------------------------- انغرز خنجر ثورفين في جذع الشجرة بقوة، لتتطاير رقائق اللحاء تحت أثر الضربة الخاطفة. لم ينظر خلفه، بل ظل عيناه مثبتتين على تلك النقطة المحفورة في الخشب، عضلات كتفيه مشدودة كأوتار القوس. في الجانب الآخر من المعسكر، كان أسكلاد يمسح نصل سيفه بقطعة من القماش الخشن، وعيناه تراقب بحذر تحركات رجاله الذين أنهكهم طول المسير. قال أسكلاد بصوت مبحوح خالٍ من المودة: يا ثورفين، كف عن استعراض غضبك على الأشجار، فالمعركة الحقيقية لا تنتظر من يفرغ غيظه في جذوع الموتى. التفت الصبي، كانت نظراته حادة كحد السيف، وأجاب باقتضاب: اصمت. لا تظن أنني هنا لأسمع نصائحك. ضحك أسكلاد ضحكة قصيرة لا تصل إلى عينيه الماكرتين، ثم أردف: الطاعة صفة لا يمتلكها إلا من يملك غاية، وأنت يا صغيري لا تملك سوى حقداً أعمى سيبتلعك قبل أن تصل إلى خصمك. كانت رائحة الشواء تفوح في الأرجاء، لكن أحداً لم يكن يشعر بطعم الطعام؛ التوتر كان سيد الموقف. اقترب أحد المحاربين، وجهه ملطخ بآثار المعارك السابقة، وقال بصوت خشن: القافلة تتقدم ببطء عبر المضيق. هل نتحرك الآن؟ وضع أسكلاد سيفه في غمده بصوت معدني رنان، ونظر إلى الأفق حيث بدأت خيوط الظلام تنسج ستائرها فوق الغابة، ثم قال بنبرة آمرة: ننتظر حتى يغيب القمر خلف التلال. لا نريد ضجيجاً يفسد متعتنا في اصطياد الفريسة. عاد ثورفين إلى الظل، منطوياً على نفسه، يلمس نصل خنجره، يتخيل في كل حركة يد، لحظة المواجهة الحاسمة التي تنتظره. في تلك اللحظة، لم يكن هناك مكان للتردد، فقط انتظار بارد وخطوات مدروسة نحو جحيم لا مفر منه.', '', 29, '2026-07-15 15:17:39.712', '2026-07-15 15:17:39.712');
INSERT INTO public.chapters VALUES ('92e9ae4c-1c65-43d0-a4fa-bab96dd826ea', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 30: رصانة الحافة', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في وحل المخيم، بينما يحدق في أسكلاد الذي كان يمسح نصل سيفه بقطعة قماش خشنة، بنظرات باردة لا تحمل أي أثر للتردد. لم يقل أسكلاد شيئاً، كان يعلم أن الصبي سيعود، وأن غريزة الانتقام هي الخيط الوحيد الذي يربط ثورفين بالحياة. ''إلى متى؟ '' سأل ثورفين، وصوته يشبه احتكاك الحجر بالمعدن، جافاً ومقتضباً. رفع أسكلاد رأسه ببطء، ارتسمت على زاوية فمه ابتسامة خفيفة تفتقر إلى الدفء. ''حتى تشيخ، يا فتى، أو حتى تُقتل. الخيار لك''. لم تكن هناك كلمات مواساة، ولم تكن هناك وعود بالعدالة. كان أسكلاد يمارس لعبته المفضلة، تحويل الكراهية إلى وقود للقتال. تنهد ثورفين، وانقبضت عضلات ساعده حول مقبض خنجره حتى ابيضت مفاصل أصابعه. في تلك اللحظة، لم يكن هناك شعور بالخوف، بل فراغ موحش يملأ صدره. نظر أسكلاد إلى الجنود المحيطين بهم؛ كانوا يتهامسون، يترقبون لحظة انفجار الصبي. قال أسكلاد بنبرة ساخرة موجهة للمحيطين: ''لا تستهينوا بالصغار الذين يرفضون النوم، فهم الأكثر خطراً حين يحين وقت الحصاد''. غادر أسكلاد مكانه دون التفات، تاركاً ثورفين وسط الصمت الثقيل. لم يكن ثورفين بحاجة إلى خطة، ولا إلى نصيحة، كان بحاجة فقط إلى مسافة تقربه من هدف لن يدركه أبداً. تحرك نحو خيمته، خطواته ثقيلة، بينما كانت نظراته تلاحق ظلال الرجال، تبحث عن ثغرة في دفاعات خصمه، أو ربما تبحث عن سبب يمنعه من طعنه في ظهره الآن. كان يدرك أن القوة وحدها لن تكفي، وأن ذكاء أسكلاد هو الجدار الذي يجب أن يهدمه. التقط ثورفين قطعة من الخبز اليابس، مضغها ببطء، كانت قاسية ومُرّة، تماماً مثل تلك الليلة. وضع خنجره تحت وسادته، وأغمض عينيه، ليس ليرتاح، بل ليتخيل في ظلام جفونه طعنة واحدة دقيقة، تنهي كل هذا العبث.', '', 30, '2026-07-15 15:17:39.984', '2026-07-15 15:17:39.984');
INSERT INTO public.chapters VALUES ('50e98520-66df-425b-9386-a1827f9a45da', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 31: خلف أسوار الترقب', '— --------------------------------------- انزاح الستار عن خيمة الأمير كنوت، حيث الجو مشحون بتوتر خانق لا تكسره إلا أنفاس متلاحقة. كان أسكلاد يراقب المشهد من زاوية الظل، عيناه تلاحقان تحركات الجنود بدقة الصياد الذي يحصي أنفاس فريسته. لم يكن في وجهه سوى قناع من اللامبالاة المدروسة، بينما كانت أصابعه تتحسس مقبض سيفه بخفة لا تثير الريبة. اقترب ثورفين، ملامحه متصلبة كصخرة نحتتها رياح الشمال القاسية، عيناه لا تحيدان عن هدف واحد؛ إنه ذلك الغضب المكتوم الذي يتأجج كلما لمح وجه أسكلاد. قال ثورفين بصوت مقتضب جاف: متى؟ لم يلتفت إليه أسكلاد، بل اكتفى بابتسامة باهتة مرت على شفتيه كسم زعاف، وأجاب بنبرة تهكمية خفيضة: الصبر يا صغيري، القوة لا تُسترد بالتعجل، بل باقتناص اللحظة التي يغفل فيها الخصم عن سيفه. صمت المكان، ولم يعد يُسمع سوى طقطقة الجمر في الموقد. كان كنوت جالساً، صامتاً، جسده يبدو كتمثال من رخام بارد، بينما تدور في رأسه موازين السياسة التي لا يدرك كنهها إلا الملوك. تحرك أحد الحراس عند المدخل، فارتفعت حدقتا ثورفين بحدة، وانقبضت عضلات ساعده، كان مستعداً للانقضاض في أي لحظة، كذئب جريح يرفض الاستسلام. التفت أسكلاد نحوه، ونظر في عينيه نظرة باردة خالية من الرحمة، ثم همس بنبرة لا تحمل سوى المكر: لا تكن أحمق، فموت الأمير الآن ليس إلا حتفك. سحب ثورفين نفساً عميقاً، وشعر بيبوس حلقوم، لكنه لم يتردد في إرخاء قبضته، وإن ظل الجمر في عينيه يرفض الخمود. في الخارج، كانت أصوات الخطوات العسكرية تعلو وتخفت، تنذر بقرب عاصفة من نوع آخر، عاصفة لا تُحسم بالسيوف وحدها، بل بدهائها الذي يملأ أروقة المعسكر. لم تكن هناك كلمات إضافية، فقد كان الصمت بينهما أبلغ من أي حوار، صمت محمّل بوعود بالانتقام وخطط لا تزال حبيسة العقول.', '', 31, '2026-07-15 15:17:40.162', '2026-07-15 15:17:40.162');
INSERT INTO public.chapters VALUES ('5e692106-e8ba-4fd6-bcb2-d33bb6bce397', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 32: خيوط المصير في مأدبة الغدر', '— --------------------------------------- انحنى أسكلاد على المائدة الخشبية الخشنة، تلمع عيناه ببريقٍ مريب في ضوء الشعلات المتراقصة. كان الهواء داخل الخيمة ثقيلاً برائحة اللحم المشوي والشراب المخمر. ألقى نظرة فاحصة على الأمير كانوت الذي كان يجلس بجمود كتمثال حجري، غارقاً في صمته المعتاد. التفت أسكلاد نحو ثورفين، الذي كان يقف في الزاوية، يده تقبض على مقبض خنجره بضغط خفي أبيض مفاصل أصابعه، وعيناه تلاحقان حركات أسكلاد بحقد لا يهدأ. قال أسكلاد بصوت منخفض، يتخلله تهكم لاذع: «يا سمو الأمير، إنَّ قادتك يظنون أنني أخطط لشيء ما، يظنون أن الثعلب العجوز قد فقد مخالبه». لم يجب كانوت، بل اكتفى بتثبيت نظراته الفارغة في الفراغ، بينما كان راغنار يراقب المشهد بقلق متصاعد، يده لا تفارق مقبض سيفه. اندفع أحد الجنود نحو المدخل، أنفاسه متسارعة، وصاح بقلقٍ غير منضبط: «القوات الدنماركية تقترب من الشمال! إنهم لا يرفعون رايات الحرب، لكنهم مدججون بكل ما يملكون من حديد». تحرك أسكلاد ببطء، ووضع كأس الشراب جانباً، لم يظهر عليه أي أثر للفزع، بل ارتسمت على زوايا فمه ابتسامة باردة تحمل في طياتها نذير شؤم. التفت ثورفين برأسه بسرعة خاطفة، اتسعت حدقتا عينيه للحظة قبل أن تعودا للجمود، وخطا خطوة واحدة نحو الأمام، متمتماً بصوت خشن: «سأقتلك إن حاولت خيانته». ضحك أسكلاد بصوت خافت ومكتوم، ثم نهض بوقار متصنع، مشيراً إلى رفاقه بالاستعداد. صمتت الخيمة تماماً، لم يعد يُسمع سوى طقطقة الحطب في الموقد، وتلاحق أنفاس الجنود المرتبكة. أدرك الجميع في تلك اللحظة أن الهدوء الذي ساد لم يكن سوى نذير لعاصفة من الدماء، وأن أسكلاد كان قد نسج خيوط لعبته الأخيرة، حيث لا مكان للضعفاء أو المترددين.', '', 32, '2026-07-15 15:17:40.397', '2026-07-15 15:17:40.397');
INSERT INTO public.chapters VALUES ('6580081e-f0b0-49c6-8ae3-22761ac5db43', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 49: خريف الخيانة في انتظار الملك', '— --------------------------------------- انزلق النصل الفولاذي من غمده بصوتٍ معدنيٍ خافت، ليرتطم بقرع الدرع. في خيمة القيادة، كانت الأجواء خانقة، تفوح منها رائحة الجلد المدبوغ وعرق الجنود المتراكم. أسكلاد، بملامحه التي لا تفصح عما يعتمل في صدره، كان يتأمل خرائط الحملة الملقاة على الطاولة الخشبية الخشنة، بينما كان ثورفين يقف في الزاوية، يحدق في العدم، قبضتاه مشدودتان حتى ابيضت مفاصله. لم تكن هناك كلمات تكسر الصمت، سوى صوت قطرات المطر التي تضرب جلد الخيمة بقسوة. التفت أسكلاد نحوه ببطء، بابتسامة صفراء لا تصل إلى عينيه الصقريتين، وقال بصوتٍ هادئ ينضح بالسخرية: ''يا ثورفين، هل تظن أن الانتقام يمنحك دفئاً في ليلة باردة كهذه؟ ''. لم يجب الفتى، بل ارتجفت عضلات فكه السفلي. كان الغضب يعمي بصيرته، غضبٌ صامت كبركانٍ يغلي تحت قشرة من الجليد. خارج الخيمة، كانت الضوضاء تتعالى؛ صراخ الجنود، وقع أقدام الخيول، وضجيج التجهيزات العسكرية التي تعلن عن فجرٍ لن يحمل في طياته سوى الدماء. استدار أسكلاد نحو مخرجه، متجاهلاً وجود الفتى تماماً، ونادى بصوته الأجش: ''استعدوا. الملك ليس بالحمق الذي تظنونه، إنه يعرف متى يستدرج الذئاب إلى فخها''. خرج أسكلاد إلى الوحل، تاركاً ثورفين في عزلته، يصارع أشباح ماضيه. لم تكن في عيني ثورفين سوى صورة والده، وصورة النصل الذي لا يزال يطمح لغرزه في قلب الرجل الذي سلب منه كل شيء. في الخارج، كان الجيش يتحرك ككتلة واحدة من الحديد، والرياح التي تلفح الوجوه لم تكن سوى نذير بأن شيئاً ما قد انكسر في موازين القوى، وأن مصير أسكلاد وثورفين صار معلقاً بخيطٍ رفيع من التلاعب والمكائد السياسية.', '', 49, '2026-07-15 15:17:43.617', '2026-07-15 15:17:43.617');
INSERT INTO public.chapters VALUES ('c478385a-29f6-49c7-bdf6-ffe4f1eb2077', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 33: خيوط المصير في ساحة الوغى', '— --------------------------------------- انتصبت الأجساد المنهكة تحت وطأة المطر الخفيف الذي يلف قرية هيدباي. في وسط الساحة، وقف أسكلاد بنظراته التي تشبه نصل خنجر، يمسح بصريه في وجوه رجاله الذين نال منهم القتال والترقب. ثورفين كان قابعاً في زاوية مظلمة، قبضتاه تنزفان دماً جافاً، وعيناه لا تغادران محيا أسكلاد، يترقب إشارة، أو ربما ينتظر فرصة للثأر الذي تحول إلى روتين دموي. تقدم أحد الفايكنج بجسده الضخم المثقل بدروع صدئة، متمتماً بشكوى خافتة عن مؤن الطعام التي نفدت وعن طول الرحلة التي لا تنتهي. لم يلتفت أسكلاد نحوه، بل اكتفى بابتسامة صفراء لا تصل إلى عينيه وهو يقول بلهجة لاذعة: - هل قرقرة معدتك أعلى من صوت الطبول التي سمعناها في الأفق؟ إذا كنت تبحث عن وليمة، فعليك أن تأتي بدمائك لا بأنينك. خيم صمت مريب، وقطعت حدة كلام أسكلاد أي تفكير في الاعتراض. ثورفين لم يتحرك، لكن عضلات كتفيه انشدت بوضوح، فلقد كان في ذهنه مشهد والده ثورس، تلك الذكرى التي تطارده كشبح لا يرحم. في مكان ليس ببعيد، كان النبلاء يقفون خلف تحصيناتهم، يراقبون المشهد بتوتر؛ فأسكلاد لم يكن مجرد قرصان، بل كان لغزاً يتحرك ببراعة فوق رقعة شطرنج من الجثث. التفت أسكلاد نحو ثورفين، وبنبرة ساخرة قال: - يا ذا الشعر الأشعث، ألم تمل من كونك ظلاً يتبعني؟ أتحسب أن القوة في تكرار الغضب؟ ثورفين لم يجب، لكنه نهض ببطء، جاعلاً مفاصله تصر تحت ضغط حركته. لم يكن ثورفين بحاجة إلى الرد بالكلمات؛ ففي عالمهم، كانت النظرة أصدق من الخطب. رمق أسكلاد الفضاء المحيط به، حيث بدأت طلائع القوات المناوئة تظهر في الأفق كبقع سوداء تتسع في ضباب الصباح. أدرك الجميع أن لحظة الفصل قد اقتربت، وأن الهواء المشبع برائحة الطين المبلل سيمتزج قريباً برائحة الحديد. انحنى أسكلاد ليلتقط خوذته، وقال بصوت خافت لم يسمعه سوى القريبين منه: - لا تمُت قبل أن تفي بوعدك، ثورفين. استعد الفايكنج، وأطبقوا قبضاتهم على مقابض سيوفهم، بينما كان المطر يزداد غزارة، مغطياً على خطوات الموت القادم.', '', 33, '2026-07-15 15:17:40.581', '2026-07-15 15:17:40.581');
INSERT INTO public.chapters VALUES ('33af27de-0fe9-4c3b-b23b-8b53b3f38bfd', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 34: وليمة الرماد والأطماع', '— --------------------------------------- انزاح ثقل الخيمة الجلدية عن مدخلها، ليدخل أسكلاد متهادياً، عيناه تلمعان ببريق مراوغ تحت أضواء المشاعل الخافتة. التفت ثورفين نحوه، يده اليمنى تقبض على مقبض خنجره المعهود، مفاصل أصابعه بارزة كأنها حجارة صوان. لم يقل ثورفين شيئاً، لكن صدره كان يعلو ويهبط بوتيرة متسارعة، فكلما نظر إلى هذا الرجل تذكر النيران التي التهمت قريته والظلال التي سرقت طفولته. جلس أسكلاد على مقعده الخشبي، ألقى بعباءته جانباً، ثم سكب لنفسه كأساً من نبيذ رخيص. قال أسكلاد بصوت أجش ونبرة تقطر سخرية: ما زلت هنا يا فتى؟ ألا تمل من مراقبتي كأنني وحش في قفص؟ رمقه ثورفين بنظرة حادة، جسده مشدود كوتر قوس لن ينكسر، وأجاب بصوت أجش ومقتضب: سأقتلك. ليس اليوم، ولكن حين يأتي الوقت المناسب. ضحك أسكلاد، ضحكة خالية من الدفء، هزت كتفيه قليلاً، ثم أردف: الطموح صفة نبيلة، يا ثورفين، لكنها كسم الأفاعي، إن لم تكن حذراً، قتلت صاحبها قبل خصمه. كان الحوار في المعسكر يدور حول الغارات القادمة ووعود الثراء التي يوزعها أسكلاد كغنائم بصرية على رجاله، بينما كان ثورفين غارقاً في عالمه الخاص، حيث لا وجود إلا لصرير المعادن وأنين الموتى في ذاكرته. في الخارج، كانت أصوات المقاتلين تتعالى، خليط من صخب السكارى وخشخشة السيوف التي تُشحذ، ورائحة العرق الممتزجة بنتانة الجلود المتعفنة تملأ الأرجاء. اقترب أحد رجال أسكلاد، ضخم الجثة، ندوب وجهه تحكي قصص معارك منسية، وهمس شيئاً في أذن قائده. تغيرت ملامح أسكلاد للحظة، اختفت السخرية وحل محلها برود عسكري حاد. نهض أسكلاد، مسح شفتيه بظهر يده، ونظر إلى ثورفين نظرة عابرة لم تحمل تقديراً ولا شفقة، ثم أشار بيده نحو الباب: لدينا عمل. الخصم لا ينتظر المترددين. اندفع ثورفين خلفه، قدماه تطآن الأرض الموحلة بخفة المفترس، وعقله لا يرى سوى رقبة أسكلاد التي تتوسط الظلام، هدفاً وحيداً في عالم لا يعرف الرحمة. لم تكن هناك كلمات إضافية، فالمعركة التي تلوح في الأفق كانت اللغة الوحيدة التي يفهمها الجميع في ذلك المخيم المتهالك، حيث تنتهي الولائم غالباً بالدم، وتبدأ الطموحات بموت رجل آخر.', '', 34, '2026-07-15 15:17:40.79', '2026-07-15 15:17:40.79');
INSERT INTO public.chapters VALUES ('e607e3c5-b64e-453d-8ecd-0817278e9334', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 35: خيوط المصير القانية', '— --------------------------------------- توقف وقع أقدام ثورفين على الأرض الموحلة، كانت عيناه تتفحصان ملامح أسكلاد المتجهمة تحت ضوء خافت. لم يكن هناك صدى لأي صوت سوى طقطقة الجمر في الموقد القريب. قبض ثورفين على مقبض خنجره حتى ابيضت مفاصل أصابعه، واندفعت أنفاسه حارة ومتقطعة من منخريه. سخر أسكلاد وهو يلقي بنظرة عابرة على الغلام، ثم مسح نصل سيفه بقطعة قماش خشنة بحركة روتينية باردة. قال أسكلاد بصوت متهكم خالٍ من أي عاطفة: «أما زلت متمسكاً بهذا الهوس يا صغير؟ كلما ازدادت رغبتك في قتلي، أصبحت حركتك أكثر توقعاً. عد إلى رشادك، فالموت في هذا السن ليس بطولة، بل هو غباء فج». لم يكترث ثورفين للكلمات، بل تقدم خطوة أخرى، متجاهلاً الارتجاف الطفيف في عضلات فخذيه من شدة التوتر. ارتسمت على وجه أسكلاد ابتسامة مريبة وهو يضع سيفه جانباً، مستخفاً بخصمه كما يستخف الصياد بفرسية لا تملك سوى مخالب واهنة. في الخارج، كانت أصوات الجنود تتعالى بضحكات صاخبة ومشاجرات مبتذلة حول حصص الطعام، مما زاد من حدة الصمت المطبق داخل الغرفة. التفت أسكلاد نحو النافذة المطلة على معسكرهم المهترئ، وقال بنبرة مقتضبة تخلو من الشفقة: «الغد يحمل زحفاً نحو غينسبورو. إن أردت رأسي، فافعل ذلك في ساحة المعركة حيث يغرق الجميع في دمائهم، لا هنا حيث تعبث بكرامتك». تحرك ثورفين في مكانه، انقبض كتفاه استعداداً للهجوم، لكنه كبح جماح اندفاعه حين رأى أسكلاد يغادر المكان دون أن يلتفت خلفه. بقي الغلام وحيداً، يحدق في المساحة الفارغة التي كان يشغلها عدوه، بينما ظل خنجره يلمع في الضوء الخافت، شاهداً على غضب مكبوت لا يجد مخرجاً له سوى في دوامة من الصراع الذي لا ينتهي.', '', 35, '2026-07-15 15:17:40.978', '2026-07-15 15:17:40.978');
INSERT INTO public.chapters VALUES ('76e2ea11-99e9-4f06-9532-9c8fae192c16', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 36: خيوط العاصفة في غينسبورو', '— --------------------------------------- توقفت حركة العربة العسكرية فجأة تحت سماء ملبدة بغيوم رمادية ثقيلة، حيث كان الأمير كنوت يجلس متصلباً فوق مقعده، تحدق عيناه في الأفق الخالي من أي حياة. على مقربة منه، كان أسكلاد يراقب المشهد بابتسامة باهتة لا تصل إلى عينيه الحادتين، يمسح نصل سيفه بقطعة قماش خشنة بحركات رتيبة ومحسوبة. بادر أسكلاد بنبرة ساخرة تخترق صمت المكان: لا تقلق يا سمو الأمير، الجوع سيجعل من رجالنا وحوشاً لا تعرف الكلل في اقتفاء أثر الدنماركيين، فالمعدة الخاوية هي المحرك الأول للولاء في هذه الغابات القذرة. لم يلتفت كنوت، بل اكتفى بضم معطفه الصوفي إلى صدره، بينما اقترب منه ثورفين بخطوات ثقيلة وسريعة، ملامحه محتقنة بالغضب المكتوم. نبح ثورفين بصوت أجش: متى سننتهي من هذه المطاردة؟ لقد سئمت رائحة الطين والخيول، أريد رأسه فقط، أعطني الإذن وسأنهي هذا العبث. حدق أسكلاد في الفتى ببرود، ثم أشار بطرف سيفه نحو الغابة الممتدة أمامه: الصبر يا ثورفين، القتل فن لا يتقنه إلا من يعرف متى يرخي القبضة ومتى يطبقها، أما أنت فلا تزال تحرك سيفك بعاطفة صبي يغار على لعبته. انقبضت كف ثورفين على مقبض خنجره حتى ابيضت مفاصله، وازداد تنفسه حدة وتواتراً، لكنه لم يجد رداً غير صمت الغابة المطبق. تحركت فرقة من الجنود ببطء بين الأشجار، يجرون خلفهم خيولاً منهكة، بينما كان أسكلاد يتأمل تحركاتهم بتركيز، كمن يقرأ خريطة من الضعف البشري. اقترب أسكلاد من أذن الأمير وقال بصوت خافت: هؤلاء الرجال هم أدواتنا، فإذا انكسرت الأداة، كان على الصانع أن يبحث عن غيرها، أو أن يبدأ في نحت قدره بيده. نظر كنوت إليه بنظرة خالية من التعبير، وكأن الكلام لا يعنيه، بينما استدار ثورفين نحو الطريق المظلم، تاركاً غباره خلفه، منتظراً إشارة الانطلاق التي لا تأتي، مدركاً في قرارة نفسه أن أسكلاد لا يقوده إلى نصر، بل إلى متاهة لا تخرج منها إلا بخراب أكبر.', '', 36, '2026-07-15 15:17:41.171', '2026-07-15 15:17:41.171');
INSERT INTO public.chapters VALUES ('b5d2b491-86d7-4152-833f-985d77dbd3ba', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 37: خيوط القدر المتمزقة', '— --------------------------------------- انتصبت خيام المعسكر كأنها ندوب غائرة على وجه الأرض الجرداء. لم يغادر ثورفين مكانه منذ ساعات، يراقب حركات أسكلاد المريبة وسط الميدان. كانت عينا الصبي تلاحقان كل حركة للرجل الذي سلب منه طفولته، تتأرجحان بين الرغبة في الانقضاض وبين عجز القيد النفسي الذي يفرضه عليه قانون المبارزة. اقترب أسكلاد، كان يمشي بخفة القط المفترس، يمسح نصل سيفه بقطعة قماش خشنة. توقف أمام ثورفين، ارتسمت على شفتيه ابتسامة ساخرة لم تصل إلى عينيه الباردتين كالثلج. قال أسكلاد بنبرة هادئة تشوبها السخرية: ألم تمل بعد من هذه النظرات القاتلة يا صبي؟ إنك لا تزداد إلا وهماً. زم ثورفين شفتيه، انقبضت كفاه حتى ابيضت مفاصله، لم يخرج منه صوت، بل اكتفى بتركيز حدقتيه على رقبة أسكلاد، وكأنه يغرز خنجراً خفياً فيها. تابع أسكلاد سيره متجاهلاً حدة الصمت، تاركاً خلفه اضطراباً في أنفاس الصبي. في زاوية أخرى، كان الجنود يتبادلون أحاديث خشنة حول الغنائم المنتظرة، أصواتهم المتداخلة تشبه صرير المعادن. كان هناك توتر ملموس يطفو في الأجواء، ليس توتر الخوف، بل توتر الترقب لقرار سيقلب موازين القوة. التفت ثورفين نحو الأفق، حيث تبدأ السماء بالامتزاج مع تضاريس الأرض القاسية. لم يكن يبحث عن إجابات في السماء، بل كان يستحضر ملامح والده ثورس، تلك الهيبة التي لم يستطع الزمن محوها من ذاكرته. همس ثورفين لنفسه بصوت مبحوح: سأقتلك، ليس اليوم، لكنني سأفعل. لم تكن الكلمات وعيداً بقدر ما كانت عقيدة يقتات عليها ليتحمل قسوة العيش تحت إمرة قاتل أبيه. في تلك اللحظة، تعالت أصوات القادة في الخيمة الرئيسية، نبرات حادة ونقاشات محمومة حول التحركات القادمة. دخل أحد المساعدين يهرول، ووجهه يشي بخبر طارئ. انتبه أسكلاد للضجيج، وتلاشت ابتسامته الساخرة ليحل محلها قناع الجدية الذي لا يرتديه إلا في لحظات الحسم. ألقى نظرة سريعة على ثورفين، وكأنه يقيس مدى استعداده لمهزلة جديدة، ثم مضى بخطوات واثقة نحو قلب العاصفة القادمة. بقي ثورفين وحيداً، يراقب غبار المعسكر المتطاير، بينما كان عقله ينسج خيوط الانتقام في صمت مطبق، بعيداً عن ضوضاء الرجال وادعاءات القادة.', '', 37, '2026-07-15 15:17:41.346', '2026-07-15 15:17:41.346');
INSERT INTO public.chapters VALUES ('27255484-1b5b-4137-9267-57cfca8208c9', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 38: خيوط الخديعة المنسوجة', '— --------------------------------------- توقف أسكلاد عن تنظيف نصل سيفه، ورفع رأسه ببطء نحو ثورفين الذي كان يقف بجمود كتمثال من صخر. ظلال الخيمة تتراقص على وجه القائد الماكر، بينما كان ثورفين يضغط على قبضة خنجره حتى ابيضت مفاصل أصابعه. لم يكن ثورفين ينتظر، كان يغلي بصمت، وعيناه لا تغادران محيا أسكلاد الذي أطلق ضحكة قصيرة جافة، خالية من أي دفيء. قال أسكلاد بنبرة متهكمة وهو يعيد السيف إلى غمده: لا تستهلك طاقتك في التحديق، يا فتى. الغضب لا يقطع الرقاب، بل العقل. رمقه ثورفين بنظرة حادة، وأجاب بصوت متهدج بالكاد يخرج من بين أسنانه المطبقة: أريد رأساً. اليوم. لا يهم من، طالما أنه يمنحني حق المبارزة معك. هز أسكلاد كتفيه بلا مبالاة، ملقياً بنظره نحو الخريطة الممدودة أمامه على الطاولة الخشبية الخشنة. إن كنت مستعجلاً على الموت، فلا داعي لإضاعة وقتي في تدريبك. ألقى نظرة خاطفة نحو الخارج حيث يمتزج صخب الجنود بوقع خطواتهم على الأرض الموحلة، ثم أضاف بسخرية: هناك في القافلة المتقدمة… ستجد هدفك. خذ خنجرك وافعل ما تشاء، لكن لا تترك جثة خلفك تجذب الأنظار. استدار ثورفين دون كلمة واحدة، تحركت عضلات ظهره بقوة تحت قميصه البالي، وغادر الخيمة بخطوات واسعة وسريعة. راقبه أسكلاد وهو يبتعد، ثم عاد ليشعل غليونه، وتصاعد دخان أبيض في الهواء الساكن. في الخارج، كان الليل يلف المكان بعباءته، ومع ذلك، لم يكن ثورفين يشعر ببرودة الهواء. كان تركيزه الوحيد منصبًا على الوجهة التي حددها له خصمه. وصل إلى أطراف المخيم، حيث كانت النيران تخبو وتصدر طقطقة متقطعة. لم يتردد، تسلل بين الظلال بخفة قط بري، متجنباً مسارات الحراس، وعيناه تمسحان المكان بحثاً عن أول ضحية تقع تحت يده ليكون جسراً نحو غايته. كان يعلم في قرارة نفسه أن أسكلاد يتلاعب به، يسخر من دافعه، يدفعه للقتل ككلب ضال، لكنه لم يكترث. الانزلاق في دماء الآخرين كان الثمن الوحيد الذي يعرف كيف يدفعه ليرتقي خطوة واحدة نحو الانتقام الذي يمزق أحشاءه.', '', 38, '2026-07-15 15:17:41.524', '2026-07-15 15:17:41.524');
INSERT INTO public.chapters VALUES ('34fdd798-b1cc-4064-aba5-fcb31d8d6358', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 39: نهاية المحارب', '— --------------------------------------- تصلبت ملامح أسكلاد وهو يراقب ثورفين الذي توقف في مكانه، نظراته المثبتة على الأرض كانت تشي بانكسار داخلي أعمق من أي جرح جسدي. حولهما، كانت بقايا المعركة تنضح برائحة الدم والرماد. استدار أسكلاد ببطء، ممسكاً بساعده الذي تلقى ضربة غير مباشرة، وقال بنبرة متهكمة يغلفها الفتور: لقد انتهت اللعبة يا فتى. لم يعد ثورفين يتحرك، فقدت يداه قبضتيهما على الخنجرين، وسقطت الأسلحة على الأرض الرطبة بصوت معدني مكتوم. ساد صمت مطبق إلا من أنفاس الجنود المتسارعة في الخلفية. تقدم أسكلاد نحوه، متجاهلاً الآلام في جسده، وانحنى قليلاً ليواجه وجه ثورفين الشاحب. قال أسكلاد بصوت منخفض لا يسمعه إلا هو: ليس من شيم المحاربين البكاء بعد الهزيمة، إذا كنت تريد رأسي، فعد للتدريب، أو ابحث عن غاية تستحق الموت من أجلها. لم يجب ثورفين، بل انقبضت عضلات فكه وتجمدت عيناه في فراغ بعيد. تدخل أحد الرجال، وهو يمسح نصل سيفه بخرقة متسخة، متسائلاً بصوت أجش: ماذا سنفعل بهذا الجرو الآن؟ أطلق أسكلاد ضحكة خافتة ومقتضبة، ثم أشار بيده نحو السفن الراسية في الأفق، حيث كان الدخان يتصاعد كأعمدة سوداء تلتهم السماء. نحن نغادر. إذا أراد اللحاق بنا، فليحاول البقاء حياً حتى ذلك الحين. تحركت المجموعة ببطء، مخلفين وراءهم ساحة شهدت ذروة صراع ثورفين، بينما ظل هو واقفاً هناك، جسده النحيل يرتجف انقباضاً تحت عباءته المهترئة. لم تكن هناك كلمات وداع، ولا وعود. فقط صوت تكسر الجليد تحت أقدام المنسحبين، ووحشة المكان التي بدأت تلف ثورفين، تاركة إياه وحيداً مع ذكرى والده التي تلاشت في ضباب النسيان.', '', 39, '2026-07-15 15:17:41.709', '2026-07-15 15:17:41.709');
INSERT INTO public.chapters VALUES ('ced178ee-8fe6-4131-b1a3-abac81598b86', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 40: خيوط المصير في مأدبة الظلال', '— --------------------------------------- انغرزت خنجر ثورفين في الطاولة الخشبية الخشنة، تاركةً ثقباً غائراً في قلب الألياف الصلبة. لم يرمش أسكلاد، بل استمر في تقليب قطعة اللحم بحديدة، وعيناه تلاحقان حركة ثورفين المتشنجة. قال أسكلاد بصوتٍ هادئ يقطر تهكماً: «أنت تفتقر إلى الصبر يا فتى، الغضب يغطي على عينيك مثل ضباب الشتاء». انقبضت كف ثورفين على مقبض خنجره حتى ابيضت مفاصل أصابعه، وزم شفتيه بقوة كأنما يمنع صرخة مكتومة من الانفلات. التفت ثورفين بعنف، مخلفاً وراءه صدى خطواته على الأرضية الخشبية المتهالكة، وخرج إلى ساحة المخيم حيث لا يزال الدخان يتصاعد من بقايا النيران. لم تكن هناك كلمات تعبر عما يغلي في صدره؛ فقط زفرات قصيرة ومتقطعة. اقترب منه بيورن، ملقياً بثقله على كتفه بقسوة، وقهقه بصوت خشن يشبه احتكاك الصخور: «اتركه وشأنه يا صبي، القائد لا يضيع وقته مع الصغار، عد إلى رفاقك واصقل سيفك بدلاً من التحديق في الفراغ». لم يعره ثورفين التفاتة، بل اتجه نحو سياج المخيم، حيث كانت الرياح تعبث بملابسه الممزقة. في الزاوية المظلمة، كان أسكلاد يراقب من النافذة، يرتشف نبيذه ببطء، يفكر في هذا المراهق الذي يحمل سيفاً في قلبه أكثر مما يحمله في يده. لم يكن ثورفين يبحث عن النصر، بل عن لحظة استرداد لشيء ضاع في ذكريات الطفولة البعيدة. في تلك الأثناء، كان الجنود يتجادلون حول الغنائم، وأصوات ضحكاتهم الفجة تتصادم مع صمت الليل الجليدي. دخل ثورفين خيمته المتواضعة، وارتمى على فراشه الجاف، لكن عينيه ظلتا مفتوحتين، ترصدان شقوق السقف الخشبي، في انتظار فجرٍ لا يحمل سوى مزيد من الدماء والوعود الزائفة بالانتقام.', '', 40, '2026-07-15 15:17:41.889', '2026-07-15 15:17:41.889');
INSERT INTO public.chapters VALUES ('5078e3cd-df57-4688-99d2-75fc98997ebd', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 41: خيوط الظل والمكر', '— --------------------------------------- توقف أسكلاد عن تنظيف شفرة سيفه، ورفع رأسه ببطء نحو الأفق حيث تلاشت آخر بقايا وهج الشمس خلف التلال الرمادية. لم تكن عيناه تتابعان المشهد، بل كانتا تحصيان احتمالات التحرك القادم لجيش الدنماركيين الذي بات يطبق الحصار حول مخيمهم الصغير. بجانبه، كان ثورفين يجلس على صخرة متآكلة، يحدق في فراغ الأرض، أصابعه تفرك مقبض خنجره بعنف غير واعٍ، وكأنما يحاول استمداد الدفء من المعدن البارد. صمت ثورفين لم يكن هدوءاً، بل كان ضجيجاً مكتوماً من الحنق والترقب. انحنى أسكلاد نحو النار الهامدة، صوته كان هادئاً، تقطر منه السخرية المعهودة وهو يخاطب رجاله: ''أي ذكاء أحمق دفعنا للبقاء في هذا الوادي؟ نحن كالفئران في مصيدة يمسك طرفها كُنيت''. التفت ثورفين نحوه فجأة، برقت عيناه بحدة ذئب جريح، وقال بلهجة جافة ومقتضبة: ''لا يهمني الحصار، سأقتلك أمامهم جميعاً''. ضحك أسكلاد، ضحكة خفيضة لم تصل إلى عينيه الباردتين، وألقى نظرة فاحصة على الصبي، ثم قال بتهكم: ''سيكون موتي متعة للجميع يا ثورفين، لكن موتك أنت الآن سيكون خسارة لفن التكتيك الذي أحتاجه غداً''. لم يرد الفتى، بل عض على شفته السفلى حتى ظهر أثر الدم، ونهض بمرونة مفترسة مبتعداً نحو الظلام. راقبه أسكلاد وهو يختفي بين الخيام، ثم عاد لتركيز نظره على الخريطة المرسومة على الأرض. كان يدرك أن الحقيقة التي يواجهها ليست في جيش الخصم، بل في هذا الولد الذي يرفض أن ينمو، والذي لا يرى من العالم سوى نصل خنجره. ارتفع صوت الضجيج في المعسكر؛ صيحات الجنود وهم يستعدون للمواجهة، وقع أقدامهم الثقيلة على الأرض الطينية، ورنين الدروع الذي يمزق سكون الليل. لم يلتفت أسكلاد، كان يعلم أن الفجر سيحمل معه ثمن البقاء، وأن الحيلة وحدها هي من ستبقي الرؤوس فوق الأعناق. في زاوية أخرى، وقف القادة يتناقشون بنبرات متوترة، كلماتهم المبتورة حول خطوط الدفاع ومواقع القوس والنشاب تنم عن خوف لم يعترفوا به صراحة. أما ثورفين، فقد كان يراقب من وراء خيمة مهترئة، يترقب اللحظة التي سيفقد فيها الجميع حذرهم، اللحظة التي سيتحول فيها الفوضى إلى فرصة، فرصة لا يراها إلا هو.', '', 41, '2026-07-15 15:17:42.071', '2026-07-15 15:17:42.071');
INSERT INTO public.chapters VALUES ('9d4d5591-7530-4ac4-9c14-d8da7c568b1e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 42: خيوط القدر المتمزقة', '— --------------------------------------- توقف ثورفين فجأة، كانت أنفاسه المتقطعة هي الصوت الوحيد الذي يخرق سكون اللحظة. حدق في جثة أسكلاد الملقاة بلا حراك، الدماء القانية تغطي يديه، ولم تعد تلك النيران التي كانت تحرق صدره بالانتقام تجد وقوداً. سقط خنجره من يده ليصطدم بالحجر البارد برنة معدنية خافتة. صرخ ثورفين، صرخة بدت كأنها ممزقة من أعماق روحه، لم تكن غضباً، بل كانت إعلاناً بضياع الغاية التي عاش من أجلها لسنوات. وقف كانوت وسط الحطام، عباءته الملكية ملوثة بالتراب، وعيناه لا تحملان أي بريق، سوى برود حسابي حاد. نظر كانوت إلى ثورفين الذي كان لا يزال يرتجف، ثم التفت نحو جنوده الذين تراجعوا بخطوات مضطربة. قال كانوت بصوتٍ رخيم ومستقر: لقد انتهى عهده. لم يجب ثورفين، بل انكب على جسد أسكلاد، يضغط بيديه على الجرح في محاولة عبثية لإيقاف نزيفٍ قد توقف بالفعل. اقترب الحراس، وضعوا أيديهم على مقابض سيوفهم، لكن كانوت أشار إليهم بالتوقف. اقترب الملك الشاب من ثورفين، انحنى حتى أصبح بمستوى وجهه، وهمس بنبرة خالية من أي شفقة: أنت الآن لا تملك شيئاً يا ثورفين. لا والد، لا عدو، ولا هدف. ما الذي ستفعله حين تجردك الحياة من كل شيء؟ انتفض ثورفين، وارتدت عيناه نظرة ضياع مريرة، دفع كانوت بعيداً ونهض متراجعاً إلى الوراء، كل خطوة يخطوها كانت تبعده أكثر عن ساحة المعركة، عن العرش، وعن الهوية التي نحتها لنفسه طوال سنين. غادر ثورفين ساحة القصر، تاركاً خلفه التاريخ يكتب فصلاً جديداً بدمه، بينما كانت الرياح التي بدأت تهب تحمل معها أصداء معارك لم تعد تعنيه في شيء.', '', 42, '2026-07-15 15:17:42.266', '2026-07-15 15:17:42.266');
INSERT INTO public.chapters VALUES ('7ed6bafe-70e3-493b-857f-346ce252aa00', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 43: وليمة الذئب في قصر غينزبورو', '— --------------------------------------- توقفت حركة العربات عند بوابة قصر غينزبورو، وانحسر غبار الطريق عن موكبٍ يبدو غريباً على هذه الديار. أسكلاد، بملابسه التي لا تشي بمركزه المتواضع، ترجل عن جواده بهدوء، بينما كانت عيناه تمسحان السور الحجري بعين الصياد الذي يقيم فريسته. خلفه، ثورفين، الصبي ذو الملامح المتصلبة كحجر الصوان، لم يلتفت يميناً أو يساراً؛ كان يده في قبضتها الدائمة على مقبض خنجره، وكأن جسده وترٌ مشدود ينتظر لمسةً ليعزف لحن الموت. دخلوا القاعة الكبرى، حيث تفوح رائحة الخنزير المشوي والشراب الرخيص، ومزجت أصوات ضحكات الجنود السكارى بصخب أواني المعدن. لم يكترث أسكلاد لعيون الرجال التي رمقتهم بحذر، بل تقدم بخطوات واثقة حتى بلغ مائدة الملك سوين. كان الملك يجلس بصمتٍ مريب، وجهه شاحب يخفي خلفه دهاليز من التخطيط السياسي الذي لا يرحم. انحنى أسكلاد في حركة محسوبة، نبرته التي مزجت التبجيل بالتهكم الخفي قطعت همس الجالسين: سيدي الملك، ها أنا ذا أضع بين يديك ما وعدتك به. ارتفع حاجب أحد القادة الجالسين، وتفوه بصوت خشن: وهل يظن هذا القرصان أن قاعة الملك تصلح لبيع بضائعه؟ صمت أسكلاد للحظة، ابتسامة باردة ارتسمت على شفتيه وهو ينظر إلى القائد، ثم التفت إلى الملك متجاهلاً الآخر تماماً. ثورفين، من زاويته المظلمة، كان يراقب الجميع. لم يكن مهتماً بالسياسة أو الذهب، بل كان يبحث عن ثغرة في وقار أسكلاد، عن لحظة ضعف يمكنه استغلالها. لاحظ ثورفين كيف ضاقت عينا الملك حين ذكر أسكلاد اسم الأمير كانوت، وكيف توترت عضلات رقبة الحراس المحيطين بالعرش. حين عرض أسكلاد تفاصيل خطته لاستدراج الأمير، لم تكن كلماته مجرد سرد، بل كانت رقصة سياسية بارعة، يبتلع فيها الحضور طُعمه دون أن يدركوا. رمى أسكلاد قطعة نقدية على الطاولة، فصوت رنينها المعدني الحاد في سكون القاعة كان كإعلان عن بدء لعبة كبرى لن يخرج منها الجميع أحياء. خرج الجميع من القاعة تاركين خلفهم خلفية من التساؤلات، وبينما كانت الرياح تضرب نوافذ القصر، نظر أسكلاد إلى ثورفين الذي كان يمشي بظله: استعد يا صبي، فالأيام القادمة لن تكون سوى سلسلة من الخيانات التي سيتقنها الضعفاء، أما نحن، فسنكون السكاكين التي تقطع حبالها.', '', 43, '2026-07-15 15:17:42.442', '2026-07-15 15:17:42.442');
INSERT INTO public.chapters VALUES ('2c40738d-6ff9-4af1-9326-0e5a8de546ca', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 44: وليمة الدم والندم', '— --------------------------------------- انغرس نصل الخنجر في الطاولة الخشبية بقوة، تاركاً أثراً غائراً تكسوه شظايا الخشب المتناثرة. حدق ثورفين في أسكلاد، كانت يداه ترتجفان بحدة محبوسة، وعروق ساعديه تبرز كأوتار مشدودة لآلة تعزف لحناً جنائزياً. صمت القاعة كان ثقيلاً، مشبعاً برائحة اللحم المشوي والنبيذ الرخيص الذي يختلط برائحة العرق والصدأ. سحب أسكلاد يده بهدوء، ممسكاً بكأس خمر ملطخة بحافة معدنية، ثم ابتسم ابتسامة مقتضبة لم تصل إلى عينيه اللتين تشبهان لون البحر قبل العاصفة. قال أسكلاد بصوته الهادئ الذي يحمل نبرة تهكمية: «ما زلتَ تظن أن الغضب وقودٌ كافٍ يا صبي، الغضب أعمى، يجعلك تقفز في فوهة البركان ظناً منك أنك تبرد الحمم». انتفض ثورفين من مكانه، صوته خرج كهدير مكتوم: «أنت لا تملك الحق في الكلام عن الوقود، أنت من أشعل النار في حياتي». لم يهتز أسكلاد، بل أخذ رشفة من كأسه، وأشار بيده إلى الجنود السكارى من حولهم الذين تعالت ضحكاتهم الخشنة في الزاوية. قال أسكلاد بنبرة باردة تقطر براغماتية: «هؤلاء القتلة الذين تراهم، لا يكترثون لمبادئك أو انتقامك. إنهم ينتظرون الغنيمة القادمة، يبحثون عن الدم الذي يسيل ليحوله إلى عملات معدنية. كن مثلهم، أو واصل الموت ببطء في هذه الزاوية». نظر ثورفين حوله؛ وجوه الرجال بدت كأقنعة من طين وجلد، يلتهمون طعامهم بشراهة حيوانية، لا شيء في عيونهم يوحي بأي نبل. قبض ثورفين على قبضة خنجره مرة أخرى حتى ابيضت مفاصل أصابعه. تذكر للحظة وجوه الموتى، صوت والده الراحل الذي كان يردد أن المحارب الحقيقي لا يحتاج لسيف، لكن في هذه القاعة، كان الصوت الوحيد الذي يعلو هو صوت شحذ النصال وقرع الكؤوس. انسحب ثورفين نحو الظلال، بعيداً عن ضوء المشاعل المتراقص، بينما استمر أسكلاد في مراقبته بصمت، ماسحاً دماءً طفيفة عن ثوبه، وكأن كل هذه الدراما ليست سوى نكتة سمجة في ليل طويل لا ينتهي.', '', 44, '2026-07-15 15:17:42.631', '2026-07-15 15:17:42.631');
INSERT INTO public.chapters VALUES ('261420b5-2f90-45ea-bdc8-a3a6d0127679', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 45: حين يغدو التاج قيداً', '— --------------------------------------- توقف المطر عن الهطول، لكن الأرض بقيت وحلاً يلتصق بالأحذية كخطيئة لا تمحى. وقف الأمير كانوت وسط خيمته، يحدق في انعكاس وجهه على نصل سيفه الصقيل. لم يكن يرى الأمير الذي عرفه الجند، بل رأى شيئاً آخر، كياناً وُلد من رحم المعاناة والخذلان. دخل أسكلاد، بخطواته التي لا تكاد تسمع، يتلاعب بخنجره في حركة دائرية باردة. نظر إلى كانوت بنظرة فاحصة، لم تكن نظرة خضوع بل نظرة مقامر يراقب ورقة رابحة بدأت تتحرك من تلقاء نفسها. قال أسكلاد بصوت أجش وخالٍ من التكلف: الجوع لا ينتظر يا صاحب السمو، والرجال بدأوا يتململون في خيامهم، فهل ننتظر موتهم أم نأخذهم إلى حتفهم بأيدينا؟ استدار كانوت ببطء، لم تكن حركاته توحي بالارتباك الذي كان يغلفه سابقاً. عقد يديه خلف ظهره وقال بصوت هادئ، ثقيل بوطأة القرار: لن نموت هنا، ولن نموت كما يشتهي الملك سوين. سنحول جيش الفارين هذا إلى قوة لا يملك الملك إلا أن يخشاها. ابتسم أسكلاد، ابتسامة لم تصل إلى عينيه الماكرتين، وقهقه بخفوت: إذاً أنت تقرر التحول إلى وحش لتواجه الوحوش، أليس كذلك؟ صمت كانوت، واتسعت حدقتا عينيه وهو يثبت نظره على أسكلاد، دون أن ترمشا. في الزاوية المظلمة من الخيمة، كان ثورفين يراقب الحوار بصمت مطبق، أصابعه تقبض على مقبض خنجره بقوة حتى ابيضت مفاصله. لم يكن يكترث بتفاصيل السياسة التي يتداولونها، فبالنسبة له، كان أسكلاد يظل الهدف الذي لن يغيب عن بصره. اقترب أسكلاد من ثورفين، وربت على كتفه بقسوة متعمدة، ثم همس له: لا تكن غبياً يا فتى، لا تدع غضبك يسبق سيفك، فالمعركة القادمة ستحتاج إلى ذكاء القتلة لا إلى صراخ الأطفال. أزاح ثورفين يده بعنف، وارتدت خطواته إلى الخلف ليصبح في وضعية الاستعداد. رمقه بحدة، وعروق رقبته بارزة، لكنه لم ينطق، فالحروف في حضرة أسكلاد كانت كالسياط التي تنقلب على صاحبها. تحرك كانوت نحو مدخل الخيمة، فُتح الستار الجلدي، ليتسرب ضوء النهار الباهت ويضيء وجه الأمير الذي تبدلت ملامحه تماماً، من الوداعة المسكينة إلى برودة الحاكم الذي لا يرحم. نظر إلى جيشه المنتشر في الأفق، حيث الدخان يتصاعد من النيران الخاملة، وقال بصوت حازم قاطع لكل جدل: جهزوا الخيول. اليوم نبدأ في بناء مملكة لن يجرؤ أبي على الاقتراب منها، أو سنحرق هذا العالم ونرتاح من ضجيجه.', '', 45, '2026-07-15 15:17:42.843', '2026-07-15 15:17:42.843');
INSERT INTO public.chapters VALUES ('ec280674-1a60-404b-83f6-258a6d80ac1c', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 46: رصانة الحافة', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في وحل المخيم العسكري، بينما كانت عيناه، بحدتهما المعهودة، لا تفارقان وجه أسكلاد. لم يكن هناك صراخ، بل ثقل غير مرئي يضغط على الصدور. أسكلاد، بابتسامته التي لا تصل أبداً إلى عينيه، كان يعبث بخنجره، يمرره بين أصابعه برشاقة توحي بالاستهتار. قال أسكلاد بصوته المتهكم الذي يمزق سكون المكان: ''ما زلت تصر على النزال يا فتى؟ إن إصرارك يثير إعجابي بقدر ما يثير اشمئزازي''. لم يرد ثورفين. انقبضت عضلات فكه السفلي، وبرزت عروق يده التي تقبض على مقبض خنجره حتى تحول لون مفاصله إلى البياض. تذكر ثورفين، في ومضة سريعة، كلمات والده عن طبيعة القوة، لكن تلك الحكمة تلاشت تحت وطأة الغضب المشتعل في أحشائه. دفع ثورفين جسده إلى الأمام بحركة مباغتة. اندفع كالسهم، محاولاً استغلال الفجوة في دفاع أسكلاد. بلمحة عين، تحرك أسكلاد ببرود، متفادياً الضربة بجسده، ليغرس مرفقه في كتف ثورفين، دافعاً إياه نحو الطين. ارتطم وجه الصبي بالأرض، فذاق طعم التراب الممزوج بمرارة الهزيمة. وقف أسكلاد فوقه، ناظراً إلى الأعلى نحو السماء الرمادية. قال بلهجة باردة كالمعدن: ''القوة ليست في الغضب، يا ثورفين. الغضب أداة الضعفاء الذين لا يملكون صبراً لانتظار اللحظة المناسبة. أنت لا تحاربني، أنت تحارب ظلك''. تنهد أسكلاد، ثم أدار ظهره تاركاً ثورفين في مكانه، يلهث بشدة، بينما كان رجاله يراقبون المشهد بصمت مريب، دون أن يجرؤ أحدهم على التدخل. لم يمتلك ثورفين القدرة على النهوض فوراً، بل بقي مستنداً على كفيه، ينظر إلى أصابع يده الملطخة بالوحل، يشعر ببرودة الحديد في قلبه أكثر من برودة الجو من حوله.', '', 46, '2026-07-15 15:17:43.028', '2026-07-15 15:17:43.028');
INSERT INTO public.chapters VALUES ('057c6f0a-8948-433e-b4fc-150eb49b4c44', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 47: سوطُ الغدر وسكينةُ النهاية', '— --------------------------------------- تصلبت ملامح أسكلاد وهو يراقب الأمير كنوت ينهض ببطء، لم تكن حركته تلك التي اعتادها في الفتى المرتجف، بل كانت وقفةً استمدت صلابتها من هدوءٍ غريب غلف المكان. بادر أسكلاد بنبرةٍ متهكمة لم تخفِ حدة تركيزه: أظنك وجدت شيئاً في قاعِ بؤسك يا سمو الأمير. لم يلتفت كنوت، بل ثبت بصره على الأفق الرمادي، وأجاب بصوتٍ خافتٍ لكنه يحمل نبرةً معدنية حادة: لم أجد شيئاً، لقد فقدت كل شيء. اقترب ثورفين من المشهد، كانت قبضتاه مضمومتين لدرجة ابيضاض مفاصل أصابعه، وعيناه تلاحقان أسكلاد وكأنه حيوانٌ مفترس يترقب لحظة وثوب، زفر ثورفين بضيقٍ مكتوم وهو يزمجر: كف عن هذا الهراء… متى ستواجهني؟ هل تظن أن الأمير سيحمي رأسك للأبد؟ تبادل أسكلاد نظرة جانبية باردة مع ثورفين، ثم أخرج سيفه ببطء، وصوته يقطر سخرية: يا صغيري الغاضب، ما زلت تظن أن العالم يدور حول نزالك الصغير؟ انظر حولك، لقد انتهت حقبة القراصنة التي تعرفها. ضحك أسكلاد ضحكة قصيرة لا تصل إلى عينيه، وأضاف موجهاً حديثه للجميع: الحاكم الحقيقي لا يحتاج لسيفه ليقتل، بل يحتاج لأرضٍ خصبة ليغرس فيها بذور الدمار. كان الصمت الذي أعقب كلماته ثقيلاً، مشحوناً برائحة الطين المبلل وتوتر الجنود الذين تراجعوا خطواتٍ للوراء. وضع كنوت يده على مقبض سيفه، لم يكن هناك ارتجاف، فقط حركة ميكانيكية دقيقة، وقال ببرودٍ جماد: سأبني عالماً لا مكان فيه لأسالك. اتسعت بؤبؤة عين أسكلاد للحظة، ربما كانت صدمةً أو ربما إعجاباً خفياً بجرأة الفتى، لكنه استعاد قناعه البارد سريعاً، ملوحاً بسيفه في الهواء بحركةٍ دائرية احترافية، وهو يهمس لنفسه: إذاً، فليكن العرض الأخير.', '', 47, '2026-07-15 15:17:43.243', '2026-07-15 15:17:43.243');
INSERT INTO public.chapters VALUES ('1b198673-2eb1-4435-be75-8db191aa38e6', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 48: سديم المأزق الأخير', '— --------------------------------------- سحب الدخان الرمادي الكثيف كانت تلتف حول أسوار قلعة غينزبورغ مثل أفعى خانقة، بينما كانت صرخات الجنود المذعورين تتلاشى تحت وطأة نيران المنجنيق. وقف أسكلاد في زاوية الحصن المحطم، يمسح الدم عن نصله ببرود، وعيناه الزرقاوان تراقبان الفوضى بنظرة تقييمية لا تعترف بالشفقة. بجانبه، كان ثورفين يزفر أنفاساً متلاحقة، قبضته على خنجريه تضغط بقوة حتى ابيضت مفاصل أصابعه، وعيناه لا تحيدان عن الأفق حيث تتجمع القوات الدنماركية. «أتحسب أننا سنخرج من هذا الجحيم بجلودنا يا ثورفين؟» قال أسكلاد بصوتٍ هادئ، مشوب بنبرة ساخرة لم تخفِ حدة الواقع. لم يجب ثورفين، بل اكتفى بمسح العرق الممزوج بالرماد عن وجهه، مشدداً من وقفته القتالية. كانت رائحة الاحتراق واللحم المتفحم تملأ الأجواء، بينما كانت الجثث تتراكم عند البوابات المنهارة. اقترب أحد المرتزقة من أسكلاد متعثراً، أنفاسه متقطعة: «سيدي، الحرس الملكي قد اخترقوا الجناح الشرقي، لا طاقة لنا بالمواجهة!». ضيق أسكلاد عينيه، ثم ضحك ضحكة قصيرة خالية من أي مرح: «إذن، حان وقت الرحيل، فالبقاء في حفرة تحترق ليس من شيم العقلاء». في تلك اللحظة، تحرك ثورفين كالسهم المنطلق نحو الفجوة في الجدار، متجاهلاً نداء أسكلاد، دافعه الوحيد هو ذلك الحقد الأعمى الذي يغلي في صدره ضد قائد المرتزقة. كان المشهد يختزل حتمية الفناء؛ فالقلعة التي صمدت لقرون لم تكن سوى كومة من الحجارة المتهاوية أمام قسوة الغزاة. نظر أسكلاد إلى الفتى المندفع، وهز رأسه بأسف مصطنع قبل أن يتبع خطواته، مدركاً أن القدر قد رسم خطوط نهايتهم في هذا الجحيم المنسي.', '', 48, '2026-07-15 15:17:43.427', '2026-07-15 15:17:43.427');
INSERT INTO public.chapters VALUES ('c1f50d2b-9389-4d9d-a042-75b0cde91f2c', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 50: سقوط القناع في ساحة غينزبورو', '— --------------------------------------- تصلب جسد أسكلاد، لا ارتجاف، بل سكون مباغت يشبه سكون المفترس قبل الانقضاض. كان الأمير كانوت جالساً على العرش المرتجل، وجوه الجنود من حوله تتأرجح بين الترقب والذهول. رمى أسكلاد بسيفه أرضاً، صليل المعدن على الأرضية الخشبية كان الصوت الوحيد الذي مزق صمت القاعة. التفت أسكلاد نحو الأمير، ونظراته تخترق برود كانوت المعهود. قال أسكلاد بصوت منخفض، مشحون بتهكم مريب: لقد انتهت اللعبة يا سمو الأمير. لم يطلب السماح، ولم يظهر ندماً، بل وقف بشموخ المحارب الذي أدرك أن أوراقه قد احترقت. كان ثورفين يراقب من الظلال، قبضتاه منقبضتان لدرجة أن مفاصل أصابعه أبيضت، وعيناه لا تفارقان وجه أسكلاد. كانت هذه اللحظة التي انتظرها ثورفين لسنوات، لكن عندما حانت، لم يجد في نفسه تلك النشوة التي تخيلها، بل وجد فراغاً بارداً. سحب أسكلاد خنجره، ليس ليطعن أحداً، بل ليشير به إلى الجند المذهولين، وصرخ بصوت أجش ومتهكم: ألا تريدون رؤية كيف يموت ملك؟ في تلك اللحظة، لم يعد أسكلاد ذلك القائد الماكر، بل تحول إلى شيء آخر، شخص لا يبالي ببقائه. اقترب منه الجنود ببطء، سيوفهم مسلولة. ثورفين لم يتحرك، تنفسه كان مسموعاً في صمت القاعة، صدره يعلو ويهبط بانتظام قسري. نظر أسكلاد إلى ثورفين للمرة الأخيرة، لم تكن نظرة اعتذار، بل نظرة استعلاء بارد، كأنه يقول له: الآن، مهمتك تبدأ من حيث انتهت خيبتي. تقدمت الرماح نحو صدر أسكلاد، وبدأت الدماء القرمزية تغطي قميصه، لكنه ظل يبتسم بتهكم حتى حين سقط على ركبتيه. ثورفين لم يصرخ، ولم يندفع، بل وقف مجمداً بينما تحولت القاعة إلى ساحة فوضى، ورأى حياته التي كرسها للثأر تنهار أمام عينيه مع كل قطرة دم تسيل من جسد عدوه اللدود.', '', 50, '2026-07-15 15:17:43.821', '2026-07-15 15:17:43.821');
INSERT INTO public.chapters VALUES ('be68efc5-af1b-49eb-8da8-0a13748e7a20', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 51: نصل الخيانة وصدى الندم', '— --------------------------------------- تسلل الضوء الشاحب عبر شقوق الجدار الخشبي في الغرفة المظلمة، حيث كان كنوت يراقب انعكاس وجهه في سطح الماء الراكد داخل وعاء نحاسي. دخل أسكلاد الغرفة بوقفة واثقة، ملامحه تعكس مكر المتربص، بينما كانت يداه تعبثان بخرائط ملقاة على الطاولة. لم يلتفت كنوت إليه، بل استمر في مراقبة ملامحه التي بدأت تتغير؛ حلاقة شعره وذقنه لم تكن مجرد طقس لتغيير المظهر، بل كانت تمزيقاً لهوية الأمير الضعيف. قال أسكلاد بصوت متهكم خالٍ من الوقار: ستبدو أخيراً كحاكم يخشاه الرجال، لا كطفل يرتجف خلف العباءات. توقف كنوت عن الحركة، وتلاقت عيناه بعيني أسكلاد عبر انعكاس الوعاء، كانت نظرة الأمير خالية من التردد الذي اعتاد الناس رؤيته، سأل كنوت بنبرة هادئة ومستقرة: وهل تظن أن المظهر يكفي لتغيير قدر الممالك؟ ضحك أسكلاد بخفة، صوته الأجش يملأ زوايا الغرفة: المظهر هو نصف القوة، يا صاحب السمو، والنصف الآخر هو أن تجعل الآخرين يظنون أنك تمتلك النصف الأول. في الخارج، كان ثورفين يراقب من نافذة قريبة، يده تقبض على مقبض خنجره حتى ابيضت مفاصل أصابعه، كان يراقب أسكلاد وهو يتحرك بخفة حول الأمير، ينسج له خطواته القادمة كخيوط العنكبوت. التفت أسكلاد نحوهما فجأة، محطماً حاجز الصمت بسؤال مباشر: ثورفين، أرى في عينيك غضباً يغلي منذ الصباح، هل يضايقك أن ترى الأمير يخلع ثوب الطفولة؟ لم يجب ثورفين، بل اكتفى بضغط أسنانه وتضييق عينيه، كانت أنفاسه متسارعة، وصدره يعلو ويهبط بوتيرة حادة. خرج أسكلاد إلى الفناء حيث تجمع الرجال، كانت أصواتهم الخشنة تملأ المكان، يتبادلون نكاتاً فجة عن الحرب القادمة ومصير الغنائم. لم تكن هناك فلسفة في كلماتهم، فقط جوع للذهب وتوق لكسر العظام. نظر أسكلاد إلى السماء الغائمة، مدركاً أن تحول كنوت لم يكن مجرد انقلاب سياسي، بل بداية لانزلاق الجميع نحو الهاوية. التفت ثورفين نحوه، وكان الحقد في قلبه لا يزال يطالب بالدم، لكنه لم يجد ثغرة في دفاعات أسكلاد الباردة، لا اليوم، ولا في هذا الوقت الذي صار فيه الأمير رقعة أساسية في رقعة الشطرنج التي يديرها أسكلاد ببراعة شيطانية.', '', 51, '2026-07-15 15:17:43.992', '2026-07-15 15:17:43.992');
INSERT INTO public.chapters VALUES ('beba8dde-83e2-4d2d-af5d-6048a5322a88', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 52: خريف الخيانة وقيود الدم', '— --------------------------------------- توقف صوت حوافر الخيل فجأة وسط الغابة، مخلفاً صمتاً ثقيلاً لا يقطعه سوى أنفاس الجياد المتلاحقة. استقر أسكلاد على سرجه، يراقب ملامح الأمير كانوت الجامدة كتمثال من رخام. التفت أسكلاد نحو ثورفين الذي كان يقف بكتفين مشدودتين، وعيناه تلاحقان حركات المحيطين بهما بحذر ذئب جريح. قال أسكلاد بصوت منخفض، مشبع بمرارة ساخرة: هل تعتقد حقاً أن الكاهن سيبارك خطوتنا هذه يا كانوت؟ أم أنك ما زلت تنتظر إشارة من السماء وسط هذا الوحل؟ لم يجب الأمير، بل اتسعت حدقتا عينيه للحظة وهو يرى الجنود الدنماركيين يحيطون بالمكان بأدواتهم المعدنية التي تلمع ببريق قاتل تحت ضوء الشمس الباهت. اقترب ثورفين خطوة، قبضته تضغط على مقبض خنجره حتى ابيضت مفاصل أصابعه، وسأل بصوت خشن: متى تبدأ المذبحة؟ رد أسكلاد بابتسامة باهتة لم تصل إلى عينيه الماكرتين: الصبر يا صغيري، الحروب لا تُكسب بالسيف وحده، بل بمن يملك الصمت في الوقت المناسب. في تلك اللحظة، تقدم أحد القادة العسكريين، وجهه تغطيه ندبة قديمة، وبصق على الأرض قبل أن يهمس بكلمات غليظة عن الولاء للتاج والتحالفات المنهارة. كان الجو مشحوناً بتوتر يكاد يُلمس باليد، حيث تلاقت نظرات المرتزقة والجنود النظاميين في رقصة الموت التي سبقت المعركة. رفع أسكلاد يده، مشيراً إلى رفاقه بالاستعداد، بينما كان ثورفين يراقب الظلال التي بدأت تطول على العشب، مدركاً أن عهداً من التيه قد بدأ ينتهي اليوم بدماء ستسيل على هذه الأرض الغريبة. لم يكن هناك وقت للفلسفة أو التردد، فالمواجهة حتمية، والعدو لم يعد يختبئ وراء الأقنعة، بل صار يقف وجهاً لوجه، شاهراً سخطه المكتوم في وجوههم.', '', 52, '2026-07-15 15:17:44.165', '2026-07-15 15:17:44.165');
INSERT INTO public.chapters VALUES ('9c46f30f-516b-43d7-904f-b81a83a0f406', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 53: خيوط العبيد والحرية', '— --------------------------------------- انزلق ثورفين داخل حظيرة الماشية، حيث الرائحة الثقيلة للروث والتبن القديم تملأ الأرجاء. كانت عيناه، الغائرتان تحت وطأة الإرهاق، ترصدان حركة إينار الذي كان لا يزال مستغرقاً في نومه على القش. تحرك ثورفين بخفة، جسده النحيل يتحرك كظل في الغرفة المظلمة. لم يكن قد مر وقت طويل على كابوسه المعتاد؛ صور النيران، أصوات السيوف المتقاطعة، ووجه والده الذي لا يغادر ذاكرته، ظلت عالقة في ذهنه كجرح لا يندمل. اقترب من إينار، وضعت يده على كتف رفيقه في الشقاء، وهزه بخفة. استيقظ إينار فزعاً، وارتدت يداه غريزياً لتغطي وجهه، قبل أن يدرك أن الملمس كان بشرياً وليس قبضة سياف. سأله ثورفين بصوت خفيض لم يكد يتجاوز الهمس: هل ما زلت تفكر في الهروب؟ لم يجب إينار فوراً، بل سحب نفساً عميقاً وقطرات العرق تتلألأ على جبينه في ضوء القمر الشحيح المتسلل من فجوات الجدار الخشبي. رد إينار بصوت مرير: إلى أين؟ نحن مقيدون بأغلال لا نراها، والحقول هنا ليست سوى سجن واسع. نظر ثورفين إلى كفيه الخشنين، تلك اليدان اللتان لم تعتادا سوى على التلويح بالخناجر، والآن تحفران الطين. قال ثورفين بجمود: القوة لا تحل مشكلة القيد. الصمت ساد المكان لدقائق، كانت أنفاسهما المنتظمة هي الصوت الوحيد المسموع وسط سكون المزرعة. لم يكن ثورفين يبحث عن المواساة، بل كان يحاول استيعاب حقيقة أن حياته الحالية، مهما بلغت من الذل، هي واقع صلب يختلف عن فوضى المعارك. تطلع إينار نحو السقف المتداعي، وقال بنبرة متهدجة: لقد مات الجميع في قريتي… لم يتبق لي سوى هذا الجسد، فهل تسمح لي بأن أهدره في محاولة يائسة؟ رمقه ثورفين بنظرة ثابتة، وعيناه لا تحملان شفقة، بل تفهماً قاسياً نابعاً من تجربة مشابهة. أجاب ثورفين باقتضاب: إذا كنت ستفعل شيئاً، فلا تفعل ذلك من أجل الموت. الهروب هو مجرد تغيير لمكان العذاب. لم يضف أي منهما كلمة أخرى. كان إينار يدرك أن هذا الفتى الغريب، الذي يبدو كأنه يحمل جبلاً من الأسى في صدره، يعرف عن العنف أكثر مما يعرفه أي رجل في هذه البلاد. وبينما كان الصباح يبدأ في التسلل، معلناً بداية يوم شاق آخر في حقول القمح، عاد ثورفين إلى مكانه في الزاوية، مغمضاً عينيه، مستسلماً لنوم خفيف مليء باليقظة، مدركاً أن الحرية ليست في تجاوز الأسوار، بل في القدرة على تحمل ثقل الحياة دون السقوط.', '', 53, '2026-07-15 15:17:44.342', '2026-07-15 15:17:44.342');
INSERT INTO public.chapters VALUES ('451f6f39-5308-40f7-ad63-7107f74f8d8e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 55: خلف الأفق الملطخ', '— --------------------------------------- توقف ثورفين عن الحركة. كان صدى وقع أقدامه على التربة الصخرية قد تلاشى، تاركاً المكان في صمت موحش لا يقطعه سوى أنفاسه المتقطعة. رفع بصره نحو الحشود التي تقف أمام خيمته، وجوه الرجال كانت مزيجا من الترقب والضجر. لم يكن هناك وقت للتردد. التفت ثورفين نحو إينار الذي كان يراقب الموقف بوجوم، وقال بنبرة جافة لا تحمل سوى حقيقة الموقف: ''سأرحل، لا تتبعني''. لم ينتظر رداً، بل اندفع نحو المخرج بخطوات واسعة، متجاهلاً نداءات إينار التي ارتطمت بظهره كأنها صدى بعيد. في الخارج، كانت السماء رمادية بلون المعدن، والسهول الممتدة تبدو وكأنها لا نهاية لها. توقف فجأة عندما لمح خيالاً ينتظر عند مفترق الطريق. كان كانوت، بملامحه التي تجمدت في قناع من الهدوء الملكي، محاطاً بحراسه الذين بدت أجسادهم الضخمة كأنها تماثيل من صخر. اتسعت بؤبؤ عين ثورفين للحظة قبل أن تستعيد ثباتها. اقترب كانوت ببطء، وتوقفت حركته على بعد خطوات قليلة. قال كانوت بصوت منخفض، خالٍ من أي انفعال: ''ثورفين، الطريق الذي اخترته لا يؤدي إلى السلام. أنت لا تبحث عن العدو، بل تبحث عن مبرر لموتك''. شد ثورفين قبضتيه حتى ابيضت مفاصله، وأجاب بنبرة حادة كالنصل: ''لا أهتم لما تراه. طريقي لا يعنيك، ولا يعني جيوشك''. لم يتزحزح كانوت، بل أمال رأسه قليلاً، متأملاً الفتى الذي وقف أمامه بصلابة تنبئ عن رفض كامل للخضوع. قال كانوت مجدداً، بنبرة حملت مسحة من السخرية الباردة: ''العالم لا يتغير برغباتك الفردية، يا ثورفين. القوة وحدها تفرض واقعاً جديداً''. بصق ثورفين على الأرض، وتقدم خطوة واحدة مقتحماً المساحة الفاصلة بينهما، عيناه تشتعلان بوميض لا يلين. صمت الجانبان، والرياح التي بدأت تهب لم تجلب معها سوى نذر صراع صامت، صراع بين إرادتين لا تلتقيان. انقبضت عضلات ثورفين استعداداً لاحتمال المواجهة، بينما بقي كانوت ثابتاً كالجبل، يراقب الفتى الذي قرر أن يواجه قدره بمفرده، بعيداً عن أطماع الملوك ودموية الساحات. أدار ثورفين ظهره ورحل، تاركاً خلفه الملك وخططه، وخطواته تخترق الأرض الصلبة بعزم لا يلتفت للوراء.', '', 55, '2026-07-15 15:17:44.716', '2026-07-15 15:17:44.716');
INSERT INTO public.chapters VALUES ('58293ee6-559e-4eab-b960-e1a355fa557b', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 56: خلف أسوار الترقب', '— --------------------------------------- توقف وقع الأقدام فجأة عند مدخل الخيمة. داخل الغرفة شبه المظلمة، لم تكن هناك سوى حركة نصل معدني يمسح بقطعة قماش خشنة. رمق أسكلاد الداخل بطرف عينه، كان الأمير كانوت يقف بصلابة غير معهودة، ملامحه التي كانت توحي بالضعف قد استقالت، لتحل محلها جفوة باردة كصقيع الشمال. قال أسكلاد وهو يغمد خنجره بهدوء: يبدو أن صاحب السمو قرر أخيراً الخروج من شرنقة الصمت. رد كانوت دون أن يرمش، صوته كان مسطحاً وخالياً من الرعشة المعتادة: الموت في الخارج يحصد الرجال، وأنا لن أموت في خيمة بينما تضيع المملكة في أيدي الجبناء. ثورفين، الذي كان يجلس في الزاوية، رفع رأسه ببطء، ظلال وجهه تخفي ندبات غضبه المكبوت، قذف قطعة خشب صغيرة على الأرض وقال بصوت أجش: التاج لا يمنحك القوة إن كنت عاجزاً عن حماية رأسك من الفأس. التفت إليه كانوت، نظرة عيناه الزرقاوين حملت ثقلاً لم يعهده ثورفين من قبل، وكأن صبياً قد تبخر ليبقى محارب بقلب محنط. سأله الأمير: وهل تعتقد أن الفأس هي الفيصل الوحيد يا ثورفين؟ أجاب ثورفين وهو ينهض، تتركز عضلات كتفيه بحدة: لا أعرف الفلسفة، أعرف فقط أن البقاء للأسرع، ومن يتردد هنا يغدو جثة قبل أن يكتمل غروب الشمس. ضحك أسكلاد ضحكة قصيرة خالية من المرح، واضعاً يده على مقبض سيفه: الصغار يتحدثون عن البقاء، والكبار يخططون للعروش. يا أمير، إذا كنت قد قررت خلع ثوب الرهبنة، فاستعد لارتداء ثوب الدم. لا مكان للرحمة في معادلاتنا، فالإله الذي تدعو له يبدو أنه أخذ إجازة طويلة من أرض الدنمارك. لم يهتز كانوت، بل تقدم خطوة نحو أسكلاد، فارق الطول بينهما لم يمنعه من النظر بعينين لا تعترفان بالهزيمة: الإله لا يحتاج لإجازة حين يكون البشر هم من يقررون مصيرهم بالحديد. لن ننتظر وصول الإمدادات، سنبدأ التحرك عند الفجر. نظر ثورفين إلى الباب، قبض على نصل خنجره حتى ابيضت مفاصل أصابعه، كان يعلم أن الطريق الذي يسلكه الأمير سيمر حتماً عبر حقول من الجثث، ولم يعد يكترث لأي شيء سوى تلك اللحظة التي سيلتقي فيها بخصمه القديم. صمتٌ مطبق ساد الخيمة، ولم يقطعه سوى صوت اشتعال الحطب في الخارج، بينما كان مستقبل المملكة يُرسم في تلك الغرفة الصغيرة بكلمات قليلة ونظرات تتبادل التحدي.', '', 56, '2026-07-15 15:17:44.896', '2026-07-15 15:17:44.896');
INSERT INTO public.chapters VALUES ('e1924037-179f-4543-897d-e732be9d499e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 57: خيوط العبيد والقيود المنسية', '— --------------------------------------- توقف ثورفين عن الجري حين تلاشت أصوات مطارديه في ضجيج السوق الصاخب. كانت أنفاسه متلاحقة، صدراً يرتفع ويهبط بعنف تحت قميصه المهترئ. نظر حوله، لم يعد ذلك المحارب الذي يطارد الأشباح، بل طيفاً يجر جسداً أنهكه العمل في المزارع. اقترب منه إينار، ملامحه غارقة في القلق وهو يمسح العرق عن جبينه. قال إينار بصوت خافت ومتحشرج: «لا يمكننا العودة هكذا يا ثورفين، سيفتشون عن كل هارب». لم يجب ثورفين، كانت عيناه مثبتتين على الأفق البعيد، حيث تلوح تلال المزرعة كأنها زنزانة لا تنتهي. في تلك اللحظة، ظهرت صورة أسكلاد في مخيلته، ضحكته الساخرة التي كانت تتردد في أذنيه كصوت نحاسي لا يصدأ، تذكر وقع خطواته الثقيلة ونبرته التي كانت تقطر سماً وذكاءً. اقترب رجل مسن من السوق، ملامحه محفورة بالندوب، وضع يده على كتف ثورفين، كانت يده خشنة كجذع شجرة. همس الرجل: «الحرية لا تخرج من جروح السيوف، بل من بذور تزرعها في أرض لا تخصك». صمت ثورفين، وتشنجت عضلات فكه. لم تكن فلسفةً، بل كانت حقيقة مادية واجهته كل صباح حين كان يغرس الفأس في الأرض القاسية. تحرك إينار خطوة للأمام، واضعاً يده على كف ثورفين، كانت قبضته ترتجف قليلاً لكنها كانت ثابتة. قال إينار: «دعنا نعود، سنبني شيئاً من هذا الحطام، سنزرع القمح حتى وإن كانت الأرض ملكاً لغيرنا». التفت ثورفين، نظرت عيناه الصامتتان إلى إينار، لا يأس ولا غضب، بل فراغٌ بدأ يمتلئ بقرارات صامتة. سار الرجلان نحو المزرعة تحت وهج الشمس الغاربة التي صبغت السماء بلون الدم والصدأ، تاركين خلفهم خيالات المعارك ونداء الموت الذي طالما طاردهم. لم تكن العودة استسلاماً، بل كانت بداية صراع من نوع آخر، صراع لا يحتاج إلى نصل حاد، بل إلى صبرٍ يفتت الحجر.', '', 57, '2026-07-15 15:17:45.084', '2026-07-15 15:17:45.084');
INSERT INTO public.chapters VALUES ('7a335553-bf9a-49cc-bcbf-345a3f26cede', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 58: سلاسل لا تقيد', '— --------------------------------------- تثاقلت خطى ثورفين على الأرض الموحلة، كانت عيناه، الغائرتان تحت وطأة الإرهاق، تحدقان في الفراغ، بينما صدى صراخ العمال وسياط الحراس يتردد في أرجاء المزرعة كوقع طبول جنائزية. لم يكن ثورفين يبحث عن القوة أو الانتقام في تلك اللحظة؛ كان يبحث عن اللاشيء. بجانبه، وقف إينار يمسح العرق الممزوج بالتراب عن جبينه، يتنفس بصعوبة، ونظر إلى ثورفين بنظرة يملؤها القلق المكتوم. قال إينار بصوت مبحوح: «أنت لا تنام، يا ثورفين. جسدك ككومة من الخشب الجاف، أي ريح قد تكسره». لم يلتفت ثورفين إليه، بل استمر في حفر الأرض بحافره، مقتضباً في رده: «النوم لا يغير الواقع. الحقل لن يحرث نفسه». في تلك الأثناء، كان الحراس يراقبونهم من بعيد، تتبادل أعينهم نظرات السخرية والازدراء، حيث لم يكن ثورفين بالنسبة لهم سوى آلة بشرية مكسورة الروح. مرت الساعات ثقيلة كأنها دهور، وبينما كان ثورفين يغوص في فكروه، تذكر للحظات وجه والده؛ لم تكن الذكرى مشبعة بالحقد، بل كانت طيفاً لسكينة غريبة لم يدرك كنهها بعد. اقترب إينار أكثر، محاولاً كسر حاجز الصمت الجليدي بينهما: «ما الذي تطارده في أحلامك؟ أرني ما وراء هذا القناع الخشبي». توقف ثورفين عن العمل، انقبضت عضلات فكه، وارتجفت يده للحظة على مقبض أداته، ثم زفر بحدة قائلاً: «لا توجد أحلام. فقط عمل يؤدي إلى طعام، وطعام يؤدي إلى بقاء». كانت كلماته جافة، تخلو من أي نبرة عاطفية، مما جعل إينار يتراجع خطوة إلى الوراء، مدركاً أن رفيقه غارق في قاعٍ لا يمكن لنداءات البشر أن تصل إليه. ومع غروب الشمس، اختفت الألوان الدافئة لتحل محلها رمادية باهتة، وبدأ ثورفين يمشي بخطوات آلية نحو كوخهم، تاركاً خلفه ندوباً في الأرض، وكأن الأرض نفسها شاهدة على رجل يحاول التخلص من قيود ماضٍ لا يرحم.', '', 58, '2026-07-15 15:17:45.266', '2026-07-15 15:17:45.266');
INSERT INTO public.chapters VALUES ('198252b3-ecf8-4411-98da-9dc702f08377', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 59: وليمة الذئاب في ظلال العرش', '— --------------------------------------- توسطت المائدة خنازير مشوية بدت جلودها محمصة حتى السواد، بينما كانت أبخرة اللحم والدهن المذاب تملأ قاعة الاجتماعات الكبرى في غاينزبورو. جلس كنوت في الصدارة، ملامحه الجامدة كتمثال منحوت من مرمر، عيناه الزرقاوان تراقبان الحاضرين دون أن ترف لهما جفن. إلى يمينه، كان أسكلاد يمسك بقطعة خبز خشنة، يفتتها ببطء بأصابعه الطويلة، وعيناه تلمعان ببريق مريب. رمق أسكلاد النبلاء المتجمهرين حول المائدة، ثم التفت نحو ثورفين الذي كان يقف في الظل كخنجر مشحوذ، مكتوف اليدين، يحدق في الفراغ. همس أسكلاد بصوت خفيض لا يسمعه إلا من يقترب منه: ''انظر إليهم يا ثورفين، يتصنعون الولاء للملك بينما تتسابق أيديهم لنهب الفتات''. لم يلتفت ثورفين، بل انقبضت عضلات فكه السفلي، ولم يخرج منه سوى زفير حاد. على الجانب الآخر، كان اللوردات يتجادلون بصوت عالٍ حول تقسيم الأراضي، متجاهلين وجود كنوت تماماً، حتى ارتطم كأس من المعدن بالطاولة بقوة أحدثت دوياً صامتاً في القاعة. توقف الجميع عن الكلام. نظر كنوت إلى اللورد ثوركيل، الذي كان يضحك بجنون، ثم قال بصوت هادئ ومستقر: ''ليس الميد هو ما سيملأ بطونكم يا سادة، بل القرار الذي ستتخذونه الآن''. سادت لحظة من التوجس، حيث تبادل النبلاء نظرات قلقة. تحرك أسكلاد ببطء، وقف بثقة المعتاد على السيطرة، ووضع يده على مقبض سيفه، ملمحاً إلى أن أي حركة خاطئة ستكلفهم حياتهم. قال أسكلاد بسخرية لاذعة: ''الملك يتحدث، ألا تعتقدون أن الصمت هو الخيار الأكثر حكمة لبقائكم على قيد الحياة؟ ''. انحنى أحد النبلاء برأسه، واصفر وجهه تحت ضوء الشموع الخافت، بينما استمر ثورفين في مراقبة كل حركة، مستعداً للانقضاض. لم تكن هذه مجرد مأدبة، بل كانت رقعة شطرنج بشرية حيث تقرر الأرواح مصير المملكة في ليلة لم يعد فيها أي مجال للخطأ.', '', 59, '2026-07-15 15:17:45.431', '2026-07-15 15:17:45.431');
INSERT INTO public.chapters VALUES ('62c4983e-f938-4d58-8d55-78377c14a506', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 60: خريف العبيد: نصل الكبرياء', '— --------------------------------------- انغرز المعول في التربة القاسية محدثاً رنيناً مكتوماً، وارتدت الصدمة إلى ذراعي ثورفين، لتوقظ في عضلاته وجعاً مزمناً. لم ينظر خلفه. كان يدرك أن العينين اللتين تراقبانه من وراء أكوام الحطب لا تحملان شفقة، بل تفتشان عن ذرة ضعف في إيقاع عمله. قال ''إينار'' بصوت متهدج بالكاد يخرق صمت الحقل: اترك الفأس يا ثورفين، لقد نزفت يداك بما يكفي اليوم. لم يلتفت ثورفين، بل شد قبضته على المقبض الخشبي الملطخ بالدماء المتيبسة، ومسح وجهه بساعده، تاركاً أثراً طينياً داكناً على جبهته. قال ثورفين بنبرة حادة وخالية من أي نبرة ود: عد إلى الكوخ، لا أحتاج مساعدتك. كان الظل الممتد على الأرض يتغير ببطء، دليلاً على زحف المساء. التفت إينار، وعيناه تضيقان بحدة، ثم خطى خطوة نحو ثورفين، متجاهلاً نبرة الرفض: نحن لسنا هنا لنحفر قبورنا بأيدينا. العمل هنا لن ينتهي، لكننا سننتهي إذا استمرينا بهذا الهوس. سكت ثورفين لحظة، كانت عضلات فكه تنقبض وتنبسط بإيقاع متوتر، ثم ألقى المعول أرضاً، ليس ارتخاءً بل بحدة تثير الغبار. اقترب منه إينار، صوته الآن خافت كهمس مخادع: أخبرني، ما الذي تبحث عنه في قاع هذه الأرض؟ هل تعتقد أن النسيان يدفن تحت الصخور؟ حدق ثورفين في الفراغ، بعيداً عن حقول القمح الممتدة خلفهما، وتذكر وجوه الرجال الذين قتلهم، لا كذكريات حزينة، بل كوجوه باهتة لا ملامح لها. رمق ثورفين رفيقه بنظرة باردة وقال: لا أبحث عن شيء. أنا فقط أنتظر اليوم الذي تنتهي فيه هذه المهمة. كان الحوار بينهما يغور في صمت مريب، يقطعه صوت صرير عربة تمر من بعيد، محمولة على عجلات خشبية متهالكة. لم يكن ثورفين يبحث عن الخلاص، بل كان يتجنب التفكير في الغد، لأن الغد بالنسبة له لم يعد يحمل سوى مزيد من العمل الشاق وجدران الكوخ الخشبية التي تضيق عليه في كل ليلة. حينما بدأ المطر يقرع الأرض بقطرات ثقيلة، نهض ثورفين بصمت، التقط معوله، واتجه نحو الكوخ بخطوات ثقيلة ومتزنة، تاركاً إينار خلفه في الحقل الموحش، شاهداً على تحول جديد في روح رجل لم يعد يملك من حياته سوى ألم جسده.', '', 60, '2026-07-15 15:17:45.668', '2026-07-15 15:17:45.668');
INSERT INTO public.chapters VALUES ('97c7940e-30aa-4fc8-8806-a8934a6ca590', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 62: خلف أسوار العبودية', '— --------------------------------------- انغرس طرف المنجل في الأرض القاسية، مقتلعاً جذور الشوك بعنف لا يهدأ. كان ثورفين يزفر أنفاساً متقطعة، وعيناه الفارغتان من أي بريق تراقبان حبات العرق وهي تتساقط لتختفي في جوف التربة الجافة. بجانبه، كان إينار يمسح جبينه بساعده المتسخ، ثم التفت إليه قائلاً بنبرة مبحوحة من الإرهاق: - هذا الحقل لا ينتهي يا ثورفين. إذا استمررنا بهذا المعدل، فسنحتاج إلى أعوام لنصل إلى طرف الغابة. لم يلتفت ثورفين، بل استمر في حركته الآلية، صوته خرج جافاً ومقتضباً: - لا يهم. العمل هو السبيل الوحيد للبقاء. صمت إينار، ونظر إلى ثورفين بتفحص. كان يرى في رفيقه شيئاً يثير الريبة؛ ذلك الصمت المطبق الذي يغلفه كدرع لا يمكن اختراقه. وفجأة، قطعت حدة الصمت أصوات حوافر خيول تقترب من بعيد، تلاها صراخ حاد لأحد الحراس من اتجاه السكن. توقف ثورفين عن العمل، وشد على مقبض منجله حتى برزت عروق يده وبيضت مفاصل أصابعه. لم يكن ثمة فزع في ملامحه، بل ترقب بارد وحيواني. كان الحراس يطوقون المكان، تتقدمهم ملامح المتغطرس ''باك'' الذي يلوح بسوطه في الهواء، صوته أجش يملأ الفضاء: - توقفوا عن التكاسل أيها الأوغاد! المالك يريد الحقل جاهزاً قبل حلول الظلام، ومن يقصر سيعرف عاقبته جيداً. اقترب باك من ثورفين، ونظر إليه باحتقار قبل أن يركل كومة القمح التي جمعها برفق. تناثر القمح وتفرق في مهب الريح. انقبض فك ثورفين، وتحركت عضلات رقبته بتوتر مكتوم. لم ينطق بكلمة، بل انحنى بهدوء لجمع ما تبعثر، بينما كانت نظرات إينار تتنقل بين الحارس ورفيقه، محاولاً منع ثورفين من فعل شيء قد يكلفهما حياتهما. غادر الحراس متبوعين بضحكاتهم القاسية، تاركين وراءهم صمتاً أشد ثقلاً من ذي قبل. رمى إينار بيده على كتف ثورفين، محاولاً استجماع شجاعته: - لا تعرهم اهتماماً، ثورفين. إنهم مجرد حثالة، لا يستحقون أن تلوث يديك بدمائهم. انتصب ثورفين واقفاً، ونظر إلى الأفق البعيد، حيث تغرب الشمس مخلفة وراءها ألواناً دامية. لم تكن هناك فلسفة في عينيه، بل كان ثمة فراغ مطلق، صدى لأصوات معارك قديمة تلاشت في زوايا عقله. قال بصوت خفيض، يكاد لا يُسمع: - الدم لا يغسل الدم، يا إينار. أنا لا أهتم بما يقولون، أنا فقط أريد لهذا اليوم أن ينتهي. استأنف الاثنان العمل، وكان إيقاع المنجل يضرب الأرض في توافق حزين، بينما كان الظلام يزحف ببطء ليطوي المشهد، مخفياً وراءه ندوباً لم تندمل بعد.', '', 61, '2026-07-15 15:17:45.876', '2026-07-15 15:17:45.876');
INSERT INTO public.chapters VALUES ('e36b4cd1-48b8-4a25-823c-d2429eeaea50', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 63: خلف أسوار الجحيم الصامت', '— --------------------------------------- انغرس نصل الفأس في جذع الشجرة الخشبي بقوة، مخلفاً صوتاً مكتوماً هز أرجاء الغابة الساكنة. تنفس ثورفين بحدة، صدره يعلو ويهبط بوتيرة مضطربة، بينما كانت عيناه، الغائرتان في ملامح وجهه النحيل، مسمرتين على الفراغ. لم يكن في ذهنه سوى صورة واحدة: تلك اللحظة التي سقط فيها والده. مرت سنوات، لكن الندوب في داخله لم تلتئم؛ كانت تتجدد مع كل إشراقة شمس. اقترب أسكلاد منه بخطوات واثقة، صوته المتهكم اخترق سكون المكان كشفرة باردة: «لا يزال فأسك يرتجف يا صبي، الغضب لا يمنحك قوة، بل يعمي بصيرتك عن رؤية اللحظة المناسبة للضرب». التفت ثورفين نحوه، يداه مقبوضتان حول مقبض الفأس حتى ابيضت مفاصله، وقال بنبرة مقتضبة تخلو من أي خضوع: «سأقتلك، بغض النظر عن كلماتك». ضحك أسكلاد، ضحكة قصيرة وجافة لم تلمس عينيه الباردتين، ثم أضاف وهو ينفض الغبار عن ثيابه: «اقتلني؟ أنت حتى لا تعرف كيف تقتل عدوك، أنت تقتل ذكرياتك فقط». في تلك الأثناء، كان المخيم يضج بالحركة؛ رجال يسنون سيوفهم، وآخرون يتشاجرون حول نصيبهم من المؤن. لم يكن ثورفين جزءاً من هذا الضجيج. كان يراقبهم من بعيد، كذئب وحيد ينتظر فرصة الانقضاض، لا يكترث لوعود الثراء أو المجد، بل لمجرد لحظة واحدة يواجه فيها قاتل والده في نزال عادل. اقترب رجل ضخم البنية، ذو ندبة عميقة تشق وجهه، وصفع ثورفين على كتفه بقوة: «كفاك تحديقاً في اللاشيء، فالعمل بانتظارنا». تجاهله ثورفين، ونظر نحو الأفق البعيد، حيث تغيب الشمس مخلفة وراءها سماءً ملطخة بلون الدم. كان يعلم أن الطريق أمامه طويل، وأن كل خطوة يخطوها تقربه أكثر من مصيره المحتوم، أو من نهايته التي رسمها لنفسه في مخيلته منذ زمن. لم يكن يطمح للسلام، ولم يكن يبحث عن مأوى، بل كان يسير في مسارٍ لا ينتهي إلا بالدماء.', '', 62, '2026-07-15 15:17:46.059', '2026-07-15 15:17:46.059');
INSERT INTO public.chapters VALUES ('c092419d-d7f5-4efc-bbc9-d890030cb25a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 64: خسارة الظل وقيود العبودية', '— --------------------------------------- انغرز الفأس في الأرض الطينية، تاركاً شقاً عميقاً في وجه الأرض، بينما كان أنفاس ثورفين المضطربة هي الصوت الوحيد الذي يخرق سكون الحقل. وقف ثورفين، عيناه الغائرتان تراقب الجسد الملقى بلا حراك، جسد ''هينكوس'' الذي سقط أخيراً تحت وطأة العمل الشاق. اقترب ''إينار''، ملامحه مشدودة، ونبرته تحمل ثقلاً لا يخفى على أحد: ''لقد مات يا ثورفين. توقف عن محاولة انتزاع العمل من جثة هامدة''. لم يلتفت ثورفين، بل ظلت عيناه مثبتتين على كومة القمح التي لم يكتمل حصدها. همس ثورفين بنبرة متهالجة، خالية من أي بريق: ''لو استمر في العمل، لربما تعافى. الجوع لا ينتظر''. زفر إينار بقوة، مسح العرق المتصبب على جبينه بيده الخشنة، وقال بحدة لا تخلو من الشفقة: ''الاستمرار يعني الموت للجميع. انظر حولك، هذه المزرعة ليست ساحة معركة، إنها مقبرة لمن يظن أن القوة هي الحل الوحيد''. في تلك اللحظة، خيم صمت ثقيل، صمت يزحف كالأفعى بين أكوام القمح المحصود. لم يكن ثورفين يبحث عن منطق، بل كان يهرب من فراغ داخلي ينهشه كلما توقف عن الحركة. استدار إينار مغادراً نحو كوخ السكن، ملقياً بجملته الأخيرة كحجر في بئر عميق: ''النمو يحتاج صبراً لا يملكه المحاربون، يا ثورفين. فكر في الأمر، هل ستظل عبداً لظلك القاتل طوال حياتك؟ ''. تركه ثورفين خلفه، ممسكاً بمنجله بيد ترتجف، ليس من برد أو إرهاق، بل من ثقل تلك الكلمات التي لم يجد لها جواباً. في الأفق، كانت الشمس تميل نحو المغيب، تصبغ الأرض بلون دموي يذكره بساحات قديمة أراد نسيانها، لكنه وجد نفسه يغرق في تفاصيلها كلما حاول التحرر. لم تكن هناك معارك اليوم، لكن الندوب في داخله كانت تنزف بصمت، تذكره بأن القيود ليست دائماً من حديد، بل غالباً ما تكون من ذكريات لا تموت.', '', 63, '2026-07-15 15:17:46.242', '2026-07-15 15:17:46.242');
INSERT INTO public.chapters VALUES ('b97a7bf8-bb11-4dde-a1db-d96c55071268', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 65: خلف أسوار العبودية', '— --------------------------------------- تتزاحم الأقدام الموحلة في ساحة المزرعة، بينما يتردد صدى السياط الجافة على الأجساد المنهكة. ثورفين، بقامته النحيلة وملامحه التي تآكلت فيها بريق الحياة، يجر أقدامه المثقلة بالقيود نحو الحقل. لم يعد يرى العالم كساحة قتال، بل كبقعة رمادية من التربة والعمل الشاق. إلى جانبه، يمضي أينار، الذي لا تزال عيناه تحملان أثراً من غضب لم يمت بعد، يجز على أسنانه وهو يرقب الحراس. التفت أينار فجأة، وصوته المبحوح يمزق رتابة الصمت: ألا تشعر بذلك؟ تلك النظرات التي تراقبنا من الظل؟ لم يجب ثورفين، بل اكتفى بمسح جبهته من العرق الممزوج بالتراب، وكانت حركته بطيئة، مدروسة، وخالية من أي اندفاع. إنهم ليسوا أعداءنا هنا، يا أينار، هم فقط حراس لسجن لا نملك مفتاحه. رمقه أينار بنظرة ساخرة: سجن؟ بل هو مقبرة للأحياء، وأنت يا ثورفين، تبدو كأنك ميت منذ سنوات. لم يتوقف ثورفين عن العمل؛ ظهره المقوس تحت أشعة الشمس كان يجيب بوضوح أكبر من الكلمات. انقبضت كف ثورفين على مقبض المحراث بقوة جعلت مفاصله تبرز ككتل عظمية تحت الجلد الشاحب. في الجانب الآخر من المزرعة، وقف السيد، يراقب المشهد ببرود، يداه خلف ظهره، ولا شيء في عينيه يشير إلى تعاطف أو قسوة؛ كان ينظر إليهما كأدوات زراعية تكتسب قيمتها من جودة المحصول. اقترب أحد الحراس، تلاشت خطواته على الأرض الطينية، وبصوت فظ خشن أردف: عودوا للعمل ولا تثرثروا، وإلا تذوقتم نصل السوط. ساد صمت مطبق، لم يقطعه سوى احتكاك الحديد بالأرض الصلبة. كان ثورفين يدرك أن القوة التي اكتسبها في سنوات القتال قد تحولت الآن إلى قدرة غريبة على التحمل، صمتٌ يغلفه كدرع. التفت ثورفين نحو أينار، بنظرة خالية من أي توتر، وقال بصوت منخفض: استمر في الحفر، لا تمنحهم سبباً إضافياً، فالهدف هو الحياة، لا النزال. في تلك اللحظة، اتسعت حدقتا أينار قليلاً، كأنما أدرك ثقلاً جديداً في كلمات رفيقه، فتراجع قليلاً عن حدته، وعاد يغرس أداة الحفر في جوف الأرض، بينما كانت الشمس تميل نحو المغيب، تاركة خلفها أفقاً بلون الدم الجاف، شاهداً على يوم آخر ضاع في طيات العبودية.', '', 64, '2026-07-15 15:17:46.502', '2026-07-15 15:17:46.502');
INSERT INTO public.chapters VALUES ('37181f9b-3bca-48f6-a196-aac84c867b26', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 66: بذور الضغينة في حقول العبيد', '— --------------------------------------- انغرس النصل الخشبي في التربة الطينية بقوة، مخلفاً خدشاً عميقاً في وجه الأرض التي بدت مستكينة لثقل الفأس. تنفس ثورفين بانتظام، كان صدره يعلو ويهبط بوتيرة هادئة، بينما كانت قطرات العرق تفر من جبهته لتسقط على نصل فأسه الملطخ بالتراب. لم يلتفت خلفه عندما سمع وقع خطوات تقترب؛ عرف طبيعة الخطوات الثقيلة التي لا تعبأ بإخفاء أثرها. توقف أولار على مسافة مترين، يمسح يديه الخشنتين في ثيابه الرثة، وعيناه تراقبان ثورفين بفضول يشوبه الريبة. قال أولار بصوت أجش تقطعه خشونة الحياة في المزرعة: لا تزال تواصل العمل حتى بعد غروب الشمس يا غريب، هل تطمع في أن تشتري حريتك بهذا العرق؟ توقف ثورفين عن الحركة تماماً، لكنه لم يرفع رأسه، بل ظل محدقاً في الفراغ الذي خلفه شق الخشب. لم يأتِ الرد فوراً، بل مر صمت ثقيل لم يقطعه سوى طنين حشرة ليليّة. أجاب ثورفين بنبرة مقتضبة، خالية من أي نبرة ودّ: لا يهمني. اتسعت عينا أولار قليلاً، وبدت دهشته واضحة في ارتجافة طفيفة في شفته السفلى، فقد اعتاد على أن يتسول العبيد نظرة أو كلمة. اقترب أولار خطوة أخرى، محاولاً استجلاء كنه هذا الشاب الذي لا يكترث بما حوله. هل أنت ميت في الداخل؟ سأل أولار، وصوته يحمل الآن نبرة استفزازية مقصودة. استدار ثورفين ببطء، كانت عيناه الجامدتان كحجرين مصقولين تلتهمان مساحة وجهه النحيل. لم تكن هناك شرارة غضب، ولا وميض كراهية، بل فراغ سحيق جعل أولار يتراجع لا إرادياً خطوة إلى الوراء، مستشعراً برداً غريباً يسري في عموده الفقري. قال ثورفين ببرود: العبودية ليست في القيود يا أولار، العبودية هي أن تظل منتظراً خلاصاً لن يأتي إلا إذا توقفت عن السؤال. ألقى الفأس جانباً، وسقط المعدن على الأرض بصوت مكتوم. ترك ثورفين أولار يقف مذهولاً في مكانه، ومضى بخطوات ثابتة نحو كوخه، متجاهلاً نداءات الرجل الذي بدأ يتمتم بكلمات غير مفهومة عن الجنون والقدر. في تلك الليلة، لم ينم ثورفين؛ كان يحدق في سقف الكوخ الخشبي المتآكل، مسترجعاً أصداء المعارك القديمة التي لم تعد تتردد في أذنيه كصيحات نصر، بل كضجيج بعيد لم يعد يعنيه أمره في شيء.', '', 65, '2026-07-15 15:17:46.68', '2026-07-15 15:17:46.68');
INSERT INTO public.chapters VALUES ('3aa8940d-6a41-49ad-a760-d4757e2dca71', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 67: خيوط القدر المتمزقة', '— --------------------------------------- انغرس نصل السكين في الطاولة الخشبية محدثاً صوتاً مكتوماً، وارتجفت يد ثورفين وهو يحدق في وجه الملك كانوت. لم تكن الغرفة في مزرعة كيتيل تتسع لكل هذا التوتر؛ فالهواء ثقيل بوجود الحراس وتنهيدات الرجال الذين أرهقهم الانتظار. تقدم كانوت ببطء، بخطوات هادئة تخلو من التردد، وثيابه الملكية تتناقض بحدة مع فوضى المكان. لم يقل ثورفين شيئاً، كانت عيناه، الغائرتان تحت وطأة ندوب الماضي، تراقب بؤبؤي عين الملك، باحثةً عن ذرة من إنسانية قديمة، لكنه لم يجد سوى هدوء جليدي. التفت كانوت ببطء نحو رفاقه، صوته كان كهدير بعيد، بارد ومباشر: سأقتلع هذا المكان من جذوره. صمت ثورفين للحظة، ثم قبض على مقبض سكينه بقوة جعلت مفاصل أصابعه تبيض، صوته خرج أجشاً ومتهدجاً: لن أفعل ذلك. لا مزيد من الدماء. لم يلتفت الملك، بل اكتفى بابتسامة باهتة تكاد لا تلمح على شفتيه، وكأن حديث ثورفين ليس أكثر من طنين ذبابة مزعجة. تدخل إينار، متمسكاً بكتف ثورفين، وعيناه تجولان بذعر مكتوم بين الحراس المحيطين بهم، صوته كان متهدجاً حين همس: ثورفين، لا تتهور، هم كثر. لكن ثورفين كان قد حسم أمره، انحنى جسده للأمام، وتصلبت عضلات فخذيه استعداداً لاندفاعة انتحارية. فجأة، تعالت أصوات في الخارج، صرخات الجنود المذعورين تخترق الصمت، وانفتح الباب بعنف، لتظهر ملامح القلق على وجه أحد القادة الذي اندفع للداخل قائلاً: الحصار يشتد يا مولاي، المزارعون لا يقاتلون كعبيد، بل كمن فقدوا كل شيء. لم يهتز كانوت، بل نظر مباشرة إلى ثورفين قائلاً بنبرة ساخرة: هل ترى؟ العالم لا يتسع لأحلامك الساذجة يا ثورفين، العنف هو اللغة الوحيدة التي يفهمها هؤلاء. ألقى ثورفين نظرة أخيرة على الرجل الذي كان في يوم ما رفيقاً له، ثم استدار ببطء نحو الباب، ضاغطاً على أسنان فكيه بقوة حتى برز عصب في صدغه. خرج إلى الساحة؛ حيث كانت النيران قد بدأت تلتهم مخازن الحبوب، والدخان الأسود يتصاعد ليحجب شمس الظهيرة. لم يكن هناك وقت للندم، فقط وقت للاختيار بين البقاء في صمت الذل أو السقوط في معركة لا تؤمن بها روحه.', '', 66, '2026-07-15 15:17:46.883', '2026-07-15 15:17:46.883');
INSERT INTO public.chapters VALUES ('6c84550d-ffb9-4e3b-9050-6de56a032bdb', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 68: خيوط المصير المشتبكة', '— --------------------------------------- توقف ثورفين عن الحركة. كانت حدقة عينيه تتركز بصلابة على ذلك الرجل الواقف أمامه، الرجل الذي كان يمثل في ذاكرته كل ما هو قاتل ومراوغ. الهواء داخل الغرفة كان ثقيلاً، مشحوناً برائحة العرق والترقب. لم تكن هناك كلمات تلطف حدة الموقف؛ كان الصمت هو السيد الوحيد في تلك اللحظة. أسكلاد، بابتسامته الساخرة التي لم تفارق ملامح وجهه، كان يقلب خنجراً في يده بحركات رتيبة ومستفزة. قال أسكلاد بصوت منخفض، مشوب بنبرة تهكمية لا تخطئها الأذن: يبدو أن الوقت قد حان لنواجه الحقائق، يا فتى، لا يمكن لغضبك أن يظل حبيس صدرك إلى الأبد. انقبضت كف ثورفين على قبضة سيفه حتى ابيضت مفاصل أصابعه. لم يرد، بل كانت أنفاسه المتقطعة تكفي للتعبير عن الصراع المحتدم داخله. كان يرى في أسكلاد ليس فقط قاتل أبيه، بل سجان سنوات ضياعه. اقترب أسكلاد خطوة أخرى، متجاهلاً وضعية ثورفين الهجومية، وأضاف ببرود: هل تظن أنك ستنال ثأرك اليوم؟ إن السعي خلف شبح الماضي لا يورث إلا رماداً في اليد. حدق ثورفين في عيني أسكلاد، باحثاً عن أي ذرة تردد، لكنه لم يجد سوى مرآة لواقعه القاسي. تحرك ثورفين أخيراً، ليس للهجوم، بل ليعلن عن حضوره بكلمة واحدة مقتضبة: سأفعلها. كانت الكلمة تخرج من أعماقه كأنها حجر صلب. تلاشت ابتسامة أسكلاد للحظة، وحل محلها تعبير جدي، وكأنه يرى في ثورفين أخيراً نداً، لا مجرد طفل تائه في خضم الحرب. غادر أسكلاد الغرفة دون التفات، تاركاً ثورفين في صمت مطبق، بينما كانت ذكريات ثورس تتراقص أمام عينيه كظلال خافتة. في تلك اللحظة، أدرك ثورفين أن طريقه لن يكون مفروشاً بالدماء فحسب، بل بقرارات ستحدد إن كان سيظل عبداً لماضيه، أم سيصنع لنفسه وجوداً خارج إطار الانتقام.', '', 67, '2026-07-15 15:17:47.072', '2026-07-15 15:17:47.072');
INSERT INTO public.chapters VALUES ('cb63e779-a231-44c7-b1fc-a4fdf623efd6', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 69: صدى المطرقة على سندان العزلة', '— --------------------------------------- توقف ثورفين عن تقطيع الحطب. استقرت الفأس في كتلة الخشب، محدثةً شقاً عميقاً استعصى على الانفلاق. لم تكن عضلات ذراعيه تشتكي من الإجهاد، بل كان عقله هو المعطل تحت وطأة الصمت الذي يلف المزرعة. اقترب أينار بخطوات ثقيلة، ممسكاً بقطعة خشب أخرى، ونظر إلى ثورفين الذي كان يحدق في الفراغ. قال أينار بصوت متهدج: ألا تزال تسمعهم؟ تجمعت بؤبؤة ثورفين واتسعت، بينما قبض على مقبض الفأس حتى ابيضت مفاصل أصابعه. هز رأسه بنفي قاطع، لكن ارتعاشاً طفيفاً في شفته السفلى فضح كذبه. في تلك الليلة، كان الظلام يبتلع زوايا الغرفة. استلقى ثورفين محدقاً في سقف الكوخ الخشبي، حيث تتراقص خيالات الكوابيس التي لا ترحم. في حلمه، كان الدم يغطي يديه، ليس دماء محاربين سقطوا في النزال، بل دماءً لا تنتهي، تطارده في أزقة مدينة لم يعرف لها اسماً. استيقظ فجأة، تنفسه مسموع بوضوح في السكون المطبق، قطرات عرق بارد انحدرت على صدغه. نهض وجلس على حافة فراشه، محاولاً السيطرة على دقات قلبه التي كانت تدق في أذنيه كقرع طبول حرب بعيدة. كان أينار لا يزال غارقاً في سباته، أنفاسه منتظمة، مما جعل ثورفين يشعر بالغربة أكثر. خرج ثورفين إلى الخارج، حيث كان الجو لا يزال يحمل برودة ما قبل الفجر. لم يتجه إلى العمل، بل سار نحو الحقل المفتوح. كانت الأرض تحت قدميه قاسية وغير مبالية بوجوده. تذكر كلمات أسكلاد، تلك السخرية اللاذعة التي كانت تخترق درعه النفسي كالسهم المسموم. لم يعد هناك صوت يوجهه، ولا غاية يركض خلفها، سوى ثقل الذنب الذي يزداد وطأة مع كل بزوغ فجر. التفت ثورفين نحو الأفق، حيث تبدأ خيوط النور الأولى في اختراق السواد. قال لنفسه بصوت خافت لم يسمعه غيره: لا أحد يحمل سيفاً هنا. ومع ذلك، كان ثقل النصل لا يزال يضغط على كفه الفارغة. التقط ثورفين حجراً عن الأرض وقذفه بكل قوته نحو المدى البعيد، مفرغاً صرخة مكتومة لم تخرج من حنجرته، بل بقيت محبوسة في صدره، صرخة رجل يحاول التكفير عن حياة كاملة من القتل، في عالم لا يعرف سوى لغة النصل والدم.', '', 68, '2026-07-15 15:17:47.244', '2026-07-15 15:17:47.244');
INSERT INTO public.chapters VALUES ('d4456397-6853-4df2-85d9-022da20db41f', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 70: خلف أسوار المزرعة', '— --------------------------------------- توقف ثورفين عن تقليب التربة حينما تعالت صرخات الحراس من جهة البوابة الرئيسية. وضع المعول جانباً، ومسح بيده المتسخة عرقاً بارداً تسلل إلى عينيه. كان إينار يقف بجانبه، ممسكاً بمقبض المحراث بقوة حتى ابيضت مفاصل أصابعه. في تلك اللحظة، ظهر كنوت. لم يكن مظهره يوحي بأنه ملك، بل بدا كشخص أرهقته السنون رغم صغر سنه، تحيط به هالة من الصمت الثقيل الذي جعل الجنود يتراجعون بضع خطوات إلى الوراء. تقدم كنوت نحو ثورفين، عيناه الزرقاوان ثابتتان، تخترقان كل الحواجز التي وضعها ثورفين حول نفسه. نطق كنوت بصوت خفيض، خالٍ من أي نبرة آمرة: ألا تزال تحمل الحقد يا ثورفين؟ انتصب ثورفين، عض على شفته السفلى حتى كاد الدم يقطر منها. لم يجد رداً جاهزاً. ذكريات الحرب، رائحة الغبار في المعارك القديمة، ووجه أسكلاد الذي لا يفارقه، كلها تلاطمت في ذهنه كأمواج عاتية. قال ثورفين بصوت أجش ومتقطع: لم أعد مقاتلاً يا كنوت. لم أعد أملك رغبة في القتل. ابتسم كنوت ابتسامة باهتة، كانت خالية من السخرية، أشبه بمرآة تعكس خيبة أمل مشتركة. نظر حوله إلى الحقول الممتدة، ثم أعاد بصره إلى ثورفين: الأرض لا تطلب دماً، لكن الرجال يصرون على إراقة المزيد. هل تعتقد أن السلام ممكن في عالم مبني على الجثث؟ صمت ثورفين، ونظر نحو إينار الذي كان يراقب الحوار بتوتر شديد. شعر ثورفين بضغط في صدره، ليس ضغط الخوف، بل ضغط القرار. لم يعد يرى كنوت كعدو يسعى للانتقام منه، بل كحمل ثقيل لتاج لم يطلبه أحد. التفت ثورفين نحو إينار، ثم عاد بنظره إلى الملك وقال: سأبقى هنا. سأزرع هذا الحقل حتى يزهر. هذا هو جوابي الوحيد. ضيق كنوت عينيه، ثم أومأ برأسه ببطء، واستدار ليرحل، تاركاً وراءه صمتاً أثقل من وقع أقدام الحراس.', '', 69, '2026-07-15 15:17:47.448', '2026-07-15 15:17:47.448');
INSERT INTO public.chapters VALUES ('09a88772-8306-41b1-ab90-90d382bafa22', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 71: بذور الحقد في أرض المزرعة', '— --------------------------------------- سحب ثورفين الفأس من بين شقوق الخشب، بقعة من الدماء الجافة كانت لا تزال عالقة على حدها المعدني. في المزرعة، كانت الأجواء خانقة، ليس بسبب حرارة الشمس، بل بسبب التوتر الصامت الذي يلف المكان. نظر إليه إينار، ملامحه متصلبة وعيناه تلاحقان حركات ثورفين المترددة. سأل إينار بنبرة مشحونة بالريبة: هل تنوي حقاً القيام بذلك؟ توقف ثورفين عن مسح النصل، وتجمد في مكانه. لم تكن هناك إجابة فورية، بل انقباض في عضلات فكه وتشتت في نظراته. كانت ذكريات المعارك القديمة، صراخ الموتى، ووجه أسكلاد الذي لا يبارح مخيلته، تتدافع في رأسه كعاصفة لا تهدأ. قال ثورفين بصوت متهدج: لا أعرف. كل ما أعرفه أنني لا أجد مخرجاً من هذا السجن الذي نصبته لنفسي. اقترب إينار خطوة، ووضع يده على كتف ثورفين، فارتد الأخير وكأنما لسعته نار. صاح ثورفين: ابتعد! لا تلمسني. كان الحوار بينهما يتحول إلى اشتباك لفظي، حيث يحاول إينار استعادة إنسانية رفيقه التي يبدو أنها تذوب تحت وطأة ذنوبه الماضية. في تلك اللحظة، كان الفضاء في المزرعة يضيق، حيث تلاشت أصوات الحقول وحلت محلها خفقات قلوبهم المتسارعة. تذكر ثورفين كلمات والده عن المحارب الحقيقي، لكن الصدى كان ضعيفاً، يغرق في ضجيج رغباته المكبوتة للانتقام. لم يكن إينار يرى فيه سوى إنسانٍ يحاول النجاة، بينما كان ثورفين يرى في نفسه مسخاً لا يستحق الخلاص. وبينما كانت الشمس تميل نحو الغروب، تاركةً ظلالاً طويلة وموحشة على الأرض المحروثة، وقف ثورفين وسط صمته القاتل، يدرك أن كل خطوة يخطوها نحو السلام هي معركة أصعب من أي حرب خاضها بالسيف.', '', 70, '2026-07-15 15:17:47.612', '2026-07-15 15:17:47.612');
INSERT INTO public.chapters VALUES ('efef76bd-1e45-4164-bc36-335c5cd950ff', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 72: بذرة في أرض القحط', '— --------------------------------------- انغرس المجذاف في مياه النهر الضحلة، محدثاً طرطشة خافتة كسرت رتابة الرحلة. كان ثورفين يحدق في الأفق، حيث تتقاطع الغابات الموحشة مع السماء الرمادية. لم يعد السيف الذي يتدلى من خصره يشكل وزناً مألوفاً، بل بات مجرد قطعة حديد صدئة تثقل خطاه. التفت إينار بجانبه، ماسحاً العرق عن جبينه بظهر كفه الخشنة، وقال بنبرة متهدجة: هل تعتقد حقاً أن هذه الأرض ستمنحنا شيئاً؟ نحن نحفر في الصخر وننتظر من الجليد أن ينبت. توقف ثورفين عن التجديف، وساد صمت ثقيل لم يقطعه سوى طنين الحشرات في الأرجاء. لم يلتفت إليه، بل ظل مسمراً ببصره نحو التلة البعيدة، وأجاب بصوت مقتضب، جاف كأرض قاحلة: إذا لم تحفر، فلن تعرف أبداً. لم يكن صوته يحمل وعيداً أو أملاً زائداً، بل كان صوتاً يفتقر إلى طعم الحياة التي عرفها سابقاً. استدار إينار ليواجهه، كانت عيناه مليئتين بأسئلة لم يجرؤ على نطقها، لكنه اكتفى بهز رأسه ومتابعة العمل. في تلك اللحظة، لم يكن هناك عدو يتربص خلف الأشجار، ولم تكن هناك دماء تلطخ يديه، فقط طين الأرض الذي يلتصق بأظافره. تذكر ثورفين، في ومضة خاطفة، وجه والده، تلك الملامح التي كانت تشع بهدوء غريب وسط ساحات الموت. حاول أن يجد في ذاكرته تلك الطمأنينة، لكنها ظلت بعيدة، مغطاة بطبقات من الغبار والذكريات المرة. هز رأسه بقسوة ليطرد الفكرة، وأمسك بالمجذاف مجدداً بضغط متزايد على مفاصل أصابعه، مغوراً إياه في الماء بقوة أفرغت كل ما في صدره من شجن مكتوم. قال ثورفين، ونبرته أكثر حدة الآن: لا وقت للتأمل. الأرض لا تنتظر أحداً. كانت حركته في العمل ميكانيكية، دقيقة، وخالية من أي تردد. لقد استبدل رقصة الموت التي كان يتقنها برقصة البقاء تحت شمس باردة، مدركاً أن كل حركة يقوم بها هي صرخة صامتة ضد ماضيه الذي يرفض أن يغادر مخيلته.', '', 71, '2026-07-15 15:17:47.816', '2026-07-15 15:17:47.816');
INSERT INTO public.chapters VALUES ('54dbf41d-66ff-424d-a5c9-20402bd17505', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 73: بذور الفناء في حقول الرقيق', '— --------------------------------------- انغرس طرف المنجل في ساق القمح الجاف، محدثاً خريراً خافتاً يكسر صمت الحقل الممتد تحت شمسٍ لا ترحم. لم يلتفت ثورفين لصوت خطوات إينار التي تقترب، بل استمر في حصد الحزم بقبضات متشنجة، كانت عيناه ذابلتين، تعكسان انكساراً قديماً يرفض الالتئام. توقف إينار فجأة، ماسحاً العرق عن جبينه بطرف قميصه المتسخ، ثم نظر إلى ثورفين قائلاً بنبرة مشوبة بالحيرة: ألا تشعر بعبثية هذا يا ثورفين؟ نحن نحصد لنمو سيد لا يعرف أسماءنا، ونأكل لنستمر في الحصاد. القمح ينمو من دماء أهلي، وأنت تحصد لتعيش يوماً آخر في حفرة الجحيم هذه. لم يجب ثورفين، بل زاد من حدة ضرباته بالمنجل حتى تطاير القش في الهواء. تنفس ثورفين بعمق، كان صدره يعلو ويهبط بوتيرة مضطربة، ثم همس بصوت أجش بالكاد يلامس مسمع إينار: لا تفكر. التفكير في الحقل يقتل ما تبقى منك. الصمت ساد بينهما مجدداً، لم يكن صمتاً تصالحياً، بل كان جداراً من الغبار والقيظ. في تلك الأثناء، كان باتل يعتلي حصانه في الأفق، يراقب المشهد بعينين ضيقتين لا تخفيان احتقاره المعتاد للعبيد، صرخ بصوتٍ أجش يمزق سكون الظهيرة: عودوا إلى عملكم أيها الجرذان! الأرض لا تنتظر المتثائبين! لم يرفع ثورفين رأسه، ولم يظهر على وجهه أي أثر للضيق أو الخوف؛ كان وجهه قناعاً من جليد لا يذوب. واصل العمل بحركة ميكانيكية دقيقة، وكأن جسده قد انسلخ عن روحه المعذبة. إينار، الذي لم يحتمل هذا البرود، قبض على مقبض منجله بقوة حتى ابيضت مفاصل أصابعه، ورمق ثورفين بنظرة حادة متسائلاً: كيف تستطيع تحمل هذا؟ كيف تطفئ النار التي في صدرك؟ التفت ثورفين أخيراً، كانت عيناه فارغتين من أي بريق، ونظر إلى إينار طويلاً قبل أن يقول باقتضاب: النار تحرقني كل ليلة في أحلامي، وفي النهار… أتركها تموت جوعاً خلف جدران عقلي. عاد ثورفين لينحني فوق الأرض، يقطع السيقان بلا هوادة، تاركاً إينار يراقب انحناءة ظهره المنهك تحت شمس كانت توشك أن تغرب، مخلفةً وراءها ظلالاً طويلة ممتدة، كأنها ندوب على وجه الأرض التي لا تشهد إلا ذل الرجال وقسوة المواسم.', '', 72, '2026-07-15 15:17:48.062', '2026-07-15 15:17:48.062');
INSERT INTO public.chapters VALUES ('e92d2c34-d21c-4ec9-b5ab-83cf0f0cbb97', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 74: بذور الحصاد المر', '— --------------------------------------- انغرس النصل في الطين المبتل بصوت مكتوم، سحب ثورفين سيفه تاركاً خلفه ثلمة في التربة القاسية. كان الحقل في مزرعة كيتيل يمتد أمام ناظريه كلوحة شاحبة من سنابل القمح المنهكة بفعل الخريف. التفت إليه أينار، يمسح العرق المتساقط عن جبينه بظهر كفه الخشنة، وقال بصوت متهدج: ألا ترى أننا بالغنا اليوم؟ إن أجسادنا ليست من حديد يا ثورفين. لم يجب ثورفين، بل اكتفى بتصويب نظره نحو الأفق، حيث تلوح غيوم رمادية ثقيلة تنبئ بمطر وشيك. تحركت أصابع ثورفين المليئة بالندوب لتتحسس قبضة سيفه الملقى جانباً، كانت تلك الحركة لا إرادية، ذكريات القتل والرماد تطوف في رأسه كأشباح لا ترحل. اقترب منه أينار ببطء، وضع يده على كتفه، مما جعل ثورفين ينتفض بجسده بالكامل، انكمشت عضلات كتفيه استجابة لرد فعل غريزي اعتاد عليه في سنوات الجحيم. هدئ من روعك، نحن هنا في سلام، لا صراخ هنا ولا دماء، فقط هذه الأرض التي نفلحها بدمائنا لتطعمنا في الشتاء. أجاب ثورفين بصوت أجش بالكاد يسمع: الأرض لا تعرف الرحمة، إنها تأخذ كل ما نعطيه لها وتظل جائعة. وبينما كانا يتبادلان الصمت المثقل بالتعب، لمعت في ذهن ثورفين صورة والده ثورس، ملامحه الرصينة التي لم تكن تعرف الارتجاف، وكلماته التي لا تزال تصدى في أعماقه كجرس عتيق. لم يكن ثورس يحمل سيفاً ليقتل، بل ليحمي هذا الصمت الذي يرفضه ثورفين الآن. نظر ثورفين إلى كفيه المتسختين بالطين، كان يرى فيهما دم المئات، لم يغسلهما المطر ولم يمحُ أثرهما العمل الشاق في المزرعة. فجأة، سمع وقع أقدام ثقيلة على الطريق الترابي القادم نحو المزرعة، كانت خطوات واثقة ومنتظمة، لا تشبه مشية الفلاحين المتعبة. تجمد ثورفين في مكانه، اتسعت حدقتا عينيه وهو يلمح ظلاً يقترب، رجلٌ يرتدي ملابس لا تناسب هذا المكان المنسي. قبض ثورفين على معوله بقوة حتى ابيضت مفاصل أصابعه، وشعر ببرد غريب يتسلل إلى عموده الفقري رغم حرارة العمل، فقد عرف هذا النذير جيداً؛ الماضي لا يطرق الأبواب، بل يقتحمها بفظاظة.', '', 73, '2026-07-15 15:17:48.234', '2026-07-15 15:17:48.234');
INSERT INTO public.chapters VALUES ('b2c4d6de-ed9a-42a7-8f6e-f44a263522f2', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 75: صدى النصل في حقول القمح', '— --------------------------------------- تصلب جسد ثورفين حين تلاقت عيناه بعيني والده. لم تكن ثمة رياح تعصف، بل سكون خانق يلف مزرعة كيتيل، حيث تشتتت أصوات الحصادين في الأفق وبقي هو مسجوناً في فضاء ذكرياته. قبض ثورفين على قبضة فأسه بقوة جعلت مفاصل أصابعه تبيض، بينما ارتجفت حدقتاه في محاولة لاستيعاب هذا الطيف الذي يرتدي هيئة والده الراحل. وقف ثورس، بشموخه المعهود وكتفيه العريضتين اللتين تخفيان خلفهما أهوال ساحات القتال، ناظراً إلى ابنه بملامح لا تشوبها شائبة من لوم، بل بصدقٍ يمزق القلب. استجمع ثورفين أنفاسه، ونبرة صوته المتهدجة اخترقت الصمت: أنت لست هنا. والدي مات في ذلك اليوم، غدراً على يد أسكلاد. لم يرمش ثورس، بل اتخذ خطوة هادئة نحو ابنه، كانت وقع أقدامه على التربة الجافة تشبه دقات طبول الجنازة. أجابه بصوتٍ عميق كأنه يخرج من قاع بئر سحيقة: لستُ هنا لأحاسبك على دماء أهدرتها، بل لأرى ما الذي اخترت أن تزرعه في أرضك بعد أن توقفت يدك عن القتل. سقطت الفأس من يد ثورفين لترتطم بالأرض بصوت أجش. انحنى جسده، وتدفقت ذكريات النيران والدماء، وجه أسكلاد الساخر، وصيحات الموتى التي لم تفارقه قط. سأله ثورفين بصوتٍ أقرب إلى الهمس المكتوم: هل كان عليّ أن أصبح قاتلاً لأفهم معنى الحياة؟ وقف ثورس فوقه، يظلله بجسده الضخم، وقال: لا أحد يولد ليموت في ساحة المعركة، لكن كل واحد منا يبني معناه الخاص من ركام خطايا الماضي. لا تنظر إلى الخلف، فالعشب ينمو من فوق القبور، وأنت اليوم لست ذلك الطفل الذي يبحث عن الانتقام، أنت رجلٌ قرر ألا يرفع سيفه. غابت ملامح ثورس تدريجياً في ضباب الحلم، تاركةً ثورفين وحيداً وسط الحقول الواسعة. استدار ثورفين نحو أفق المزرعة، ومسح العرق عن جبينه. لم تكن يداه ترتجفان بعد الآن، بل بدأ يشعر بصلابة الأرض تحت قدميه. اقترب منه إينار، واضعاً يده على كتفه، ليسأله بقلق مريب: ثورفين، هل أنت بخير؟ لقد توقفت عن العمل فجأة. نظر ثورفين إلى السماء الصافية، ثم إلى كفيّ يديه الملطختين بتراب الأرض لا بدم الأعداء، وأجاب بهدوء غير مسبوق: أنا بخير، إينار. لنكمل العمل، فالحصاد لا ينتظر.', '', 74, '2026-07-15 15:17:48.59', '2026-07-15 15:17:48.59');
INSERT INTO public.chapters VALUES ('9895af33-b9f4-4626-9201-2dd9befe3b7a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 76: صدى النصل والقيود', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه غارقتين في وحل المزرعة الممتد نحو الأفق، لكن عقله لم يكن هنا. ثقل السيف الذي اعتاد حمله في يده اليمنى كان قد تبخر، تاركاً فراغاً لا يملأه سوى أشباح الماضي التي تنهشه في أوقات السكينة. رفع رأسه، محاولاً تجاهل أصوات الجلادين وتأوهات الرجال المقيدين في الساحة المجاورة، لكن أذنه التقطت صوتاً مألوفاً، صوتاً يحمل مرارة السنين. نظر نحو المدخل حيث كان ''إينار'' يقف، ملامحه تعكس مزيجاً من الرعب والارتباك. لم يتبادل الرجلان الكلمات؛ ففي هذه اللحظة، كان صمت إينار أبلغ من أي احتجاج. اقترب ثورفين من الأسير الملقى أرضاً، كان الرجل يرتجف، ليس من برد الشتاء، بل من هول المصير الذي ينتظره تحت نير السادة. انحنى ثورفين، ملامح وجهه خالية من أي انفعال ظاهر، لكن عروق يده التي ضغطت على ركبته كانت بارزة. نظر الأسير إلى عيني ثورفين، باحثاً فيهما عن رحمة، فلم يجد سوى مرآة لحياته القاسية. قال ثورفين بصوت خشن ومقتضب: لا تتحرك، سأفك قيدك. كان الحراس يراقبون من بعيد، يتبادلون نظرات التشكيك والسخرية. أحدهم بصق على الأرض وقال بصوت أجش: انظروا إليه، يظن نفسه مخلصاً وهو لا يملك حتى قميصاً نظيفاً. تجاهل ثورفين الإهانة؛ فقد اعتاد أن تكون الكلمات أسلحة لا تصيب إلا من يمنحها قيمة. بلمسات سريعة ومتقنة، تمكن من حل العقدة التي كانت تكبل معصمي الأسير، رغم اعتراضات إينار الذي همس بحذر: ثورفين، هذا جنون، ستجلب علينا غضب ''كيتيل''. لم يلتفت ثورفين، بل وقف منتصباً، ونظراته تتجاوز سياج المزرعة نحو الغابات البعيدة، حيث لا وجود لسيد ولا لعبد. أجابه ببرود تام: لا أحد يملك حق تصفيد روح إنسان آخر. كانت هذه الجملة كفيلة بإنهاء الحوار. تحرك إينار خطوة إلى الوراء، متأملاً في هذا الرفيق الذي قضى سنوات في الحروب ثم عاد ليحمل وزناً أخلاقياً أثقل من أي درع فولاذي. في تلك اللحظة، اقترب الحارس بخطوات ثقيلة، يده على مقبض سيفه، صوته المتهكم يمزق سكون المكان: هل تظن أن شجاعتك ستنجيك من العقاب، أيها العبد؟ التفت ثورفين ببطء، اتسعت حدقتا عينيه للحظة وهو يقيس المسافة بينه وبين الحارس، جسده متأهب، لا كقاتل، بل كشخص قرر أن يضع حداً لكل ما يراه من طغيان، حتى لو كان الثمن حياته.', '', 75, '2026-07-15 15:17:48.84', '2026-07-15 15:17:48.84');
INSERT INTO public.chapters VALUES ('68225ec5-3214-44a2-8905-c4578eccbfb2', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 77: بذور السلام في أرض الرماد', '— --------------------------------------- توقف ثورفين عن الجري حين تلاشت أصداء صراخ إينار في المدى. كان ثقل القيدين الحديديين في معصميه يذكره بتبعيته، لكن عقله لم يكن هنا؛ بل في تلك المساحات الشاسعة من أرض المزرعة التي لم تكن يوماً ملكاً له. التفت ليجد إينار واقفاً، أنفاسه متسارعة، وصدره يعلو ويهبط بعنف. لم تكن المسافة الفاصلة بينهما مجرد أمتار، بل كانت هوة من الذكريات المحفورة بالدم. قال إينار وصوته يتهدج بين الغضب والارتباك: أنت لا تفهم، تلك الأرض لم تكن مجرد تراب، كانت حياتنا. ضيق ثورفين عينيه، وشد على قبضة يده حتى تلونت مفاصل أصابعه بالبياض. لم يرد بعبارات الاعتذار المعتادة التي تمقتها نفسه، بل اكتفى بكلمات مقتضبة كأنها صخرة تسقط في قاع بئر: أعرف. ما الذي تريده مني الآن؟ ارتجف كتف إينار، ثم اندفع بخطوة واحدة نحو ثورفين، كاد يلامس وجهه، صارخاً: أريدك أن تحيا كما فعلتُ أنا. أريدك أن ترى ثمار الحنطة التي زرعناها، أن تشعر بالتراب تحت أظافرك بدل بقع الدماء. إن أردت العيش، فعليك أن تنزع روح المحارب التي تسكنك، تلك الروح هي التي قتلت عائلتي، وهي التي ستقتلنا جميعاً. ساد صمت ثقيل، لم يقطعه سوى خرير مياه الجدول البعيد. نظر ثورفين إلى كفيه، كانتا خشنة من العمل، لكن ندوب السيوف القديمة كانت لا تزال تشق جلده كخرائط لأزمنة غابرة. تذكر كلمات والده ثورس، تلك الهمسات التي تلاشت في ضجيج الحروب: لا أعداء لك. تلاشت حدة نظرات ثورفين، وانطفأت تلك الشعلة الضارية التي لطالما حركته، ليحل محلها فراغ وجودي موحش ولكنه صافٍ كمرآة. ليس لدي ما أعود إليه، تمتم ثورفين، ونبرته انخفضت لتصبح مجرد حشرجة خافتة، ولكن، ربما، يمكنني البدء من هذا التراب. لم تكن كلمات اعتذار، بل كانت اعترافاً بضعفٍ بشري لم يعهده من قبل. تنفس إينار الصعداء، وأرخى قبضته، تاركاً إياها تسقط بجانبه. نظر كلاهما إلى الأفق، حيث بدأت الشمس تغيب خلف تلال المزرعة، تاركة وراءها مسحة من الأرجواني على حقول القمح. في تلك اللحظة، لم يكن هناك مقاتل ولا ضحية، بل رجلان يحاولان فهم ثقل الحياة في عالمٍ لا يعرف الرحمة.', '', 76, '2026-07-15 15:17:49.074', '2026-07-15 15:17:49.074');
INSERT INTO public.chapters VALUES ('1da364a5-df02-482c-bcde-99dda7bc8749', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 78: خلف أسوار العبودية', '— --------------------------------------- انغرس طرف المعول في التربة القاسية محدثاً صوتاً مكتوماً، وسرعان ما تبعته دفعة قوية من كفي ثورفين الملطختين بالتراب. كان العرق ينحدر على جبينه، يمتزج بغبار الأرض ليخط مسارات طينية على وجهه الشاحب. بجانبه، كان إينار يلهث بصوت مسموع، صدره يعلو ويهبط بانتظام مضطرب. لم تكن هناك كلمات بينهما منذ ساعات؛ فالعمل هنا في مزرعة كيتيل لم يترك مجالاً للثرثرة. توقف ثورفين فجأة، مسح جبينه بظهر يده، ونظر إلى الأفق حيث تمتد الحقول التي حولوها من أرض بائرة إلى حقول قمح واعدة. صمت إينار هو الآخر، وتلاقت أعينهما للحظة. قال إينار بصوت أجش ومتقطع من الإرهاق: أتعتقد حقاً أننا سننتهي من تطهير هذه القطعة قبل مغيب الشمس؟ مسح ثورفين بؤرة نظره بالأرض ولم يجب على الفور. كانت ملامحه جامدة، وكأن ندوب الماضي قد حفرت في وجهه قناعاً من اللامبالاة. أجاب ثورفين بكلمات مقتضبة: لا يهم الوقت. المهم أن نواصل. استأنف الضرب بالمعول، عضلات ذراعيه تبرز وتتقلص بجهد ميكانيكي. لم يكن في حركته رغبة في العنف التي ميزت أيامه السابقة، بل كان هناك نوع من الخضوع المنهجي للعمل الشاق. فجأة، اخترق السكون صوت حوافر خيول تقترب بسرعة. توقف الرجلان عن العمل. من بعيد، كان غبار يرتفع، وظهرت هيئة خيال أحد حراس المزرعة يمتطي جواده بزهو، يتبعه عدد من الرجال الذين يبدون غرباء عن طبيعة المزرعة. اقترب الحارس، وبدت على وجهه ملامح الامتعاض وهو ينظر إلى ثورفين وإينار. صاح الحارس بصوت أجوف: توقفا عن التحديق. أيها العبيد، عودوا إلى العمل ولا ترفعوا رؤوسكم حتى تسمعوا صراخ العشاء. لم يرمش ثورفين. بقيت عيناه مثبتتين على الحارس بنظرة خالية من التحدي، ولكنها أيضاً خالية من الخوف. هذه النظرة تحديداً هي التي أزعجت الحارس، فشد لجام حصانه ليرتفع بضعة سنتيمترات قبل أن يزجر به مبتعداً. بعد رحيلهم، اقترب إينار من ثورفين هامساً، غيظ مكتوم يغلي في نبرته: ألا تشعر بذلك؟ تلك النظرة التي ينظرون بها إلينا… كأننا قطعان ماشية لا تملك حتى حق الشعور بالإهانة. توقف ثورفين عن الحفر تماماً، وألقى نظرة سريعة نحو المكان الذي اختفى فيه الحراس. لم تكن في عينيه شرارة الغضب القديمة، بل وميض باهت لشيء أكثر تعقيداً، شيء يشبه التصميم. قال ثورفين بنبرة خفيضة ومباشرة: لا تلتفت للغضب يا إينار. الغضب يستهلك طاقتنا، ونحن بحاجة إليها لنخرج من هنا كرجال أحرار. سكت إينار، ونظر إلى يديه اللتين بدأت تظهر عليهما بثور العمل، ثم نظر إلى ثورفين بإعجاب صامت. كانت الشمس تميل نحو الغروب، تاركة ظلالاً طويلة تمتد عبر الحقل، ظلال رجلين محاصرين بواقع قسري، لكنهما في لحظة السكينة هذه، كانا ينسجان خيوط مستقبلهما بعيداً عن صخب الحروب والسيوف.', '', 77, '2026-07-15 15:17:49.299', '2026-07-15 15:17:49.299');
INSERT INTO public.chapters VALUES ('6f731a67-7b5d-4dc8-be87-cc8a8ec74eb9', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 79: خلف أسوار المزرعة', '— --------------------------------------- انغرس طرف المنجل في التربة الطينية، ليرفع ثورفين كومة من الأعشاب الضارة، عروقه بارزة على ساعديه المحروقتين من لفح الشمس. لم يكن هناك صمت، بل ضجيج رتيب من احتكاك الأدوات المعدنية بالأرض. توقف ''إينار'' عن العمل، مسح جبينه بيده الموحلة، ونظر نحو ثورفين الذي كان غارقاً في صمته المعتاد. قال إينار بصوتٍ أجش: ''لقد تجاوزنا المساحة المتفق عليها مع السيد كيلتيل، إذا أنهينا هذا الجزء اليوم، فقد نحصل على فائض من الحبوب قبل حلول الشتاء''. لم يرد ثورفين، اكتفى بهز رأسه موافقاً. في تلك اللحظة، اخترق هدوء الحقول صوت حوافر خيول تقترب بسرعة غير مألوفة، لتتوقف عند أطراف الحقل. ترجل رجل يرتدي درعاً جلدياً مهترئاً، ملامحه توحي بتوترٍ مكتوم، وأشار بيده نحو ثورفين. اقترب الرجل، وكانت عيناه تتجولان بقلق بين إينار وثورفين قبل أن ينبس بكلمات متقطعة: ''أنتما… السيد كيلتيل يطلبكما في دار الضيافة. الآن''. استوى ثورفين واقفاً، نبضات قلبه ظلت مستقرة، لكن عينيه استقرتا على مقبض المنجل في يده. ''ما السبب؟ '' سأل إينار، محاولاً إخفاء نبرة الارتباك في صوته. لم يجب الجندي، بل أشار بسيفه نحو الطريق المؤدي للمنزل الكبير. سار ثورفين خلف الرجل بخطوات ثابتة، بينما كانت أفكاره معلقة بالوعود التي قطعها على نفسه. عند الوصول إلى باحة المنزل، كان المشهد مختلفاً؛ رجال مسلحون بأسلحة غريبة يحيطون بالساحة، ووجوههم غريبة عن المزرعة. كان ''كيلتيل'' يقف بمنتصف الباحة، وجهه شاحب، يفرك يديه بتوتر، بينما كان ابنه ''أولمار'' يرتجف خلفه، ممسكاً بسيفه بطريقة عشوائية تدل على غياب الخبرة التامة. تقدم ثورفين بضع خطوات، وعندما لمح الضيف الجالس على مقعد الصدارة، تصلب جسده. لم تكن مواجهة مع جنود، بل كانت مواجهة مع سلطة لم يتوقع ظهورها في هذه الأرض النائية. انزاح الظل عن وجه الجالس، فظهرت نظرة استعلائية باردة لا تأبه لحياة القرويين. ساد صمت مطبق، لم يقطعه سوى نهيق حمار من بعيد، وتنهيدة حادة من صدر أولمار الذي بدأ صوته بالارتجاف حين حاول أن يصرخ في وجه الحرس، لكن خنجراً استقر على بعد مليمترات من رقبته، جعل صوته يختنق في حنجرته. همس ثورفين لإينار دون أن يلتفت: ''لا تتدخل، مهما حدث، ابقَ في الخلف''. كان يعلم أن أي حركة متهورة تعني نهاية كل ما بناه بجهد السنين.', '', 78, '2026-07-15 15:17:49.52', '2026-07-15 15:17:49.52');
INSERT INTO public.chapters VALUES ('b5d50db2-38d4-4c30-907d-59389c00675d', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 80: خيوط العزلة في مزرعة كيتيل', '— --------------------------------------- توقف ثورفين عن تقليب التربة الصلبة، تاركاً معوله يستقر في الأرض الجافة. كانت عيناه، الغائرتان تحت وطأة ذكريات لا تهدأ، تتفرسان في الأفق حيث تتلاشى حمرة الغسق. بجانبه، كان إينار يمسح العرق عن جبينه بظهر كفه الخشنة، وقد بدت عليه علامات الإنهاك بعد يوم طويل من الكدح. «لقد أنهينا القسم الغربي، يا ثورفين،» قال إينار بصوت متهدج، مشيراً إلى الأرض التي حولوها بعناء إلى مساحة صالحة للزراعة. لم يجب ثورفين فوراً؛ بل ظل صامتاً، يراقب سرباً من الطيور يبتعد نحو الغابة. كان الصمت بينهما ثقيلاً، مشبعاً بعبء العمل اليومي الذي كان السبيل الوحيد لإسكات ضجيج الماضي في رأس ثورفين. التفت ثورفين نحوه، وبدت ملامحه أكثر حدة في ضوء الشمس الخافت. قال بكلمات مقتضبة: «غداً سنبدأ في تجريف الصخور الكبيرة قرب المجرى المائي. لا وقت للراحة.» لم يكن في صوته أي حماس، بل نبرة رجل لا يعرف طريقاً آخر سوى الإنجاز المادي. في تلك الليلة، وبينما كانا يجلسان أمام نار خافتة، بدا إينار متردداً قبل أن يفتح فمه مجدداً. «هل تساءلت يوماً، ثورفين، عما إذا كان هذا التعب كافياً؟ هل يغسل حقاً ما علق بأيدينا؟» توقف ثورفين عن مراقبة ألسنة اللهب، وارتفعت بؤبؤ عيناه قليلاً نحو إينار. قال بحدة باردة: «لا أعرف. لكن البقاء في مكاني يعني العودة إلى ما كنت عليه. العمل هو كل ما يمنعني من التفكير في الخناجر.» انقبضت كفه حول عصا خشبية كان يمسكها، وضغط عليها حتى برزت عروق ذراعه. كان إينار يدرك جيداً تلك الحالة، فابتلع كلماته واكتفى بالإيماء. في تلك اللحظة، لم يكن هناك مكان للفلسفة أو الأمل، بل فقط رجلان يحاولان طمر ماضيهما تحت طبقات من الطين والتراب، بانتظار فجر جديد لا يحمل في طياته صرخات المعارك التي تركت ندوباً لا تندمل على أرواحهما.', '', 79, '2026-07-15 15:17:49.69', '2026-07-15 15:17:49.69');
INSERT INTO public.chapters VALUES ('398cc2ea-cacf-4b31-ac11-6f527ed8b8b6', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 81: خلف أسوار المزرعة', '— --------------------------------------- انغرس طرف المعول في التربة الصلبة، فارتد الذراع بصدمة خفيفة وصلت إلى كتف ثورفين. رفع يده ممسحاً عن جبينه عرقاً اختلط بتراب الحقل. كان الصوت الوحيد المسموع هو إيقاع ضربات الفؤوس في البعيد، حيث يعمل آينار بصمت مطبق منذ الفجر. التفت ثورفين يميناً، كان آينار لا يزال غارقاً في عمله، عضلات ظهره تنقبض وتنبسط تحت قميصه الرث مع كل حركة. لم يتحدثا، فالكلمات بدت ثقيلة كأحجار الحقل التي يقتلعونها. اقترب أوليفر، المشرف على العمال، بخطوات ثقيلة جعلت التربة تئن تحت حذائه الجلدي. توقف خلف ثورفين، ورمقه بنظرة فاحصة لم تخلُ من ريبة. قال أوليفر بصوت أجش: ستنتهون من هذه البقعة قبل غروب الشمس، أو لن تنالوا نصيبكم من الخبز. لم يرفع ثورفين رأسه، بل اكتفى بهزة خفيفة من كتفيه، ثم عاد يغرس المعول في الأرض بقوة أكبر. في تلك اللحظة، قطعت ضحكات مرتفعة سكون الحقل. كان بعض المرتزقة من أتباع مالك الأرض يمرون بمحاذاة السور، يتبادلون نكاتاً فجة حول كميات الحبوب التي سرقوها لتوهم. توقف آينار عن العمل فجأة، تصلبت قبضته على مقبض الفأس حتى ابيضت مفاصل أصابعه. رمقهم بنظرة ملتهبة، غير أن ثورفين لم يلتفت إليهم؛ كان يراقب حشرة صغيرة تحاول تسلق ساق نبات قمح مائل. قال آينار بصوت منخفض، مخنوق بالغل: انظر إليهم يا ثورفين، ينهبون جهدنا ويبتسمون. ألا تشعر بشيء؟ وضع ثورفين المعول جانباً، واستقام في وقفته. اتسعت بؤبؤا عينيه قليلاً حين التقت نظراته بنظرات آينار. لم تكن في عينيه تلك الشعلة التي كان يحملها في الماضي، بل نوع من الفراغ الذي يسبق العاصفة، أو ربما الهدوء الذي يليها. رد ثورفين ببرود، نبرته خالية من أي انفعال: الغضب لن يطعمنا يا آينار. الحقل يحتاج لمن يحرثه، لا لمن يشتم المارة. صمت آينار، وأحنى رأسه مجدداً، لكنه ركل كومة من الحجارة بقدمه بعنف، متناثرة في كل اتجاه. عاد ثورفين إلى عمله، كانت يداه المشقوقتان تتحركان بآلية دقيقة. في أعماقه، كان يرى ظلال الماضي تلوح من خلف سياج المزرعة؛ أسكلاد، المعارك، صرخات المحتضرين. لكنه ضغط على أسنانهم، وطرد تلك الصور. الأرض هي الواقع الوحيد الذي لا يكذب. حين مالت الشمس نحو الأفق، تاركةً خلفها خيوطاً برتقالية باهتة على وجه الأرض، توقفا عن العمل. كان الجسد يصرخ من الإرهاق، لكن الذهن كان ساكناً. قال ثورفين، وهو يمسح التراب عن ثيابه: غداً سننهي القسم الشمالي. لم يجب آينار، بل اكتفى بالتحديق في الغابة البعيدة، حيث كانت الظلال تتمدد لتبتلع تفاصيل الحقل، تاركةً إياهما في صمت يقطعه فقط حفيف الأعشاب الجافة.', '', 80, '2026-07-15 15:17:49.913', '2026-07-15 15:17:49.913');
INSERT INTO public.chapters VALUES ('0497a3f8-a509-45d7-97a0-e4ce70b2c040', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 82: خيوط المصير في أرض الجليد', '— --------------------------------------- انغرس نصل السكين في رقعة الجلد المدبوغ بحدة، مزق ثورفين الهواء بحركة خاطفة قبل أن يغرس خنجره في قطعة اللحم القاسية. لم يرفع عينيه عن طاولة العمل الخشبية الملطخة ببقايا الزيت والصمغ. كان صوت النصل يرتطم بالخشب هو الإيقاع الوحيد في الغرفة، حتى اخترق السكون صوت ثقيل لخطوات رجل لا يزال يحمل ثقل السنين على كتفيه. رفع ثورفين رأسه، التقت عيناه بنظرات إينار الذي وقف عند عتبة المدخل، يمسح بيده كفه المغطاة بغبار الحقول. قال إينار بصوت متهدج: ألم تكتفِ من هذا العمل؟ لقد حل المساء يا ثورفين. لم يجب ثورفين، بل ألقى بالنصل جانباً واتجه نحو الكوة التي تسمح بمرور ضوء القمر الشاحب. قال ثورفين بصوت أجش، متجاهلاً نبرة القلق في صوت صاحبه: العمل لم ينتهِ بعد. أومأ إينار برأسه، وسار نحو زاوية الغرفة حيث تراكمت الحزم الخشبية. ألقى بنفسه على مقعد خشبي خشن، وقال بنبرة متهكمة: الحلم الذي رأيته الليلة الماضية، كان غريباً يا رفيق. رأيتُ نفسي أطارد ذئباً لا يملك وجهاً، وحين أدركته، لم يكن هناك سوى فراغ. تنهد ثورفين والتفت إليه، كانت ملامحه حادة كصخرة نحتتها الرياح، لم يبدُ عليه أدنى أثر للدهشة أو الانفعال. قال بنبرة جافة: الأحلام لا تعني شيئاً يا إينار. الأهم هو ما سنفعله حين تشرق الشمس. تلاشت ابتسامة إينار، وانعقد حاجباه وهو ينظر إلى يدي ثورفين المليئة بالندوب، ثم قال: هل ستظل حبيس هذا الغضب؟ لقد مر وقت طويل، والجروح التي تحملها بدأت تندمل، لكنك تصر على كشطها بيدك. وضع ثورفين يده على مقبض سيفه القديم المعلق بجانبه، صمت للحظات كان فيها صوت تنفسهما المتلاحق هو الشيء الوحيد المسموع، ثم قال بحدة: لا أملك ترف النسيان. النسيان هو امتياز للأحرار، ونحن ما زلنا عبيداً لماضٍ لم يتركنا وشأننا. اقترب إينار خطوة، مد يده كأنه يريد وضعها على كتف الآخر، لكنه توقف في اللحظة الأخيرة، مفضلاً الحفاظ على تلك المسافة التي يفرضها ثورفين حول نفسه. قال إينار بنبرة خافتة: العبودية ليست في القيود التي وضعوها في معاصمنا، بل في الأفكار التي نغذيها في رؤوسنا. سكت ثورفين، اتسعت حدقتا عينيه للحظة وهو ينظر إلى البعيد، عبر نافذة الغرفة الصغيرة إلى الحقول التي يغطيها الصقيع، وكأنه يرى وجوهاً لم تعد موجودة. لم يضف شيئاً، بل عاد ليحمل خنجره، وبدأ ينحت قطعة الخشب بتركيز مفرط، تاركاً إينار في صمته المطبق، بينما كان الليل في الخارج يبتلع آخر خيوط الضوء في الأفق.', '', 81, '2026-07-15 15:17:50.094', '2026-07-15 15:17:50.094');
INSERT INTO public.chapters VALUES ('f856c350-0701-45d0-a06e-9240064db317', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 83: بذور السلام في أرض العبيد', '— --------------------------------------- انحنى ثورفين فوق الأرض الرطبة، كانت يداه المشقوقتان تغوصان في التربة السوداء، تسحبان بقايا الجذور العالقة. خلفه، كان إينار يراقب بصمت، يمسح العرق عن جبينه بساعده الخشن. لم تكن المزرعة مجرد مساحة للعمل الشاق، بل كانت جبهة قتال جديدة، تختلف في طبيعتها عن ساحات الدماء التي ألفها ثورفين، لكنها لا تقل عنها قسوة. التفت إينار نحو ثورفين، وقال بنبرة متهدجة من التعب: ''نحن لا نتوقف، أليس كذلك؟ هل تعتقد حقاً أن هذا المحصول سيكفينا لنشتري حريتنا قبل حلول الشتاء؟ ''. رفع ثورفين رأسه، لم تكن عيناه تحملان ذاك البريق القاتل الذي ميزه في السابق، بل نظرة ثابتة تخلو من التردد. أجاب بكلمات مقتضبة: ''سيكفي. علينا أن نواصل العمل حتى نكسر هذه القيود، لا خيار آخر أمامنا''. كان الحوار يقتطع من صمت الحقول الممتدة. أخذ إينار نفساً عميقاً، ثم أضاف: ''أحياناً أشعر أن الحقد الذي كان يغلي في صدري بدأ يبرد، ليس لأنه اختفى، بل لأن العمل اليدوي يستنزف كل ما هو متبقٍ من غضبي''. لم يرد ثورفين فوراً، بل عاد إلى تقليب التربة، محدثاً خربشة مسموعة في سكون الغروب. وفجأة، اقتربت خطوات ثقيلة على العشب المجاور، كان السيد ''كيتيل'' يسير بتثاقل نحوهم. توقف الرجل العجوز، متأملاً الفوضى المنظمة التي صنعها الشابان في الحقل. اقترب كيتيل ووضع يده على كتفه، ثم قال بصوت متهدج: ''لقد قمتما بعمل جيد. العمل في الأرض هو الطريق الوحيد لنسيان صخب العالم الخارجي''. لم يرفع ثورفين بصره تماماً، لكنه توقف عن العمل، شاعراً بثقل نظرات كيتيل التي لم تكن تحمل مكر السادة، بل كانت تنم عن رجل يحاول الحفاظ على ما تبقى من إنسانيته في عالم يغرق في العنف. في تلك اللحظة، لم تكن هناك سيوف تتقاطع، بل صمت ثقيل مشحون بإدراك عميق؛ كلاهما كان يهرب من ماضٍ يطارده بظلاله، كلاهما يبحث عن معنى وسط هذا الغبار والتعرق. غابت الشمس خلف التلال، تاركةً خلفها خيوطاً برتقالية باهتة على وجوههم، بينما استمر ثورفين في تفتيت كتل الطين بين أصابعه، وكأنه يفكك صراعات سنين طويلة، عاقداً العزم على أن ما يبنيه اليوم بالبذور، هو الشيء الوحيد الذي لن يضطر لاحقاً لتلطيخه بالدماء.', '', 82, '2026-07-15 15:17:50.296', '2026-07-15 15:17:50.296');
INSERT INTO public.chapters VALUES ('c7a699c7-7d2c-4eca-9628-2d3f21e095b5', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 84: بذور السلام في أرض العبيد', '— --------------------------------------- انحنى ثورفين بظهره المنهك تحت وطأة الحزمة الثقيلة، مقتلعاً جذور الشجيرات الميتة بيديه اللتين تآكل جلدُهما وتصلب. لم تكن الغابة في مزرعة كيتيل تسمح بالرحمة؛ الأرض طينية لزجة تلتصق بالثياب وتجعل كل خطوة نضالاً صامتاً. بجانبه، كان أينار يتنفس بانتظام، وقد غطى الغبار وجهه، لكن عينيه ظلتا يقظتين تراقبانه. قال أينار صوته خشن من جفاف الحلق: لن ننتهي قبل مغيب الشمس يا ثورفين، إذا استمرت وتيرتنا هذه سنظل نقتلع الجذور حتى يكسونا الصقيع. توقف ثورفين، مسح جبهته بساعده الملطخ بالتراب، ولم يجب فوراً. ارتعدت عضلات كتفيه من الإجهاد المتراكم. كانت رؤاه لا تزال تطارده في النوم؛ صور الحروب القديمة، السيوف التي تنهش اللحم، صراخ الموتى الذي لا يهدأ. هز رأسه بقوة محاولاً طرد الأشباح. أضاف أينار بنبرة أقل حدة: أنت تفكر مجدداً، أليس كذلك؟ تلك الكوابيس التي تجعل جسدك يتشنج في منتصف الليل. نظر ثورفين إلى يديه، ثم أغمض عينيه للحظة؛ لم يكن الخوف هو ما يدفعه للارتجاف، بل الندم الذي ينهش في أعماقه كحيوان مفترس. قال ثورفين بصوت مكتوم وأجش: إنهم لا يرحلون. كلما حاولت أن أبدأ يوماً جديداً، استيقظت على أصواتهم. ساد صمت مطبق إلا من صوت حفيف الأشجار البعيدة. لم يكن هناك وعظ في كلماته، فقط حقيقة قاسية يواجهها يومياً. التقط أينار فؤساً صدئاً وبدأ بضرب الأرض بعنف موجه، وكأنه يفرغ كل غضبه المكبوت ضد ظروف عبوديتهما. نحن لسنا قتلة بعد الآن يا ثورفين، نحن مزارعون، قال أينار وهو يلهث، هذه الأرض هي التي ستحررنا، لا السيوف التي دفناها. لم يرد ثورفين؛ كان يدرك أن الحرية أبعد مما يتخيل زميله، لكنه أومأ برأسه موافقاً. انحنيا مجدداً، وشرعا في تقليب التربة، صامتين، بينما كانت الشمس تهم بالغروب خلف التلال، تاركة خلفها أفقاً بلون الدم، لونٍ ذكّر ثورفين بدرس قديم لم ينسه قط: أن السلام لا يُمنح، بل يُنتزع من وسط الحطام.', '', 83, '2026-07-15 15:17:50.51', '2026-07-15 15:17:50.51');
INSERT INTO public.chapters VALUES ('787e9955-ec73-43e2-8a11-e1c15da0e9f4', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 85: حقول القمح وميزان العدالة', '— --------------------------------------- انحنى ثورفين فوق الأرض، متمسكاً بحفنة من التربة السوداء الرطبة، بينما كان هدير الرياح يتقطع خلفه. لم تكن هناك دماء على يديه اليوم، بل بقايا طين التصق بأظافره. خلفه، كان إينار يقف متهالكاً، يمسح العرق عن جبينه بساعده الخشن، وعيناه لا تزالان معلقتين بصفوف القمح التي بدأت تشق طريقها نحو الحياة وسط حقلٍ كاد أن يُدمر. التفت إينار، صوته مبحوح من عناء العمل الطويل: ''ثورفين، هل تعتقد أن هذا يكفي حقاً؟ أن نزرع ونحصد لنشتري حريتنا؟ ''. لم يرفع ثورفين رأسه، بل نقر بيده على الأرض وكأنه يختبر صلابتها. قال بصوت منخفض، جاف من أي انفعال: ''لا خيار آخر. القوة لن تحررنا هنا، والقتل ليس خياراً متاحاً''. تجمد إينار في مكانه للحظة، مستذكراً ومضات الماضي، تلك الندوب التي لم تندمل في ذاكرتهما معاً. لم تكن فلسفةً، بل كانت حقيقة مادية قاسية يفرضها عليهما السجن والعمل الشاق. اقترب أوليفر، صاحب المزرعة، يجر قدميه في مشية ثقيلة تدل على تعب الأيام، ونظراته تتقلب بينهما بحذر. توقف على مسافة قصيرة، ثم قال بلهجة يغلفها التردد والشك: ''الأرض تعطي من يخدمها، لكن الحقد لا ينمو إلا على الدماء. اسمعا، إذا أردتما هذه الحرية، فاعملا حتى تخرجا ما في باطن هذه التربة''. لم ينتظر ثورفين رداً، بل نهض ببطء، مفاصله تصدر طقطقة مكتومة. التفت نحو الأفق، حيث كان ثقل الأيام الماضية يضغط على صدره، لا كخوف، بل كمسؤولية ثقيلة. قال ثورفين بلهجة حادة ومباشرة: ''سنكمل. ليس لأجل الأرض، بل لأجل اليوم الذي لا نضطر فيه للنظر خلفنا''. هز إينار رأسه إيجاباً، وأمسك بالمذراة مرة أخرى، بينما تلاشت أصوات الحقول لتترك المكان لصمتٍ عملي ثقيل. كان ثورفين يدرك أن كل سنبلة تنمو هي خطوة بعيدة عن الرجل الذي كانه، ذلك الغلام الذي لم يعرف سوى صليل السيوف، والآن، يجد نفسه في صراع من نوع آخر، صراع الصبر أمام الطبيعة، وصراع الذات أمام الندم.', '', 84, '2026-07-15 15:17:50.685', '2026-07-15 15:17:50.685');
INSERT INTO public.chapters VALUES ('667bed7f-ce72-4bc8-aaaf-39bd83e1331d', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 86: خلف أسوار الرماد', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في تربة حقل البطاطس الرطبة، بينما كانت أنفاسه تتصاعد غائمة في الهواء البارد. أمامه، لم تكن هناك سوى الحقول الممتدة نحو الأفق، لكن صوته خرج أجشاً، متحشرجاً بما تراكم في صدره من أثقال السنوات: «أنا هنا… عدت يا أبتاه». لم يكن بانتظاره صوت يرد، بل صمت مطبق إلا من حفيف أوراق يابسة تتلاعب بها ريح خفيفة. نظر ثورفين إلى يديه؛ كانت ندبات النصال القديمة تغطي مفاصله، شاهدة على حياة أمضاها في سفك الدماء من أجل لا شيء. طعنة الخنجر التي وجهها له في الماضي لم تعد تؤلمه جسدياً، لكنها تركت في روحه فراغاً يبتلعه. اقترب من المنزل الخشبي المتداعي، دفع الباب العتيق ليئن تحت وطأة الضغط، كاشفاً عن فجوة مظلمة تفوح منها رائحة التراب المخزن والغبار. لم يجد أحداً، لكن طيف والده، ثورس، كان يحضر في كل زاوية، في مقبض الباب الذي كان يلمسه، وفي عتبة الدار التي خط عليها بيده. جلس ثورفين على الأرضية الخشبية، طوى ركبتيه، وأسند رأسه إلى كفيه. تذكر ليلة الحلم، تلك التي تلاحقه كظله، حيث يقف والده وسط ميدان معركة، يلقي سيفه جانباً، ويقول بصوته الرخيم الذي لا يرتجف: «يا بني، لا وجود لأعداء في هذا العالم. لا أحد يستحق الموت». سخر ثورفين من نفسه، ضحكة مريرة ومكتومة خرجت من حنجرته. لقد قاتل العالم بأسره ليثبت خطأ تلك العبارة، لكنه الآن، وسط هذا السكون، وجد أن الحقيقة هي التي طاردته. نهض ثورفين ببطء، مسح الغبار عن ملابسه، واتجه نحو الباب مرة أخرى. لم يعد الرجل الذي كان، ولم يعد ذاك الصبي المهووس بالانتقام. وقف في الخارج، رافعاً بصره نحو السماء الرمادية؛ لقد انتهت الرحلة هنا، وبدأت أخرى في أعماق نفسه، رحلة لا تتطلب سيوفاً، بل قلباً قادراً على تحمل ثقل السلام.', '', 85, '2026-07-15 15:17:50.894', '2026-07-15 15:17:50.894');
INSERT INTO public.chapters VALUES ('f167786d-1454-4ee8-a8fd-8d954a1a5d94', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 87: خلف أسوار الجليد والوعود', '— --------------------------------------- توقف ثورفين عن الحركة فجأة، ويده لا تزال تضغط على مقبض خنجره المهترئ. استقر بصره على إينار الذي كان لا يزال واقماً في مكانه، تغمره علامات الذهول. صمتت الغابة تماماً، ولم يعد يُسمع سوى طنين خافت لحشرة عالقة في العشب اليابس. التفت ثورفين برأسه ببطء، كانت ملامحه جامدة، وعيناه اللتان اعتادتا على رؤية الدم باتتا الآن تتأملان أفقاً أبعد من حدود المزرعة. قال إينار بصوت متهدج: أتعني حقاً أننا سنغادر؟ إن الرحلة نحو الغرب ليست مجرد عبور بحر، إنها غمار المجهول. حدق ثورفين في الأرض، ثم ركل حفنة من التراب بحذائه الثقيل وقال بلهجة جافة ومقتضبة: لن نبقى هنا. الأرض هنا تخصهم، والحياة هنا مقايضة بالخضوع. لا أريد خضوعاً بعد اليوم. كان ثورفين يدرك أن كل خطوة نحو الأمام تعني التخلي عن شيء من ماضيه، لكنه لم يعد يكترث. نظر إينار إلى أيدي ثورفين، لاحظ تلك الندبات القديمة التي لا تندمل، ففهم أن الرجل الذي يقف أمامه لم يعد ذلك المقاتل الهائج الذي عرفه في ذروة عذاباتهما. كان هناك هدوء مريب في نظرات ثورفين، هدوء يشبه سكون ما قبل العاصفة، لكنه لم يكن يعتزم القتال. اقترب إينار خطوة، محاولاً قراءة ما وراء ذلك الصمت: ثورفين، إذا انطلقنا، فهل نملك حقاً مكاناً نلجأ إليه؟ لم يلتفت ثورفين هذه المرة، بل اكتفى برفع بصره نحو السماء الرمادية حيث تتجمع الغيوم المحملة بالشتاء القادم. أجاب بصوت منخفض، خشن لكنه ثابت: لا مكان ينتظرنا، لكننا نصنع المكان حين نقرر ألا نكون ضحايا للآخرين. كانت كلماته تخلو من أي نبرة فلسفية منمقة، بل كانت أشبه بحقيقة مادية لا تقبل الجدل. تحرك ثورفين نحو كوخه الصغير، تاركاً إينار في حيرته، بينما كان الضباب يبدأ بالزحف بين الأشجار، غامراً المكان ببرودة قاسية، إلا أن ثورفين لم يرتجف، بل مضى في طريقه بخطوات وئيدة وواثقة، وكأنما قد عقد صفقة مع القدر لا مجال للتراجع عنها. في تلك اللحظة، لم يكن ثورفين بطلاً أسطورياً، بل كان مجرد إنسان قرر أن يضع حداً لنزيف لا ينتهي، حتى لو كان الثمن هو عبور المحيط نحو أرض لا يعرف عنها سوى اسمها.', '', 86, '2026-07-15 15:17:51.106', '2026-07-15 15:17:51.106');
INSERT INTO public.chapters VALUES ('b636afa0-56d0-42ac-b093-32579a4efefe', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 88: بذور السلام في أرض العبيد', '— --------------------------------------- انحنى ظهر ثورفين وهو يغرز مجرفته في التربة القاسية للمزرعة، كان العرق يتصبب من جبينه ليمتزج بغبار الأرض الجافة. بجانبه، كان إينار يلهث، أنفاسه المتقطعة تخترق صمت الحقول الممتدة. التفت إينار نحو ثورفين، عيناه محتقنتان بوميض غضب خافت، وقال بصوت أجش: لماذا تتحمل هذا؟ لقد ضربوك حتى كادت أنفاسك تخرج، ومع ذلك عدت للعمل كأن شيئاً لم يكن. لم يلتفت ثورفين، بل استمر في حفر أخدوده بانتظام آلي، ورد بمقتضب: لا فائدة من الشجار. إذا قاومت، سأضطر للقتال. وإذا قاتلت، سأقتل مجدداً. توقف إينار عن العمل، ارتسمت على وجهه علامات الحيرة والاستنكار، صرخ بنبرة مشحونة بالمرارة: ألا تملك كبرياءً؟ لقد سلبوا حريتنا، وعائلاتنا، وحياتنا! ألا تشعر بالرغبة في الانتقام؟ توقف ثورفين أخيراً، استقام ببطء، وترك المجرفة مغروسة في الطين. نظر إلى أفق الحقول البعيد، كانت يداه المليئتان بالندوب ترتجفان طفيفاً قبل أن يضم قبضتيه بإحكام. قال ثورفين بنبرة ميتة لا تحمل رنيناً: لا يوجد شيء يستحق أن أقتل من أجله الآن. في تلك اللحظة، كان صمت المكان ثقيلاً، مشحوناً بتناقض بين وحشية الماضي التي تسكن روح ثورفين، وواقع العمل اليومي البائس. لم تكن فلسفة التسامح لديه نتاج قراءة أو وعظ، بل كانت الندبة التي خلفتها الدماء التي سفكها في شبابه. انقبضت عضلة في فك إينار، اقترب منه قليلاً، وقال بحدة: أنت تتحدث وكأنك لا تشعر بألم الفقد. لكن ثورفين لم يضف كلمة أخرى، التقط مجرفته مجدداً، وعادت إيقاعات العمل لتمزق صمت الحقل، تاركاً إينار يصارع عاصفة من التساؤلات والغيظ المكتوم تحت أشعة الشمس التي بدأت تميل نحو المغيب.', '', 87, '2026-07-15 15:17:51.308', '2026-07-15 15:17:51.308');
INSERT INTO public.chapters VALUES ('f8385776-c1a6-4e75-9ea7-f276540be7a8', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 89: ثقل الأرض وأوهام المجد', '— --------------------------------------- انحنت قامة ثورفين أمام كتلة الملح التي كان يحاول حملها، وتصلبت عضلات ظهره تحت وطأة الوزن الذي بدا وكأنه يبتلع قوته. لم تكن مجرد أكياس ملح، بل كانت ثقلاً يذكره بأن حياته الآن ليست سوى سلسلة من المهام الرتيبة في مزرعة كيتيل. وقف إينار بجانبه، يمسح العرق المتصبب عن جبينه بكفه الخشنة، ونظر إلى ثورفين الذي كان لا يزال مشدوداً لشيء ما في أعماقه. قال إينار بصوت خفيض ونبرة يملؤها القلق: ''أنت تزيد من سرعة خطاك وكأنك تهرب من شيء لا أراه''. لم يجب ثورفين، بل اكتفى بترك الحقيبة تسقط على الأرض بقوة أصدرت صوتاً مكتوماً في التربة الرملية. انصرف ذهنه للحظة إلى أشباح الماضي؛ صرخات المحاربين، وبريق النصال الذي اعتاد أن يراه في عينيه هو نفسه، قبل أن يمحو تلك الصور بإطباق جفنيه بقوة. دخل كيتيل الميدان بخطوات واثقة، يحيط به هالة من الهيبة التي يفرضها صاحب الأرض. لم تكن عيناه كعيني المحاربين الذين عرفهم ثورفين، بل عيون رجل يرى في الأرض مكسباً وفي العمال مجرد تروس في آلة لا تتوقف. اقترب كيتيل منهم، وتلاشت حدة التوتر في المكان أمام سطوته. تحدث كيتيل بلهجة عملية تخلو من العاطفة، مستعرضاً طموحه في توسيع نفوذه الزراعي، بينما كان ثورفين يصغي بصمت، يراقب حركات كيتيل الجسدية؛ كيف يفرك يديه ببعضهما، وكيف ينظر إلى أفق الأرض بامتلاك متعالٍ. في تلك اللحظة، لم يعد ثورفين يرى فيه سيداً، بل رأى رجلاً يغرق في وهم السيطرة، تماماً كما غرق الملوك في أوهام الفتوحات. بادل إينار نظرة سريعة، كأنما كلاهما أدرك في تلك اللحظة أن الصراع الذي يهرب منه ثورفين لم يعد في ساحات القتال، بل في الطريقة التي يتملق بها البشر السلطة والملكية. ''العمل هو الخلاص''، قالها إينار محاولاً كسر حاجز الصمت، لكن ثورفين حمل حقيبته مجدداً، وبدلاً من الإجابة، مشى بخطوات منتظمة نحو المخزن، تاركاً كلمات إينار معلقة في هواء المساء البارد، وعقله يصارع فكرة أن العنف لا يموت، بل يغير شكله فقط.', '', 88, '2026-07-15 15:17:51.504', '2026-07-15 15:17:51.504');
INSERT INTO public.chapters VALUES ('d9a6d5a9-e90d-4eb1-bb9e-2f35df9f0a3f', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 90: نذير العاصفة في مزارع الأثير', '— --------------------------------------- توقف ثورفين عن تقليب التربة، وجسده المتشنج يعلن عن إرهاق أصاب مفاصله. لم تكن الشمس قد بلغت كبد السماء بعد، لكن قطرات العرق كانت تنزلق لتغرز ملوحتها في عينيه. بجانبه، لم يكد إينار يرفع رأسه عن المحراث، صامتاً إلا من زفير متقطع يخرج من صدره العريض كأنه مكبس حديدي. في تلك اللحظة، قطعت سكون الحقل صيحة رجلٍ يركض من جهة البوابة، صوته كان متهدجاً، محملاً ببوادر ارتباك لم يعتدها العمال في مزرعة ''كيتيل''. توقف ثورفين عن الحركة تماماً، مثبتًا قدميه في الطين الجاف، بينما تحولت عيناه نحو الأفق حيث بدا غبار يرتفع كأنه نذير سوء. ''إينار، انظر هناك''، قال ثورفين بنبرة مقتضبة، لم تحمل ذعراً بل ترقباً حذراً. لم يجب إينار، بل ألقى بيده عن مقبض المحراث وخطا خطوات قصيرة، مشدداً قبضته على مقبض معوله الخشبي. تقدم ''كيتيل'' نحوهم بخطوات ثقيلة، ملامح وجهه المعتادة التي تميل إلى اللين والتردد قد اختفت، وحل محلها تجهم بارد، فكاه مشدودان، ونظراته تائهة بين رجاله القادمين وبين أفق المزرعة. كان ''باذر'' يتقدم الصفوف بملامح يملؤها الغضب المكتوم، وعيناه تلمعان ببريق عدواني غير مبرر، ملوحاً بيده كأنه يريد السيطرة على مشهد يتداعى أمامه. لم يكن ثورفين في حاجة لسماع التفاصيل؛ فالفوضى في حركة الرجال وتناثر الأدوات في الممرات كانت تروي القصة قبل أن ينطق بها أحد. تقدم ''باذر'' نحو ثورفين، ونظراته تتوعد بمواجهة لم يطلبها الفتى، لكن الأخير وقف ساكناً، يداه متدليتان بجانبه، دون أي محاولة لاتخاذ وضعية قتالية. ساد صمت مطبق إلا من نعيق غراب بعيد، صمتٌ لم يقطعه إلا صوت خطوات ثقيلة لأشخاص يقتربون من خارج نطاق السور. لم يلتفت ثورفين، بل ظل مراقباً لوجه ''كيتيل'' الذي بدأ لونه الشاحب يميل إلى الاصفرار، وكأن دماءه تجمدت في عروقه. لم يكن ثورفين يبحث عن قتال، ولم تكن فلسفته تملي عليه الصمت، بل كان يدرك أن لحظة التغيير في هذه الأرض القاحلة قد حانت، وأن السلام الهش الذي كان يزرعه مع إينار قد صار مهدداً بزلزال لا يرحم.', '', 89, '2026-07-15 15:17:51.667', '2026-07-15 15:17:51.667');
INSERT INTO public.chapters VALUES ('86eaa62d-a3fc-4b64-8a15-c7bf5834fd8a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 91: بذور في أرض قاحلة', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في تربة ''كيتيلي'' الرخوة، بينما كانت يداه، اللتان اعتادتا قبض مقابض الخناجر، مغطتين بطبقة كثيفة من الطين والتراب. لم تكن هذه أرض معركة، بل كانت حقولاً تئن تحت وطأة العمل الشاق. اقترب ''إينار'' منه، كان عرقه يقطر على وجهه المجهد، مسح جبهته بساعده الملطخ وقال بصوت أجش: «إذا استمررنا بهذا المعدل، سننهي تصفية هذه البقعة قبل الغروب. هل تعتقد أن السيد سيسمح لنا ببيع الفائض؟» نظر ثورفين إلى الأفق، حيث تلوح غابات الدنمارك في البعيد. لم يجب فوراً، بل التقط فأس الحفر، كانت عضلاته متصلبة من ساعات العمل المتواصل، لكن نظراته كانت تخلو من ذلك التوقد الدموي القديم. قال ثورفين بنبرة مقتضبة: «لا يهم. العمل هو ما يبقينا أحياء الآن». كان الجو يضج بأصوات الرجال وهم يقلبون الأرض، وأصوات السياط البعيدة التي تذكرهم بوضعهم كعبيد. في تلك اللحظة، ظهر ''كيتيلي'' في المدى، يحيط به حراسه. توقف الجميع عن العمل، انحنت الرؤوس في صمت مطبق، إلا ثورفين؛ فقد ظل واقفاً، يراقب الرجل الذي يملك حياته بموجب قانون لا يرحم. اقترب كيتيلي، كانت ملامحه تنم عن نفوذ يغلّفه القلق، نظر إلى الأرض المحروثة التي أنجزها ثورفين وإينار، ثم مسح بعينيه الصفين الممتدين من المحصول. لم تكن هناك كلمات مديح، بل كان هناك فحص دقيق لجدوى الآلات البشرية التي يمتلكها. التفت كيتيلي نحو مساعده، متمتماً بصوت مسموع: «هؤلاء العبيد يبدون أكثر كفاءة مما توقعت. ابقوا عليهم تحت المراقبة». غادر كيتيلي، وعادت الحركة إلى الحقل، لكن ثورفين شعر بضغط حدقة ''إينار'' عليه. التفت إينار وسأله بخفوت، كأنما يخشى أن تلتقط الرياح كلماته: «ألا تشعر بالرغبة في الهروب؟ نحن نغرس بذوراً لن نحصد ثمارها أبداً». توقف ثورفين عن الحفر، استند إلى مقبض الفأس، وانقبضت ملامحه للحظة. تذكر وجوه الذين ماتوا، تذكر صراخ الساحة التي لم تغادره، ثم نظر إلى كفيه المتسختين بتراب الأرض. قال ثورفين بصوت منخفض وخشن، يكاد يكون هامساً: «الهروب لن يغير ما نفعله هنا. الأرض لا تهتم بمن يحرثها، هي فقط تريد بذوراً لتعطي. أنا أحرث، وهذا يكفي الآن». لم يضف شيئاً، وعاد ليهوي بالفأس في قلب الأرض، في إيقاع رتيب يتناغم مع نبضات قلبه الذي بدأ يتعلم، ببطء مؤلم، معنى أن تكون إنساناً في عالم لا يقدم سوى الدم.', '', 90, '2026-07-15 15:17:51.864', '2026-07-15 15:17:51.864');
INSERT INTO public.chapters VALUES ('358d612c-2b32-4daa-a114-e5a28c79ffcb', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 92: بذار في أرض قاسية', '— --------------------------------------- انحنى ثورفين فوق التربة المتجمدة في مزرعة كيتيل، أصابعه غائرة في الطين البارد، يقلب الأرض بجهد ينم عن إصرار محموم. كان العرق يتصبب من جبينه رغم لسعة الهواء التي تنهش جسده النحيل. لم يكن يزرع القمح فحسب، بل كان يحاول ردم الفراغ الذي خلفته سنوات السيف والدم. اقترب إينار بخطوات ثقيلة، ممسكاً بيده كيس البذور، وقال بنبرة مقتضبة تخلو من المجاملة: «الأرض هنا لا تعطي شيئاً دون حرب، يا ثورفين. القسوة التي نراها في الناس هنا هي انعكاس لهذه التلال الصخرية». لم يرفع ثورفين رأسه، بل اكتفى بمسح وجهه بكفه الملطخة بالتراب، ورد بصوت أجش كأنه لم يستخدمه منذ زمن طويل: «لا أريد منها سوى أن تنبت. لا أريد نزاعاً، ولا أريد دماءً تسقى بها الجذور. إذا كان العمل الشاق هو الثمن، فأنا مستعد». استقر نظر إينار على الندوب الممتدة على ذراعي رفيقه، تلك التي تروي قصصاً لم يجرؤ يوماً على سؤال ثورفين عنها، ثم تنفس بعمق وقال: «الحرية ليست مجرد قطعة ورق تثبت أننا مأجورون، إنها ألا نعود لما كنا عليه». توقف ثورفين عن الحفر، وثبت نظره على الأفق الرمادي حيث لاحت ظلال المزرعة. كانت عيناه، اللتان اعتادتا ترصد حركة الخصوم في ساحات الوغى، تبحثان الآن عن شيء مختلف؛ شيء لا يلوح في أفق العنف. قطع حبل الصمت صوتُ خطوات قادمة من بعيد؛ كان ذلك المزارع العجوز يراقبهم بفضول، ملامحه المنهكة تخفي حذراً فطرياً تجاه الغرباء. لم يكترث ثورفين، فقد كانت يداه قد بدأتا بالفعل في غرس الحبوب في الثقوب الصغيرة التي حفرها في الأرض. في تلك اللحظة، لم يكن ثورفين المحارب الذي يخشاه الجميع، بل كان رجلاً يحاول استعادة جزء من إنسانيته التي جرفتها أمواج الغزوات، مدركاً أن البذرة التي يضعها في هذه اللحظة، قد تكون الوحيدة التي ستنمو في حياته دون أن تنتهي بجنازة.', '', 91, '2026-07-15 15:17:52.047', '2026-07-15 15:17:52.047');
INSERT INTO public.chapters VALUES ('630b6523-4958-49d8-8648-6691741fff32', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 93: بذرة في أرض الرماد', '— --------------------------------------- انغرس نصل الفأس في التربة الصلبة، مخلفاً خدشاً غائراً في الأرض التي لم تكن تعرف سوى القحط. مسح ثورفين جبينه بظهر كفه، تاركاً أثراً من الطين والدم الجاف. تنفسه كان متسارعاً، يخرج من صدره كأزيز مسموع، بينما كانت عيناه، الغائرتان تحت وطأة الإرهاق، تراقب الأفق الذي لا ينتهي. نظر إينار إليه، كان يمسح العرق عن وجهه المتعب، ثم ألقى نظرة على حقل القمح الذي بدأ يتشكل ببطء شديد تحت رعايتهما. سأله إينار بصوت مبحوح: هل تظن أن هذه الأرض ستطعمنا يوماً؟ صمت ثورفين للحظات، لم يجب بكلمات معسولة، بل أشار بيده إلى بقعة خضراء صغيرة نبتت وسط القسوة: انظر، لقد اخترقت الأرض. لم يعد ثورفين ذلك الفتى الذي يبحث عن المجد في ساحات القتال، بل صار جسداً تآكلت روحه وعادت لتتشكل من جديد بين الفأس والمحراث. في تلك الأثناء، كان سيد الأرض، ذلك الرجل الذي يراقب من بعيد، يتمتم بكلمات غير مسموعة عن جدوى هذا العناء. اقترب أسكلاد في خياله، تراءى له طيفه بابتسامته الماكرة ونبرته التي تقطر سخرية: ما زلت تبحث عن شيء لتقتات عليه يا ثورفين، بينما كنت تقتات على دماء الرجال؟ انتفض ثورفين، انقبضت عضلات ساعده حول مقبض الفأس حتى ابيضت مفاصله. ضغط على أسنانه، لم يكن صوته سوى فحيح منخفض: لن أعود لتلك الدائرة. إينار، الذي لم يفهم صراعه الصامت، وضع يده على كتفه الخشن، كانت لمسة عفوية، لكنها هزت ثورفين من الداخل. قال إينار ببساطة: الشمس تغيب، لننهِ هذا الجزء قبل أن يداهمنا البرد. أومأ ثورفين برأسه، وعاد للعمل. كانت الحركات رتيبة، لكنها حملت في طياتها شيئاً جديداً، ليس الكراهية التي اعتاد عليها، بل إصراراً غريباً على البقاء. لم تكن هناك فلسفة في صمتهما، كان هناك فقط واقع مادي بحت، تربة قاسية، ومحاولة يائسة لتحويل بقعة من الأرض القاحلة إلى حياة. وبينما تلاشت أطياف الماضي في عتمة الغسق، بقي ثورفين واقفاً، يراقب شتلة القمح الوحيدة، مدركاً أن الألم الذي خلفته الحرب لم يعد يقارن بالأمل الصغير الذي ينبض الآن بين أصابعه الملطخة بالتراب.', '', 92, '2026-07-15 15:17:52.283', '2026-07-15 15:17:52.283');
INSERT INTO public.chapters VALUES ('17152822-0788-4ce3-a5e6-a5473dd02911', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 94: خيوط القدر في بلاد اليونان', '— --------------------------------------- توقف ثورفين عن مضغ قطعة الخبز اليابس، كانت عيناه مثبتتين على الأفق حيث تتقاطع مسارات السفن في البحر المتوسط. هيلد لم ترفع بصرها عن خريطتها، أصابعها تتحرك فوق الجلد المدبوغ ببطء. قالت بصوت أجش خالٍ من العاطفة: «نحن نقترب من ميناء ميكلاغارد. المرتزقة هناك لا يفرقون بين الغريب والعدو، تأكد من إبقاء خنجرك بعيداً عن الأنظار». هز ثورفين رأسه إيجاباً، لم تكن الحاجة للكلمات حاضرة. كان التوتر في عضلات كتفيه يكفي لتوضيح استعداده. على سطح السفينة، كان غودريد تتفحص الحبال، ملامحها تشي بتركيز حاد، بينما كان إينار يقف قرب الصاري يراقب حركة الأمواج التي بدأت تتغير سرعتها. اقترب منه ثورفين، ملامحه الجادة لم تتغير، وقال بصوت منخفض: «إينار، لا تبتعد عن المجموعة. الميناء ليس مكاناً للبحث عن أصدقاء». التفت إينار إليه، كانت نظراته تفيض بالشك، سأل بنبرة خشنة: «هل تعتقد حقاً أننا سنجد من يبيعنا ما نحتاجه دون أن يغدر بنا؟». أجابه ثورفين ببرود: «الكل يغدر إذا كان الثمن مغرياً، لذا لن نترك لهم فرصة». في تلك اللحظة، ظهرت ملامح الميناء العملاق بين الضباب، أبراج شاهقة وسفن تجارية تصطف كأنها جيش من العمالقة الخشبية. لم يكن هناك وقت للتردد، فبدأت السفينة تشق طريقها نحو الرصيف، بينما انقبضت كف ثورفين على قبضة خنجره، ليس حباً في القتال، بل إدراكاً بأن السلام في هذه الأصقاع هو مجرد حلم يطارد الفقراء. صمت الجميع، ولم يبق سوى صوت احتكاك الخشب ببدن الرصيف، وبدأت رحلة جديدة في قلب المجهول، حيث القوة هي اللغة الوحيدة التي يفهمها الجميع.', '', 93, '2026-07-15 15:17:52.457', '2026-07-15 15:17:52.457');
INSERT INTO public.chapters VALUES ('a547b373-bbe5-480d-aa21-295b8710357e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 95: خلف أسوار الرماد', '— --------------------------------------- ارتطم جسد ثورفين بالأرض الترابية بقوة، مخلفاً سحابة من الغبار عجز عن تبديدها بصرُه المشتت. لم يكد يسترد أنفاسه المتقطعة حتى برزت أمامه قامة ''سيغورد'' الضخمة، تغطيها دروعه التي تعكس ضوءاً باهتاً تحت سماء رمادية. التقط سيغورد حفنة من التراب بيده المكسوة بالجلد، ثم ألقاها باستهانة نحو ثورفين قائلاً بنبرة تفيض احتقاراً: ''أهذا هو المحارب الذي يهذي به الجميع؟ جسدٌ هش لا يقوى على الصمود أمام ركلة''. انتصب ثورفين على ركبتيه، لم يلتفت للكلمات، بل كانت عيناه ترصدان حركة عضلات خصمه، تبحثان عن ثغرة في وقفته المتغطرسة. صمتُ ثورفين كان أشد وطأة من أي شتيمة، صمتٌ بارد ينم عن إدراك عميق بأن المعركة ليست في القوة العضلية وحدها. اندفع سيغورد مجدداً، فاستقبل ثورفين الهجمة بانحناءة جانبية خاطفة، تاركاً خصمه يغرس قبضته في الفراغ. لم يكن ثورفين يقاتل بغضب؛ كانت حركاته اقتصادية، دقيقة، كأنما يحل معادلة رياضية معقدة. ''توقف عن الالتفاف كالجرد''، زمجر سيغورد، مخرداً سيفه الذي أحدث صليلًا حاداً في الهواء. لم يجب ثورفين، بل انزلق تحت ذراع سيغورد الممدودة، موجهًا ضربة دقيقة إلى مرفق خصمه، مما جعل السيف يترنح في قبضة الأخير. في تلك اللحظة، تبادل الرجلان نظرة خاطفة؛ في عين سيغورد وميض ارتباك، وفي عين ثورفين خلوٌ تام من أي رغبة في القتل. كان ثورفين يرى في خصمه مجرد عقبة، بينما كان سيغورد يرى في ثورفين تحدياً لكرامته التي لا تترمم إلا بالدم. تراجع سيغورد خطوتين، تنفسه يضطرب، بينما ظل ثورفين واقفاً، يداه مسترخيتان بجانبه، وكأنه ينتظر نهاية النوبة التي أصابت خصمه. ''أنت لا تقاتل بجدية''، صاح سيغورد، وقد بدأت ملامحه تتشنج من الإحباط. أجابه ثورفين بصوتٍ خافت، أجش، ومباشر: ''ليس لدي ما أثبته لك. الطريق أمامي لا يتسع لقتالٍ عقيم''. تحركت أصابع ثورفين قليلاً، استعداداً لصد أي هجوم طائش، مدركاً أن الدقائق القادمة ستحدد ما إذا كان بإمكانه المضي قدماً نحو هدفه، أم أنه سيغرق في هذا المستنقع من الكبرياء والأسلحة المحمومة.', '', 94, '2026-07-15 15:17:52.74', '2026-07-15 15:17:52.74');
INSERT INTO public.chapters VALUES ('abe99c51-4f60-4f3c-be56-52b53ba899e3', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 96: صدى المطرقة على سندان العبيد', '— --------------------------------------- توقف ثورفين عن القرع. كانت يداه، المتورمتان من أثر المقبض الخشبي، ترتعشان ببطء تحت وطأة الإرهاق. نظر إلى كومة الحديد المشكل أمام قدميه؛ كانت تلك الأداة الزراعية ناقصة، غير متقنة بما يكفي لتفي بمتطلبات سيد الأرض. خلفه، كان إينار يمسح العرق عن جبينه بساعدٍ موشوم بالندوب، أنفاسه المتقطعة هي الصوت الوحيد الذي يكسر سكون الورشة. قال إينار بصوت مبحوح: «إذا لم ننهِ حصتنا اليوم، فسيقتطعون جزءاً آخر من حصة طعامنا. لم نعد نملك طاقةً للعمل أكثر». لم يلتفت ثورفين، بل اكتفى بتثبيت نظره على الفحم المتوهج في الموقد. كانت عيناه، الغائرتان والفاقدتان لكل بريق، تعكسان لهيباً لا يحرق. اقترب منهما ''كيتي''، صاحب المزرعة، بخطوات ثقيلة ومتحفظة، يتبعه أحد رجاله المدججين بالسلاح. توقفت نظرات كيتي عند القطعة التي كان ثورفين يعمل عليها، ثم انتقلت ببرود إلى وجه ثورفين. قال كيتي بنبرة جامدة تخلو من أي ود: «العمل يتباطأ. هل تعتقد أن حريتك ستأتي عبر أدوات ناقصة؟». لم يجب ثورفين. انقبضت عضلات فكه السفلي بقوة حتى برزت عظام وجهه الحادة. كان يعلم أن أي مبرر هو ذريعة واهية في نظر السادة. اقترب الرجل المرافق لكيتي خطوة، ووضع يده على مقبض سيفه، معيداً توجيه دفة الحديث نحو ضرورة الانضباط. في تلك اللحظة، لم يكن ثورفين يفكر في الحرية كهدف بعيد، بل كان يرى في ضربات المطرقة المتوالية صدىً لصراعاتٍ قديمة لم تغادر عقله تماماً. قال ثورفين بصوت منخفض، خشن، وكأن الكلمات تجرح حنجرته: «سننتهي قبل غروب الشمس». لم تكن وعوداً، بل كانت استجابة ميكانيكية لواقعٍ لا يقبل الجدال. حين غادر كيتي المكان، ساد صمت مطبق. التفت إينار إلى ثورفين، ملامحه تعكس مزيجاً من الحيرة والشفقة على هذا الرفيق الذي يبدو وكأنه فقد القدرة على الشعور بالألم أو الخوف. قال إينار: «لماذا لا تدافع عن نفسك؟ لماذا تتقبل هذا الذل كأنه قدر لا فكاك منه؟». رفع ثورفين المطرقة من جديد، وبدأ يطرق الحديد بقوة أشد، كانت الضربات رتيبة، قاسية، ومتلاحقة. قال ثورفين دون أن يرفع رأسه: «لا فائدة من الصراخ في وجه العواصف. العمل هو الحقيقة الوحيدة هنا. إما أن ننهي المهمة، أو ننتظر العقاب. لا خيار آخر». عاد الصمت، ولم يبقَ في المكان سوى رنين الحديد الذي يتردد صداه في جنبات الورشة المظلمة، موثقاً فصلاً آخر من حياةٍ تستنزف الأرواح قبل الأجساد.', '', 95, '2026-07-15 15:17:52.918', '2026-07-15 15:17:52.918');
INSERT INTO public.chapters VALUES ('bd242795-7005-49b7-b380-334f21e9306c', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 97: صدى الغفران تحت سياط الندم', '— --------------------------------------- تشنجت عضلات فك ثورفين وهو يحدق في وجه الرجل الجالس أمامه. لم تكن الغرفة سوى قفص خشبي تفوح منه رائحة الرطوبة والعفن، لكن الصمت الذي يلف المكان كان أثقل من قيود الحديد. رفع ثورفين يده المرتجفة، ليس ليضرب، بل ليتحسس وجهه، محاولاً استجماع شتات وعيه الذي مزقته كوابيس السنوات الماضية. كان الرجل المقيد أمامه يمثل كل ما سعى ثورفين لتدميره، وكل ما أصبح هو عليه. نظر ثورفين إلى كفيه؛ دماء قديمة لا تغسلها مياه الأنهار ولا يمحوها زمن. لم يتكلم، بل أطلق زفيراً حاداً ومتقطعاً، فالتفت الرجل المقيد ببطء، عيناه الغائرتان تحملان ثقلاً يفوق سنواته. قال الرجل بصوت أجش كحفيف الشجر اليابس: أنت لم تعد ذلك الصبي الذي يلهث خلف الانتقام، أليس كذلك؟ لم يجب ثورفين، بل انقبضت كفه حول مقبض خنجره المغمود، ثم ارتخيت أصابعه فجأة. شعر بثقل غريب في صدره، صراع بين الرغبة في إنهاء حياة خصمه وبين إدراك العبث الذي قاده إلى هنا. سادت لحظة من الترقب، حيث لم يُسمع سوى طنين حشرة تحوم حول القنديل الخافت. لم يكن هناك وعظ أو كلمات مواساة، بل كان الواقع يفرض حقيقته القاسية: القاتل الذي يقف أمام القاتل لا يرى عدواً، بل يرى انعكاساً لخرابه الخاص. نهض ثورفين ببطء، تاركاً الظلال تتراقص على جدران القفص، واتجه نحو المخرج بخطوات ثقيلة ومترددة، تاركاً خلفه ليس غريماً، بل ماضياً كان يجب عليه أن يقتله في نفسه أولاً قبل أن يغادر هذا المكان.', '', 96, '2026-07-15 15:17:53.118', '2026-07-15 15:17:53.118');
INSERT INTO public.chapters VALUES ('593d5121-5713-49bc-9ebe-44defc8bc072', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 98: خلف أسوار العزلة', '— --------------------------------------- توقف ثورفين أمام البوابة الخشبية العتيقة لدار هيلد، حيث تداخلت أصوات الغابة مع طنين الحشرات في رتابة مثيرة للأعصاب. لم تكن الغابة صامتة، لكنها كانت تفرض رهبتها على كل من يخطو نحو كوخ المرأة التي نذرت حياتها للبحث عن الثأر. دفع ثورفين الباب بخفة، فصدر صرير حاد خرق سكون المكان. في الداخل، كانت هيلد جالسة، لا تشبه في هيئتها المحاربات اللواتي واجههن ثورفين في معارك المرتزقة؛ كانت تحمل قوساً من خشب السنديان المصقول بعناية فائقة، وعيناها مثبتتان على الداخلين ببرود يغني عن أي حديث. وضع ثورفين يديه أمام صدره، ليس كمن يستسلم، بل كمن يطرح ثقلاً من على كاهله. قال بصوت منخفض، خالٍ من أي نبرة عدائية: أتيت وحدي، لا سلاح معي، ولا نية لي في إراقة قطرة دم إضافية. كانت هيلد تراقبه، بؤبؤا عينيها يتحركان بدقة ماسحةً تفاصيل وجهه، كأنها تبحث عن أثر لخداع في تجاعيد جبهته. سألت بصوت جاف لم يرتجف: لماذا تعتقد أن كلماتك قد تمنع سهماً من استقرار في قلبك؟ أجاب ثورفين وهو يخطو خطوة أخرى للأمام: لا أطلب الصفح، فما اقترفته يداي لا يمحوه الاعتذار، لكنني أطلب فرصة لأصلح ما يمكن إصلاحه. كان الصمت الذي تلا كلماته يثقل جدران الكوخ الخشبية. لم تكن هناك فلسفة في صمته، فقط إقرار بمرارة الواقع. تحركت هيلد قليلاً، وأرخت قبضتها عن وتر القوس لكن دون أن تبعده كلياً. تنفس ثورفين بعمق، وشعر بجفاف ريقه، لكنه استمر في تثبيت نظره نحو عينيها، متحداً مع ثقل اللحظة التي قد تعني نهايته. لم تكن هناك وعود بالسلام، بل كان هناك لقاء بين شخصين حطمهما الماضي بطرق مختلفة، يلتقيان الآن تحت سقف واحد ليواجها عدواً مشتركاً لا يرى في ذكراهم سوى فراغ للقتل. التفتت هيلد نحو الطاولة حيث وضعت أدواتها الميكانيكية، وقالت بلهجة آمرة: ابقَ حيث أنت، فالطريق إليك قد انتهى عند هذه العتبة، وسأقرر وحدي ما إذا كنت ستخرج من هنا حياً أم أن الأرض ستكتسي بدمك.', '', 97, '2026-07-15 15:17:53.338', '2026-07-15 15:17:53.338');
INSERT INTO public.chapters VALUES ('8bbc3773-6342-4d68-b9e0-e32c41d7ea6e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 99: خيوط العودة إلى أرض الأحلام', '— --------------------------------------- انغلق باب كوخ ليف اريكسون خلف ثورفين، بينما كان صوت ارتطام الأمواج ببدن السفينة يمتزج بأزيز الرياح في الخارج. استقر ثورفين على المقعد الخشبي، يراقب حركات ليف المعتادة؛ تلك اليدان الخشنتان اللتان تتحركان بدقة بين الخرائط والجلود. قال ليف دون أن يرفع بصره عن الخريطة: سأذهب معك. توقف ثورفين عن تحريك أصابعه، ورمق الرجل العجوز بنظرة فاحصة. رد ثورفين بلهجة مقتضبة: لن يكون الأمر سهلاً يا ليف. الرحلة إلى فينلاند ليست نزهة بحرية. وضع ليف الخريطة جانباً، وظهرت تجاعيد وجهه تحت ضوء القنديل الخافت بوضوح كأنها تاريخ من الأسفار. أجابه بهدوء: لم أعد أبحث عن الراحة. هناك طفلٌ في قريتي انتظر عقوداً ليرى أساطير والده حقيقةً، والآن أنت تمنحني تلك الفرصة. ساد الصمت لبرهة، لم يقطعه سوى أنين الخشب المجهد. لم يكن ثورفين بحاجة للمزيد من الكلمات؛ فقد كان يعرف أن إصرار ليف لا يلين. تحول الحديث إلى تفاصيل المسار، حيث تلاشت نبرات العاطفة لتحل محلها دقة الملاحة. سأل ثورفين عن التيارات المتوقعة في عرض المحيط، فأجابه ليف ببرود الخبير: الشمال دائماً هو بوصلتنا، لكن الرياح في تلك المنطقة تخدع الغرباء. لا تعتمد على ما حفظته في طفولتك، المحيط يتغير كلما اقتربت من الحافة. انحنى ثورفين على الطاولة، محدقاً في الخطوط المرسومة بالحبر الباهت، وشعر بثقل المسؤولية يضغط على كتفيه. تذكر الوجوه التي تركها خلفه، والوعود التي قطعها على نفسه. لم تكن فينلاند مجرد أرض بالنسبة له، بل كانت النقطة التي سيبدأ عندها محو دماء الماضي. وفي الخارج، كانت السماء تميل إلى السواد، وبدا الأفق موعوداً بمتاعب لم يحسب لها أحد حساباً. نظر ليف إلى عيني ثورفين وقال بنبرة واثقة: السفينة جاهزة، والطاقم ينتظر إشارتك. نحن لا نبحث عن الغنائم، نحن نبحث عن بداية لا تلطخها دماء السيوف. أومأ ثورفين برأسه، واضعاً يده على مقبض خنجره، ليس ليشهره، بل ليذكره بوزن القرار الذي اتخذه. غادر ليف الكوخ، تاركاً ثورفين وسط الغرفة الخاوية، وحيداً مع خرائط كانت يوماً ما مجرد حكايات، والآن أصبحت ممراتٍ لنجاته.', '', 98, '2026-07-15 15:17:53.538', '2026-07-15 15:17:53.538');
INSERT INTO public.chapters VALUES ('1381c064-c87f-4061-aee1-50133f2e1d67', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 100: بذرة في تربة الغربة', '— --------------------------------------- انحنت قامة ثورفين فوق الأرض الصلبة، مخترقة أصابعه الطين المتجمد بحثاً عن بصيص حياة. كان عرق جبينه يقطر، ليس من وهج الشمس، بل من الجهد المضني لترويض أرضٍ رفضت الانصياع منذ قرون. وقفت غودريد خلفه، تراقب حركات يديه الخشنة التي اعتادت إراقة الدماء، وهي الآن تتحسس حبات الشعير بحذر كأنها تلمس أرواحاً هشة. قال ثورفين وصوته أجش، مقتضب كعاداته القديمة: «التربة هنا عنيدة، لكنها ليست قاحلة. إن أعطيناها، ستعطي». التفتت غودريد إليه، لم تكن تبحث عن وعود براقة، بل عن استمرارية في يوم لا ينتهي من التعب. سألت بصوت خافت: «وهل تكفي هذه البذرات لنقتات؟». توقف ثورفين عن الحفر، رفع نظره إلى الأفق حيث تمتد مزارع المستعمرة الناشئة، وقال بلهجة حازمة خالية من الزخرفة: «تغرس البذرة اليوم، فتأكل غداً. هذا هو الفرق بيننا وبين المحاربين، نحن لا ننهب المستقبل، نحن نصنعه». لم يكن حديثه يحمل سمو المواعظ، بل كان تقريراً لواقعٍ يفرضه جوع المعدة ومسؤولية البقاء. وفي تلك اللحظة، قطعت صرخة بعيدة صمت الحقول. كان إينار يلوح بيده من طرف الحقل، ملامح وجهه مشدودة تنبئ بحدث طارئ. انقبضت كف ثورفين تلقائياً، تحركت عضلات كتفيه بذاكرة عضلية لم تنسَ القتال، قبل أن يزفر بعمق، مرخياً قبضة يده. نظر إلى الأرض مرة أخرى، ثم إلى غودريد، وقال: «استمري في الغرس. السلم ليس غياباً للضجيج، بل هو مواصلة العمل رغم كل ما يحيط بنا». مشى ثورفين نحو إينار بخطوات ثابتة، تاركاً خلفه ثقباً صغيراً في الأرض، بذرةً وحيدةً في عالمٍ لا يزال يحاول أن يقرر ما إذا كان سيسمح لهم بالعيش أم سيسحقهم تحت وطأة الجليد.', '', 99, '2026-07-15 15:17:53.768', '2026-07-15 15:17:53.768');
INSERT INTO public.chapters VALUES ('d9e6838c-c6bb-4a1f-8397-1f37b1649a28', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 101: خلف أسوار العزلة', '— --------------------------------------- توقف ثورفين أمام البوابة الخشبية الثقيلة، حيث تنبعث من الداخل أصوات ارتطام الحديد بالأرض. لم تكن ثمة حاجة للتردد؛ دفع البوابة بقوة لترتد على الجدران الحجرية محدثة دوياً مكتوماً. في الساحة الوسطى، كان إينار ينتظر، ملامحه مشدودة، وعيناه تلاحقان حركات ثورفين التي اتسمت بهدوء غير معتاد. لم يتحدث ثورفين فوراً، بل مسح بظهره على الحائط الخشبي، مشيراً برأسه نحو الرجال الذين بدأوا يتجمعون في الزوايا. التفت إينار إليه، صوته خرج أجشاً ومباشراً: هل أنت مستعد لما سيأتي؟ أجابه ثورفين باقتضاب دون أن ينظر إليه: المزارع لا تنتظر، والحصاد لن يؤجل بسبب شكوكنا. كانت تلك الكلمات بمثابة إعلان لبدء يوم جديد من الكدح تحت شمسٍ لا ترحم، لكن ذهن ثورفين كان مشتتاً، يتأمل في صمت أثر الندوب التي تركتها سنوات القتال على كفيه. في تلك الأثناء، اقترب منه أحدهم، رجلاً ضخم البنية يغطي وجهه أثر جرح قديم، وقف أمامه متحدياً، وبصق على الأرض ثم قال بلهجة فظة: لا تظن أن صمتك يجعل منك فارساً يا ابن المحارب. لم يرمش ثورفين، بل ظل ثابتاً كصخرة في مهب الريح، بينما انقبضت عضلات ساعده تحت قميصه الخشن. رد ثورفين بنبرة باردة كالفولاذ: لا أبحث عن لقب، ولا أبحث عن نزاع. انصرف عن طريقي. تراجع الرجل خطوة، وقد اتسعت عيناه قليلاً أمام ثبات ثورفين المريب، ليعم المكان صمت ثقيل لا يقطعه سوى طنين الحشرات في الحقول المجاورة. تحرك إينار بينهما، واضعاً يده على كتف ثورفين، هامساً له: لا تلتفت للنباح، فالعمل هو ما يحدد قيمتنا هنا، لا السيوف. أومأ ثورفين برأسه، تاركاً خلفه تلك المشاحنات الصغيرة، ومتوجهاً نحو الحقول حيث تنتظرهم مهام النهار. في تلك اللحظة، أدرك كلاهما أن العزلة التي فرضت عليهما ليست مجرد سجن، بل هي بوتقة تصهر أطرافهما لتشكل منهما شيئاً جديداً، بعيداً عن صخب الدماء وأوهام المجد التي طالما طاردتهما في الماضي القريب.', '', 100, '2026-07-15 15:17:53.956', '2026-07-15 15:17:53.956');
INSERT INTO public.chapters VALUES ('b31967d4-d88d-4347-a703-bf45407ac05a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 102: سوق العبيد والقيود الخفية', '— --------------------------------------- انغرس طرف الحذاء في التربة الطينية، ليتناثر الرذاذ الأسود على قمصان ثورفين وايينار الرثة. لم تكن رائحة السوق تذكّر بشيء سوى العفن والماشية البشرية المكدسة. التفت ثورفين نحو ايينار، كانت ملامحه جامدة، كأنما نُحتت من صخر أصم، لا يكسر جمودها سوى وميض حذر في عينيه يمسح الحشود. وقف ''أولف'' بضخامته التي تحجب ضوء الشمس، يمسح المكان بنظرات فاحصة خالية من الاكتراث. قال ثورفين بصوت خفيض، نبرته تحمل ثقل التجربة: ''لا تلتفت خلفك، ايينار. اجعل بصرك مثبتاً على الأرض أمام خطواتنا''. تنفس ايينار بصعوبة، كانت يداه المربوطتان خلف ظهره تتشنجان مع كل حركة. همس ايينار، وقد جف حلقه: ''هل سننتظر حقاً؟ كل لحظة تمضي هنا تشبه الدهر''. لم يجب ثورفين، بل اكتفى بضغط كتفه بقوة كإشارة للصمت. تقدم رجل ذو لحية مشذبة وعينين زائغتين، كان يتفحص البضاعة البشرية كأنه يقيم جودة خشب أو معدن. اقترب من ثورفين، مد أصابعه الخشنة ليمسك بذقنه ويقلب وجهه يميناً ويساراً. ساد صمت مطبق بينهما، صمت لم يقطعه سوى نهيق حمار بعيد. رفع ثورفين بصره، كانت نظراته باردة، محايدة، تخلو من الخضوع أو التحدي، مجرد استسلام للواقع. همس الرجل المشتري: ''هذا يبدو ضعيفاً، لكن عينيه تخبران قصة أخرى''. رد أولف بضحكة خشنة، صوته كاحتكاك الصخور: ''ضعيف؟ جرب إجباره على العمل، ستجد أنك اشتريت ثوراً لا يكل''. نظر ثورفين إلى الأفق، حيث تختفي الشمس خلف غابات الشمال، متذكراً دروساً قديمة لم تعد تجد لها مكاناً في هذا العالم الموحش. لم يقل شيئاً، لم يرتجف، فقط قبض على أسفل قميصه الممزق حتى ابيضت مفاصل أصابعه، منتظراً مصيراً لم يكتبه هو بيده هذه المرة.', '', 101, '2026-07-15 15:17:54.145', '2026-07-15 15:17:54.145');
INSERT INTO public.chapters VALUES ('0d4e0a51-7a0d-4fcf-a02c-754e09cf9498', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 103: بذور في أرض الجليد', '— --------------------------------------- توقفت العربة الخشبية الثقيلة عن الحركة، غارسة عجلاتها في طين الأرض الرطبة التي لم تعتد وطأة الغرباء. قفز ثورفين إلى الأرض، متهالكاً من إرهاق السفر الطويل، بينما كان إينار يمسح عن وجهه غبار الطريق، وعيناه تمسحان الأفق بذهول الحالم. لم تكن أرضاً يغزوها القراصنة، بل كانت برية بكراً، تترامى فيها مساحات شاسعة من العشب الأخضر الممزوج بلفحات ضباب بارد. نظر إينار إلى يديه اللتين اعتادتا قسوة النصال، ثم بسطهما فوق التربة السوداء الخصبة، وقال بصوت متهدج: «هذه الأرض… تبدو عطشى للعمل، يا ثورفين. لم تلمسها أقدام الجيوش بعد، لم يفسدها الدم». لم يجب ثورفين فوراً، بل انحنى ليلتقط حفنة من التراب، يفركها بين أصابعه الخشنة. كان صمته ثقيلاً، مشبعاً بذكريات النصال التي كسرت حياته، لكن عينيه الآن كانتا تراقبتا مساحة الأرض الشاغرة لا بصفتهما ساحة معركة، بل رقعة يمكن البدء فيها من جديد. اقترب ليف هيرسون، متكئاً على عصاه، يراقب حماسهما بنظرة دافئة، وقال بنبرة واثقة: «هذا المكان سيكون منزلكما. هنا، بعيداً عن صخب الملوك وتجار العبيد، ستكتبان تاريخكما الخاص». تبادل ثورفين وإينار نظرة صامتة؛ لم تكن نظرة رفاق سلاح، بل نظرة رجلين قررا أخيراً أن يضعا السلاح جانباً. تحرك ثورفين نحو كوخ قديم مهجور، دفع بابه الخشبي الذي أصدر صريراً حاداً، كاشفاً عن مساحة ضيقة تفوح منها رائحة القدم والتراب الجاف. لم يكن هناك أثاث سوى مواقد باردة، لكنها بالنسبة لهما كانت أكثر من مجرد جدران. قال ثورفين، بينما كان يلقي بحقيبته على الأرض: «سنبدأ بقلع الجذور الميتة. كل شبر من هذه الأرض يحتاج إلى عرقٍ حقيقي قبل أن يمنحنا شيئاً». في الخارج، بدأ إينار في إفراغ ما تبقى من المؤن، وقد استقرت في أعماقه لأول مرة فكرة أن الحياة قد لا تعني دائماً الموت في سبيل البقاء. وبينما كانت الشمس تميل نحو المغيب، صابغة السماء بلون نحاسي شاحب، جلس ثورفين عند باب الكوخ، ينظر إلى البعيد. لم يعد يرى وجوه الضحايا في الظلال، بل كان يرى حقولاً من الحبوب التي لم تُزرع بعد. لم تكن فلسفة، بل كانت ضرورة؛ حياة لا تعتمد على سلب الآخرين، بل على ما يمكن انتزاعه من جوف الأرض.', '', 102, '2026-07-15 15:17:54.381', '2026-07-15 15:17:54.381');
INSERT INTO public.chapters VALUES ('aae491e6-fe37-4976-93b2-213e5e13c288', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 104: خلف أسوار العزلة', '— --------------------------------------- توقفت العربة الخشبية الثقيلة عن الحركة، مخلفة وراءها أثراً عميقاً في التربة الطينية. قفز ثورفين أرضاً، وسرعان ما تبعته إينار، لتقع أعينهما على المشهد الذي طالما بحثا عنه: مزرعة كيتيل. لم تكن هذه الأرض تبدو كبقية الأراضي الجرداء التي مروا بها؛ فقد كان الحصاد قد بدأ لتوّه، ورائحة القمح الجاف تمتزج برائحة العرق المنبعثة من العمال المتكدسين في الحقول. نظر ثورفين نحو الأفق، حيث تتقاطع صفوف السنابل الذهبية مع الأفق البعيد. انقبضت كفه حول حزام خصره، وشعر بضغط الغربة يثقل كاهله. لم ينطق بكلمة، بل اكتفى بمسح المكان بنظرات فاحصة، وكأنه يزن ثقل الأيام التي ستقضيها قدماه على هذا التراب. تقدم إينار خطوة للأمام، وقد ارتسمت على وجهه علامات الذهول، هامساً بصوت خافت ومتحشرج: ''هل هذه هي فعلاً أرض العبودية؟ تبدو… هادئة بشكل مريب''. التفت إليه ثورفين، وكانت عيناه غائرتين، خاليتين من أي بريق عاطفي. قال بنبرة مقتضبة وجافة: ''العمل لا يهتم بهدوء المكان. المهم هو ما نفعله نحن هنا''. لم يعد ثورفين ذلك الفتى الذي يبحث عن الخلاص في القتال، بل صار رجلاً يرى العالم من خلال مسام جلده التي تفتحت على قسوة الحياة. وبينما كان العمال ينادون بعضهم بأصوات خشنة، تعالت ضحكات رجل ضخم البنية، يضع على كتفيه عباءة جلدية، كان ''أولمار''، ابن كيتيل، يسير بتثاقل، متجنباً النظر إلى الوافدين الجدد، مفضلاً التركيز على خنجره الذي يلمع في ضوء الشمس. اقترب ''كيتيل'' من العربة، بخطوات واثقة تعكس سلطته في هذا المكان. كانت لحيته الكثيفة تخفي الكثير من ملامحه، لكن عينيه كانتا تشعان ببريق الرجل الذي بنى إمبراطوريته من العمل الشاق. لم يلقِ عليهم خطبة طويلة، بل أشار بيده نحو الحقول، وقال بلهجة آمرة ومباشرة: ''هنا لا مكان للكسالى. إذا أردتم الطعام، فاحفروا الأرض حتى تخرج أرواحكم. هنا، العرق هو العملة الوحيدة''. انحنى ثورفين قليلاً، ليس خضوعاً، بل اعترافاً بقواعد اللعبة الجديدة. أدرك أن الطريق إلى فينلاند ليس معبداً بالورود، بل هو سلسلة من الآلام اليومية التي يجب عليه تحملها. وفي تلك اللحظة، وسط ضجيج المنجل واحتكاك القمح، أدرك أن حريته لم تكن في الهروب، بل في تحويل هذا الجحيم الصغير إلى مساحة للنجاة. سحب إينار نفساً عميقاً، وأمسك بأداة الحفر التي ألقيت إليهما. كان الصمت بينهما أبلغ من الكلام، فقد بدأت رحلة التغيير، ليس بالسيوف، بل بقطرات العرق التي ستبتلعها هذه الأرض الجائعة.', '', 103, '2026-07-15 15:17:54.637', '2026-07-15 15:17:54.637');
INSERT INTO public.chapters VALUES ('93542164-be61-4fa4-ba99-837be05b23b8', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 105: خلف أسوار الترقب', '— --------------------------------------- توقفت العربات عن الحركة فجأة، وامتزج صرير العجلات الخشبية المتهالكة مع أنفاس الخيول المجهدة. كان الممر الجبلي ضيقاً، تكتنفه صخور جرداء تمنع الرؤية لما وراء المنعطف. ترجل ثورفين، ممسكاً بمقبض خنجره، عيناه تمسحان المكان بحدة، لا شيء سوى الصمت المطبق الذي يسبق العاصفة. تقدم إينار بجانبه، ملامحه متشنجة، يده تقبض على مقبض فأسه بقوة جعلت مفاصل أصابعه تبرز تحت جلده المحروق. لم تكن المسافة تفصلهم عن وجهتهم سوى بضع مئات من الأمتار، لكنها كانت مسافة محفوفة بالمخاطر المتربصة. قطع الصمت صوت خطوات ثقيلة تقترب من الجهة الأخرى للمنحدر. ظهرت هيئة عريضة تبرز من خلف الصخر، رجل بملامح حفرها الزمن والمعارك، يرتدي درعاً جلدياً قديم الأثر. توقف الرجل، وألقى نظرة فاحصة على القافلة، ثم أشار بيده إلى رفاقه المختبئين في الظلال. قال الرجل بنبرة خشنة تفتقر إلى أي تهديد مباشر: الطريق مغلق بأمر من السادة، لا مرور اليوم، ولا غد. كان صوت ثورفين مقتضباً حين أجاب، دون أن يغير وضعيته الدفاعية: نحن لا نبحث عن قتال، فقط طريق العبور إلى الأرض الموعودة. ارتسمت على وجه الرجل ابتسامة صفراء باهتة، وقال بتهكم: الأرض الموعودة؟ الجميع هنا يبحث عن أرض، لكن لا أحد يملك ثمن المرور. وضع ثورفين قدمه للأمام، انقبضت عضلات فخذيه استعداداً لاندفاع سريع، لكنه لم يهجم. كانت عيناه، الغائرتان والمليئتان بندوب الماضي، تراقبان كل حركة لخصمه، ليس كعدو، بل كعقبة يجب تجاوزها بالحكمة أو بالقوة. استمرت المواجهة الصامتة، حيث الثواني تمر كأنها ساعات، وأي حركة خاطئة قد تشعل شرارة دماء لا يحتاجها أحد. اقترب إينار خطوة، هامساً بصوت مخنوق: ثورفين، لا يمكننا العودة، المؤن بدأت تنفد. أومأ ثورفين برأسه دون أن يلتفت، ثم وجه نظره مباشرة إلى الرجل الواقف أمامهم: إذا كان الثمن دماً، فقد دفعنا منه الكثير، وإذا كان ذهباً، فنحن لا نملك سوى العمل. ساد صمت ثقيل، نظر الرجل في عيني ثورفين، وكأنه يبحث عن الخوف أو الكذب، لكنه لم يجد سوى جدار من الصلابة. تنفس الرجل بعمق، ثم أشار لرجاله بالتنحي عن الممر، وقال متمتماً لنفسه: هؤلاء مجانين، ولكنهم لا يخشون الموت. تحركت القافلة ببطء، وتجاوزت رجال العصابات الذين بقوا يراقبونهم بنظرات مريبة. مع كل خطوة، كان ثورفين يشعر بعبء الرحلة يثقل كاهله، لكنه لم يلتفت للوراء. كانت الأفق أمامهم يبدأ بالانكشاف، حيث تلوح في البعيد تضاريس الأرض التي وعدوا ببنائها، أرض لا تحكمها السيوف، بل تحكمها الإرادة.', '', 104, '2026-07-15 15:17:54.838', '2026-07-15 15:17:54.838');
INSERT INTO public.chapters VALUES ('4c60aad5-db4c-4c3f-8357-a62f274446d7', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 106: أصداء السيوف الصدئة', '— --------------------------------------- توقف ثورفين عن الحركة فجأة، كانت يداه المضمومتان ترتجفان بشكل طفيف، لا من البرد، بل من وطأة ما يراه. أمامه في الساحة، وقف الرجل ذو الندبة، ملامحه المنقوشة بمرارة الزمن تشي بماضٍ لا يرحم. لم يقل ثورفين شيئاً، بل أطبق فكيه بإحكام حتى برزت عروق عنقه. في هذه اللحظة، لم تعد الغابة المحيطة أو صخب الرجال خلفه ذوي أهمية؛ كان العالم قد انحصر في تلك المسافة القصيرة التي تفصله عن خصمه. نبح أحد الرجال بأمرٍ خشن، مكسراً حدة الصمت، لكن ثورفين لم يلتفت. تلاشت حدة اندفاعه المعهودة، وحلت محلها حالة من اليقظة الحذرة، تلك التي تعلمها في رحلاته الطويلة. سحب خصمه نصله ببطء، صرير المعدن حين احتك بالغمد كان كافياً لشد أعصاب الحاضرين. ألقى الرجل نظرة فاحصة على ثورفين، نظرة خالية من الاحترام، مشوبة بتهكم صامت. قال ثورفين بصوت متحشرج، وكأنه يقتلع الكلمات من باطن صدره: لا أريد قتالك. ضحك الخصم، ضحكة جافة تشبه تكسر الأغصان اليابسة، ثم رد ببرود: العودة عن الطريق المسدود لا تسمى حكمة هنا، بل ضعفاً. لم يرد ثورفين، بل اتخذ وضعية دفاعية صلبة، باسطاً ذراعيه قليلاً ليوازن ثقل جسده. كان يعلم أن أي خطأ في الحساب يعني نهاية الرحلة قبل أن تبدأ. تحرك خصمه كبرقٍ خاطف، سيفه يقطع الهواء باتجاه كتف ثورفين، لكن الأخير انحنى في حركة رشيقة، تاركاً النصل يمر على بعد شعرة من جلده. ارتطمت قدما ثورفين بالتربة، ودفع بجسده للأمام، مستغلاً الفراغ الذي تركه اندفاع خصمه. لم تكن حركة ناتجة عن غضب، بل عن حاجة ماسة للبقاء. تصادمت نظراتهما للحظة، وفي تلك العيون لم يجد ثورفين سوى الفراغ الموحش الذي يتركه القتل خلفه. انزوى الرجال ليشاهدوا، يتنفسون بصوت عالٍ، يراقبون الرقصة الدموية التي بدأت للتو. لم يندفع ثورفين للهجوم، بل ظل يراوغ بتركيزٍ حاد، مراقباً تذبذب حركة كتفي خصمه، باحثاً عن الثغرة التي ستنهي هذا العبث دون أن يضطر لتلطيخ يديه بالدماء مجدداً. كان النصل يلمع تحت ضوء النهار الشاحب، وكل ومضة كانت تذكره بأن السلام الذي يبحث عنه يمر دائماً عبر بوابة القتال.', '', 105, '2026-07-15 15:17:55.054', '2026-07-15 15:17:55.054');
INSERT INTO public.chapters VALUES ('5561c24c-2ebf-4bb7-974c-1628a8e554ef', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 107: خلف أسوار العزلة', '— --------------------------------------- توقف ثورفين أمام البوابة الخشبية العتيقة، كان صمت المكان يثقل كاهله أكثر من أي نصل. لم تكن هناك رياح، فقط صوت تنفسه المتقطع يتردد في الممر الضيق. التفت نحو إينار الذي كان يقف خلفه، يمسح العرق عن جبينه بظهر يده الملوثة بالطين، ملامحه تعكس مزيجاً من التوجس والترقب. دفع ثورفين البوابة بكتفه، فأصدرت صريراً حاداً مزق سكون النهار. في الداخل، لم يجد ثورفين سوى كومة من الذكريات المحطمة وأدوات ملقاة في فوضى متعمدة. حدق في الفراغ، شعر بانقباض في عضلة فكه؛ فكل زاوية في هذه الغرفة تعيد صدى الكلمات التي حاول نسيانها. تقدم إينار خطوة، ونظر إلى الرماد المتناثر في الموقد، ثم همس بصوت خفيض: ''هل هذا هو المكان الذي كنت تبحث عنه؟ ''. لم يجب ثورفين، بل انحنى ليلتقط قطعة معدنية صدئة، أصابعه ترتجف طفيفاً، ليس من الخوف بل من وطأة الماضي. في تلك اللحظة، لم تعد الغرفة مجرد مساحة مهجورة، بل تحولت إلى ساحة معركة داخلية، حيث تتقاطع رؤى السلام مع ظلال العنف التي لم تغادر مخيلته قط. التفت ثورفين بحدة، عيناه كانتا باردتين كالفولاذ، وقال بصوت مقتضب لا يقبل التأويل: ''لا تلمس شيئاً هنا''. استدار عائداً نحو ضوء الشمس المتسلل من الفتحة، تاركاً إينار في صدمته، بينما كانت أفكاره تتلاطم كأمواج عاتية، لا تبحث عن مخرج، بل تبحث عن معنى لحياة لم يعد فيها مكان للسيف.', '', 106, '2026-07-15 15:17:55.302', '2026-07-15 15:17:55.302');
INSERT INTO public.chapters VALUES ('3e1ff3cd-5076-4399-bc0d-53ce94d6c99d', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 108: صدى الماضي في أروقة النسيان', '— --------------------------------------- انقبضت أصابع ثورفين حول مقبض خنجره المتهالك، فبرزت عروق يده كأنها تضاريس خريطة من الألم القديم. في تلك اللحظة، لم يكن العالم سوى مساحة ضيقة من الغبار والضوء الشاحب الذي يتسرب من شقوق السقف. كان ''سنيغ'' يراقب من زاوية الغرفة، عيناه تزيغان بترقب حيواني، بينما كان ثورفين يحدق في الفراغ، يرى وجوهاً لم تعد موجودة إلا في أروقة ذاكرته المعذبة. انكسر الصمت المطبق بصوت حشرجة خافتة، حين ألقى ثورفين بكلماته الأولى، كانت مقتضبة، خشنة، كأنها حجارة تُخرج من جوف بئر: ''لا يمكن للندم أن يمحو الدماء يا سنيغ. لا يمكن للماضي أن يعيد ترتيب أجزائه''. لم يكن ثورفين يبحث عن المواساة، بل كان يواجه حقيقة استيقاظ الوحش الذي حاول طمسه طويلاً. تحرك جسده بتشنج، مشى بضع خطوات نحو النافذة الخشبية؛ كان وقع قدميه على الأرضية الخشبية المتهالكة يتردد بحدة في أذنيه. أسفل النافذة، كانت القرية تغط في سبات يثير الضجر، لكن داخل رأسه، كانت طبول الحرب تقرع بانتظام رهيب. لم يكن ''سنيغ'' يملك ما يقال، اكتفى بمسح جبهته المتعلقة بالعرق، فالحوار مع ثورفين لم يكن يوماً تبادلاً للأفكار، بل كان صراعاً ضد الصمت المطبق الذي يغلف روح الفتى. التفت ثورفين فجأة، كانت ملامحه حادة كشفرة سيف، وسأل بصوت منخفض، مشحون بنبرة تهديد خفية لذاته قبل الآخرين: ''هل تعتقد أن الغفران متاح لمن أيدي ملطخة بظلال الموتى؟ ''. سقطت كلمة ''الموتى'' في الغرفة كثقل مادي، وتجمد الهواء بينهما. لم ينتظر ثورفين إجابة، بل استدار ليرمي بجسده على فراشه، مغلقاً عينيه بإحكام، محاولاً حجب صور وجوه أولئك الذين سلبهم الحياة في رحلاته السابقة. في الخارج، بدأت السماء تتلبد بكتل رمادية من السحب، وبدأ المطر يقرع بانتظام على السقف، صوتاً كان يشبه إلى حد بعيد وقع السيوف على الدروع في ساحات الوغى التي لا تنتهي.', '', 107, '2026-07-15 15:17:55.557', '2026-07-15 15:17:55.557');
INSERT INTO public.chapters VALUES ('6c3895be-ee32-4ba7-b95d-274aaf22ba2b', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 109: خلف أسوار الجليد', '— --------------------------------------- توقف ثورفين عن الحركة. لم تكن ثلوج فينلاند الساكنة هي ما استوقفه، بل الصوت الخافت لخطواتٍ لم تكن تنتمي لأي من رجاله. استدار ببطء، كانت عيناه تتفحصان الأفق الرمادي حيث تتلاشى الغابة في الضباب. وقف ''ايهنار'' خلفه متأهباً، ويده اليمنى تستقر على مقبض فأسه، عضلات كتفيه مشدودة بانتظار أمر. لم يكن هناك صراخ، ولا ضجيج حرب، بل صمت مطبق يسبق المواجهة. ظهرت ملامح الغرباء ببطء؛ كانوا رجالاً أشداء ذوي نظرات واجفة، أسلحتهم ملطخة بآثار معركة لم يشهدها ثورفين، وفي عيونهم انعكاس لخوفٍ غريزي. تحرك ثورفين خطوة للأمام، رافعاً كفيه ببطء، دلالة على خلوهما من السلاح. نطق بصوتٍ أجش، لم يملؤه التهديد بل الاستقصاء: من أنتم، وما الذي يجلبكم إلى أرضنا في هذا الوقت؟ لم يأتِ الرد بالكلمات، بل بتراجعٍ طفيف من أحد الغرباء الذي بدا وكأنه يرى في ثورفين شبحاً لا بشراً. حدق ايهنار في وجوههم، ثم همس بنبرة خفيضة تخلو من الطمأنينة: هؤلاء ليسوا صائدي حيوانات، يا ثورفين. انظر إلى طريقتهم في حمل السيوف، إنهم معتادون على دماء البشر لا الوحوش. لم يلتفت ثورفين إليه، ظلت عيناه مثبته على قائد المجموعة، رجل ذو ندبة عميقة تقطع حاجبه الأيسر. تنفس ثورفين بعمق، وشعر بضغط الهواء البارد في رئتيه، صمت للحظات، يراقب تشنج يد الرجل الغريب على مقبض سيفه، ثم قال بلهجة قاطعة: لا نريد قتالاً، لكنني لن أسمح لأي روحٍ أن تروع أرضنا. تلاشت المسافة بين الطرفين حتى بات بإمكانهم سماع دقات قلوب بعضهم في ذلك الفراغ البارد. اتسعت بؤرة عين الغريب، وتجمدت حركته في محاولة لاستيعاب ثبات ثورفين المريب. لم يكن هناك مفر، فالقوانين القديمة التي صاغتها الحروب في عقولهم كانت توشك على الاصطدام بقناعة ثورفين الجديدة. ببطء، أخذ القائد الغريب يغمد سيفه، حركةٌ لم تكن توحي بالسلام، بل بحذرٍ شديد وريبة لا تنتهي. نظر ثورفين إلى الأفق، مدركاً أن عهداً من الصمت قد انتهى، وأن ما بناه في فينلاند بات الآن تحت تهديدٍ لا يمكن صده بالكلمات وحدها.', '', 108, '2026-07-15 15:17:55.732', '2026-07-15 15:17:55.732');
INSERT INTO public.chapters VALUES ('407c44fe-1410-438e-a6bd-46377ac991ae', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 110: خلف أسوار الخوف', '— --------------------------------------- انغلق باب خيمة سيغورد بإيقاع ثقيل، مخلفاً وراءه صدى اصطدام الحديد بالخشب. لم يلتفت ثورفين، بل ظل بصره معلقاً بتلك الرقعة من الأرض القاحلة التي تفصل بين معسكرهم وبين المجهول الذي ينتظرهم خلف التلال. كانت أذناه تلتقطان أنفاساً مضطربة ووقع خطوات غير منتظمة لجنود لا يجدون في الانتظار سوى ضريبة من أعصابهم. اقترب غودريد، كانت ملامحها تشي بتوتر محبوس، قبضت بيدها على حافة ثوبها بقوة جعلت مفاصل أصابعها تبرز شاحبة. همس ثورفين دون أن يغير وضعيته: «الخوف يسبق النصل دائماً، لكنه أحياناً يكون البوصلة الوحيدة التي تبقينا على قيد الحياة». لم تكن جملة مواساة، بل تقريراً بارداً لواقع يدركه كلاهما. في الجهة المقابلة، كان رجال سيغورد يتجمعون حول نيران مخبوءة، يتبادلون نظرات لا تخلو من الترقب والحذر. لم تكن هناك أحاديث مفعمة بالأمل؛ كانت أصواتهم عبارة عن شظايا جمل مقتضبة حول العتاد، وسلامة السيوف، ومدى ثبات الدروع. ساد صمت مفاجئ عندما توقف صوت غناء بعيد، ليحل محله دوي صهيل خيلٍ في المرعى، مما دفع الجميع إلى التصلب في أماكنهم، عيونهم تتفحص الظلال الممتدة على الأرض كأنها أعداء يتربصون. مسح ثورفين وجهه بكفه الخشنة، وتراجع خطوة إلى الوراء ليختفي في شبه عتمة الخيمة، تاركاً غودريد تواجه برودة المساء. لم تكن المسألة تتعلق بالقتال، بل بالقدرة على البقاء واقفاً بينما يتداعى العالم من حولهم. أدرك ثورفين أن اللحظة الفاصلة لن تأتي بجلبة الصراخ، بل بالتلكؤ الذي يسبق هدوء العاصفة، حيث يتوقف كل شيء، وتصبح نبضات القلب هي الصوت الوحيد المسموع في المدى الفسيح.', '', 109, '2026-07-15 15:17:55.931', '2026-07-15 15:17:55.931');
INSERT INTO public.chapters VALUES ('f9042deb-ded0-4bd6-bef2-c7fcf9c6e0b9', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 111: حين تصمت السيوف في أرض الأحلام', '— --------------------------------------- انغلق باب خيمة القائد خلف ثورفين، تاركاً إياه في مواجهة مباشرة مع إيغار. لم تكن هناك مقدمات؛ كان هواء الخيمة ثقيلاً برائحة التبغ والجلد الجاف. رمق إيغار ثورفين بنظرة فاحصة، تلك النظرة التي لا تبحث عن سلاح، بل عن صدق النية في عينين خبت فيهما بريق الانتقام القديم. قال إيغار بصوت متهدج: أتعلم ما الذي نطلبه حقاً؟ نحن لا نبحث عن أرض للزراعة فحسب، بل عن مكان لا تلاحقنا فيه ظلال الماضي. ثورفين لم يجد في كلمات إيغار رغبة في القتال، بل وجد انعكاساً لرحلته هو. ساد صمت مطبق، لم يقطعه سوى أنين الخشب تحت ثقل الريح الخارجية. أجاب ثورفين ونبرة صوته تفتقر إلى أي تهديد أو حدة اعتيادية: لن تكون مهمة سهلة. العقبات أمامنا ليست من خشب أو حجر، بل هي في طبيعة الرجال الذين سيرافقوننا. قبض إيغار على مقبض كرسيه، وشد على أسنانه حتى برزت عضلات فكه. التفت ثورفين نحو مخرج الخيمة، وكانت ملامحه قد تجمدت في قناع من التصميم الهادئ، بعيداً عن صخب المعارك التي خاضها في شبابه. خرج ثورفين ليتنفس الهواء الطلق، بعيداً عن ثقل المفاوضات. في الخارج، كانت السفن ترسو بانتظام، والرجال يتبادلون الأوامر بصوت خشن ومباشر. لم يعد هناك مكان للأسئلة الفلسفية التي كان يطرحها على نفسه في الليالي الطويلة. كانت الأولوية الآن واضحة: جمع المؤن، حشد الرجال، والتحرك نحو المجهول الذي سُمي فينلاند. وبينما كان يمشي على الرصيف الخشبي المتهالك، اصطدم كتفه بكتف أحد البحارة الذي نظر إليه بحدة، لكن ثورفين تجاوز الأمر ببرود، فجسده لم يعد يستجيب للاستفزاز كما في السابق. عضلاته التي اعتادت على تقلبات النصل، باتت الآن مشدودة نحو هدف واحد: البقاء وصناعة حياة في أرض لم يطأها الحقد بعد.', '', 110, '2026-07-15 15:17:56.185', '2026-07-15 15:17:56.185');
INSERT INTO public.chapters VALUES ('4b8c9978-c858-4cad-9b7e-37c11026a642', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 112: خلف أسوار الترقب', '— --------------------------------------- توقف إينار عن التجديف، سقط المجدفان في مياه النهر بضجيج مكتوم. كان الصمت الذي يلف أطراف مستوطنة ''ثورفين'' ثقيلاً، مشحوناً برائحة الطين والأرض المبللة. وقف ثورفين على حافة القارب، عيناه مثبتتان على الهياكل الخشبية التي بدأت تظهر خلف الضباب. لم يكن التوتر ملموساً في الهواء فحسب، بل كان يرتسم على تجاعيد وجوه الرجال الذين اصطفوا على الضفة. هيلد لم تنطق بكلمة، لكن يدها استقرت فوق قوسها، وأصابعها تتحسس نصل السهم المعتاد. سأله إينار بصوت منخفض تشوبه ريبة واضحة: هل هم حقاً بانتظارنا؟ اكتفى ثورفين بهزة رأس بطيئة. تقدمت المجموعة نحو المركز، حيث كان حشد من السكان المحليين قد تجمعوا في دائرة غير منتظمة. لم تكن وجوههم تعبر عن الترحيب، بل كانت مزيجاً من الحذر والعداء الصامت. اقترب رئيس القبيلة، خطاه ثقيلة، ونظراته تنبش في ملامح ثورفين بحثاً عن غاية خفية. قال الرجل بلغة مكسورة ونبرة حادة: قل لنا ما جئت به، ولا تدع كلماتك المسمومة تخدعنا هذه المرة. ثورفين لم يتراجع، وضع يده على صدره، ملامحه هادئة لكنها تخفي خلفها سنوات من النزاع الذي أحرقه. رد ثورفين بوضوح: نحن هنا لنبني، لا لنسلب. جئنا لنعيش بسلام، لا لنكرر فصول الماضي. تصاعدت همسات بين الحشود؛ شاب يمسك بفأس ارتجفت يده، وامرأة مسنة أدارت وجهها نحو الغابة. لم يكترث ثورفين للهمس، بل استمر في سرد رؤيته لبلاد ''فينلاند'' حيث لا حاجة للسيف. قاطعه أحد المحاربين بضحكة ساخرة، صرخ بمرارة: لا أحد يأتي من الشمال بيده خالية! الجميع يطلب شيئاً، الجميع يطمع في أراضينا. اقترب هيلد خطوة، صمتها كان أشد وطأة من ضجيجهم، ثم قالت بصوت مسموع وبارد: نحن نطلب الحق في العيش، فإذا كان هذا طمعاً، فليكن. تلاشت حدة النقاش للحظات، تاركة المكان للفراغ والرياح التي بدأت تشتد. نظر ثورفين إلى أفق الأرض البكر، كان يدرك أن السلام الذي ينشده ليس مجرد قرار، بل هو معركة يومية أشد قسوة من حروب السيوف التي خاضها في شبابه.', '', 111, '2026-07-15 15:17:56.42', '2026-07-15 15:17:56.42');
INSERT INTO public.chapters VALUES ('1d2ffc86-ee76-429d-b99b-bea43e119ed0', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 113: سُباتُ السيف ونداءُ الأرض', '— --------------------------------------- توقف ثورفين عن الحركة فجأة، كانت يداه، اللتان اعتادتا لسنوات أن تكونا مخلبين للفتك، تسترخان الآن بجانبه كأنما فقدتا غرضهما. ساد صمت ثقيل في أرجاء المعسكر، صمت لا يقطعه إلا خشخشة النار الهامدة. نظر هيلد إلى ثورفين، عيناها تراقبانه بحذر، ليس كحليف، بل ككائن غريب يحاول فك شفرة تناقضه. قال ثورفين بصوت خفيض، نبرته خشنة كأنها تخرج من حلق لم يمارس الحديث الصادق منذ زمن: لن نقتل أحداً. ساد صمت آخر، أطول وأكثر حدة. استدارت هيلد نحوه، ضيقت عينيها، وقالت بصوت متهكم خالٍ من التعاطف: أنت تتحدث عن عالم لا وجود له، يا ابن ثورس. خيارك هذا ليس سلاماً، بل هو انتحار بطيء. لم يجب ثورفين، بل اتجه ببصره نحو الأفق المظلم، حيث تختبئ التلال خلف ستائر الضباب. تذكر كلمات والده التي كانت تتردد في أصداء ذاكرته كجرسٍ بعيد: لا عدو لأحد. تلك الفلسفة التي بدت في صباه كأنها سذاجة مطلقة، أصبحت الآن عبئاً ثقيلاً ينوء به كاهله. في هذه الأثناء، كان إينار يراقب المشهد من بعيد، عيناه تعبران عن حيرة ممزوجة باحترام صامت. كان يعلم أن ثورفين لا يهرب من المعركة، بل يواجه حرباً من نوع آخر، حرباً داخلية لا تُخاض بالسيوف، بل بضبط النفس القسري الذي يكاد يمزق أوردته. تحرك ثورفين خطوة للأمام، تجاه الغابة الموحشة التي تنتظرهم، لم يكن يرتدي درعه، ولم تكن يده تتلمس خصرَه حيث اعتاد حمل نصله. كان يمشي كمن يمشي على حافة هاوية، مدركاً أن أياً من رفاقه قد يطعنه في ظهره، أو قد ينهار هو نفسه تحت وطأة الذكريات. هيلد، التي كانت تضع إصبعها على مسمار قوسها، خففت من قبضتها قليلاً، لكنها لم تزل حذرة. تساءلت: وماذا لو واجهنا الموت؟ أجاب ثورفين دون أن يلتفت: سنتلقاه، لكننا لن نكون سبباً فيه. كانت نبرته خالية من التردد، صلبة كصخرة جبلية، مما جعل هيلد تبتلع كلماتها الساخرة وتكتفي بنظرة طويلة تملؤها الريبة. انطلق الفريق في المسير، تاركين خلفهم رماد النار ومكان إقامتهم المؤقت، متوجهين نحو مصير مجهول لم يرسمه القوة، بل رسمه إيمان ثورفين بوجوب الخلاص من دائرة الدم.', '', 112, '2026-07-15 15:17:56.621', '2026-07-15 15:17:56.621');
INSERT INTO public.chapters VALUES ('1a992829-5908-4aab-845f-1c4cdf305103', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 114: خلف أسوار الخديعة', '— --------------------------------------- انزلق النصل الحديدي عبر الفراغ ليصيب هدفه بدقة جراحية في مفصل الركبة. لم تكن صرخة الرجل الذي سقط هي ما ميز المشهد، بل الصوت الجاف لتمزق الأنسجة الذي تردد في أرجاء المكان. وقف ثورفين وسط الغبار، يراقب خصمه الذي حاول جاهدًا التشبث بسيفه الملقى بعيداً. كانت عيناه، الغائرتان خلف إرهاق السنين، لا تحملان غضباً، بل بروداً حاداً كالمشرط. همس ثورفين بكلمة واحدة: كفى. لم يلتفت نحو رفاقه، كانت حواسه مسلطة بالكامل على وتيرة أنفاس الرجل المحطم أمامه. من زاوية الغرفة، برز هيلد، ممسكاً بسلاحه الخشبي المصمم بإتقان، وجهه مقنع بهدوء مريب. كان الصراع بينهما لا يُحسم بالحديد، بل بالترقب. تحرك هيلد بخفة، مباغتاً ثورفين بحركة دائرية سريعة استهدفت معصمه، لكن ثورفين انحنى بجسده في اللحظة الأخيرة، تاركاً الريح تصفّر في الفراغ الذي شغله رأسه قبل ثانية. لم يتحدث هيلد، فقد كان صمته سلاحه الأفتك. اقترب هيلد خطوة، وارتسمت على شفتيه ابتسامة شاحبة حين أدرك أن ثورفين لم يستل خنجره بعد. قال هيلد بصوت متهدج بالكاد يُسمع: أنت لا تقاتل يا ثورفين، أنت تتلقى الضربات بانتظار معجزة. هز ثورفين رأسه نفياً، وتصلبت عضلات فكيه. لم تكن معجزة، كان إيماناً أعمى بأن القتال يمكن أن ينتهي دون إراقة المزيد من الدم. وفي الخارج، كانت أصوات حوافر الخيول تبتعد مخلفة وراءها سحابة من الغبار، بينما كان الرجال داخل الحصن يتبادلون نظرات الترقب والريبة. كان الجو مشحوناً بتوتر صامت؛ صراع أرادات لا يقطعه إلا خشخشة الدروع الثقيلة عند كل حركة مترددة. التفت ثورفين إلى الباب المفتوح، حيث كان الضوء المتسلل يغطي أرضية القاعة بخطوط حادة، وبدأ يدرك أن طريقه نحو فينلاند لن يكون مفروشاً بالكلمات الطيبة فحسب، بل بقرارات قاسية تقتلع جذور العنف من داخل نفسه، حتى وإن كلفه ذلك حياته.', '', 113, '2026-07-15 15:17:56.82', '2026-07-15 15:17:56.82');
INSERT INTO public.chapters VALUES ('ed90b250-43e0-4059-8fd5-ece13f830e9e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 115: خلف أسوار الرماد', '— --------------------------------------- ارتطم نعل ثورفين بالأرض الترابية بقوة لم يكترث معها لصوت ارتطامه، كان إيجيل يقف أمامه، ملامحه متصلبة كصخر نورديك صلد، بينما تفوح من المكان رائحة الأرض المحروثة حديثاً الممزوجة بحدة الحديد المتأهب. لم يلقِ إيجيل تحية، بل أشار بيده ذات المفاصل البارزة نحو الحقول التي تمتد خلفه كبساط عظيم من القمح الذهبي. قال إيجيل بصوت أجش ونبرة تقطر حدة: هل تظن حقاً أن الأرض التي نزرعها بالدم ستنبت لنا سلاماً يا ابن ثورس؟ ثورفين لم يرمش، بل ثبت بصره على نصل فأس إيجيل المغروس في وتد خشبي قريب، وشد على قبضتي يديه حتى ابيضت مفاصله. أجابه ثورفين بصوت منخفض، مشحون بثقل السنين: لست هنا لأحاضر في الزراعة، جئت لأرى ما إذا كان هذا المكان يستحق البقاء. ضحك إيجيل ضحكة مقتضبة، خالية من أي مرح، وخطا خطوة واحدة نحو ثورفين، مما جعل الهواء بينهما يبدو وكأنه يتكثف بفعل التوتر. كان إيجيل رجلاً يزن الكلمات كما يزن الذهب، ولا يثق في الغرباء الذين يدعون السلم. تساءل إيجيل بتهكم: السلم الذي تبحث عنه ليس سوى وهم يطارده الضعفاء، أنت تحمل ندوباً في وجهك تروي قصصاً لا تشبه كلماتك المنمقة عن اللاعنف. صمت ثورفين، بينما تحركت عضلات فكه السفلي ببطء، وتذكر للحظة وجوه الرجال الذين قتلهم، وجوههم التي تلاحقه في يقظته. حاول إيجيل اختباره بلمحة عدائية، فرفع يده فجأة نحو كتف ثورفين، لكن الأخير لم يتراجع، بل بقي صامداً، عيناه الغائرتان تحكيان عن حرب داخلية لا تنتهي. قال إيجيل حينها بنبرة تغيرت فجأة إلى شيء يشبه الاحترام الحذر: يبدو أنك رأيت الجحيم بما يكفي لتعرف أن السلم ليس خياراً، بل هو عبء ثقيل لا يقوى عليه إلا الموتى أو من ماتوا في الداخل. ساد صمت مطبق إلا من حفيف سنابل القمح التي تداعبها ريح خفيفة. أدرك ثورفين في تلك اللحظة أن إيجيل ليس مجرد عامل في مزرعة كيتيل، بل هو رفيق في رحلة البحث عن معنى لوجود سُلب منهم في ميادين الوغى. استدار ثورفين ونظر نحو الأفق، حيث تبدأ الغابات المظلمة، وقال بصوت حازم: سنعمل، سنزرع، وسنرى ما إذا كانت الأرض ستطعمنا أم ستطالب بالمزيد من الدماء.', '', 114, '2026-07-15 15:17:57.033', '2026-07-15 15:17:57.033');
INSERT INTO public.chapters VALUES ('79f4e616-a0d1-42d5-b1e2-e4cf1bd71634', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 116: ثمن العودة إلى الديار', '— --------------------------------------- توقف ثورفين عن الحركة. في ساحة العرض القاحلة، وسط جلبة الرجال واستعدادات الرحلة التي بدت في نظرهم خلاصاً وفي نظره عبئاً، كان الضجيج يبتلع صدى الكلمات التي لم تُقل. نظر إلى يديه، تلك اليدان اللتان اعتادتا قبض مقبض السيف، واللتان باتتا الآن مفرغتين من غايتهما القديمة. اقترب منه إينار، ملامحه مشدودة، وعيناه تفتشان في وجه ثورفين عن إشارة طمأنة لم يجدها. قال إينار بصوت خفيض تشوبه رغبة جامحة في الرحيل: هل حقاً سنغادر؟ هل انتهى الأمر هنا؟ التفت ثورفين نحوه، لم تكن عيناه تعبران عن حماس الفاتحين، بل عن ثقل رجل يدرك أن الأرض التي سيعبرونها ليست مجرد رمال، بل قبور لم تفتح بعد. أجاب ثورفين بصوت مقتضب: الرحلة ليست خروجاً من هنا، بل دخولاً في غياهب المجهول. لا تتوقع أن ترحب بك الأرض التي لم تزرعها. كان هوفار ورفاقه يتحركون في الخلفية، أصوات احتكاك الدروع المعدنية تطغى على همساتهم. اقترب منهم ''هلد''، صمتها كان أشد وطأة من ضجيج المعسكر. وقفت تراقب الأفق، بؤبؤا عينيها كانا يتحركان ببطء، يحصيان السفن القليلة التي ستبحر نحو ''فينلاند''. لم تنطق بكلمة، لكن انقباض كفيها على قوسها كان يشي بالصراع الذي تضمره. التفت ثورفين إليها، توقف الزمن للحظة بينهما؛ لم يعد هناك عدو ليطعنه، ولا ثأر يدفعه للأمام، فقط تلك الرغبة المشتعلة في بناء شيء لا يرتوي من الدماء. التفت ثورفين إلى الطاقم وصرخ بنبرة خشنة خالية من التودد: لن نعود لنهب القرى، ولن نعود لنحرق المنازل. من يبحث عن المجد في جثث الآخرين، فليغادر الآن. صمت الرجال، ارتجفت الأرجل في أماكنها، وانكسر الهدوء المفاجئ بصوت ارتطام مرساة بالسفينة. تحركت الأيادي المخشوشنة لتعديل الأشرعة، بينما بدت السفينة كأنها وحش أسطوري يستعد لابتلاعهم في جوف البحر الواسع. كانت تلك اللحظة هي الفاصلة بين ماضٍ يجرونه خلفهم كالسلاسل، ومستقبل لا يملك ثورفين له ضماناً، سوى إيمانه الراسخ بأن الأرض التي تنبت بذور السلام لا تسقى إلا بالصبر، لا بالدم.', '', 115, '2026-07-15 15:17:57.263', '2026-07-15 15:17:57.263');
INSERT INTO public.chapters VALUES ('13fb8a20-9c1b-4d4a-9d03-208db57a198d', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 117: سديم الوعود المنسية', '— --------------------------------------- تصلب إينار في مكانه، عيناه معلقتان بملامح ثورفين التي خلت من أي تعبير سوى ترقب صامت، بينما كانت أصوات صخب الميناء تتلاشى في الخلفية لتتحول إلى طنين بعيد. لم تكن المسافة الفاصلة بينهما مجرد بضعة أمتار من الأرض الرطبة، بل كانت هوة من الاعترافات المؤجلة. قال إينار بصوت متهدج، وقد برزت عروق عنقه تحت ضغط انفعاله: هل تعي حقاً ما تقوله؟ أتريد حقاً بناء مجتمع بلا حرب في بقعة من الأرض لم تطأها أقدامنا بعد؟ ضيق ثورفين عينيه، ومال بجسده إلى الأمام قليلاً، محتجاً على الاندفاع في نبرة رفيقه، ورد بصوت منخفض، جاف، وخالٍ من التنميق: لن نبني شيئاً بوجود السيوف في أيدينا. نحن نحمل أوزار الماضي، وإذا واصلنا السير في ذات الدرب، فسننتهي جثثاً هامدة كما انتهى من سبقونا. كان ثورفين يفرك كفيه الخشنتين، حركات عصبية تظهر صراعاً داخلياً لم يطمس بعد رغم سنوات السعي نحو السلام. هز إينار رأسه بنفي، وابتسم بمرارة، مشيراً بيده إلى الأفق البعيد حيث تلاطم الأمواج الصخور: الأرض التي تنشدها يا ثورفين ليست جنة، بل هي غابة وحشية، إن لم تكن ذئباً فستلتهمك الذئاب. هذا هو القانون الذي نعرفه، القانون الذي نعيشه. توقف ثورفين عن الحركة فجأة، وثبّت نظره في عيني إينار مباشرة، صمته هذه المرة كان أشد وطأة من أي حجة لغوية. لم يكن يحاول إقناعه بمنطق، بل كان يعرض عليه ندوب روحه كدليل على أن العنف لم يجلب سوى الخواء. في تلك اللحظة، لم تعد المسألة تتعلق بالرحلة إلى فينلاند أو باحتمالات النجاة، بل بنوع الحياة التي يستحقون أن يحيونها. قال ثورفين، ونبرته الآن تحمل ثقلاً لا يقبل الجدل: لا أطلب منك أن تثق في قدرتي، بل أطلب أن تثق في أننا نستطيع فعل ما هو أفضل من التكرار. تراجع إينار خطوة إلى الوراء، وقد اتسعت عيناه قليلاً قبل أن يطبق جفنيه للحظات، محاولاً استيعاب فداحة القرار. كان الهواء يتصاعد من أنفاسهما في رذاذ خفيف مع تباشير الصباح، بينما كانت السفينة راسية بانتظار إشارة الانطلاق، كتلة خشبية ضخمة تلوح كأنها صلة الوصل الوحيدة بين ماضٍ ملطخ بالدماء ومستقبل غامض لا يلوح فيه أفق للطمأنينة.', '', 116, '2026-07-15 15:17:57.455', '2026-07-15 15:17:57.455');
INSERT INTO public.chapters VALUES ('c34092b9-886f-4ed2-b81f-2be5e81b1195', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 118: صدى النصال في مأدبة اليأس', '— --------------------------------------- تصلبت ملامح ثورفين وهو يراقب الجرح المفتوح على ذراع خصمه. لم تكن هناك كلمات تلطف حدة الموقف، فقط صوت أنفاسه المتقطعة التي تمتزج بضجيج الميدان الصاخب. تقدم الرجل الضخم، تلوح فأسُه في الهواء كقوس من حديد بارد، بينما تراجع ثورفين خطوة واحدة إلى الوراء، موازناً ثقله على ساقيه المشدودتين. لم يكن في عيني ثورفين ذاك البريق القتالي المعتاد، بل كان ثمة تركيز حاد، أشبه بتركيز حيوان يترقب لحظة انقضاض لا بديل عنها. زمجر الخصم ملوحاً بسلاحه، لكن ثورفين انحنى بجسده انحناءة خاطفة، ليمر نصل الفأس فوق رأسه بسنتيمترات معدودة، مخلفاً صوتاً حاداً كطنين النحل. في تلك اللحظة، استدار ثورفين بجسده بالكامل، مستغلاً اندفاع خصمه، وسدد ضربة دقيقة وموجعة إلى مفصل الركبة. تهاوى الرجل الضخم، وارتطم جسده بالأرض الموحلة بضجيج مكتوم. لم يتوقف ثورفين، بل أمسك بمعصم خصمه بيده القوية، لوي ذراعه خلف ظهره بضغط وحشي. صاح الرجل بألم مكتوم، محاولاً التملص، لكن ثورفين ثبته بإحكام أكبر، بينما كانت عيناه تمسحان المكان بحثاً عن تهديدات أخرى. تساءل أحدهم من خلفه بصوت أجش: هل ستقتله؟ لم يلتفت ثورفين، بل استمر في ضغطه على ذراع الرجل، وقال بصوت خشن ومختصر: ليس اليوم. ثم دفعه بقوة بعيداً عنه، لينهض الخصم متعثراً وهو يلهث، وقد اختفت رغبته في المواصلة. نظر ثورفين إلى كفيه المرتجفتين قليلاً بفعل الأدرينالين، ثم مسح العرق عن جبينه بظهر يده، متجاهلاً نظرات المراقبين المحيطين به. كان الهواء ثقيلاً، لكنه لم يعد يحمل رائحة الموت التي اعتادها في الحروب السابقة؛ كان هناك شيء غريب، صمت يغلف المكان بعد صخب النزال، صمت يعيد لثورفين ذكرى نصيحة والده التي ترفض الرحيل، رغم كل الدماء التي غطت يديه. لم يتفوه ببنت شفة، بل مضى مبتعداً، تاركاً الجميع في ذهول من قراره بالرحمة، مدركاً في أعماق نفسه أن هذه القوة التي يمارسها، في كبح جماح رغبته في القتل، هي المعركة الحقيقية التي لا تنتهي أبداً.', '', 117, '2026-07-15 15:17:57.633', '2026-07-15 15:17:57.633');
INSERT INTO public.chapters VALUES ('0baaebf9-1adf-4724-92cb-f782009a0e5a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 119: خلف أسوار التوقعات', '— --------------------------------------- انزلق ثورفين داخل خيمة القائد، بخطوات مكتومة لا تكاد تلامس التربة. لم يلتفت يميناً أو يساراً، فقد كان تركيزه منصباً على الرجل الجالس في العمق، الذي بدت ملامحه منحوتة من قسوة الأيام. رفع القائد رأسه ببطء، نظرة عينيه حادة كشفرة سيفٍ جُربت في معارك لا حصر لها، لم يلحظ ثورفين أي أثر للاستغراب في وجهه، بل كان هناك هدوء مريب يغلف المكان. قال القائد بصوت أجش لم يكد يخرج من حنجرته: لقد تأخرت يا صبي. توقف ثورفين عن الحركة، شد قبضتي يديه حتى برزت عروق ذراعيه، وبدا ملمس جلده مشدوداً تحت وطأة الضغط النفسي. لم ينبس ببنت شفة، بل اكتفى بتركيز بصره على خريطة جلدية متهالكة تفترش الطاولة الخشبية أمامهما. سادت لحظات من الصمت الثقيل، لم يقطعه سوى طقطقة الحطب في الموقد القريب. تابع القائد حديثه بنبرة ساخرة تكاد تلامس التحدي: هل جئت لتبحث عن إجابات، أم جئت لتضع حداً لمسيرتك؟ تقدم ثورفين خطوة واحدة إلى الأمام، غاصت قدماه في التراب، وبدأ صدره يعلو ويهبط بانتظام متمهل. لم تكن هذه المواجهة عابرة، بل كانت اصطداماً لإرادتين تشكلتا في أتون النيران والدم. رد ثورفين بنبرة حادة ومقتضبة: جئت لأن الطريق لم يعد يتسع لاثنين. ضحك القائد ضحكة قصيرة جافة، أشبه بوقع الحجارة على الصخر، ثم انحنى قليلاً إلى الأمام، وألقت ظلال السراج المرتعش بظلالٍ مشوهة على وجهه، مما منح ملامحه هيئة شيطانية. رمى القائد خنجراً صغيراً على الطاولة، دارت نصله الفضي لدورة كاملة قبل أن يستقر ثابتاً. قال بنبرة آمرة: إذاً، أثبت جدارتك. لم تكن الكلمات بحاجة إلى تفسير؛ ففي عالمهم، كانت الأفعال هي العملة الوحيدة المعترف بها. استدار ثورفين نحو السلاح، وبريق الفولاذ يعكس اضطراباً دفيناً في عينيه. كان يعلم أن هذه الخيمة قد تصبح مرقده الأخير، أو المكان الذي يبدأ فيه بكسر قيود الماضي. تنفس بعمق، ثم مد يده نحو المقبض، وشعر ببرودة المعدن تخترق جلده، مذكرة إياه بأن الخيارات قد انتهت، وأن اللحظة الحاسمة قد حانت دون رجعة.', '', 118, '2026-07-15 15:17:57.903', '2026-07-15 15:17:57.903');
INSERT INTO public.chapters VALUES ('f98a0636-3089-4e9b-8c8f-5f927717efe1', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 120: خلف أسوار الجليد', '— --------------------------------------- توقفت العربة بصرير معدني حاد حين اصطدمت نتوءات الطريق المتجمد بحوافر الخيول. نزل ثورفين، وسحبت قدماه ثقل الجليد تحت معطفه السميك. كانت ''هيلد'' تقف على مسافة غير بعيدة، يداها مطبقتان بإحكام على قوسها، وعيناها لا تغادران جسده، وكأنها تترقب رعشة منه أو حركة مريبة. لم يكن الهواء ساكناً، بل كان ينهش الوجوه ببرودة قاسية، لكن ثورفين تجاهل هذا كله، مشدداً قبضته على مقبض أدواته. قال ثورفين بصوت متحشرج قليلًا من أثر البرد: إننا لا نملك ترف التوقف، الطريق لا يزال طويلاً والنهار يوشك على الأفول. نظرت هيلد نحوه، تحركت عضلات فكها وهي تزن كلماته، ثم قالت بحدة: أتعتقد أن السرعة ستغفر لك ما اقترفته يداك؟ ثورفين لم يلتفت، بل تابع ترتيب المؤن على العربة، كانت حركاته ميكانيكية، دقيقة، خالية من أي توتر عاطفي ظاهر. رد ببرود مقتضب: أنا لا أبحث عن مغفرة منك، ولا من غيرك، أبحث فقط عن إتمام ما بدأته. صمت المكان، باستثناء صوت شهيق الخيول البخاري الذي يتصاعد في الهواء الطلق. كانت هيلد تراقبه بتركيز حاد، تبحث في ملامحه الجامدة عن ثغرة، عن أثر لندم أو ارتباك، لكن ثورفين ظل ثابتاً كصخرة جبلية. تحركت هيلد خطوة، وظهرت خلفها ظلال الأشجار العارية كأنها أشباح تترقب حواراً لم يكتمل. قالت بصوت خافت: إنك تحمل معك وزراً يثقل كاهل الأرض التي تمشي عليها، ألا تشعر بوطأته؟ توقف ثورفين عن الحركة تماماً، انحنى قليلاً ليشد حزام العربة، ثم استدار ببطء. لم تكن في عينيه شرارة غضب، بل فراغ واسع يشبه شتاء الشمال الطويل. أجاب بصوت منخفض ومباشر: الشعور لن يغير الواقع. الواقع هو أننا هنا، وهذا الطريق يؤدي إلى وجهتنا، وسأصل مهما كلف الثمن. عادت هيلد لترخي قبضتها عن القوس، لكن عينها بقيت يقظة. انطلقت العربة مجدداً، تاركة خلفها خطوطاً عميقة في الثلج، بينما بدأت الشمس تنحدر نحو الأفق في وهج باهت، تاركةً ثورفين وهيلد يمضيان في رحلتهما نحو المجهول، وصمت الطريق هو الحكم الوحيد بينهما.', '', 119, '2026-07-15 15:17:58.133', '2026-07-15 15:17:58.133');
INSERT INTO public.chapters VALUES ('c33869d2-9d9f-411d-811f-80fa27e050e2', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 121: حكاية السيف والمحراث', '— --------------------------------------- توقفت حركة المقطورة فجأة حين تعثر أحد الثيران في وحل الطريق، لتتردد أصداء صليل المعدات على متن العربة في أرجاء المكان. هيلجا، التي كانت تراقب الأفق بعينين اعتادتا تقلبات الفصول، التفتت نحو ثورفين. لم تكن هناك حاجة لتبادل كلمات طويلة، فقد أدرك الجميع أن المضي قدماً في هذا الطين سيؤدي إلى تمزق العجلات. نزل ثورفين من على العربة، غاصت قدماه في الوحل اللزج، ووجه أنظاره نحو ثورز الذي كان يتفحص بروداً وتأنٍ حالة الحِمل. كان ثورز يقف شامخاً، يمسح بيده الخشنة على عنق الثور المنهك، وكأن صمته المطبق يملأ الفراغ أكثر من أي توجيه صوتي. لم ينطق ثورز بكلمة، لكنه أشار بيد واحدة إلى الجهة اليمنى من الطريق، حيث الأرض أكثر تماسكاً. استجاب ثورفين على الفور، ممسكاً بزمام الدابة، وعضلات ذراعيه تبرز تحت قميصه القماشي الخشن وهو يضغط بكل ثقله لتصحيح المسار. في تلك اللحظة، لم يكن هناك أعداء أو معارك، بل كانت الحياة تختزل في جهد عضلي بسيط، وعلاقة صامتة بين أب وابنه يحاولان شق طريق في أرض قاسية. كانت نظرات ثورفين محملة بتساؤلات لم يجد لها جواباً بعد، بينما كان ثورز يكتفي بنظرة عابرة تملؤها السكينة، وكأنه يرى في هذا العمل الشاق جوهر الحرية التي طالما سعى إليها. توقفت الرياح للحظة، وساد صمت مطبق لم يقطعه سوى أنفاس الثيران الثقيلة وخرير ساقية بعيدة. التفت ثورفين إلى والده، متسائلاً بصوت أجش وقليل التردد عن جدوى الرحلة الطويلة التي لا تلوح لها نهاية، فجاء رد ثورز مقتضباً وقوياً، مخترقاً سكون الهواء: انظر تحت قدميك، الطريق الذي نبنيه الآن هو وجهتنا، ولا أثر لمن لا يملك وجهة. لم يضف ثورز شيئاً، عاد إلى عمله، تاركاً ثورفين في حيرة مفعمة بالتبجيل، يدرك أن كل خطوة يخطونها في هذا الوحل هي درس في الصبر الذي لم يتعلمه يوماً في ميادين القتال.', '', 120, '2026-07-15 15:17:58.313', '2026-07-15 15:17:58.313');
INSERT INTO public.chapters VALUES ('fa49e8f3-ef9d-4f46-b5a8-88746ae7b1b2', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 122: خلف أسوار الخديعة', '— --------------------------------------- انزلق النصل الحديدي عبر ثغرة في خوذة الحارس، لم يصرخ الرجل، بل اكتفى بلفظ زفير مكتوم بينما ارتخت قبضته عن مقبض رمحه. سحب ثورفين نصله ببرود، متفادياً بقع الدماء التي تناثرت على الرمل. خلفه، كان إينار يتحرك بوقار متوتر، عيناه تجولان في فناء الحصن الضيق حيث تتراكم المؤن وتتعالى أصوات الأقدام على الأرضية الخشبية. لم يكن هناك مجال للخطأ؛ فكل حركة محسوبة تقربهم من هدفهم، أو تعجل بقطع أعناقهم. التفت ثورفين نحو إينار، وهمس بصوت خفيض خاوٍ من الرعشة: «لا تبتعد عن ظلي». لم ينتظر رداً، بل اندفع نحو الممر المؤدي إلى بهو الملك. داخل الغرفة المظلمة، كان الهواء ثقيلاً برائحة التبغ واللحم المجفف. وقف ''جيفورد'' وسط الحشد، ملامحه متصلبة كتمثال صخري، بينما كانت أصوات المداولات في الخارج توحي بأن الحصار يشتد. تلاقت أعين ثورفين وجيفورد للحظة واحدة، صمتٌ قصيرٌ كان يحمل في طياته وزناً أكبر من صراخ المعركة في الخارج. لم يتحدث أي منهما، فالمكان لا يحتمل الكلمات المنمقة. حركة سريعة من رأس جيفورد أشارت إلى المخرج الخلفي. انقض ثورفين بحركته المعتادة، كفهد يترصد فريسة، متجاوزاً الحراس الذين غرقوا في نقاشاتهم السخيفة حول غنائم الحرب. كانت خطة الهروب تتشكل في ذهنه كخارطة معقدة؛ الخروج من البوابة الشمالية، عبور الجدول، والوصول إلى الغابة قبل أن يكتشفوا غياب الحارس عند مدخل البرج. دفع ثورفين الباب الخشبي الثقيل، لينفذ إلى فضاء خارجي واسع، حيث كانت تلوح تباشير الفجر في الأفق البعيد، نذيراً بيوم جديد من النزاع الذي لا ينتهي.', '', 121, '2026-07-15 15:17:58.566', '2026-07-15 15:17:58.566');
INSERT INTO public.chapters VALUES ('e8bef6bd-44a6-4136-8625-d13283a5ff21', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 123: خلف أسوار التوقعات', '— --------------------------------------- توقف إينار فجأة عن العمل، ممسكاً بيده مقبض المنجل الذي غاص في التربة الصلبة، بينما كان ثورفين يراقب الأفق بعينين غائرتين. لم تكن المسافة تفصلهم عن التوقعات فحسب، بل عن حقيقة ما سيؤول إليه أمر المزرعة في ظل أطماع الآخرين. استدار إينار، مسحت كفه العرق عن جبينه، وقال بصوت خشن: ثورفين، لا يمكننا الاستمرار في تجاهلهم، الأرض التي حرثناها بدمائنا ليست ملكاً لرجال لا يعرفون معنى التعب. لم يرد ثورفين فوراً، بل اكتفى بتركيز بصره على أطراف الغابة حيث تلاشت ظلال الرجال. كانت يداه، المتشققتان من العمل الشاق، ترتجفان ببطء، ليس من الخوف، بل من ثقل القرار الذي يلوح في الأفق. إنهم يريدون كل شيء، أضاف إينار وهو يبصق على الأرض، لم يعد الأمر مجرد حصاد، إنه بقاء. تنفس ثورفين بعمق، وشعر بضغط عضلات كتفيه يتراكم، ثم نطق بكلمات مقتضبة: لن نغادر، هذه الأرض أصبحت جزءاً من أجسادنا. كان صوته خالياً من التردد، مليئاً بصلابة لا تلين. في تلك اللحظة، ظهر هيلد من بين الأشجار، سكونها المريب جعل إينار يترقب، بينما اكتفى ثورفين بإيماءة بسيطة. كان الصمت الذي ساد المكان أبلغ من أي حوار، صمت الرجال الذين عرفوا الحرب والآن يواجهون تحدياً مختلفاً؛ تحدي الحفاظ على سلامهم وسط عالم لا يفتأ يجرهم نحو النزاع. انحنى ثورفين مجدداً، غارزاً المنجل في التربة، معلناً بموقفه أن العودة إلى العنف ليست خياراً، بل اضطراراً سيتعاملون معه حين يحين أوانه، لا قبل ذلك. اتسعت بؤبؤة عين إينار وهو يرى ثبات صاحبه، مدركاً أن عهد الهروب قد ولى، وأن المزرعة، بأشجارها وصخورها، أصبحت خط الدفاع الأخير عن حياة اختاراها بإرادتهما الحرة.', '', 122, '2026-07-15 15:17:58.759', '2026-07-15 15:17:58.759');
INSERT INTO public.chapters VALUES ('79f69530-119e-4f21-8b12-6a5528480cea', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 124: خلف أسوار العزلة', '— --------------------------------------- توقف إينار عن الحفر فجأة، وترك مقبض المسحاة يرتطم بالأرض الجافة محدثاً رنيناً مكتوماً في جوف الصمت المطبق. نظر نحو الأفق حيث تذوب الشمس في لون النحاس الباهت، ثم التفت إلى ثورفين الذي كان يعاين بذور القمح بعينين غائرتين. لم تكن هناك طيور في الأرجاء، ولا أصوات ركض أو صخب؛ فقط دبيب الحياة البطيء في حقولهم التي استصلحوها بعرق الجبين. قال إينار وهو يمسح وجهه بكفه الخشنة المتسخة بالطين: هل تعتقد أننا فعلنا الصواب؟ ظلت يدا ثورفين ثابتتين، لم يرفع نظره، بل أجاب بصوت خافت يشبه احتكاك الحصى: الصواب ليس خياراً نتبادله، إنه الثمن الذي ندفعه مقابل كل صباح لا نضطر فيه لرؤية الدماء. لم يلحظ إينار التغير في نبرة ثورفين، بل استمر في تحديق النظر نحو الطريق الترابي الذي يقود خارج المزرعة. كان الضيف الغريب يقف هناك منذ ساعات، جسده نحيل يلفه رداء رمادي باهت، وعيناه تراقبانهما كأنما ترصدان حركة نملة في قاع بئر. اقترب ثورفين منه بخطوات وئيدة، لم تكن مشيته تحمل تهديد المحارب القديم، بل ثقل التعب الذي يسكن عظام رجل لم يذق طعم الراحة الحقيقية. توقف على مسافة مترين، فبادر الغريب بالحديث بنبرة تهكمية لا تخلو من مرارة: يبدو أن الحقول لا تزال تنبت أحلاماً هشة يا ثورفين. تجمد ثورفين في مكانه، انقبضت عضلات كتفيه لا إرادياً، لكنه لم يلتفت للخلف، بل قال بنبرة مقتضبة: أنت لست مرحباً بك هنا، ولا بحديثك. ضحك الغريب، وهي ضحكة جافة لم تصل إلى عينيه، ثم خطى خطوة إلى الأمام: العالم خارج هذا السياج الخشبي لا يزال يلتهم نفسه، وأنت لا تزال تظن أن زراعة القمح ستطعم ضميراً مات منذ أمد. أدار ثورفين رأسه ببطء، كانت ملامحه حادة كشفرة سيف قديم، وقال دون أن يطرف له جفن: ارحل من هنا، لا مكان للسيوف في أرضي، ولا للرجال الذين يقتاتون على إحياء الموتى. التفت الغريب منصرفاً، تاركاً وراءه أثراً غائراً في التراب، بينما عاد إينار إلى عمله بخطوات مضطربة، مفضلاً الصمت الذي يعيد إليه طمأنينة الحقول على كلمات ثورفين التي لا تزال تتردد في أذنيه كصدى لجرس جنائزي بعيد.', '', 123, '2026-07-15 15:17:58.938', '2026-07-15 15:17:58.938');
INSERT INTO public.chapters VALUES ('add3d6dd-61e5-4e4f-8cee-c39b62b150e4', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 152: عواقب الخطيئة في أروقة فينيسيا', '— --------------------------------------- انزلق ثورفين داخل ردهات قصر الملك بكتل ببطء، محاولاً التماهي مع الظلال التي كانت تلتف حول الأعمدة الحجرية كأفعى متأهبة. كان العرق يتصبب على جبينه، ليس خوفاً، بل من ثقل اللحظة التي تسبق المواجهة. فجأة، توقف عند ركنٍ مظلم، حيث كان ''إينار'' يقف متسمراً، وعيناه تلاحقان حركة الحراس في الساحة الخارجية. همس إينار بصوت منخفض ومتهدج: ثورفين، إنهم يحيطون بكل المداخل، لا سبيل للانسحاب الآن. تجاهله ثورفين، فتركيزه كان منصبًا على الغرفة الكبيرة التي يجلس فيها الملك. دفع الباب الخشبي الثقيل بصمت مريب، ليفاجأ بوجود ''غودريد'' و''هيلد'' في الداخل. كانت عيناهما توحيان بالارتباك، لكن ثورفين لم يكترث؛ فقد رأى ما كان يخشاه: الملك ''سيغورد'' يقف وسط الغرفة، محاطاً بحرسه الخاص، وجوههم جامدة كتماثيل من رخام. نظر سيغورد إلى ثورفين، بريق من السخرية تلمع في عينيه الضيقتين، ثم نطق ببرود: لم أكن أتوقع رؤية ''مقاتل'' مثلك هنا، يا ثورفين. هل جئت لتطلب الغفران أم جئت لتموت؟ لم يجبه ثورفين، بل قبض على مقبض خنجره الذي يتدلى بجانبه، واتسعت حدقتا عينيه وهو يلمح سيفاً مسلولاً بيدي أحد الحراس. في تلك اللحظة، لم تعد الغرفة مكاناً للنقاش، بل ساحة مشحونة بكل ذنوب الماضي التي طاردت ثورفين إلى أقاصي الأرض. لم يقل ثورفين شيئاً، لكن حركات جسده كانت تعبر عن تأهب حيوان مفترس محاصر، عضلات كتفيه انقبضت، وبدأ جسده يميل قليلاً نحو الأمام، مستعداً للانفجار في أي لحظة. كان الصمت الذي يسود القاعة ثقيلاً، مشبعاً برائحة الخوف الذي بدأ يتسرب إلى عروق الجميع، بينما ظل ثورفين ينظر إلى الملك مباشرة، وعقله يزن كل حركة، وكل نبضة، وكل احتمال للموت أو النجاة.', '', 151, '2026-07-15 15:18:04.653', '2026-07-15 15:18:04.653');
INSERT INTO public.chapters VALUES ('e3329260-c1e0-4089-9d1f-35c5a855d464', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 125: خلف أسوار الرماد', '— --------------------------------------- ارتطم جسد ثورفين بالأرض الموحلة، كانت أنفاسه متلاحقة، وتصدر عن صدره خشخشة مكتومة كأنما يحاول انتزاع الهواء من رئة منهكة. لم يكن هناك وقت للتقاط الأنفاس، ففي الأفق، كانت نيران الموقد في القرية تقترب، توحي باقتراب النهاية التي سعى لتجنبها. نهض ثورفين، مسحت يده الملطخة بالطين جبينه، وبدت عيناه ثابتتين رغم التعب. وقف إينار بجانبه، كانت يداه ترتجفان بوضوح، قبض عليهما بقوة ليخفي ضعفه. حدق إينار في ثورفين، كأنه يبحث في ملامحه عن يقين مفقود. لم ينبس ثورفين ببنت شفة، بل اكتفى بإيماءة خفيفة برأسه نحو الطريق الممتد بين الأشجار. كان الصمت الذي يغلف المكان ثقيلاً، لا يقطعه سوى وطء أقدامهم على الأرض الرطبة. في تلك اللحظة، ظهرت ملامح ''غاردان'' في الأفق، كانت حركاته بطيئة ومثقلة بالدماء، ورغم جراحه النازفة، ظل وجهه محافظاً على جمود صخري لا يلين. توقف غاردان، اتكأ بظهره على جذع شجرة ضخم، وسعل دماً لطخ ذقنه. نظر إلى ثورفين، ارتخت عضلات وجهه قليلاً، وقال بصوت مبحوح خالٍ من أي ندم: لقد انتهى كل شيء، يا فتى. لا تتبع طريقي، فالموت هنا ليس خلاصاً، بل هو عبء أبدي. لم يعقب ثورفين، بل اقترب منه، مراقباً بؤبؤي عيني غاردان اللتين بدأتا تفقدان بريقهما تحت ضوء القمر الخافت. كان إينار يراقب المشهد من بعيد، متسائلاً إن كان ثورفين سيجد في هذه اللحظة ما يبرر الرحلة التي خاضاها. انحنى ثورفين ليضع يده على كتف غاردان، ولم يقل شيئاً، كان في تلاحم جسدهما تعبير عن فهم عميق لمعاناة لا توصف. ساد سكون عميق، سكون لا يشوبه تصنع، حيث أدرك الجميع أن ما يربطهم ليس القتال، بل الرغبة في التحرر من أغلال العنف التي طالما قيدت حياتهم. التفت ثورفين نحو الغابة، كانت خطواته موزونة، ثابتة، ومحملة بقرار لم يسبق له مثيل.', '', 124, '2026-07-15 15:17:59.151', '2026-07-15 15:17:59.151');
INSERT INTO public.chapters VALUES ('6fc015c3-49c9-4a1a-ac77-adbfcdcd2743', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 126: عقدة في حبال القدر', '— --------------------------------------- توقف ثورفين عن الجدال فجأة، حين اصطدمت نظرته بملامح ''جادر''، الذي كان يقف هناك بهدوءٍ مريب، ممسكاً بسيفه كأنه يزن ثقلاً زائداً. في تلك اللحظة، لم تعد كلمات ''إينار'' حول السلام تتردد في ذهن ثورفين؛ فقد حل محلها صوت حاد لحديدٍ يخرج من غمده. بادر جادر بالكلام، نبرته تحمل ثقة الرجل الذي اعتاد إنهاء النزاعات بالدم لا بالحجة: هل تظن حقاً أن الأرض التي تحرثونها ستمنحكم النجاة؟ هؤلاء الرجال الذين يحيطون بكم ليسوا مزارعين، بل ذئابٌ جائعة، وأنت يا ثورفين، رائحة المعارك لا تزال عالقة في مسام جلدك. لم يجب ثورفين، بل انقبضت عضلات فكه وتصلبت قامته، محدقاً في الفراغ بينهما. تدخل إينار، ملوحاً بيديه اللتين شقتهما الحراثة، وصوته يرتجف من الغيظ: نحن هنا للزراعة، لا للموت. لكن جادر تجاهله تماماً، واضعاً يده على مقبض سيفه، ومشيراً إلى أن التهديد قد بدأ للتو. التفت ثورفين نحو إينار، كانت عيناه هادئتين بشكل مخيف، صوت خافت خرج من بين شفتيه: ابتعد يا إينار. كانت تلك الجملة بمثابة إعلان عن تحول داخلي؛ فقد أدرك ثورفين أن الهروب من الماضي ليس بترك السيف، بل بمواجهة الذين لا يعرفون لغةً غيره. وبينما كان جادر يتقدم بخطوات واثقة، ضيقة، بدأت أصوات صراخ الرجال في المزرعة تقترب. لم تكن هناك حاجة لخطبٍ طويلة؛ فكل حركة لجسد ثورفين كانت توحي بأنه يزن الاحتمالات، فإما أن يسقط هنا، أو يكسر حلقة العنف التي تلاحقه كظله. رفع جادر سلاحه، ومع شعاع الضوء الذي انعكس على النصل المعدني، انقضَّ كلاهما في حركة خاطفة، تاركين خلفهما عبق القش الممزوج بتراب الحقل، وفي أذني ثورفين، لم يعد يسمع سوى دقات قلبه المنتظمة التي كانت تعدُ بتصفية الحساب، لا رغبة في الانتقام، بل رغبةً في الصمت الأبدي.', '', 125, '2026-07-15 15:17:59.36', '2026-07-15 15:17:59.36');
INSERT INTO public.chapters VALUES ('39a49397-957f-4b27-b328-678ed9d0f43f', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 127: حين تصمت السيوف في بلاد الشمال', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في وحل المستنقع البارد، وأنفاسه تتصاعد غيوماً متقطعة في الهواء الساكن الذي يسبق العاصفة. لم تكن هناك أصوات سوى طنين حشرات خافت يحيط بالمكان. نظر إينار إلى رفيقه، كانت ملامح ثورفين قد تجمدت في تعبير غريب، مزيج من الترقب والضياع. قال إينار بصوت خفيض لم يكد يسمعه إلا ثورفين: هل ما زلت تفكر في الطريق إلى فينلاند؟ التفت إليه ثورفين ببطء، كانت عيناه ذابلتين، وقال بنبرة جافة لا تحمل تأثراً: الأمر ليس بتلك السهولة، إينار. نحن نخطط لأرض لم نضع أقدامنا عليها، والناس الذين سنواجههم هناك… لا نعرف حقاً كيف سيستقبلوننا. كان رد إينار سريعاً ومفعماً بالأمل: ولكننا لا نملك خياراً آخر، نحن بحاجة إلى مكان لا يلاحقنا فيه شبح الماضي. صمت ثورفين طويلاً، ثم مسح بيده وجهه الملطخ بالتراب، وكأنما يحاول مسح آثار سنوات من الدماء التي لم تفارق ذاكرته. في تلك اللحظة، تحركت أغصان الأشجار بفعل ريح مفاجئة، وتناهى إلى مسامعهما وقع أقدام ثقيلة قادمة من خلف التلال. لم يكن هذا صوت حيوان بري. شد ثورفين قبضته على خنجره، ليس لهجوم، بل كعادة قديمة ترفض جسده التخلي عنها. وقف الاثنان متأهبين، عضلات أكتافهما مشدودة، وعيونهم ترصد الأفق الضبابي. لم يكن لديهم جيش، ولا دروع تلمع تحت الشمس، فقط إرادة خام وقسوة الحياة التي صقلت أجسادهم. نظر ثورفين إلى الأفق وقال بحدة: إذا كان هذا هو القدر الذي يلاحقنا، فليأتِ إذن. لم تكن في نبرته شجاعة زائفة، بل إقرار بواقع لا مفر منه. كانت الشمس خلف الغيوم تبدأ في الاختفاء، تاركة ظلالاً طويلة تمتد فوق الأرض، وكأن الطبيعة ذاتها تتهيأ لفصل جديد من المعاناة أو الخلاص، بينما ظل صمت ثورفين الثقيل يغلف المكان، مخترقاً سكون اللحظة.', '', 126, '2026-07-15 15:17:59.561', '2026-07-15 15:17:59.561');
INSERT INTO public.chapters VALUES ('40413397-42c6-4af1-a5fd-047f1b1f6cfb', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 128: عزيمة العبيد', '— --------------------------------------- تصلبت ملامح ثورفين وهو يراقب هيلغا، العبدة التي انهار جسدها تحت وطأة الإرهاق. لم يكن هناك متسع للشفقة في حقول المزرعة الموحلة. تقدم ’أولمار‘، ابن مالك المزرعة، يمسح بيده على وجهه بضجر، وعيناه لا تكادان تغادران الأرض المتشققة. سأل ثورفين بنبرة مقتضبة وهو يشد قبضته على مقبض المنجل: لماذا لم تنهض بعد؟ لم يجب ’أولمار‘، بل اكتفى بنظرة غائمة نحو الأفق، حيث كان العمال الآخرون يتحركون كظلال باهتة تحت شمس الظهيرة القاسية. في تلك اللحظة، اقترب ’إينار‘، ملامح وجهه توحي بتمسكٍ يائس بالحياة، ووضع يده على كتف ثورفين. قال بصوت منخفض: لا فائدة من صراخك يا ثورفين، الجسد له حدود، وهذا العمل لا يرحم الضعفاء. التفت ثورفين نحوه، كانت عيناه قد فقدتا بريق التحدي القديم، وحل محله هدوء غريب وموحش. لم يقل شيئاً، بل عاد إلى العمل، يقطع السنابل بحركات آلية دقيقة، وكأن كل حركة هي محاولة لنسيان ماضيه الملطخ بالدماء. في زاوية الحقل، كان ’كيتيل‘، صاحب المزرعة، يراقب المشهد بصمت. لم تكن عيناه تعبران عن قسوة، بل عن ثقل المسؤولية التي تثقل كاهل رجل يحاول الحفاظ على ممتلكاته في زمن لا يأمن فيه أحد على قوت يومه. تداخلت أصوات الأنفاس اللاهثة مع حفيف القمح، وصار الصمت سيد المكان، صمت لا يقطعه إلا وقع الفؤوس ونداءات العمال المبحوحة. نظر ثورفين إلى كفيه؛ كانت الجروح القديمة قد تحولت إلى ندوب غليظة، رمزاً لحياته الجديدة التي تخلو من السيوف، لكنها لا تخلو من عذاب العيش. ألقى إينار نظرة سريعة على ثورفين، ثم قال: هل تعتقد أننا سنحصل على حريتنا يوماً ما؟ توقف ثورفين عن العمل للحظة، استقام في وقفته، ونظر إلى السماء البعيدة دون أن يجيب. لم تكن الإجابة ضرورية؛ ففي هذا المكان، الحرية ليست سوى كلمة تُهمس في جوف الليل، بينما النهار يلتهم ما تبقى من أرواحهم.', '', 127, '2026-07-15 15:17:59.786', '2026-07-15 15:17:59.786');
INSERT INTO public.chapters VALUES ('59f8b370-910d-45e4-88e5-ae6d4d04412a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 129: خلف أسوار الجليد والوعود', '— --------------------------------------- توقف ثورفين عن الجري حين تلاشت أصوات المطاردين في متاهة الغابة الكثيفة. كان صدره يعلو ويهبط في إيقاع مضطرب، بينما تلطخت يداه بطين الأرض الرطب. إلى جانبه، ظل إينار يراقب الطريق خلفهما بعينين زائغتين، يمسح العرق عن جبينه بحركة عصبية. لم يكن هناك وقت للراحة، فالمهمة التي أخذوها على عاتقهم في يونغسفيلا كانت تمضي على حافة سكين. همس إينار بصوت متقطع: هل تعتقد أنهم كشفوا مكاننا؟ لم يجب ثورفين، بل اكتفى بضغط قبضته على مقبض سيفه الخشبي، مشاعره تتحرك تحت جلده كتيار خفي. التفت ثورفين نحو الأفق، حيث بدأت ملامح التوتر تتشكل في محياه المعتاد على الصرامة. لم تكن هذه الرحلة من أجل الانتقام هذه المرة، بل كانت سعياً لغدٍ لا يعرف طعم الحديد في الحلق. اقترب منه إينار، محاولاً استعادة توازنه: نحتاج إلى خطة، المرتزقة لن يتوقفوا عن التمشيط. حدق ثورفين في جذع شجرة ضخم، وقال بنبرة مقتضبة تخلو من أي تردد: سنعبر النهر ليلاً. المياه باردة، لكنها الطريق الوحيد لتضليل كلابهم. كان قراره حاسماً، ينم عن خبرة تراكمت في ساحات الوغى القديمة. تحركا بسرعة نحو ضفة النهر، حيث كانت المياه الجارية تصدر خريراً مخيفاً في سكون الليل. لم يلتفت ثورفين للخلف، فقد كان الماضي بالنسبة له كتاباً أغلق صفحاته، بينما ظل إينار، برغم خوفه، يتبع خُطى رفيقه بإيمانٍ يتصاعد مع كل خطوة. كانت الغابة تعج بحفيف الأشجار، لكن تركيزهما انصب فقط على النقطة التي سيعبران منها. في تلك اللحظة، ظهرت صورة خاطفة في ذهن ثورفين؛ رؤية واضحة لسهول فينلاند البعيدة التي طالما حلم بها، بعيداً عن أشباح الحرب. استجمع قوته، وأشار لإينار بالصمت. كانت المواجهة القادمة لا تتطلب سيفاً، بل عزيمة صلبة كالصخر، وصبراً يضاهي صمود الشتاء في الشمال.', '', 128, '2026-07-15 15:17:59.969', '2026-07-15 15:17:59.969');
INSERT INTO public.chapters VALUES ('e9c8eb8a-4439-43f5-b4fe-a29517e47f7e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 130: بذرة في أرض الوعود', '— --------------------------------------- انحنى ثورفين ليغرس بذور القمح في التربة الموحلة، كانت أصابعه المتشققة تتغلغل في الأرض ببطء، وكأنها تبحث عن نبض حياة لم تألفه يداه من قبل. بجانبه، وقف إينار يمسح العرق عن جبينه بقطعة قماش رثة، تراقب عيناه المساحات الشاسعة التي أزيلت عنها الأحراش. قال إينار بصوت خشن: هذه الأرض أخذت منا شهوراً، لكنها تبدو الآن وكأنها تستعد لشيء ما. لم يجب ثورفين فوراً، بل اكتفى بضغط التربة فوق البذور، كانت عضلات ظهره مشدودة بوضوح. التفت ثورفين نحوه، وبؤبؤا عينيه تتحركان بتركيز حاد: نحن لا نستعيد الأرض فقط يا إينار، نحن نصنع شيئاً لم يسبق لنا أن امتلكناه. الصمت حل بينهما، لم يكن صمتاً فارغاً، بل صمتاً ثقيلاً بالترقب. في تلك اللحظة، اقترب منهما ''باتر'' مسرعاً، كانت أنفاسه متلاحقة ووجهه شاحب، توقف أمام ثورفين وهو يلهث، مشيراً بيده نحو الأفق حيث تلوح بيوت المزرعة. لم يقل باتر كلمة، لكن نظراته المذعورة كانت كافية؛ لقد وصل ''كانيوت''. شعر ثورفين بتقلص عضلي مفاجئ في فكيه، توقف عن العمل، ووقف ببطء، فارداً قامته التي لم تعد تنحني للضعف. قال ثورفين بصوت منخفض ومباشر: إذا جاءوا، فسنبقى. لا قتال هذه المرة. نظر إينار إليه، ثم إلى الأفق، قبض على مقبض معوله بقوة حتى ابيضت مفاصل أصابعه. لم يكن هناك هروب، ولم يكن هناك مكان آخر للذهاب إليه. في تلك اللحظة، ظهرت خيول الملك تتقدم نحوهم، حوافرها تقرع الأرض بقوة تعلن عن وصول سلطة لا ترحم. وقف ثورفين شامخاً، يداه اللتان غرستا البذور للتو، هما ذاتهما اللتان ستواجهان أعتى جيوش الشمال، ليس بالسيف، بل بإرادة رجل قرر أن حياته لم تعد ملكاً للحروب.', '', 129, '2026-07-15 15:18:00.15', '2026-07-15 15:18:00.15');
INSERT INTO public.chapters VALUES ('ab9ecbf8-cbd2-4667-abb4-d7d8cccbc913', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 131: خلف أسوار الرماد', '— --------------------------------------- توقف ثورفين عن الحركة. كانت الأرض تحت قدميه في ميكلاغارد صلبة، مغبرة، وتفوح منها رائحة الزيت المحترق والأسواق المزدحمة. لم تكن صرخات الباعة أو صليل المعادن في الورش البعيدة هي ما استرعى انتباهه، بل ذلك الوجود المباغت لـ إينار الذي كان يحدق في الأفق بنظرات محتقنة. تحرك إينار خطوة للأمام، قبضتا يده ترتجفان بوضوح، وعروق عنقه بارزة كأنها ستنفجر. همس إينار بصوت مبحوح، خرج منهكاً من صدره: هل هذا حقاً هو المكان؟ لم ينتظر ثورفين إجابة، بل خطا بجانبه، مقترباً من حافة الساحة حيث كانت صفوف العبيد تمتد كقطيع خاوٍ من الأمل. كانت عيناه تمسحان الوجوه المنهكة، باحثة عن ذلك الطيف الذي طالما أرق منامه. فجأة، توقف ثورفين. انقبضت عضلات ظهره وتصلبت قدماه في مكانهما. على مسافة غير بعيدة، جلس رجل، جسده النحيل يغوص في أسمال بالية، وشعره المتسخ يغطي ملامحه التي نهشتها السنون. كان يتناول قطعة خبز يابسة بيدين ترتعشان. اتجه ثورفين نحوه، خطواته بطيئة، واثقة، رغم أن قلبه كان يقرع طبولاً عنيفة في صدره. اقترب أكثر حتى ألقى بظله فوق الرجل. رفع الأخير رأسه ببطء، بؤبؤا عينيه اتسعا في لحظة إدراك صاعقة، وسقطت قطعة الخبز من يده لتصطدم بالأرضية الحجرية بصوت أجوف. لم ينطق أحدهما بكلمة. كان الصمت بينهما أثقل من جبال الجليد التي عبروها. ارتجفت شفاه الرجل، وانفتح فمه ليصدر صوتاً غير مفهوم، مزيجاً من البكاء والدهشة، بينما ظل ثورفين واقفاً، ملامحه جامدة كالتمثال، لكن نظراته كانت تلتهم كل تفصيلة في وجه هذا الغريب. التفت إينار خلفه، مدركاً أن الرحلة الطويلة التي قطعاها عبر البحار والقفار قد بلغت منتهاها أخيراً في هذا الركن المنسي من العالم.', '', 130, '2026-07-15 15:18:00.316', '2026-07-15 15:18:00.316');
INSERT INTO public.chapters VALUES ('c00795a5-efa3-4aa1-a6a3-fa5e6b1f150b', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 132: متاهة العبيد وطموح الحرية', '— --------------------------------------- توقف إينار عن الحفر ورفع كفه الملطخة بالطين عن جبينه، بينما كان ثورفين يراقب الأفق بصمتٍ مطبق. كانت أرض المزرعة قاسية، ترفض الانصياع لمعاولهم، لكن ثورفين كان يرى فيها شيئاً آخر غير التراب؛ يرى فيها طريقاً للنجاة بعيداً عن صراعات الدماء. اقتحم هدوءهما صوت خطوات ثقيلة تقترب من خلفهما. كان ''فوكس'' يتجه نحوهما، ووجهه متجهم كعادته، يحمل في نظراته مزيجاً من الاحتقار والاستعلاء الذي يلفظه الرجال الذين اعتادوا إذلال الآخرين. قال فوكس بنبرة فظة ومليئة بالاستفزاز: «ألا زلتما تظنان أنفسكما بشراً؟ يا لغرابة الأمر، العبيد يطمحون للحرية كأنهم يملكون ثمنها». لم يلتفت ثورفين، بل استمر في تثبيت أداته في الأرض، مكتفياً بكلمات مقتضبة: «نحن نعمل لنشتري حياتنا، هذا كل ما في الأمر». ارتسمت على وجه فوكس ابتسامة ساخرة، وبصق أرضاً بجوار قدمي ثورفين ثم أضاف بنبرة حادة: «أنت لا تدرك شيئاً، يا ثورفين. الحرية ليست صفقة تجارية، هي وهم يقتات عليه الضعفاء مثلك». في تلك اللحظة، لم يغضب ثورفين، بل انقبضت عضلات فكه وتصلب جسده، ليس بدافع الكره، بل بتركيز جراح يحاول السيطرة على ارتجاف يده. كان إينار يراقب الحوار، ويداه تقبضان بقوة على مقبض معوله، محاولاً كبت رغبته في التدخل. في الأثناء، كان ''أولمار'' يراقب من بعيد، متردداً في خيالاته الصبيانية حول القوة والفروسية التي لا تناسب واقعه. كانت أجواء المزرعة تغلي تحت وطأة العبودية، حيث يتقاطع طموح الرجال مع قيود الواقع. قال ثورفين بصوت هادئ، خاوٍ من أي تهديد، لكنه يحمل ثقلاً يثير الريبة في نفس فوكس: «العدو لا يكمن في القيود التي يفرضها الآخرون، بل في الرغبة التي تجعلنا نحتاج للآخرين كي نكون ما نريد». تجمدت ملامح فوكس للحظة، وكأنه لم يتوقع رداً سوى التوسل أو الغضب، ثم ضحك ضحكة قصيرة جافة وابتعد. في تلك اللحظة، كان ثورفين يدرك أن طريقه نحو فينلاند يتطلب أكثر من مجرد العمل الشاق؛ يتطلب صموداً أمام استفزازات لا تنتهي، وقدرة على رؤية ما وراء الأفق، حتى حينما تكون الأقدام غارقة في وحل العبودية.', '', 131, '2026-07-15 15:18:00.609', '2026-07-15 15:18:00.609');
INSERT INTO public.chapters VALUES ('7a27bdfa-277a-49f4-b2ff-d74adaed6dfc', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 133: ثقل الأرض وأصداء الندم', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في التربة الرطبة، بينما ظلت عيناه مسمرتين على تلك المساحات الشاسعة التي تمتد أمامه، أرضٌ بكر ترفض أن تخضع لمحراثه. لم تكن مجرد تربة؛ كانت كتلة من الصخر والصلابة التي تختبر عزم الرجال. التفت إلى إينار، الذي كان يمسح العرق عن جبينه بساعده الملطخ بالطين، أنفاسهما تتسارع في إيقاع واحد. قال إينار بصوت متهدج من الإعياء: ما زلنا بعيدين، يا ثورفين. الأرض هنا تتحدى أيدينا، كأنها تعرف أننا غرباء عنها. لم يجب ثورفين فوراً، بل نظر إلى فأس العمل الملقاة بجانبه، تذكر لبرهة ثقل السيف الذي كان يملأ يده في الماضي، ثم أزاح الفكرة بضغط فكه الأسفل. لا يهم، رد ثورفين بنبرة مقتضبة، صلبة كصخور الحقل، علينا اقتلاع هذه الجذور اليوم. بدأ في حفر التربة بعنفوان، لم يكن مدفوعاً بحاجة إلى الحصاد، بل برغبة ملحة في محو أي طاقة فائضة في جسده قد توقظ الوحش القديم الذي تعهد بدفنه. في تلك الأثناء، كان الحوار بينهما يتردد في الفراغ، حوارٌ لا يحمل حكمة الفلاسفة، بل واقعية الفلاحين الذين يواجهون الجوع والعمل الشاق. تساءل إينار عن سبب إصرار ثورفين على هذه الأرض تحديداً، فأتاه الرد صامتاً في عمقه، نظرة ثاقبة من ثورفين لم تحمل تبريراً، بل ثباتاً مرعباً. تحركت العضلات تحت الجلد، وتصاعدت أنفاسهما في الهواء البارد، بينما غابت الشمس خلف التلال، تاركةً إياهما في مواجهة مع صمت الطبيعة القاسي. لم تكن هناك كلمات كبيرة عن السلام أو الانتقام، فقط صوت ضربات المعول على الأرض، وصوت الأنفاس اللاهثة، وتلك اليد التي تمتد لتمسح الطين عن وجه الآخر، في إيماءة بسيطة تعني أكثر من ألف وعد. في تلك اللحظة، لم يكن ثورفين مقاتلاً يبحث عن مجد، ولا صبياً يهرب من ماضيه، كان مجرد رجل يواجه الأرض، ويحاول أن يجد في خشونة التربة مخرجاً لروحه التي أرهقتها الدماء.', '', 132, '2026-07-15 15:18:00.806', '2026-07-15 15:18:00.806');
INSERT INTO public.chapters VALUES ('24fa8e08-a902-4d37-8d2c-d59a7e7cfb60', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 134: أصداء الغرب المجهول', '— --------------------------------------- انحنت كفة الميزان في قاعة الاجتماع الثقيلة، حيث التقت نظرات ''سيفارد'' بخصمه بعمقٍ أفرغ الكلام من معناه. لم تكن المسألة مجرد صفقة تجارية أو تبادل بضائع، بل كان صراع إرادات يرتكز على خرائط مرسومة على جلد الغزال وأحلام لم توطأ بعد. همس سيفارد، وصوته يشق صمت الغرفة كشفرة باردة: لن تجد في فينلاند سوى الموت، فالأرض التي تبحث عنها ليست سوى وهم يغري الضعفاء. رفع ثورفين رأسه، لم تكن عيناه تعكسان غضباً، بل ثباتاً صلبًا كصخرة نحتها الشتاء. قال بنبرة مقتضبة، خالية من الزخرفة: الأمر لا يتعلق بالذهب أو المجد، بل بالمكان الذي يمكننا فيه البدء بلا دماء. ارتسمت على شفتي سيفارد ابتسامة ساخرة، متهكماً على سذاجة الطموح الذي يغلف كلمات ثورفين، بينما كان بقية الرجال في الغرفة يتبادلون نظرات التوجس، مدركين أن المسار نحو الغرب ليس مجرد رحلة بحرية، بل اختبار للبقاء. تحرك إينار ببطء، يضع يده على حافة الطاولة الخشبية الخشنة، وكأنما يحاول استمداد القوة من ملمسها المادي، متسائلاً بنبرة مشوبة بالحذر عما إذا كان هذا الحلم يستحق المخاطرة بسلامة القافلة. لم يجب ثورفين فوراً، بل نظر إلى النافذة حيث كانت السماء تتهيأ لاحتمال عاصفة، متأملاً في أن كل خطوة يخطونها نحو ذلك المجهول هي في الواقع هروب من ماضٍ لم يترك لهم فرصة للنجاة إلا عبر البحر. في تلك اللحظة، لم تعد الغرفة مكاناً للتفاوض، بل ساحة تتقاطع فيها الأقدار، والقرار الذي سيتخذونه سيحدد ما إذا كانوا سيسجلون أسماءهم في التاريخ كبناة، أو كضحايا لمغامرة عبثية في أقاصي الأرض.', '', 133, '2026-07-15 15:18:01.005', '2026-07-15 15:18:01.005');
INSERT INTO public.chapters VALUES ('21060d87-17d0-42bf-af88-227933c0a031', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 135: خلف أسوار التوقعات', '— --------------------------------------- توقف ثورفين عن الحركة فجأةً، مسمراً عينيه على وجه إينار. كانت تلك اللحظة ثقيلة، مشحونة بتوتر غير مسبوق في رحلتهم نحو الشمال. سأل إينار بنبرة متلعثمة لم تخفِ ارتباك ملامحه: «هل تعني حقاً ما تقوله؟ أتريد منا أن نرحل إلى فينلاند؟» لم يجب ثورفين على الفور؛ بل انحنى برأسه قليلاً، متأملاً في الأرضية الخشبية المتهالكة التي تفصل بينهما. كان الصمت الذي خيم على المكان لا يقطعه سوى طنين بعيد لحشرات الليل واحتكاك السفينة بأمواج النهر الوديعة. رفع ثورفين بصره، وبدا وجهه وقد خطته الندوب وتجارب القسوة، لكن عينيه حملتا ثباتاً غريباً. قال بنبرة مقتضبة، خالية من أي تهويل: «نعم. سئمت الدم، وسئمت السيوف التي لا تبني شيئاً. فينلاند أرض لا يعرف فيها الناس معنى العبودية، أرض يمكن فيها للمرء أن يعيش دون أن يضطر لسلخ جلد أخيه». قبض إينار على حافة المقعد الخشبي حتى ابيضت مفاصل أصابعه، وسأله بنبرة مشوبة بالحذر: «وماذا عن الآخرين؟ وماذا عن ثيغرد وبقية الرجال الذين تبعونا؟ هل تعتقد أنهم سيتخلون عن طموحاتهم في الثراء والقوة من أجل أرض مجهولة؟» تنهد ثورفين، وظهرت انقباضة خفيفة في زاوية فمه، ثم أضاف بصوت خفيض: «لن يتبعني الجميع، أعلم ذلك. لكنني لن أضحي بالمزيد من الدماء من أجل أرضٍ ليست لي. سأذهب، وسأبني هناك حياةً قائمة على السواعد، لا على غنائم النهب». في تلك اللحظة، دخل ليف إريكسون إلى الغرفة، حاملاً معه برودة الهواء الخارجي ووقع خطواته الرصينة. نظر إلى الاثنين، وقد قرأ في وجوههما شرارة القرار، فقال بوقار: «لقد سمعت كفايتي. المضي نحو الغرب ليس مجرد رحلة بحرية، يا ثورفين، بل هو قرار قد يغير مصيرك ومصير من سيتبعك إلى الأبد. هل أدركت حجم العداوات التي ستخلقها بقرارك هذا؟». نظر ثورفين إلى ليف، ولم يرمش له جفن، بل أجاب بصلابة: «الأعداء موجودون ما دمنا نختارهم. أنا لا أريد أعداءً بعد الآن. سأجعل من فينلاند وطناً لا يحتاج فيه المرء إلى سلاح ليثبت أنه حي». غادر ليف المكان تاركاً خلفه ثقلاً من التفكير، بينما ظل إينار يحدق في ثورفين، مدركاً أن الرجل الذي يقف أمامه لم يعد ذلك المقاتل اليافع الذي يرتجف غضباً، بل أصبح كياناً آخر، يسعى لتحقيق سلامٍ سيكلفه الكثير من المشقة، ولكنه سلام سيختاره بملء إرادته.', '', 134, '2026-07-15 15:18:01.184', '2026-07-15 15:18:01.184');
INSERT INTO public.chapters VALUES ('d07c5643-24f4-404c-9b5a-7b6fe14c871b', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 136: صدى الخطيئة تحت سوط التذكر', '— --------------------------------------- انقبضت أصابع ثورفين على حافة الطاولة الخشبية حتى تبيّضت مفاصله. لم يكن في الغرفة سوى حفيف الأنفاس المكتومة. أمام عينيه، لم تعد جدران الكوخ الخشبية موجودة، بل تلاشت في ضباب الذكرى لتبرز ساحات المعارك المنسية، ورائحة النحاس الممزوج بالدم التي علقت في مسامه سنوات طويلة. وقف إينار يراقب ملامحه التي تموج بين الذهول والانكسار. لم ينطق إينار، فثورفين لم يعد في هذا العالم، بل كان يغوص في هوة الوجوه التي أزهق أرواحهم، وجوهٌ بدأت تتشكل في زوايا الغرفة المظلمة. نظر ثورفين إلى كفيه؛ لم يرهما ككفين لرجل يحرث الأرض، بل كأداة قتل صامتة لا تزال تئن تحت وطأة الأرواح التي لم تجد سكينة. قال ثورفين بصوت أشبه بخرير الحصى: أنا لستُ من استيقظ يا إينار. أنا من يطارده الموتى حتى في يقظتي. تحرك إينار خطوة للأمام، وضع يده على كتف ثورفين، لكنه تراجع حين شعر بتصلب عضلي مفاجئ في جسد صديقه، كما لو كان يتوقع طعنة من المجهول. لا تفتش عنهم، قال إينار بنبرة خفيضة، فالتفت إليه ثورفين، وكانت بؤبؤ عيناه متسعتين بحدة، تلمعان ببريق اليقظة المؤلمة. سأله ثورفين بحدة: كيف تعيش وأنت تحمل جيشاً في ذاكرتك؟ لا يوجد أعداء، هكذا كان يقول والدي، لكن كل خطوة أخبرتني عكس ذلك. صمت المكان، ولم يقطعه إلا صوت الريح التي تضرب الجدران الخارجية، وهو صوت تحول في أذني ثورفين إلى صرخات المعارك التي خاضها في شبابه، تلك التي بدأت كمسرحيات بطولية وانتهت بحفر في الأرض يدفن فيها أسماء لا يعرفها. تنفس ثورفين بعمق، محاولاً استعادة توازنه المفقود، بينما كانت ذكريات الغزوات والحرائق تتراقص أمام عينيه كظلال لا تموت، مؤكدة له أن السيف الذي ألقاه لم يغادر روحه بعد.', '', 135, '2026-07-15 15:18:01.346', '2026-07-15 15:18:01.346');
INSERT INTO public.chapters VALUES ('07a27740-0ccd-4eaa-871e-351571593845', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 137: خلف أسوار التوقعات', '— --------------------------------------- توقف ثورفين عن مضغ قطعة اللحم القاسية وهو يراقب هيلد التي كانت تفرك يديها المتوترتين على حافة الطاولة الخشبية. لم تكن الغرفة هادئة، بل كانت مليئة بضجيج الميناء المكتوم، لكن ثقل الصمت بينهما كان أشد وطأة. سألها ثورفين بصوت خشن: هل ما زلت تفكرين في النصل؟ نظرت هيلد إلى الأعلى، تلاقت عيناهما، ولم تكن بحاجة للرد. كانت أصابعها المرتجفة تجيب نيابة عنها. التفت ثورفين نحو نافذة الكوخ الضيقة، كان الأفق يمتد بلا نهاية، مساحة شاسعة تنتظر من يملؤها، لا بالدماء هذه المرة، بل بشيء يجهل كنهه. تدخل إينار في الحوار، صوته يحمل بقايا غضب مكبوت: نحن لا نبحث عن حروب جديدة يا هيلد. الناس هنا يحتاجون إلى الخشب، إلى الحبوب، إلى السلام الذي وعدنا به الجميع. ردت هيلد بصوت متهدج: السلام ليس مجرد كلمة يا إينار، إنه ثمن باهظ لم يدفعه الجميع بعد. ضيق ثورفين عينيه، ووضع يده على كتفه المصابة، ثم نهض ببطء، حركته كانت محسوبة، بلا استعراض. قال بلهجة قاطعة: لا أريد أن أكون ذلك الرجل الذي كنت عليه. إذا كان العبور يعني القتال، سأبحث عن طريق آخر. كان الهواء في الداخل يزداد ثقلاً، ليس بسبب الحرارة، بل بسبب اليقين الذي بدأ يتسلل إلى قلوبهم. لم تكن هناك فلسفات كبرى تُلقى، بل كانت حقائق مجردة تتشكل أمامهم في صورة رحلة لم تبدأ بعد. مسح ثورفين وجهه بيده الخشنة، وتجاهل نظرات الاستغراب من رفاقه، ثم قال بصوت أجش: اعدوا العدة للرحيل. نحن لا نعود للخلف، ولا نغرق في الماضي.', '', 136, '2026-07-15 15:18:01.534', '2026-07-15 15:18:01.534');
INSERT INTO public.chapters VALUES ('02f44246-bc57-41b1-a453-b21e9f306ae1', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 139: صدى الغياب في مروج فينلاند', '— --------------------------------------- توقف ثورفين عن وخز الأرض بحديدة غرس المحراث، منتصباً بوقفة استرخاء لم تألفها عضلاته المتشنجة طوال الأشهر الماضية. لم تكن الشمس هي ما أوقفه، بل صمتٌ ثقيل تسرّب إلى المكان، صمتٌ يختلف عن سكون الغابات المعتاد. في تلك اللحظة، لم تعد رائحة التربة المقلوبة أو رطوبة النهر ذات شأن. رأى ''إينار'' يقف على مسافة منه، عيناه مثبتتان على نقطة فارغة في الأفق. لم يلتفت إينار حين اقترب ثورفين، بل تمتم بصوت خشن ومتهدج: ألا تشعر بذلك؟ لا توجد طيور، ولا حتى حفيف للأعشاب. بدا ثورفين وكأنه يرى ظلاً مألوفاً يرتسم في خياله، طيف رجلٍ ذي لحيةٍ كثة ونظراتٍ نافذة، رجلٌ لم يترك وراءه سوى فكرةٍ ظن ثورفين أنه دفنها تحت أكوام من الضحايا والندم. انقبضت كف ثورفين على مقبض المحراث حتى ابيضت مفاصل أصابعه، وارتجفت عضلات فكه السفلي. لم يكن يرى والده ''ثورس'' بجسده الفاني، بل كانت ذكراه تطفو كغصة في الحلق، تذكره بأن الطريق نحو فينلاند لم يكن يوماً مجرد رحلة للهروب من العنف، بل كان سعياً لتعريف معنى القوة الحقيقية. قال ثورفين بصوتٍ أقرب إلى الهمس المكتوم: لم يعد هناك أعداء يا إينار. كانت كلماته قاسية، جافة كصحراء، لكنها حملت وزناً جعل إينار يلتفت إليه بذهول. لم يكمل ثورفين حديثه، فقد كان ثقل الذكرى أشد من أن يُحمل بالكلمات. نظر إلى يديه اللتين اعتادتا إراقة الدماء، واللتين باتتا اليوم تشقان الأرض لتنبثق الحياة. كانت الروح في داخله تتصارع بين رغبة قديمة في حمل السلاح ونبوءة والده التي أصبحت بوصلته الوحيدة. تحركت نسمة مفاجئة، فاهتزت رؤوس القمح في الحقول القريبة، وكأن الطبيعة ذاتها كانت تؤكد حضوره الغائب. لم يحاول ثورفين طرد الطيف؛ بل تركه يملأ فضاءه، محولاً ثقل الألم إلى عزمٍ صامت. نظر إينار إلى رفيقه، مدركاً أن ثورفين في هذه اللحظة ليس الرجل الذي عرفه من قبل؛ لقد أضحى أكثر هدوءاً، وأشد خطورة في حلمه بالسلام. التفت ثورفين وعاد لغرس المحراث في الأرض بقوة، مصمماً على أن ينمو هذا السلام من رحم هذه الأرض البكر، حتى لو تطلب الأمر أن يحمل وزر كل الأرواح التي فقدها في الطريق إلى هنا.', '', 138, '2026-07-15 15:18:01.95', '2026-07-15 15:18:01.95');
INSERT INTO public.chapters VALUES ('912730a8-c701-4bc0-b5ce-900790a3a861', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 140: صدى الماضي في أروقة الحلم', '— --------------------------------------- انغلق باب الغرفة محدثاً صريراً مكتوماً، ليبقى ثورفين وحيداً مع ظلاله المتراقصة على الجدران الخشبية. لم يكن الوقت ليلاً بالمعنى المعتاد، بل كان زمناً عالقاً بين يقظة متعبة ونوم يرفض المجيء. استند بظهره إلى الجدار الخشن، ملامساً نتوءاته الباردة، بينما كانت أنفاسه المتقطعة هي الصوت الوحيد الذي يملأ الفراغ. لم تكن الغرفة مجرد خشب وجذوع؛ كانت قفصاً يضج بأشباح لا ترحل. فجأة، بدت الزوايا المظلمة تتسع، وتلاشى قوام الغرفة الواقعي ليحل محله ضباب رمادي يغلف الحواس. وقف ثورفين في وسط الساحة القديمة، حيث تتصاعد أبخرة الجليد من الأرض. لم يعد يرى الحاضر؛ عيناه كانتا مثبتتين على الرجل الواقف أمامه. كانت هيئته مهيبة، كتفاه عريضتان كجذعي سنديان، وعيناه تحملان ثقلاً غامضاً لا يلين. ثورس. صمت الأب كان أشد وطأة من صليل السيوف. لم ينطق ثورس بكلمة، لكن حضورَه كان يملأ المدى، يدفعه للمواجهة. استل ثورفين خنجره، تلك الحركة التي باتت جزءاً من ذاكرة عضلاته، لكن يده ارتجفت لبرهة؛ لم يكن هناك عدو، بل كان هناك هو نفسه، يواجه حقيقته العارية. انقضَّ ثورفين، لا رغبة في القتل بل رغبة في الفهم، بينما ظل ثورس واقفاً بوقار جامد، لا يحرك ساكناً، وكأن جسده سدٌ منيع ضد انفعالات ابنه. وفجأة، تحول المشهد. لم يعد ثورس أمام عينيه، بل ظهر أسكلاد، يبتسم بتهكمه المعتاد، عيناه تلمعان ببريق مراوغ وبارد. قال أسكلاد بصوت مسموع كحفيف الأوراق الجافة: أنت لا تزال تحوم حول جثتي، يا صغيري. حاول ثورفين الصراخ، لكن صوته خذله، ليجد نفسه غارقاً في دوامة من الوجوه الملطخة بالدماء، وجوه رجالٍ سقطوا بسبب غضبه الأعمى. لم تكن الأشباح تحاول قتله؛ كانت تطالبه بالحساب. انقبضت عضلات فكه حتى برزت عروق عنقه، وتصبب جبينه عرقاً بارداً. استيقظ ثورفين فجأة، جسده يرتجف على الفراش، رئتاه تلهثان طلباً للهواء. كانت الغرفة ساكنة، والجدران الخشبية لا تزال صامتة، لكن الصدى في رأسه لم يهدأ. مسح وجهه بكفه المرتجفة، محاولاً استعادة توازنه. لم يعد الرجل الذي كان يبحث عن الانتقام في الأزقة المظلمة، لكن الأشباح لا تترك الموتى ولا الأحياء بسهولة. نهض ثورفين، كانت خطواته ثقيلة على الأرضية الخشبية، متجهاً نحو النافذة الصغيرة التي يتسلل منها ضوء الفجر الشاحب. نظر إلى الأفق البعيد، حيث تذوب النجوم في زرقة النهار، مدركاً أن طريقه نحو السلام ليس سوى حرب أخرى، أشد ضراوة وأكثر عمقاً من أي قتال خاضه بحد السيف.', '', 139, '2026-07-15 15:18:02.128', '2026-07-15 15:18:02.128');
INSERT INTO public.chapters VALUES ('7070e6c7-b4ea-48e2-a6d5-1888f2246015', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 141: ثمن العودة إلى الديار', '— --------------------------------------- انتصبت السفينة تشق مياه المحيط الرمادية، بينما كان ثورفين يراقب الأفق بعينين لا تبرحان مكانهما. لم تكن الرحلة نحو فينلاند مجرد إبحار، بل كانت محاولة لردم هوة سحيقة حفرتها سنوات من الدماء. التفت إليه إينار، ممسكاً بدفة القيادة، ملامحه مشدودة، وعروق يده تبرز مع كل حركة للموج. قال إينار بصوت خشن: ثورفين، المؤن تنفد. الرجال بدأوا يتهامسون. التفت ثورفين ببطء، كانت عيناه تحملان هدوءاً غريباً لا يتناسب مع عاصفة التوتر التي تملأ سطح السفينة. أجاب باقتضاب: سنصل. الأرض ليست بعيدة كما يظنون. في تلك الأثناء، كان هيلد تقف عند مقدمة السفينة، تراقب ثورفين من بعيد. لم تكن بحاجة للكلمات لتعرف أن ما يحمله الرجل في صدره ليس أمل المستكشف، بل عبء التكفير. اقترب منها كارلي، الصغير الذي لم يدرك بعد حجم الصراع الذي يدور في أرواح من حوله، فوضعت يدها على كتفه دون أن تلتفت. في قاع السفينة، كان الرجال يتجمعون حول شعلة صغيرة، وجوههم محفورة بالتعب، والأسلحة التي لم يلمسوها منذ أشهر ملقاة في الزوايا كأنها بقايا حضارة بائدة. لم تكن هناك أحاديث عن المجد أو الغنائم، بل حديث عن الخبز، وعن دفء الأرض التي لم يروها بعد. نهض ثورفين ومشى وسطهم؛ لم يرتدِ درعه، ولم يحمل سيفاً، بل سار بخطوات واثقة جعلت البعض يفسح له الطريق غريزياً. وصل إلى حافة السفينة ونظر إلى الأسفل حيث تتلاطم المياه. تذكر كلمات والده ثورس، تلك التي ظلت تتردد في ذهنه كصدى جرس قديم: القوة ليست في القدرة على الإنهاء، بل في القدرة على البدء من جديد دون سيف. انقبضت عضلات كتفه، ونظر إلى السماء؛ كانت الغيوم تتجمع، تنذر بعاصفة، لكن ثورفين لم يتحرك. لم يكن يهرب من الماضي، بل كان يواجهه في كل ميل بحري يقطعه. وعندما سأله أحد البحارة بصوت ملؤه التشكيك: لماذا لا تزال تؤمن بأنها موجودة؟ أجابه ثورفين دون أن يلتفت: لأن البديل هو العودة إلى حيث فقدت إنسانيتي، وهذا ثمن لا يمكنني دفعه. ساد صمت مطبق، لم يقطعه سوى صوت ارتطام الأمواج بجانب السفينة الخشبي، واستمرت السفينة في تقدمها نحو المجهول، حاملةً رجالاً يمزقهم الحنين إلى أرض لم يطأوها بعد، وقائداً يرفض أن يسفك دماءً أخرى ليحقق حلمه.', '', 140, '2026-07-15 15:18:02.376', '2026-07-15 15:18:02.376');
INSERT INTO public.chapters VALUES ('e8561592-2bfa-4ffd-9b4b-4306b964005a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 142: خلف أسوار الرماد', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في تربة أرض فينلاند الغامضة، بينما يرتفع الدخان الأسود من بقايا المستوطنة المحترقة. لم تكن الصرخات التي مزقت سكون الصباح قد تلاشت تماماً من مسامعه بعد، لكن صمته كان أثقل من أي ضجيج. التفت إلى ليف إريكسون، الذي كان يشد قبضته على مقبض سيفه بأسلوب ينم عن ارتجاف داخلي مكتوم. قال ثورفين بصوت أجش خالٍ من أي نبرة انفعالية: لن نتبعهم. ساد صمت مطبق، لم يقطعه سوى طقطقة الأخشاب المحترقة. نظر إينار إليه بذهول، واتسعت عيناه بينما كانت يداه الملطختان بالرماد ترتجفان غضباً. صاح إينار: أتعني أن نتركهم يغادرون؟ لقد حرقوا منازلنا، وسرقوا أرواح من نحب! التفت ثورفين ببطء، كانت عيناه ثابتتين كحجر صوان، لا أثر فيها لدموع أو انكسار، بل كان فيها حسم بارد ومخيف. رد ثورفين بنبرة قاطعة: المطاردة تعني المزيد من الدماء. هذا ما يريده أولئك الذين دفعوا بهم إلينا. نحن هنا لنبني، لا لنعيد كرة الموت. كانت الكلمات تخرج من ثورفين وكأنها حجارة ثقيلة، لا تقبل النقاش ولا تحتمل التأويل. لم يكن هناك وعظ أخلاقي في صوته، بل كان صدى لقرارات اتخذها في أعماق جحيمه الشخصي. في تلك اللحظة، لم تعد فينلاند مجرد أرض موعودة للعيش، بل أصبحت اختباراً لوجودهم ذاته. تقدم ليف خطوة للأمام، ماسحاً وجهه الملطخ بالدخان، وسأل بصوت خافت: وإذا عادوا؟ أطبق ثورفين فكيه، وبرز عرق في صدغيه، ثم قال: لن يعودوا، لأننا سنكون هنا، ثابتين كالجبال. كان ثورفين يدرك أن طريقه الجديد ليس سهلاً، وأن السلام يتطلب شجاعة أكثر من الحرب، وهو ثمن كان مستعداً لدفعه بدم بارد. نظر إلى الأفق، حيث تلاشت قوارب المعتدين في الضباب، ولم يرمش له جفن. كان يعلم أن المعركة الحقيقية ليست مع من رحل، بل مع تلك الرغبة المكبوتة في أعماقه التي تطالب بالانتقام، والتي كان عليه أن يخنقها كل يوم بوعي مؤلم.', '', 141, '2026-07-15 15:18:02.564', '2026-07-15 15:18:02.564');
INSERT INTO public.chapters VALUES ('b16def89-7dc7-4589-843f-9e8f04670ed9', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 143: خلف أسوار التوقعات', '— --------------------------------------- ارتطم صدى خطوات ثورفين بقعر السفينة الخشبية كطرقات مطرقة على سندان صامت. لم تكن الرحلة نحو فينلاند مجرد مسار بحري، بل كانت اختباراً لتوازن دقيق يتهدده الخوف من المجهول. وقف إينار بجانبه، يمسح العرق عن جبينه بظهر كفه، عيناه تجولان في الأفق الرمادي الممتد بلا نهاية. سأله إينار بصوت منخفض، مشوب بقلق لا يخطئه بصيرة: هل تعتقد أننا نبتعد عن شرور العالم القديم، أم أننا نحملها معنا في أمتعتنا؟ لم يلتفت ثورفين، بل ظل بصره معلقاً بتلاطم الأمواج الذي بدا كفوضى منظمة. رد ثورفين بحدة: الشر لا يسافر معنا، نحن من نصنعه حين ننسى لماذا بدأنا الرحلة. كان صوته خشناً، يخلو من أي نبرة تصالحية. اقترب ليف أريكسون بخطوات واثقة، رغم ثقل السنوات التي انحنت لها كتفاه. توقف أمام ثورفين، مخرجاً خريطة جلدية قديمة، أطرافها مهترئة بفعل الرطوبة. وضع ليف إصبعه على نقطة مبهمة في وسط الرسم. هذه الأرض لا ترحم من يطأها بقلب متردد، قال ليف بصوت جهوري يقطعه هدير البحر. التفت ثورفين، والتقطت عيناه نظرة ليف. لم تكن تحذيراً، بل كانت اعترافاً بمصير مشترك. في تلك اللحظة، تحركت السفينة بعنف تحت تأثير موجة عاتية، فتمايل الجميع. قبض ثورفين على حافة السفينة، برزت عروق يده من شدة الضغط، وبدا مفاصل أصابعه بيضاء كأنها عظام مصقولة. أدرك إينار حينها أن التراجع لم يعد خياراً مطروحاً، فالأفق الذي كانوا ينظرون إليه لم يعد مجرد مساحة جغرافية، بل أصبح حداً فاصلاً بين حياة مضوا بها للنسيان، وحياة لم يكتب فصلها الأول بعد. ساد صمت مطبق، لم يقطعه سوى صوت الخشب الذي يئن تحت ضغط المياه المندفعة، وانفاسهم التي بدت مسموعة في سكون الصباح. لم يقل ثورفين شيئاً إضافياً، بل انحنى ليربط حبال الأشرعة بإحكام، كمن يحاول ربط مصيره بنفسه، بعيداً عن أهواء القدر التي لطالما تلاعبت به.', '', 142, '2026-07-15 15:18:02.854', '2026-07-15 15:18:02.854');
INSERT INTO public.chapters VALUES ('1ebb55a8-4dee-4263-8adb-e1914bac9a5c', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 144: حصار الشك والوعود المؤجلة', '— --------------------------------------- توقف إينار عن الحفر فجأة، وترك المعول يرتطم بالأرض الصلبة بصوت مكتوم. كان العرق يشق طريقه في أخاديد وجهه، بينما كانت عيناه مثبتتين على الأفق حيث تلوح ملامح معسكر ''فليد'' الغريب. التفت ثورفين نحوه، ممسكاً بقطعة خشبية كان ينحتها بتركيز صارم. لم تكن المرة الأولى التي يتبادلان فيها نظرات القلق، لكن هذه المرة، ثقل الصمت كان مختلفاً. نادى إينار بصوت أجش خلت منه النبرات المرحة المعتادة: ثورفين، هل تعتقد حقاً أنهم سيتركوننا وشأننا إذا لم نعد نطلب القتال؟ لم يجب ثورفين على الفور؛ بل وضع القطعة الخشبية جانباً، ورفع يده ليمسح الغبار عن وجهه. بؤبؤ عينه اتسع قليلاً وهو ينظر إلى التلال المرتفعة، ثم قال بنبرة مقتضبة: لا أحد يترك أحداً وشأنه هنا. الخيار ليس في أيديهم، إنه في أيدينا. اقترب ''جودريد'' من خلفهما، كانت تمسك بيديها بقايا طعام بسيط، ووجهها يحمل تعابير جادة لا تناسب عمرها. همست وهي تنظر إلى الأفق: هناك رجال يتجولون حول حدودنا منذ الفجر. لا يحملون سيوفاً مشهرة، لكنهم يراقبون كل حركة نخطوها. انقبضت عضلات فك ثورفين، فنهض واقفاً بحركة مفاجئة أطاحت بالمعول الذي كان بجانبه. نظر إلى أبعد نقطة يمكن للعين أن تصل إليها، حيث تتداخل ظلال الأشجار مع الضباب المتصاعد. لم يكن الخوف هو ما يملأ صدره، بل كان وعياً حاداً بأن المسافة بين الحلم الذي يسعى إليه وبين الواقع الدموي الذي فر منه تتقلص بسرعة مخيفة. تقدم خطوة نحو حافة الحقل، صوته خرج عميقاً ومحشرجاً: لا تظهروا لهم ضعفاً. إذا اقتربوا، فليكن ذلك لسبب واحد فقط: المفاوضة على الأرض، لا على حياتنا. كان ''هيلد'' يراقب من مسافة بعيدة، يده تتحسس نصل خنجره المخفي، وعيناه تلمعان ببريق بارد. لم تكن هناك كلمات تلطف حدة التوتر، ولم يكن هناك راوٍ يفسر المصير؛ فقط كانت الأنفاس المتلاحقة، وصوت الريح الخافتة بين أعمدة الخشب، واليقين بأن الحوار القادم لن يكون بالكلمات وحدها، بل بصلابة المواقف التي يتخذونها تحت سماء شمالية لا تعرف الرحمة.', '', 143, '2026-07-15 15:18:03.039', '2026-07-15 15:18:03.039');
INSERT INTO public.chapters VALUES ('04263ea2-cf8b-4013-ad24-ba5f4da862cc', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 145: خلف أسوار الصمت', '— --------------------------------------- انغلق باب الغرفة الخشبية بصوت مكتوم، تاركاً هيلغا وثورفين في فضاء يسوده صمت مثقل بالتوجس. لم تكن الغرفة مجرد جدران، بل كانت شاهداً على ثقل السنين التي مرت في غياب الرجل الذي غير مصائرهم. اتجهت هيلغا نحو صندوق خشبي عتيق، تحركت يداها ببطء، وكأنها تلمس ذكرى لا تزال تنبض بالدفء. أخرجت منه غرضاً ملفوفاً بعناية، ثم التفتت لتواجه ثورفين. حدق ثورفين في الشيء الملقى بين يديها، اتسعت حدقتا عينيه للحظة قبل أن ينقبض فكه بقوة. كان خنجراً، ليس أي خنجر، بل هو ذلك الرمز الذي طالما ارتبط بوالده، ثورس. لم تكن الحاجة إلى الكلمات قائمة؛ فالمعدن الصدئ قليلاً يروي قصة أطول من أي حوار. قالت هيلغا بنبرة واهنة، اخترقت جمود الغرفة: هذا ملكك الآن، ثورفين. لم يكن صوته حين أجاب سوى همس خشن، مشبع بتراكمات الندم: لم أعد أستحق حمله. كانت يداه ترتجفان ببطء غير ملحوظ، أصابعه ترفض ملامسة المقبض كما لو كان قطعة من جمر. تراجعت هيلغا خطوة، تاركة إياه وحده مع إرث الرجل الذي كان يجسد القوة والحكمة دون أن يرفع سيفاً في وجه العزل. في الخارج، كانت أصوات المستوطنة البعيدة تتسلل عبر الشقوق، أصوات حياة تمضي، بينما كان ثورفين غارقاً في صراع صامت. لم تكن الحرب التي يخوضها هذه المرة بساحات المعارك، بل في ذلك الفراغ الذي تركه والده في صدره. أمسك الخنجر أخيراً، شعور الملمس الخشن للمقبض أثار في ذاكرته صوراً مشوشة؛ صوت خطوات والده، نظراته التي كانت تخترق ضجيج العالم بسلام غريب. تنفس ثورفين بعمق، محاولاً استعادة توازنه، وبينما كانت الشمس تميل نحو الغروب، كان الضوء الخافت ينعكس على نصل الخنجر، راسماً خيطاً من نور في عتمة الغرفة. لم يقل شيئاً، لكن انحناءة رأسه كانت بمثابة قبول لثقل المسؤولية التي لم يعد قادراً على الفرار منها. التفت نحو النافذة، ناظراً إلى الأفق البعيد، حيث تبدأ الأرض التي يحلمون بها، وتلاشت ملامح الغضب عن وجهه، تاركة وراءها تعبيراً مشوباً بعزم جديد، هادئ كالبحر قبل العاصفة.', '', 144, '2026-07-15 15:18:03.237', '2026-07-15 15:18:03.237');
INSERT INTO public.chapters VALUES ('57b71aaf-4efd-40a4-b3a8-a9f29db28046', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 146: صدى الماضي في سراديب الروح', '— --------------------------------------- تلاشت أصوات النيران في الموقد، ولم يبقَ سوى طقطقة الخشب المحترق التي تشق سكون الغرفة. حدق ثورفين في الفراغ، بينما كان وجه أسكلاد يطفو في ذاكرته، ليس كقائد محارب، بل كطيفٍ لا يني يطالبه بالحساب. قبض ثورفين على حافة الطاولة بقوة حتى ابيضت مفاصل أصابعه، واندفع صوته من حنجرة ضيقة: ''لقد ظننت أنني دفنت ذلك الرجل في أيسلندا، ظننت أنني تركت ذاك النصل يصدأ في أعماق المحيط. '' كان إينار يراقب صديقه بصمت، يرى كيف يرتجف كتف ثورفين، وكيف يبتعد نظره عن الحاضر ليغرق في مأساة قديمة لم تنتهِ فصولها بعد. التفت ثورفين نحوه، وعيناه لا تزالان تشعان ببريق من التيه: ''أنا لا أبحث عن الثأر، إينار. أنا أبحث عن الخلاص من وجهه الذي يلاحقني في أحلامي، ذلك الوجه الذي يبتسم بسخرية بينما يغرز الخنجر في حياة كل من أحببت. '' تنفس إينار بعمق، ثم وضع يده الثقيلة على كتف ثورفين، كاسراً حدة التوتر في المكان، وقال بنبرة خشنة ومباشرة: ''أنت لست هو، ولن تكون. لا تمنحه انتصاراً أخيراً بأن تقتات على كراهيته. '' استدار ثورفين نحو النافذة، حيث كان ضوء القمر الباهت يعكس ملامحه المنهكة. لم يعد يرى أسكلاد في الضباب، بل بدأ يرى نفسه، رجلاً يحاول بناء عالمٍ لا يعترف بلغة السيف، مهما كان الثمن باهظاً. كان الصمت الذي أعقب حديثه ثقيلاً، مشبعاً بقرارات صامتة بدأت تتشكل في جوفه، لا كوعود للآخرين، بل كعهدٍ بينه وبين جراحه التي لم تندمل بعد.', '', 145, '2026-07-15 15:18:03.447', '2026-07-15 15:18:03.447');
INSERT INTO public.chapters VALUES ('5c4bf53d-d03b-4926-93ac-eab3aac7d5e0', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 147: صدى النصال على أرض فينلاند', '— --------------------------------------- توقف ثورفين عن الحركة. لم تكن هناك رياح، بل صمت ثقيل يمتد عبر السهول العشبية، يقطعه فقط صوت أنفاس إينار المتقطعة خلفه. أمامه، وقف هيلد بنظرات حادة كشفرة صقيلة، وبقوسها المشدود نحو صدره. انقبضت عضلات فك ثورفين، بينما تجمدت يداه إلى جانبيه، خالية تماماً من أي سلاح. همس إينار بصوت متهدج: ثورفين، تنحَ جانباً. لكن ثورفين لم يزحزح قدماً، بل حدق في عيني هيلد، باحثاً عن أي وميض تردد، لكنه لم يجد سوى جدار من الجليد. لم يمتلك ثورفين حق الاعتراض على رغبتها في الانتقام، فهو يدرك أن ندوب الماضي لا تندمل بالكلمات المعسولة. قال ثورفين بنبرة خافتة ومباشرة: إذا كان سهمكِ سيمنحكِ السلام الذي تنشدينه، فلا تترددي. التوتر في ذراعي هيلد كان ملموساً؛ ارتعشت أوتار القوس تحت ضغط أصابعها، لكن عينيها اتسعتا بؤبؤاً لثانية واحدة، وهي تدرك أن الرجل الذي يقف أمامها اليوم لا يشبه القاتل الذي مزق حياتها قبل سنوات. لم يكن هناك دفاع، لم يكن هناك تملق لطلب الحياة، كان هناك قبول تام للنتيجة. خفضت هيلد قوسها قليلاً، والشرر يتطاير من نظراتها الممزوجة بالصراع المرير. تدخل إينار، محاولاً استجماع شتات الموقف بصرخات غير متزنة، ملوحاً بيديه في الهواء: نحن لسنا أعداء! نحن هنا لنبني، لا لنحصد المزيد من الدماء. لم تلتفت هيلد إليه، بل بقيت عيناها مسمرتين على ثورفين، وكأنها تنتظر منه أن يرفع يده ليقاتل، أن يستدعي الوحش الذي كانه يوماً. لكن ثورفين ظل ثابتاً، جسده مسترخٍ بطريقة استفزت هدوء هيلد القاتل. في تلك اللحظة، تبخرت فكرة القتل من الهواء، تاركةً مكاناً لثقل الحقيقة التي لا يمكن الهروب منها. خفضت هيلد القوس تماماً، وألقت نظرة أخيرة محملة بالمرارة على الأفق، قبل أن تستدير وتغادر، تاركةً خلفها صمتاً أعمق من ذي قبل. زفر ثورفين هواءً طويلاً، ثم أغمض عينيه للحظة؛ لم ينتصر في معركة، بل نجا من عاصفة كان هو نفسه وقودها.', '', 146, '2026-07-15 15:18:03.635', '2026-07-15 15:18:03.635');
INSERT INTO public.chapters VALUES ('32d08871-1493-44ee-8581-4456274afb1b', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 148: خلف أسوار الترقب', '— --------------------------------------- انتصبت أسوار مدينة ''جوتومين'' كأنها نابض مشدود لا يرتخي، وخلف بواباتها الخشبية الضخمة كان الهواء مثقلاً برائحة الترقب والرهبة. توقف ثورفين، أنفاسه منتظمة رغم اضطراب نبضاته، وعيناه تمسحان التحصينات بدقة جراحية؛ لا مجال للخطأ، فكل حجر في هذا السور يمثل عقبة يجب تجاوزها بذكاء وليس بالقوة الغاشمة التي سلكها في ماضيه القريب. التفت إلى أينار الذي بدا عليه التوتر، كانت قبضتا أينار مغلقتين بقوة حتى ابيضت مفاصله. قال ثورفين بصوت منخفض، خشن ومباشر: ابقَ خلفي، لا تتحرك إلا بإشارة مني، فالمكان لا يحتمل حماقات الاندفاع. لم يرد أينار، بل اكتفى بإيماءة سريعة، ملامحه تعكس مزيجاً من الثقة المكتسبة والخوف الفطري. في تلك الأثناء، برزت وجوه الحراس فوق الحصون، أعينهم تتفحص الغرباء بفضول حذر، لكن ثورفين كان قد حسم أمره بالفعل. لم يكن هناك وقت للتردد، فالعالم الذي يبحث عنه ليس في أطراف السيوف بل في القدرة على عبور هذه الحدود دون سفك دماء لا طائل منها. اقترب ثورفين من البوابة، خطواته ثابتة، تلمس مقبض خنجره المهجور في حزامه، لا ليشهر سلاحه، بل ليطمئن أنه ما زال تحت سيطرته، كرمز لعهد قطعه على نفسه. صمتت الرياح للحظة، وكأن الطبيعة نفسها تترقب الخطوة القادمة، بينما تقدم ثورفين نحو الحراس، ملامح وجهه خالية من أي عدوانية، لكنها مشحونة بصلابة رجل لا يخشى الموت، بل يخشى العودة إلى ما كان عليه من قبل. نادى ثورفين بصوت أجش ولكن واضح: نحن لا نطلب حرباً، بل نطلب عبوراً. توقف الحارس الذي كان يتوسط الممر، نظر إلى ثورفين نظرة فاحصة، تلك النظرة التي تزن الرجال لا بعدتهم بل بوقفتهم، ثم بصق الحارس جانباً، وقال بلهجة غليظة لا تبالي: الغرباء هنا لا يدخلون بطلب، بل بشروط. انقبضت عضلات كتف ثورفين، لكنه لم يلتفت لأينار، بل ثبت نظره في عيني الحارس مباشرة، مجيباً ببرود: سأقبل بشروطكم، طالما أنها لا تتضمن دماءً لا حاجة لنا بسفكها. كان الصمت الذي تلا كلماته ثقيلاً، صمتٌ لم يقطعه سوى صرير البوابة الخشبية وهي تبدأ بالانفراج ببطء شديد، معلنةً عن بداية مرحلة جديدة، مرحلة لن تكون فيها القوة هي اللغة الوحيدة للحوار.', '', 147, '2026-07-15 15:18:03.827', '2026-07-15 15:18:03.827');
INSERT INTO public.chapters VALUES ('aad6c9f0-8d70-468a-9976-b6871f36b6cd', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 149: حين يرتعد الحديد', '— --------------------------------------- ارتطم نصل السيف بصفيحة الدرع المعدنية محدثاً رنيناً حاداً اخترق ضجيج الميدان. كان ثورفين يلهث، وقد التصقت خصلات شعره المبتلة بالعرق بجبهته. لم تكن هذه معركة لفتح أراضٍ أو سلب غنائم، بل كانت مواجهة من أجل البقاء في قلب غابة ''فينلاند'' الموحشة. تقدم ''هيلد'' بخطوات محسوبة، عيناها لم تفارقا حركة جسد ثورفين. قبضت على مقبض قوسها بقوة جعلت مفاصل أصابعها تبرز بيضاء. صاح ثورفين بصوت متحشرج: تنحي جانباً، هذا ليس قتالك. لم تجبه، بل أطلقت سهماً خاطفاً استقر في جذع الشجرة خلف أذنه مباشرة، متجاوزاً إياه بسنتيمترات معدودة. تجمد ثورفين في مكانه؛ صوت ارتطام السهم بالخشب كان كفيلاً بإيقاظ غريزته. التفت ببطء، عضلات فكه منقبضة، ليرى الحشد المحتشد عند حافة الغابة. كان ''آيفار'' يتوسط الرجال، يمسح الدم عن وجنته بفظاظة، وعيناه تقدحان شرراً. نادى آيفار بصوته الأجش: يا ثورفين، هل ستظل تحمي هؤلاء المتوحشين بينما يذبحون رجالنا؟ كف عن هذا الهراء، السيف في يدك ليس للزينة! التفت ثورفين نحو آيفار، لم تكن عيناه تعبران عن غضب مألوف، بل عن حالة من الإنهاك الحاد. جف ريقه، وبدلاً من أن يستل خنجره المعهود، رفع يديه مفتوحتين أمام صدره. صمت الميدان فجأة، لم يبق سوى صوت تكسر الأغصان تحت أقدام المترددين. اقترب ''ييف'' ببطء، كان يرتجف لا من البرد، بل من وطأة التوتر الذي يطبق على أنفاسه. نظر ثورفين إلى الرجلين الواقفين أمامه، ثم إلى الخوف المتجذر في عيون أتباعه. قال ثورفين بصوت منخفض، مخنوق، لكنه مسموع: لن أقتل أحداً منكم. خفض آيفار سيفه قليلاً، وقد ارتسمت على وجهه ملامح الذهول الممزوج بالاحتقار: أنت مجنون. إنهم لا يعرفون الرحمة، وأنت تقدم رقبتك لهم طواعية. تقدم ثورفين خطوة نحو آيفار، لم يترنح، بل كان ثبات قدميه يغرس نوعاً من الريبة في نفوس الواقفين. أجابه ثورفين وهو يحدق مباشرة في بؤبؤ عينيه: إذا كان السلام يمر عبر التضحية، فأنا أختار أن أكون الضحية لا الجلاد. تحرك هواء الغابة، وتطايرت أوراق الشجر اليابسة بينهما، بينما بقيت النظرات معلقة في لحظة فارقة؛ حيث انكسر جبروت السلاح أمام إصرار صامت، وحيث أدرك الجميع أن ثورفين لم يعد ذلك المحارب الذي يخشى الموت، بل صار رجلاً يخشى فقط أن يلوث يديه بدم لا ذنب له.', '', 148, '2026-07-15 15:18:04.056', '2026-07-15 15:18:04.056');
INSERT INTO public.chapters VALUES ('41267e62-80e1-4cb8-b201-acd9812eaa3b', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 150: صدى النصال في بلاد العزلة', '— --------------------------------------- انغلق باب المخزن بقوة، تاركاً إيارس يحدق في وجه ثورفين بذهول لم يفلح في إخفائه خلف قناع الجندي الصارم. لم يكن ثورفين قد استل خنجره، ولم يتخذ وضعية الهجوم؛ بل وقف ساكناً، يداه مرتخيتان بجانبه، بينما كان إيارس يضيق عينيه، محاولاً استيعاب هذا التحول في خصمه القديم. صمت ثورفين كان ثقيلاً، خالياً من تلك الهالة العدائية التي اعتادها المحاربون، وهو ما أثار حنق إيارس أكثر من أي صرخة تحدٍ. قال إيارس بصوت خشن ومتهكم: هل تظن أنك بهذه الهيئة المثيرة للشفقة ستخرج من هنا حياً؟ سأقتلع تلك الثقة التي لا مبرر لها من صدرك. لم يرتجف ثورفين، بل اتسعت عيناه قليلاً قبل أن يزفر ببطء، وكأنما يحاول طرد بقايا ضجيج المعارك القديمة من ذاكرته. رد ثورفين بنبرة هادئة ومقتضبة: لست هنا لأقاتلك، ولست عدوك. كان صوته يفتقر إلى نبرة التهديد، مما جعل إيارس يترنح في مكانه من شدة الارتباك. اندفع إيارس بحركة مباغتة، لكن ثورفين تحرك بجسده في تناغم مرن، متفادياً الضربة لا بالصد، بل بالانزياح البسيط. تكررت الهجمات، وإيارس يزداد غضباً مع كل إخفاق، بينما بقي ثورفين محافظاً على مسافة آمنة. لم يكن يدافع عن نفسه فحسب، بل كان يراقب حركات إيارس، محاولاً قراءة التوتر في عضلات كتفيه المجهدة. توقف إيارس، صدره يعلو ويهبط بعنف، وقد تلطخ وجهه بالعرق. سأل ثورفين وهو يخطو خطوة واحدة نحو الأمام: لماذا لا تزال تتمسك بهذا القتال؟ نحن لا نملك ما نجنيه هنا. استشاط إيارس غضباً، محاولاً كبت رغبته في الانقضاض مجدداً، وقال بين أسنان مصطكة: هذا ليس شأنك، أيها الأحمق. القتال هو ما يحدد قيمتنا، وما دون ذلك هو فراغ لا أطيقه. نظر إليه ثورفين نظرة مطولة، نظرة خالية من الكراهية، نظرة فاحصة لرجل يبحث عن معنى في كومة من الدماء. كان الهواء في المخزن ثقيلاً، مشبعاً بصوت أنفاسهما المتسارعة، بينما استمرت محاولة ثورفين المستميتة لإيقاف هذا العبث دون أن يريق قطرة دم واحدة، مؤمناً بأن هناك طريقاً آخر غير الموت الذي نذر حياته لتركه خلف ظهره.', '', 149, '2026-07-15 15:18:04.26', '2026-07-15 15:18:04.26');
INSERT INTO public.chapters VALUES ('5dccff77-34cb-4427-b424-7e89a22cbd75', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 151: صدى الوعود في أرض الغرباء', '— --------------------------------------- توقف ثورفين عن التقدم، وثبت قدميه على التربة الرطبة التي لم تألف بعد ثقل خطاه. لم يكن في الأفق سوى امتداد شاسع من أشجار الصنوبر المتراصة كجيش صامت يتربص بالمتسللين. التفت إينار إلى رفيقه، كانت أنفاسه المتقطعة تمتزج بضباب الصباح، وقال بصوت خافت لم يكسر حدة السكون: هل تظن أنهم سيقبلون بنا؟ لم يرد ثورفين فوراً؛ كانت عيناه تمسحان أطراف الغابة، يبحث عن أثر لحياة أو تهديد. أجاب بنبرة مقتضبة، خالية من أي تهيؤات: القبول ليس خياراً، بل هو ثمن لبقائنا. تراجع إينار خطوة إلى الوراء، فركت أصابعه المتشققة من البرد بعضها ببعض، ثم أضاف: إنهم لا يعرفوننا يا ثورفين، نحن مجرد غرباء يحملون فؤوساً في أرض يدعون أنها لهم. هز ثورفين كتفيه بقسوة، وشد من حزامه الجلدي قائلاً: لا أحد يملك الأرض إلا من يحرثها. في تلك اللحظة، ظهر ظل بين الأشجار، رجل ضخم البنية يرتدي جلوداً خشنة، ممسكاً برمح قصير بوضعية توحي بالاستعداد للطعن لا للترحيب. توقف الرجل، وأمال رأسه قليلاً، وعيناه لا تغادران جسد ثورفين. قال الرجل بلهجة ثقيلة: من أنتم؟ ولماذا تحملون حديداً في أراضينا؟ لم يتردد ثورفين، تقدم خطوة واحدة، تاركاً يديه مكشوفتين بعيداً عن مقبض خنجره، وقال بصوت ثابت: نحن باحثون عن موطئ قدم، لا عن دم. ضحك الرجل ضحكة جافة، متهكمة، وقال: الدم هو العملة الوحيدة التي نعرفها هنا. تسارعت ضربات قلب إينار، وشعر بتشنج في عضلات فخذه، لكن ثورفين ظل ثابتاً كصخرة في مجرى نهر هائج. نظر ثورفين مباشرة في عيني الرجل، وقال بجدية صلبة: لقد أهرقت ما يكفي من الدماء لأعرف أنها لا تزرع شيئاً. تلاشت ابتسامة الرجل، وحل محله صمت ثقيل لم يقطعه إلا حفيف أوراق الشجر المتساقطة. كان الهواء مشحوناً بنوع من الترقب الذي يسبق العاصفة، أو ربما بداية لشيء آخر تماماً، شيء لم يعهده ثورفين في حياته التي قضاها بين النيران والسيوف. استدار الرجل دون كلمة واحدة وأشار لهم بيده أن يتبعوه. سار ثورفين خلفه، وعيناه تراقبان كل حركة، مدركاً أن هذه الخطوات هي بداية لاختبار وجودي سيكون الفشل فيه مكلفاً بقدر ما كانت المعارك قديماً.', '', 150, '2026-07-15 15:18:04.454', '2026-07-15 15:18:04.454');
INSERT INTO public.chapters VALUES ('f40da9c9-f2b3-47ab-90d9-71591516c7ee', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 153: سُعار في العراء', '— --------------------------------------- تصلبت ملامح ثورفين وهو يراقب هيلد التي تصوب قوسها نحو صدره، خيط الوتر مشدود كأعصاب ترفض الارتخاء. في ذلك الفضاء القاسي من أراضي فينلاند البكر، كان الصمت أشد وطأة من زئير البحر. قال ثورفين بصوت متحشرج: خفضي سلاحك يا هيلد. لم يكن في نبرته استعطاف، بل ثقلٌ نابعٌ من إدراكٍ مرير. أجابت هيلد وقد تضيق بؤبؤا عينيها: وعدتني يا ثورفين. وعدتني أنك لن تحمل سيفاً، وأنك ستبني عالماً بلا حروب، لكن ها أنت ذا، تضطر للقتال من جديد. التفت ثورفين نحو المحاربين الذين طوقوهم، لم يكن يبحث عن مخرج بطلٍ أسطوري، بل كان يراقب زوايا أجسادهم، يحلل توزيع ثقلهم على الأرض. هتف أحد المهاجمين: ليس أمامكم سوى خيارين، الموت أو الخضوع! لم يكترث ثورفين للتهديد؛ كان عقله يعيد ترتيب خياراته المحدودة. ألقى نظرة سريعة على إينار الذي كان يتأهب بقبضتين مشدودتين، ثم أعاد نظره إلى هيلد. قال ثورفين بحدّة: البقاء على قيد الحياة ليس خيانةً للمبدأ. إذا سقطنا هنا، فمن سيحمل الحلم الذي بدأناه؟ لم تنتظر هيلد رداً، بل تحركت بخفة قططية، وأطلقت سهماً مرق الهواء بدقة قاتلة نحو كتف أقرب المهاجمين. سقط الرجل أرضاً وهو يضغط على جرحه، بينما اندفع ثورفين نحو الفجوة التي أحدثها السهم. لم يكن قتالاً بطولياً، بل كان تفادياً محسوباً للضربات، وحركةً اقتصاديةً لا تضيع طاقة دون داعٍ. ضرب ثورفين بمقبض يده فك المهاجم الذي اعترض طريقه، سامعاً صوت انخلاع العظم مكتوماً، ثم دفع بجسده ليتجنب طعنة رمح غادرة. لم تكن هناك فلسفة تبرر هذا النزاع، فقط غريزة البقاء في وجه عدوانٍ لا يرحم. وسط غبار المعمعة، التقت عينا ثورفين وإينار للحظة، صمتٌ قصيرٌ قبل أن يندفعا معاً لفتح طريقٍ نحو الغابة. كان الهواء مشحوناً برائحة العرق والتراب المثار تحت الأقدام، بينما استمرت هيلد في إرسال سهامها، كل سهمٍ يوقف مهاجماً، وكل حركة منها توحي بمرارة داخلية لا تُوصف. قال ثورفين وهو يلهث: لا تقتليهم إن استطعتِ، لا نريد المزيد من الدماء. كان طلبه بسيطاً ومستحيلاً في آن واحد، لكنه كان بوصلته الوحيدة وسط هذا السعار الذي يجتاح المكان.', '', 152, '2026-07-15 15:18:04.861', '2026-07-15 15:18:04.861');
INSERT INTO public.chapters VALUES ('ba387944-9392-4e46-95d5-efae59bcf691', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 154: ثمن العبور', '— --------------------------------------- توقفت السفينة عند ضفاف النهر، حيث كانت الأرض الموحلة تبتلع أقدام الرجال. لم يكن ثورفين يبحث عن قتال، لكنه وجده في هيئة ثورغيل، المحارب الضخم الذي تتصاعد من عينيه رغبة عارمة في تجربة حدته. وقف ثورغيل أمام ثورفين، يمسح بيده على نصل فأسه الثقيل، ونظر إليه باحتقار ظاهر. قال ثورغيل بصوت أجش يقطر سخرية: ''هذا هو المعتوه الذي يرفض حمل السيف؟ أظن أن دمك سيسيل على هذا الطين قبل أن تنطق اعتذاراً''. لم يلتفت ثورفين نحو الرجل، كانت عيناه تركزان على المسافة التي تفصل بينهما، بينما كان صدره يعلو ويهبط بإيقاع منتظم، يحاول كبح غريزة العنف التي استوطنت روحه لسنوات. تدخلت إينار، محاولة تلطيف الأجواء، لكن كلماتها كانت كحبات رمل في وجه إعصار. تقدم ثورغيل خطوة، محدثاً خساً مكتوماً في الوحل تحت ثقله. صرخ ثورغيل: ''أيها الصبي، سأكسر عظامك فقط لأرى إن كان العقل يسكنها''. اندفع ثورغيل بقوة جبل، محركاً فأسه في قوس قاتل. انحنى ثورفين بمرونة مفاجئة، ملامساً بيده الأرض، ثم انطلق كالسهم من تحت ضربة المحارب. لم يرفع يده للهجوم، بل استغل زخم حركة ثورغيل ليوجه دفعة دقيقة في مركز توازنه. تعثر العملاق، واهتز جسده الضخم قبل أن يستعيد توازنه بصعوبة، وقد تعالت صرخات المحاربين المذهولين من حولهما. مسح ثورغيل العرق عن جبهته، ونظر إلى ثورفين نظرة خلت من الاستخفاف وحلت محلها حيرة مشوبة بغضب مكتوم. قال ثورفين بصوت هادئ، محطم، لا يخلو من صدى الندم: ''لا أحتاج لقتلك، ولا أبحث عن المجد في جثتك. الطريق أمامي، ولن أسمح لأمثالك بقطعه''. كان الصمت سيد الموقف، والتوتر يتجلى في تشنج عضلات الفك لدى الرجال الذين أحاطوا بهما. لم تكن الكلمات هي ما حسم الأمر، بل تلك القدرة الغريبة لثورفين على تفادي الموت دون أن يمنحه، تاركاً خصومه في حالة من الفراغ الذهني. انصرف ثورفين نحو وجهته، تاركاً ثورغيل متسمراً في مكانه، يحدق في يديه اللتين فشلتا في إنهاء الخصم، بينما كان طعم الهزيمة المعنوية يغمر المكان ببرودة تفوق برد الشتاء.', '', 153, '2026-07-15 15:18:05.06', '2026-07-15 15:18:05.06');
INSERT INTO public.chapters VALUES ('d17fbef2-c30d-4e81-96b1-dd476234ff9c', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 155: صدع في جدار العزلة', '— --------------------------------------- ارتطم ثورفين بباب الغرفة الخشبي، ليجد نفسه وجهاً لوجه مع ''هالدور''. كان الأخير يمسح نصل سيفه بقطعة قماش خشنة، نظراته ثقيلة كحجر الصوان. لم يكد ثورفين يفتح فمه حتى قاطعه هالدور بصوت أجش ينم عن سنوات من قسوة البحار: ''هل تعتقد أنك ستمضي في خطتك بهذه البساطة؟ ''. تجاهل ثورفين نبرة التهديد، وتجاوزه بخطوات واثقة صوب ''ايفار'' الذي كان يقف بمركز الغرفة، يطوق ذراعيه حول صدره بعناد طفولي. التفت ايفار، وبرقت عيناه بوميض غاضب. ''لن تسمح لهم بالدخول، ثورفين. هؤلاء ليسوا جيراناً، إنهم ذئاب في جلود بشر''. توقف ثورفين، وشعر بانقباض عضلي في فكه. قال بنبرة مقتضبة، صلبة كالمعدن: ''لا أريد قتالهم. الأرض تتسع لنا جميعاً، والتبادل التجاري خير من نزيف الدماء''. ضحك ايفار ضحكة متهكمة، وانحنى نحو ثورفين حتى تقاربت أنفاسهما. ''التبادل؟ أنت تتحدث كمن يبيع نفسه في سوق العبيد. نحن هنا لنبني وطناً، لا لنكون ذيولاً لغرباء''. ساد صمت ثقيل، لم يقطعه سوى طنين ذبابة تحوم فوق طاولة الطعام الخشبية. أدرك ثورفين أن الفجوة بينهما قد اتسعت لتصبح هاوية. لم يكن الصراع حول الأرض أو الموارد، بل حول جوهر وجودهم في هذه الأرض الجديدة. زفر ثورفين بحدة، واتجه نحو النافذة المطلة على المخيم. في الخارج، كانت الحركة دؤوبة، لكن الخوف كان ينهش وجوه الرجال. التفت ثورفين ببطء، وعيناه ثابتتان على ايفار: ''إن استمررنا بهذا الفكر، سنموت قبل أن تبتلعنا الشتاءات القادمة''. لم يرد ايفار، بل اكتفى بإدارة ظهره، تاركاً ثورفين في مواجهة يقينه الخاص. كان الشق قد حدث، والصدع في جدار الرفقة لم يعد بالإمكان ردمه بالكلمات، بل بالقرارات التي سيفرضها غدٌ أكثر قسوة.', '', 154, '2026-07-15 15:18:05.249', '2026-07-15 15:18:05.249');
INSERT INTO public.chapters VALUES ('dcf908a1-5079-414f-92f2-e34324c6922e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 156: صدى الغرباء في فينيكلاند', '— --------------------------------------- توقف ثورفين عن التجديف، فارتطم قاع القارب الخشبي بالرمال الضحلة لصوت مكتوم. لم تكن الضفاف تشبه أي أرض وطئتها قدماه من قبل؛ غابات كثيفة تمتد كبساط أخضر لا ينتهي، وهواء مشبع برطوبة الأرض البكر. التفت إينار نحوه، كانت عيناه تتسعان ببطء وهو يمسح الأفق، أنفاسه متسارعة، وصدره يعلو ويهبط مع كل زفرة من الترقب. قال إينار بصوت مبحوح: «هل هذه هي؟ هل هذه الأرض التي لا سادة فيها ولا عبيد؟» لم يجد ثورفين إجابة فورية، بل انحنى ليلمس بيده رمال الشاطئ، كانت دافئة، خشنة، وتحمل في طياتها صمتاً مريباً. كانت تلك أولى خطواتهم نحو أرض الاحتمالات. في تلك الأثناء، كان ليف إريكسون يقف عند مقدمة القارب، يراقب الغابة بعينين خبيرتين في تضاريس البحار. لم يكن ثورفين يشعر بالانتصار؛ بل كان يشعر بوطأة المسؤولية الثقيلة التي تستقر على كتفيه كجبل من صخر. تحرك الرجال نحو الداخل، أقدامهم تغوص في أوراق الشجر المتساقطة، كانت الأشجار شاهقة لدرجة أنها تحجب وهج الشمس، وتخلق ممراً طبيعياً من الظلال. وبينما كان الفريق يتوغل، توقف ثورفين فجأة، ملقياً بجسده خلف جذع شجرة ضخم. تجمد الجميع في أماكنهم، وتلاشى صوت أقدامهم على الأرض. همس ثورفين دون أن يلتفت: «توقفوا. هناك حركة.» لم تكن حركة حيوان، بل كانت وتيرة خطوات بشرية غير منتظمة، شيئاً غريباً لا يشبه مسيرة الجنود الذين ألفوا القتال. خرج من بين الأشجار رجل غريب الهيئة، يرتدي جلوداً لم يألفها ثورفين، ملامحه حادة وعيناه تعكسان حذراً بدائياً. لم يرفع أي منهما سلاحه؛ فالصمت كان هو اللغة الوحيدة المتاحة في تلك اللحظة الحرجة. نظر ثورفين إلى الغريب، كان يرى في عينيه انعكاساً لنفس التساؤل: هل نحن أمام غزاة أم أمام بشر ضائعين في هذا العالم الواسع؟ ألقى ثورفين سيفه جانباً، وهي الحركة التي جعلت إينار يشد قبضته على مقبض فأسه بتوتر، لكن ثورفين ظل ثابتاً، يده مفتوحة، ووجهه خالٍ من أي تعبير عدائي. كانت تلك اللحظة الفاصلة؛ حيث تنتهي خريطة العالم المعروف وتبدأ قصة جديدة كلياً، قصة قد تكتب بالدماء أو بالسلام، ولم يكن ثورفين يعلم بعد أي الطريقين سيختار.', '', 155, '2026-07-15 15:18:05.422', '2026-07-15 15:18:05.422');
INSERT INTO public.chapters VALUES ('dbcf483c-ce60-4cc1-9dbc-ce7fd91dc111', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 157: صدى الغرباء', '— --------------------------------------- انتصبت الخيام فوق الأديم القاسي لأرض فينلاند، وتراصت كما لو كانت ترفض الانصياع لقسوة الطبيعة. كان ثورفين يراقب تحركات الناس، عيناه تلاحقان غودريد وهي تجتهد في ترتيب المؤن، بينما كان صمت المكان يثقله بشعور غامض من الترقب. قاطع هذا الهدوء وصول ''إيفار''، الذي لم يترك لغة الجسد لتفسر ضيقه، بل اندفع صوته حاداً ومتهكماً: ''ألا تزال مصراً على نهجك هذا يا ثورفين؟ نحن هنا للبقاء، لا لنكون ضيوفاً على قبائل لا نعرف عنها سوى القتل''. ثورفين لم يلتفت إليه فوراً، بل استمر في مراقبة الأفق، ثم قال بنبرة مقتضبة: ''سأقابلهم. لا سلاح، لا غدر''. ضحك إيفار بمرارة، فصوت احتكاك نصل سيفه بغمده كان أصدق من أي جملة نطق بها، ثم أضاف: ''أنت تحلم بسلام لن يمنحك إياه هؤلاء المتوحشون. إن لم تقتلهم، سيقتلوننا''. تقدم ثورفين خطوة، فبرزت ملامحه قاسيةً، وانقبضت عضلات فكه بينما قال بصوت منخفض: ''لا حاجة للقتل لكي نعيش''. خلفهما، كانت نظرات هيلد تراقب المشهد دون حراك، أصابعها تتحسس طرف قوسها المعلق بكتفها، ملامحها وجهٌ من جليد لا يكشف شيئاً عن صراعها. تحرك ثورفين باتجاه الحدود الفاصلة حيث الغابة الكثيفة تخفي وراءها المجهول. لم تكن المسافة بعيدة، لكنها بدت كفجوة بين عالمين. توقف ثورفين حين سمع تكسر أغصان يابسة تحت أقدام لا تنتمي للمستوطنين. برزت من بين الظلال أشكال غريبة، وجوه ملطخة بألوان الحرب، وأعين تترصد بحذر لا يقل عن حذر الذئاب. توقف أفراد القبيلة أمامه، لم تكن هناك كلمات مشتركة، فقط لغة العيون التي تقيم الخطر. انحنى ثورفين قليلاً، وبسط كفيه ليظهر خلوهما من الحديد، وتجنب بصرهم بشكل مباشر، محاولاً كسر حاجز العداء المتجذر في نظراتهم. لم يأتِ الرد فوراً، بل ساد صمت ثقيل لم يقطعه سوى خفقان قلب ثورفين الذي اصطدم بضلوعه، وهو يدرك أن خطوة واحدة خاطئة قد تنهي حلمه قبل أن يبدأ. كان الهواء يضج بتوتر مكتوم، والقبيلة تنتظر، كأنها تختبر صدق هذا الغريب الذي تجرأ على الوقوف أمامهم عارياً من قوته.', '', 156, '2026-07-15 15:18:05.658', '2026-07-15 15:18:05.658');
INSERT INTO public.chapters VALUES ('d9db326c-e601-4853-925e-e2a606e83b9b', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 158: خلف أسوار العزلة', '— --------------------------------------- توقف إينار عن الحفر فجأة، وترك مقبض المسحاة يرتطم بالأرضية الطينية بقسوة. رفع رأسه نحو ثورفين الذي كان يحدق في الأفق الشمالي بصمت مطبق، وكأن ثمة صوتاً غريباً يتسلل من بين صمت السهول. قال إينار بصوت متهدج يملؤه القلق: هل تسمع ذلك؟ لم يعد هناك ضجيج الطيور، ولا حتى حفيف الأعشاب. ثورفين لم يلتفت، بل ضاقت عيناه وبدت عروق جبهته بارزة تحت حدة الضوء. لم يجب بشيء، لكنه تحرك بخطوات سريعة نحو حافة الحقل حيث استقرت أدوات العمل. اقترب هيلد، التي كانت تراقب المشهد من بعيد، ويداها لا تزالان قريبتين من القوس المعلق على كتفها. قالت بصوت بارد وجاف: الغرباء لا يأتون بسلام إلى هنا، خاصة حين يقطعون طريق البحر دون نية للتجارة. التفت ثورفين أخيراً، وقد تحول وهج عينيه إلى بريق صلب، وقال بنبرة مقتضبة: اتركوا العمل الآن. اجمعوا الماشية وأدخلوها إلى الحظائر المحصنة. لم يكن في صوته خوف، بل كان هناك إدراك حاد لواقع بدأ يتشكل أمام أعينهم. في الأفق البعيد، بدأت أشرعة مخضبة باللون الداكن تلوح فوق خط المياه، محطمة هدوء الصباح الذي اعتادوا عليه. نظر إينار إلى يديه الملطختين بالطين، ثم مسحهما بعنف في ثيابه، متسائلاً بنبرة مشحونة بالاستنكار: هل انتهى كل شيء؟ هل عادت تلك الأيام لتطاردنا هنا أيضاً؟ ثورفين لم يمنحه وقتاً للرثاء؛ فقد دفع به نحو الداخل بينما كان يراقب اقتراب السفن المتسارع. كانت وتيرة الحركة تزداد جنوناً، والناس من حولهم بدأوا يدركون حجم الخطر المحدق. دخل ثورفين إلى الكوخ وأمسك بحزامه، ولم تكن حركاته توحي بالاندفاع غير المحسوب، بل بتركيز حيواني متيقظ. عندما خرج، كانت السفن قد اقتربت كفاية لتكشف عن ملامح الرجال الواقفين على ظهورها، وجوه كاسية بالندوب، وأيدٍ لا تفارق مقابض السيوف. قال ثورفين لنفسه بصوت خافت لم يسمعه غيره: لا أريد قتالاً، لكنني لن أسمح للمكان أن يسلب منا مرة أخرى. كان الصمت قد خيم تماماً، باستثناء صوت ارتطام القوارب بالرمال، وهو صوت أعلن بداية نهاية فصل من الهدوء القسري.', '', 157, '2026-07-15 15:18:05.876', '2026-07-15 15:18:05.876');
INSERT INTO public.chapters VALUES ('017d7a19-692a-45ee-998e-dd4fcdf754bc', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 159: صدى الغرباء في فينيكلاند', '— --------------------------------------- توقف ثورفين عن الحركة. لم تكن الغابة صامتة، بل كانت تعج بضجيج الحياة الفطرية الذي اعتاد عليه في الأشهر الماضية، لكن صوتاً بشرياً غريباً اخترق هذا الهدوء. التفت بحدة نحو الأشجار الملتفة، قبضت يده على مقبض سكينه بآلية عصبية مكتسبة من سنوات القتل، لكنه لم يسحبها. بضع خطوات، وظهر الغريب. رجل ملتحٍ، ملامحه توحي بإنهاك طويل، يرتدي ملابس لا تنتمي لنسيج الفايكنج الذي يعرفه. وقف الرجل متسمراً، وعيناه الزرقاوان تترقبان بحذر، كحيوان محاصر يرى مفترساً أمامه. نظر ثورفين إلى جرح الرجل الغائر في ساقه، والدم الذي يلوث العشب الأخضر النضج. لم يقل ثورفين شيئاً؛ فالكلمات لا تغني عن لغة الجسد. اقترب خطوة واحدة، فارتد الغريب إلى الخلف، مستنداً بظهره إلى جذع شجرة ضخم. بادر ثورفين بخفض سلاحه، وفتح كفيه ليظهر فراغ قبضة يده. تنفس الرجل بحدة، صدره يعلو ويهبط بتسارع. استدار ثورفين قليلاً مشيراً نحو معسكره، ثم عاد بنظره إلى الغريب الذي كان يرمقه بشك لم يختفِ من نظراته. لم تكن هذه أرضاً يتوقع فيها وجود غرباء، والتوتر في الهواء كان ملموساً، ثقيلاً كغيمة عاصفة. عندما حاول الغريب الوقوف، انهار ثقله على ساقه المصابة. تقدم ثورفين هذه المرة بسرعة مدروسة، أمسك بذراع الرجل ورفعها فوق كتفه، محاولاً موازنته. ثقل الغريب كان يضغط على عضلات ثورفين، لكنه لم يترنح. كانت خطواتهما ثقيلة ومتعثرة عبر الأغصان المتشابكة. خلفهما، بدأت الشمس تميل نحو المغيب، لتصبغ الأشجار بظلال طويلة مشوهة. لم يكن أي منهما يتحدث لغة الآخر، لكن صمت ثورفين كان يحمل وعداً غير منطوق، بينما كان الغريب يراقب كل حركة يقوم بها ثورفين، باحثاً عن أي إشارة لغدر محتمل. حين وصلا إلى أطراف المعسكر، توقف الجميع. كانت نظرات إينار هي الأولى التي اصطدمت بهما، تلتها نظرات بقية المستوطنين. لم تكن دهشة، بل حذراً فاتراً. وضع ثورفين الرجل على الأرض ببطء، وابتعد خطوتين، تاركاً المسافة كفاصل أمان. كان الغريب يرتجف، ليس من البرد، بل من حالة الترقب لما سيؤول إليه مصيره في هذا المكان الموحش الذي لم يكن يعرف عنه شيئاً.', '', 158, '2026-07-15 15:18:06.067', '2026-07-15 15:18:06.067');
INSERT INTO public.chapters VALUES ('9ceafdde-b853-4aa8-b94b-c9c4978d48ef', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 160: أصداءُ الرصاصِ في أرضِ الغرباء', '— --------------------------------------- انتصبت خيمةُ هيلد في قلب المعسكر، تتراقص ظلال القناديل على جدرانها الجلدية بينما كانت هي تحدق في الأفق البعيد، حيث تلوح طلائع رجال آيفار وسط الضباب الرمادي. لم تكن الكلمات ضرورية، فثورفين الذي كان يجلس بالقرب منها، يراقب حركات أصابعها وهي تتحسس نصل خنجرها بتوتر مكتوم، أدرك أن اللحظة الحاسمة قد حانت. قال ثورفين بصوت أجش ونظرات مسمرة على الأرض: لن نرفع السيوف، مهما بلغت استفزازاتهم، علينا أن نحافظ على المسار الذي رسمناه. لم تجب هيلد، بل انقبضت عضلات فكها وهي تراقب وصول آيفار يترجل عن فرسه بوقاحة متعمدة، يجر خلفه ظلاً من الغطرسة والبحث عن صدام لا مفر منه. اقتحم آيفار الخيمة دون استئذان، وطأ أرضيتها الترابية بحذائه الثقيل، ورمق ثورفين بنظرة مشبعة بالازدراء، ثم نبس بصوت أجش يقطر سخرية: ما زلت تحلم بأرض الميعاد يا ثورفين؟ بينما الحقيقة هي أننا محاصرون وسط ذئاب جائعة، ودماؤنا هي الثمن الوحيد المتاح هنا. وقف ثورفين ببطء، لم تكن حركته مهددة، بل كانت ثابتة كالجبل، ورد ببرود: لا أعداء لي في هذا العالم، يا آيفار، ولا رغبة لي في صراع يسفك دماء الآخرين من أجل أوهام العظمة. ضحك آيفار ضحكة متهكمة ملأت أرجاء الخيمة، واقترب بضع خطوات حتى أصبحت أنفاسهما المتسارعة تتداخل في الهواء المشحون، ثم همس بتهديد مبطن: العظمة لا تُصنع بالسلام، بل بكسر عظام من يقفون في طريقنا. كان الصمت الذي أعقب كلماته ثقيلاً، كأن الزمن قد توقف بانتظار شرارة واحدة لتشعل الموقف. تحركت يد هيلد ببطء نحو قوسها المعلق، بينما كانت عيون ثورفين تراقب كل انقباضة في عضلات آيفار. لم يرتجف ثورفين، ولم يتراجع، بل ثبت بصره في عين آيفار مباشرة، محاولاً إيصال رسالة صامتة بأن منطق القوة قد انتهى عهده. غادر آيفار الخيمة مزمجراً، تاركاً خلفه رائحة الغبار والتوتر، بينما التفت ثورفين نحو هيلد التي خففت قبضتها أخيراً، قائلة بصوت منخفض ومتهدج: إنه لن يتركنا وشأننا يا ثورفين، النار التي يوقدها في قلبه ستلتهمنا جميعاً إن لم نتحرك. نظر ثورفين إلى السماء الملبدة بالغيوم، وأجاب بنبرة حازمة تخلو من التردد: سنمضي مهما كلف الأمر، فالحرية لا تُنال بالتضحية بغيرنا، بل بتضحيتنا نحن بما يربطنا بالعنف.', '', 159, '2026-07-15 15:18:06.242', '2026-07-15 15:18:06.242');
INSERT INTO public.chapters VALUES ('ad1211e4-8d51-4955-b7b1-25d1a42185c8', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 161: خلف أسوار التوقعات', '— --------------------------------------- تجاوزت خطوات ثورفين عتبة خيمة هيلد، حيث كان الهواء بالداخل يثقل بعبق الجلود المعالجة وعزلة رجل يراقب الأفق. كان هيلد يجلس في زاوية مظلمة، أصابعه تعبث بنصل سكين صغير، حركة رتيبة توحي بتوتر مكتوم. التفت هيلد ببطء، لم تكن هناك دهشة في عينيه، بل استقرار مقلق. سأل ثورفين بنبرة جافة لم تترك مجالاً للمراوغة: ما الذي يدفعك للعودة إلى هنا بعد كل ما جرى؟ وقف ثورفين جامداً، يداه مقبوضتان بجانب فخذيه، مفاصل أصابعه بارزة كدليل على صراع داخلي لم يهدأ. لم يرد بالكلمات المنمقة، بل بعبارة اقتطعت الصمت: أنا لا أبحث عن سلام زائف، بل عن مسار للنجاة. ضحك هيلد ضحكة قصيرة، خاوية من المرح، ثم نهض ببطء، مخلفاً وراءه صوتاً خشناً للأرضية الخشبية. اقترب هيلد من ثورفين، حتى تلاقت أنظارهما في مساحة لا تتسع لنفس إضافي. قال هيلد بصوت خافت ومشحون: الوعود التي قطعتها يا ثورفين ليست سوى أوهام تقتات عليها في ليلك. نظر ثورفين إلى الأسفل، ثم رفع رأسه بحدة، ملامحه متصلبة تحت ضغط الحقيقة التي يدركها الطرفان. لم يكن الوقت مناسباً للأعذار أو الاعتذارات، فالواقع الخارجي يزحف نحوهم بقسوة. أشار هيلد نحو مخرج الخيمة، حيث كانت أصوات الرجال وتجهيزات السفر تملأ الأرجاء، وقال بلهجة ساخرة: السفن جاهزة، والقدر لا ينتظر من يراجع أخطاءه. لم يجب ثورفين، بل استدار وخرج نحو ضوء النهار الذي لفحه ببرودته، تاركاً هيلد في خيمته. حين وصل إلى ساحة الميناء، كانت عيناه تمسحان الوجوه البائسة للمحاربين، مدركاً أن الفارق بين الحرب والسلام هو خيط رفيع يتمزق عند أول اختبار للولاء.', '', 160, '2026-07-15 15:18:06.479', '2026-07-15 15:18:06.479');
INSERT INTO public.chapters VALUES ('9c00f9fc-3ed0-465d-b13d-b5b174e83972', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 162: عقبات الطريق إلى فينلاند', '— --------------------------------------- توقفت العربة الخشبية الثقيلة فجأة حين غاصت عجلتها الأمامية في طين الطريق العميق، لتصدر أنيناً خشبياً حاداً تحت ثقل البضائع والمؤن. سحب ثورفين لجام الخيل بقوة، مبرزاً عروق ذراعيه المجهدتين من شدة الشد. التفت إينار خلفه، ماسحاً العرق عن جبينه بظهر يده المتسخة، ونظر إلى السماء الرمادية التي تلبدت بغيوم تنذر بمطر وشيك. قال إينار بصوت مبحوح من التعب: الطريق لا يرحم يا ثورفين، إذا استمرت الأمطار بهذه الكثافة، فلن نصل إلى وجهتنا قبل حلول الشتاء القارس. لم يرد ثورفين فوراً، بل نزل من العربة ووضع كتفه تحت الإطار العالق، دافعاً بكل ما أوتي من قوة. تشنجت عضلات ظهره وبرزت تحت قميصه الخشن. تنفس ثورفين بانتظام حاد، ثم قال دون أن يلتفت: استمر في الدفع، لا مجال للتراجع الآن. في هذه الأثناء، كان ليف إريكسون يقف على مسافة قصيرة يراقب المشهد بصمت، ممسكاً بيده خريطة قديمة مهترئة الأطراف. اقترب ليف من الشابين، وبدا على وجهه أثر السنين وتجارب البحار القاسية، وقال بنبرة هادئة خالية من التوتر: العواصف في هذه الأراضي ليست مجرد مطر، بل هي امتحان للنيات. هل تملكون ما يكفي من الوقود للروح قبل الوقود للرحلة؟ توقف إينار عن الدفع ووقف يلهث، ناظراً إلى ثورفين الذي استقام بظهره ونفض الطين عن ملابسه. كانت نظرات ثورفين ثابتة، لا تتردد، وكأن هدفه في الوصول إلى فينلاند ليس مجرد رحلة جغرافية، بل مساراً اختاره ليتجاوز ماضيه. أجابه ثورفين باقتضاب: سنمضي، ولو اضطررنا لحمل العربة على أكتافنا. نظر ليف إليه، وارتسمت على شفتيه ابتسامة غامضة، ثم أشار بيده نحو الأفق البعيد حيث تختفي تضاريس الطريق بين الغابات الكثيفة. واصلوا التقدم، كانت أصوات حوافر الخيول وهي تغوص في الوحل، وصوت احتكاك الخشب بالحجارة، هي الموسيقى الوحيدة التي تكسر صمت الغابة المطبق. لم يكن ثورفين يبحث عن الراحة، بل كان في صراع دائم مع الزمن، فكل خطوة يخطوها كانت تباعد بينه وبين الرجل الذي كانه يوماً، وتزيد من يقينه بأن الخلاص لا يكمن في سيف يستله، بل في أرض لم تطأها أقدام المحاربين من قبل.', '', 161, '2026-07-15 15:18:06.677', '2026-07-15 15:18:06.677');
INSERT INTO public.chapters VALUES ('90f79dcf-4589-4459-a7c1-29812374e338', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 163: صدى الغابة الباردة', '— --------------------------------------- توقفت حركة ثورفين فجأة. لم تكن الغابة صامتة، بل كان صمتها مثقلاً بوقع خطواتهم على الأرض المتجمدة. التفت نحو إينار، الذي كان يلهث بصوت مسموع، وعيناه الزرقاوان تلاحقان ظلاً يتحرك بين جذوع الأشجار العارية. اقترب ''هيلد'' بخطوات واثقة، قبضتها على نصلها الخشبي المحكم لم ترتجف، رغم حدة النظرات التي تبادلها مع الغرباء. قال ثورفين بصوت أجش، متجاوزاً عبارات المجاملة: ما الذي تريده يا سيد الغابة؟ لم تكن هناك إجابة فورية، بل انبعث من بين الشجيرات رجل ضخم، ملامحه محفورة بندوب الزمن والحروب القديمة. نظر الرجل إلى ثورفين نظرة فاحصة، وكأنه يزن ثقل الندم على كتفيه. لم يقل شيئاً، لكن يده التي استقرت على مقبض سيفه الصدئ كانت كافية لنقل الرسالة. استدار ثورفين قليلاً، ضغط بيده على ذراعه المصابة، وشعر بنبضات قلبه تتسارع، ليس خوفاً، بل استجابةً لغريزة القتال التي حاول وأدها طويلاً. تدخل إينار، متمسكاً بكتف ثورفين: نحن لسنا هنا للنزاع. لكن الرجل لم يكترث، وتقدم خطوة أخرى، تاركاً أثراً عميقاً في الوحل. توترت أعصاب هيلد، ومال جسدها إلى الخلف استعداداً للوثوب. في تلك اللحظة، لم تعد الغابة مجرد أشجار، بل أصبحت حلبة ضيقة يحاصرها الترقب. سأل الرجل بنبرة خشنة كأنها تخرج من قاع بئر: هل أتيت لتمحو آثارك أم لتضيف إليها؟ صمت ثورفين، وجفت شفتاه. لم يكن الرد بكلمات، بل بخطوة واثقة نحو الأمام، معلناً قبوله للمواجهة التي لا مفر منها. تلاشت المسافة، وتصلبت العضلات، وبدأت الرقصة المعهودة بين الموت والحياة.', '', 162, '2026-07-15 15:18:06.856', '2026-07-15 15:18:06.856');
INSERT INTO public.chapters VALUES ('34441170-02c4-44d0-b66d-508829d123bb', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 164: خلف أسوار التناقض', '— --------------------------------------- توقفت العربات عن الحراك في الساحة الفسيحة وسط ميكلاغارد. كان الغبار العالق في الهواء يكسو وجوه الجميع بطبقة رمادية شاحبة، بينما ظلت أعين ثورفين معلقة ببرج القصر العالي الذي يلوح في الأفق كشاهد على سطوة الإمبراطورية. لم يكن هذا الصمت المطبق الذي خيم على رفاقه نابعاً من الرهبة بقدر ما كان نتاجاً لتصادم التوقعات بالواقع المرير الذي يفرض نفسه هنا. اقترب إينار منه، مشى خطوات ثقيلة، ثم مسح العرق عن جبينه بظهر كفه، وقال بصوت خشن: ثورفين، هل تعتقد أنهم سيسمحون لنا حقاً بالدخول؟ هذه ليست أراضي الفايكنج، ولا هي الغابات الموحشة التي ألفناها. هنا القوانين مكتوبة على الحجر، والسيوف ليست لفض النزاعات، بل للزينة. لم يلتفت ثورفين، بل اكتفى بتركيز نظره على البوابة العملاقة. انقبضت عضلات فكه السفلي بينما كانت يداه ترتجفان برفق، ليس خوفاً، بل من فورة أفكار تتصارع في رأسه. كان يعلم أن مقابلة هالدور ليتجسد في هذا المكان تعني خوض معركة من نوع مختلف، معركة لا تراق فيها الدماء بل تتبدد فيها الطموحات. ألقى نظرة خاطفة على مرافقه، ثم تمتم بكلمات مقتضبة: القوة ليست في عبور البوابات، بل في النجاة من دهاء من يسكن خلفها. لا تتوقع منهم الترحيب. هذا المكان يبتلع الغرباء بابتسامة صفراء. في تلك اللحظة، ظهرت مجموعة من الحراس عند المدخل، دروعهم اللامعة تعكس أشعة الشمس ببريق يبعث على الضيق. لم يتحرك ثورفين، بل اتخذ وضعية الاستعداد، جسده متأهب كزنبرك مضغوط، بينما كانت نظراته تتبع حركة رماحهم التي لم تكن موجهة نحوه بعد، لكنها كانت تنبئ بوضوح أن الغريب هنا لا يُعامل كضيف، بل كعنصر خطر يجب تقييمه. تقدم القائد نحوهم بخطوات وئيدة، لم تكن هناك حدة في ملامحه، بل برود إداري مقيت. توقف القائد على مسافة خطوات، ونظر إليهم بوقار متكلف، ثم قال بنبرة جافة لا تحمل أي ود: لا مكان هنا لمرتزقة شماليين يحملون رائحة البحر والدم. ارجعوا من حيث أتيتم. لم يرد ثورفين بكلمة، بل أغمض عينيه للحظة، مستجمعاً كل ذرة من هدوئه، بينما تنهد إينار بحدة، ممسكاً بمقبض فأسه بوضوح كشف عن توتره البالغ. كان المشهد يختصر المسافة الشاسعة بين طموحاتهم وبين الواقع الصلد الذي يرفض الاعتراف بوجودهم.', '', 163, '2026-07-15 15:18:07.037', '2026-07-15 15:18:07.037');
INSERT INTO public.chapters VALUES ('57eabd97-e2c8-4773-a862-4dcd7a2e176c', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 165: رواسبُ النيرانِ وتساؤلاتُ الأفق', '— --------------------------------------- توقف ثورفين عن الحركة. كانت جثث الرجال المتناثرة كالحطب المهمل في ساحة القرية تملأ بصره، بينما ارتفعت سحابة دخانٍ كثيف من أكواخ ميتالين التي نالت منها ألسنة اللهب. لم يلتفت إلى إينار الذي كان يلهث بجانبه، بل ظلَّت عيناه معلقتين بـ فلاد -ذلك الرجل الضخم الذي أثقلت جسده الدروع وغطت ندبات الحروب وجهه-. اقترب فلاد بخطواتٍ ثقيلة، كان صوت احتكاك نصل سيفه بالتربة يمزق صمت المكان المريب. رفع فلاد نصله، وكانت زوايا فمه ترتسم بابتسامة قاسية وخالية من أي ذرة تعاطف. قال ثورفين بصوتٍ مبحوح، خرج من حنجرة جفت من شدة التوتر: أنتِ لا تملك حقَّ انتزاع حياتهم، الأرض هنا ليست ساحة لقراراتك الدموية. ضحك فلاد ضحكة خشنة، ارتجف لها صدره العريض، وأجاب باقتضاب: هؤلاء القرويون؟ إنهم لا شيء سوى عقبات أمام توسعنا، يا فتى. التفت ثورفين نحو إينار، كانت عضلات فكه منقبضة إلى أقصى حد، وبدا الصراع في عينيه صراعاً بين الرغبة في الفتك وبين عهدٍ قطعه على نفسه بترك لغة السيف. لم يتوسل ثورفين للرحمة، بل وقف شامخاً، يزن ثقل قراره بكل جوارحه. وسط هذا التوتر، لمعت في ذهنه ذكريات والده، لم تكن نصائح فلسفية، بل كانت تذكيراً صارماً بأن الطريق الذي اختاره هو طريقُ الوعورة. انقض فلاد فجأة، لكن ثورفين لم يترنح، بل انحنى بحركة خاطفة وسريعة، مخترقاً حيز الهجوم، ليضع يده على مقبض خنجره ثم يسحبها في اللحظة الأخيرة، مكتفياً بضربة قوية على ذراع فلاد أجبرته على إفلات سلاحه. ساد صمت مطبق، لم يقطعه سوى طقطقة الخشب المحترق. نظر فلاد إلى يده المرتجفة، ثم إلى عيني ثورفين اللتين كانتا تنظران إليه ببرودٍ قاتل لا يعرف التردد. ليس هناك عدو هنا، قال ثورفين، كلماته كانت جافة كصخر الجبال، لا أحتاج لقتلك كي أثبت أنك مخطئ. تراجع فلاد خطوة إلى الوراء، كانت كبرياؤه قد تلقت طعنة أعمق من نصله، بينما أدرك إينار أن ثورفين لم يعد ذاك الفتى الغاضب الذي عرفه، بل أصبح كياناً آخر، يحمل ثقلاً ينوء به الرجال العاديون.', '', 164, '2026-07-15 15:18:07.221', '2026-07-15 15:18:07.221');
INSERT INTO public.chapters VALUES ('f9c3fcaa-6811-40af-8ecf-480f0ded61b6', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 166: أصداءُ الفجرِ في فينلاند', '— --------------------------------------- انتصبت خيامُ المستوطنة على الحافة الصخرية، حيث يعانق الضبابُ الفجرَ البارد. وقف ثورفين وسط الساحة، يراقبُ ملامح الغضب التي ترتسم على وجوه الرجال. لم تكن الكلمات حاضرة، بل كان صوتُ تصادمِ الحجارة ببعضها ونصلِ سيفٍ يُشحذ هو ما يملأ الصمت. التفت ''هيلد'' نحو ثورفين، وكانت قبضتها على قوسها تزداد ضيقاً، مفاصل أصابعها تبرز بيضاء تحت الجلد المشدود. قالت بنبرة حادة خالية من أي لين: «أنت تحلم يا ثورفين. تعتقد أن السلم يمكن أن يُشترى بالنوايا الحسنة؟ هؤلاء القوم في الجوار لن يتوقفوا. القوة هي اللغة الوحيدة التي يفهمونها». لم يجبها ثورفين فوراً؛ حدق في الأفق حيث تبدأ الغابات العذراء، ثم مسح بيده على وجهه الذي خطت عليه السنون ندوباً لا تغيب. نطق بصوتٍ خفيض، مثقلٍ بتعبِ الرحلة الطويلة: «إنهم يخافوننا يا هيلد. الخوف هو الذي يولد العدوان. إذا أظهرنا لهم أننا لسنا هنا لننتزع أرضهم، ربما… ربما نكسر حلقة الدم». تدخل ''إينار'' في الحوار، وخطواته الثقيلة تعلن عن قلقه، إذ قال وهو يفرك لحيته الخشنة: «الرجال هنا ليسوا فلاسفة. إنهم فلاحون خسروا كل شيء، ويبحثون عن الأمان. إذا طال الانتظار، سيبدأون بالنظر إلى سيوفهم كحلٍ وحيد». وبينما كانت الرياح تعبث بملابسهم، توقف الزمن للحظة أمام نظرة ثورفين الثابتة. لم يعد ذلك الفتى المندفع الذي يسعى للثأر، بل صار رجلاً يزنُ أفعاله بميزان الندم. ساد صمتٌ خانق، قطعه صوتُ خطواتٍ قادمة من بعيد؛ كان ''أولف'' يتقدم نحوهم، ملامحه لا تنبئ بخير. توقف أمام ثورفين، وألقى نظرة فاحصة على المحيط قبل أن يهمس: «القبائل المحلية بدأت تتجمع. لا يبدو أنهم ينوون التفاوض. الخيار الآن ليس بين السلم والحرب، بل بين الاستعداد للموت أو النجاة». قبض ثورفين على كفه، وشعر ببرودةِ الفولاذ في جيب حزامه. لم يرتجف، بل استقامت قامته كمن قرر مواجهة قدرٍ كان يظنه قد ولى. نظر إلى السماء الرمادية ثم قال: «سنذهب إليهم. بلا سلاح. إنها مخاطرة، لكنني لن أسمح لهذا المكان أن يتحول إلى مقبرة أخرى».', '', 165, '2026-07-15 15:18:07.429', '2026-07-15 15:18:07.429');
INSERT INTO public.chapters VALUES ('7f83ed1d-bb61-4957-a027-57616ab6266d', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 167: أصداءُ أرضِ النزاع', '— --------------------------------------- انغرس نصل السيف في التربة القاسية بصوتٍ مكتوم، تاركاً شقاً غائراً في الأرض التي لم تسترح قط من وطأة أقدام الغزاة. نظر ثورفين إلى الأفق، حيث تختلط زرقة البحر بضباب الصباح الرمادي. لم تكن في عينيه تلك الرغبة العارمة في الانتقام التي سكنته لسنوات، بل بريقٌ حذر يراقب تحركات حراس ''هالدور''. اقترب إينار بخطوات متباطئة، مسحت يده وجهه المجهد، وقال بصوتٍ منخفض لم يقطعه سوى أنين الريح الخفيف: ''إنهم يراقبوننا، ثورفين. الوجود هنا يشبه المشي على طبقة جليدٍ رقيقة، خطوة واحدة خاطئة وستبتلعنا المياه''. لم يلتفت ثورفين، بل شد قبضته على مقبض سيفه الملقى أرضاً، ثم زفر بحدة: ''لا يهم من يراقب، المهم ما سنفعله حين نواجههم. لا أريد قتالاً، لكنني لن أقف مكتوف اليدين إذا حاولوا كسر العهد''. في تلك اللحظة، ظهرت ملامح التوتر على وجوه العمال حولهم؛ فالتجمعات الصغيرة تلاشت، والأعين أصبحت تتفادى النظر المباشر. لم يعد المكان ورشة عمل، بل ساحة تترقب انفجاراً وشيكاً. اقترب أحدهم، رجلٌ ضخم البنية يحمل ندبة غائرة تمتد من حاجبه حتى فكه، وبدأ يلقي بكلمات مقتضبة تتسم بالاستعلاء. تجاهله ثورفين في البداية، لكن نبرة الرجل المتغطرسة التي بدأت تمس كرامة الرفاق جعلت كتفي ثورفين يتصلبان. التفت ثورفين ببطء، لم تكن حركته مهددة، بل كانت هادئة بشكلٍ أثار ارتياب الرجل الضخم. قال ثورفين بصوتٍ جاف ومباشر: ''لقد جئنا هنا لنبني، لا لنستعرض قوتنا في ساحة فارغة. توقف عن هذا الضجيج، واذهب لتنفيذ عملك''. ساد صمتٌ مطبق، وتوقف الجميع عن الحركة. كان الترقب سيد الموقف، والتوتر يتصاعد في الهواء كخيطٍ مشدودٍ إلى أقصى حد قبل التمزق. لم يعد الأمر مجرد خلاف على موارد أو أرض، بل صداماً بين إرادتين؛ إحداهما تمثل عنف الماضي، والأخرى تحاول شق طريقٍ لم يختبره أحد من قبل. وبينما كانت نظراتهم تتشابك، أدرك الجميع أن لحظة الفصل قد اقتربت، وأن السلام الذي ينشده ثورفين ليس سوى حلمٍ يزداد ثقلاً مع كل قطرة عرق تسقط على هذه الأرض الغريبة.', '', 166, '2026-07-15 15:18:07.6', '2026-07-15 15:18:07.6');
INSERT INTO public.chapters VALUES ('01f6e67b-9773-4285-8d39-d6565b3bfd1c', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 168: صدع في جدار العزلة', '— --------------------------------------- توقف ثورفين عند حافة التل، كانت عيناه ترصدان تحركات القافلة المبتعدة نحو الأفق. لم تكن المسافة شاسعة، لكن ثقل الحقيقة كان يباعد بينه وبينهم أكثر مما تفعل الأميال. بجانبه، وقف غوار، يمسح بيده على مقبض سيفه، صمته أبلغ من أي احتجاج. قال ثورفين بصوت منخفض، حاد كشفرة باردة: لا نملك ترف التردد الآن. غوار نظر إليه، اتسعت عيناه قليلاً قبل أن يزفر الهواء بقوة عبر أنفه: هل تعتقد حقاً أنهم سيستمعون؟ الناس هنا لا يفهمون لغة السلام التي تنادي بها يا ثورفين، إنهم يقتاتون على الفوضى. لم يلتفت ثورفين إليه، ظل بصره معلقاً بتلك النقطة التي تلاشت فيها القافلة. لم يجب. بدلاً من ذلك، مشى بخطوات واثقة نحو مخيمهم الصغير، حيث كانت النيران تخبو وتترك خلفها رماداً متوهجاً. هناك، التقى بنظرات إينار، الذي كان مشغولاً بتفقد المتاع. تساءل إينار دون أن يرفع رأسه: هل نحن بصدد الرحيل؟ أجاب ثورفين وهو يضع يده على كتفه، قبضته قوية ومطمئنة: نحن بصدد العثور على طريق لا يضطرنا لسل السيوف. ابتسم إينار بسخرية مريرة، متمتماً: قد يكون هذا أطول طريق سلكناه في حياتنا. في تلك الأثناء، كان الحراس يتبادلون همسات قلقة حول التغير في سلوك ثورفين. لم تعد ملامحه تحمل ذاك الضجيج العنيف الذي سكنها لسنوات، بل استبدله بتركيز هادئ يربك من حوله. تساءل أحدهم، وهو يبصق على الأرض: أين اختفى المحارب الذي نعرفه؟ أين ذهبت تلك النظرة التي لا ترى إلا الدماء؟ كان ثورفين يسمعهم، لكنه لم يلتفت. في أعماقه، كان الصراع يغلي، لا كمعركة ضد أعداء خارجيين، بل كحرب استنزاف ضد نزعة قديمة تأبى الرحيل. عندما خيم الليل، استلقى ثورفين على ظهره، ناظراً إلى النجوم الباردة. تذكر كلمات والده ثورس، ليس كصدى بعيد، بل كحقيقة مادية ملموسة: لا يوجد عدو، ليس لأحد عدو. دفع ثورفين ذلك الفكر بعيداً، ليس لأنه لا يؤمن به، بل لأن ثقله كان يكاد يمزق صدره. نهض فجأة، سار نحو وسط المعسكر حيث تراقصت بقايا النيران. التفت إليه غوار وقال: أنت لا تنام. رد ثورفين وهو يحدق في الجمر: النوم ترف لمن تصالحوا مع ماضيهم، أما أنا فما زلت أبحث عن ثمن السلام الذي دفعته. لم يكن هناك المزيد ليقال، فالليل ابتلع أصواتهم، ولم يبقَ إلا صوت الريح الخافت يمر عبر أشجار الغابة المظلمة، شاهداً على تحول رجل أقسم ألا يريق دماً بعد اليوم، في عالم لا يعرف إلا لغة القوة.', '', 167, '2026-07-15 15:18:07.776', '2026-07-15 15:18:07.776');
INSERT INTO public.chapters VALUES ('030ac079-bc20-4acd-bfcc-e1946fa186df', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 169: عزلة الملح والوعود', '— --------------------------------------- تلاطمت الأمواج بجوانب السفينة الخشبية كأنها قبضة عملاق يطرق باباً موصداً. وقف ثورفين على سطح السفينة، عيناه مثبتتان على الأفق حيث يمتزج رمادي البحر برمادي السماء. لم يكن التعب بادياً في جسده، بل في حدة نظراته التي فحصت كل لوح من ألواح السفينة. بجانبه، كان إينار يشد الحبال بقوة، عروق ساعديه بارزة تحت ضغط الريح. التفت ثورفين نحوه قائلاً بنبرة جافة: تأكد من تثبيت المؤن في جوف السفينة، العاصفة التي تلوح هناك لن ترحم ما هو غير ثابت. لم ينتظر رداً، بل تحرك نحو الدفة، حركاته اقتصادية، دقيقة، خالية من أي استعراض. كانت المسافة نحو فينلاند لا تزال فكرة هشة، أشبه بخيط رفعه القدر أمام عينيه ليجره بعيداً عن صخب النزاعات والسيوف الصدئة. في الممر الضيق بين الأمتعة، جلس ليف إريكسون يحدق في خريطة جلدية قديمة، أصابعه المتغضنة تلمس الخطوط التي رسمتها أجيال من الملاحين. رفع ليف رأسه، وقال بصوت أجش: يا ثورفين، البحر لا يمنح وعوده لمن يطاردون الأشباح، بل لمن يملكون الصبر لانتظار انحسار الموج. نظر ثورفين إلى كفيه، ندوب قديمة تقطع جلده كأنها خريطة لحروب مضت. لم يجب، بل اكتفى بإيماءة خفيفة، ثم عاد لتأمل المياه. في تلك اللحظة، لم تكن السفينة مجرد خشب ومسامير، بل كانت خلية صمت وسط ضجيج المحيط. اقترب إينار منه، ومسح العرق عن جبينه بظهر يده وقال: أتشعر بالخوف؟ هز ثورفين رأسه نفياً، لا ليتظاهر بالشجاعة، بل لأن الخوف كان رفاهية لا يملكها من قرر أن يضع خلفه تاريخاً من الدماء. أجابه بصوت خافت بالكاد تسمعه الريح: الخوف ينمو حيث توجد بدائل أخرى. أما نحن، فقد أحرقنا كل البدائل خلفنا. وبينما كانت السفينة تشق عباب الماء، اتسعت حدقتا ثورفين وهو يراقب قطيعاً من الحيتان يمر بمحاذاة السفينة، ذيولها الضخمة تضرب الماء بإيقاع هادئ، بعيداً عن صخب البشر وعبثية القتال. كانت لحظة صفاء غير متوقعة، ثانية واحدة توقفت فيها أنفاس التاريخ، تاركةً ثورفين أمام الحقيقة الوحيدة التي لم يجد لها وصفاً: رحلة بلا أعداء، وبحر يتسع للجميع.', '', 168, '2026-07-15 15:18:08.009', '2026-07-15 15:18:08.009');
INSERT INTO public.chapters VALUES ('64eb52c9-b0ae-452a-93e7-79540f7857cc', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 170: خلف أسوار التوقعات', '— --------------------------------------- تصاعدت حدة النقاش داخل الغرفة الضيقة، حيث امتزجت أصوات المحتجين بوقع أقدامهم الثقيلة على الأرضية الخشبية. وقف ثورفين وسط الجمع، يراقب تشنج عضلات الفك لدى الرجال الذين ما زالوا يجدون في العنف لغة وحيدة للتفاهم. التفت إينار نحوه، كانت ملامحه تنم عن قلق مكتوم، وصوته يخرج مخنوقاً كأنه يخشى تبعات ما يقترحونه. تحرك الرجال بحدة، ملوحين بأسلحتهم كأنهم يستحضرون ذكريات حروب غابرة، بينما ظلت نظرات ثورفين معلقة ببرود على الأرض، يحاول قياس المسافة بين السلام الذي ينشده وبين جموح الغريزة الذي يحيط به. ساد صمت مفاجئ حين رفع أحدهم صوته بحدة، متهماً إياهم بالضعف، فجحظت عينا إينار واتسعت حدقتاه، لكن ثورفين لم يتحرك؛ اكتفى بشد قبضتيه حتى ابيضت مفاصله. لم تكن الكلمات المتبادلة مجرد نقاش، بل كانت اصطداماً بين عالمين؛ عالمٍ لم يغادر ساحات المعارك، وآخر يحاول بصعوبة بالغة أن يرسم حدوداً لعالم جديد لا تسكنه السيوف. انحنى ثورفين قليلاً إلى الأمام، متجاوزاً نظرات الاستنكار المحيطة به، وبدأ في تفنيد الحجج بصوتٍ منخفض ولكن بكلمات حادة كالنصل، يرفض فيها الانجرار إلى الصراع الذي سيؤدي لا محالة إلى دمار ما بنوه بجهد جهيد. استمر الجدل حتى شعرت ببرودة الهواء تتسرب من الشقوق، بينما كان ثورفين يدرك أن إقناع هؤلاء الرجال المجبولين على الولاء للقوة لا يقل خطورة عن مواجهتهم في الميدان. غادر الغرفة بخطوات وئيدة، تاركاً خلفه دوياً من الاعتراضات التي بدأت تتلاشى في صمت الممر الطويل، عازماً على المضي في مساره مهما كلفه الأمر من ثمن.', '', 169, '2026-07-15 15:18:08.189', '2026-07-15 15:18:08.189');
INSERT INTO public.chapters VALUES ('3482f262-355b-409a-8c2e-62e6bef5a897', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 171: صدى الصمت في أراضي فينلاند', '— --------------------------------------- توقف ثورفين عن الحركة. كانت أذناه تلتقطان صوتاً غريباً يشق سكون الغابة في فيني لاند؛ صوت احتكاك معدن على خشب، خافت لكنه مشحون بالتوجس. التفت إلى إينار الذي كان يضع فأسه جانباً، جحظت عينا إينار بوضوح حين التقت نظراتهما. لم تكن الصدفة هي ما قادهما لهذا المكان. اقترب ثورفين بخطوات وئيدة، تاركاً خلفه ثمار عمله في الحقل. كانت جثث الحراس الملقاة بالقرب من تخوم المستوطنة تحمل بصمة غدرٍ لا تخطئها عين خبير. سحب ثورفين خنجره، لا برغبة في القتال هذه المرة، بل بدافع الحماية. تسلل عبر الشجيرات الكثيفة حتى انكشفت له الساحة. لم يكن المهاجمون وحوشاً، بل كانوا بشراً يرتدون جلوداً خشنة، ملامحهم تفيض حقداً قديماً. وقف زعيمهم وسط الخراب، يمسح الدم عن سيفه ببرود تام. هتف ثورفين بصوت متحشرج ولكنه ثابت: لماذا؟ التفت الرجل، رسمت على وجهه ابتسامة باردة متهكمة، وقال بصوت أجش: أرضكم هذه… ليست لكم، لقد جئنا لاسترداد ما سلبتموه بأرواحكم. لم يرد ثورفين بوعظ، بل انقبضت كفه على مقبض خنجره حتى ابيضت مفاصل أصابعه. أدرك أن المسافة بين حلمه في بناء عالم بلا أسلحة وبين واقع الأرض التي يقف عليها قد تقلصت إلى حد التلاشي. لم يطلب الرحمة، ولم يعتذر. أشار إلى إينار بالانسحاب خلف الصخور بينما اتخذ هو وضعية قتالية جسدها متصلب وعيناه تمسحان الميدان بدقة جراح. كان يعلم أن دماء الغريب قد تسيل هنا، ليس لأنه يريد ذلك، بل لأن بقاء أهله بات مرتبطاً بضربة واحدة حاسمة. تنفس ثورفين بعمق، وانطلق كالسهم نحو المهاجم، تاركاً فلسفة السلام خلف ظهره، مدركاً أن الدفاع عن الحياة أحياناً يتطلب أن تتحول إلى قوة لا تُقهر.', '', 170, '2026-07-15 15:18:08.438', '2026-07-15 15:18:08.438');
INSERT INTO public.chapters VALUES ('72a7a94d-bdd8-4dd6-a294-e8beff84b551', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 172: أصداءُ مِيركاستان', '— --------------------------------------- توقف ثورفين عن التجديف، فارتطم مجذافه بحافة القارب محدثاً صوتاً خشبياً أجشاً شق صمت المياه الساكنة. أمامه، لم تكن الأرض التي وعد بها نفسه، بل كانت كتلة من الغموض والرهبة المتجسدة في سواحل ''ميركاستان''. سأل إينار بصوتٍ خافت، وقد جحظت عيناه وهو يتأمل تلك التضاريس القاسية: هل نحن حقاً في المكان الصحيح؟ لم يجب ثورفين فوراً؛ كانت عضلات رقبته متصلبة، وعيناه تمسحان الشاطئ بحثاً عن أي حركة بشرية، لكن الرياح لم تحمل سوى نعيق طائر بعيد. التفت ثورفين نحو الطاقم، كانت ملامح وجهه قاسية، كأنما نُحتت من صخر صلد، وقال بنبرة جافة لا تقبل التشكيك: سننزل هنا. كان ''غودريد'' تقف بجانبه، ممسكةً بطرف رداءها بقوة، أنفاسها منتظمة بصعوبة، وصدرها يعلو ويهبط تحت وطأة التوتر. لم يكن ثورفين يبحث عن الغنائم، ولا عن المجد، بل عن مساحة فارغة من دماء الماضي. ومع اقتراب القارب من اليابسة، قفز ثورفين في المياه الضحلة قبل أن يستقر الهيكل الخشبي تماماً، غاصت قدماه في الطين البارد، وشعر بوزن الأرض الجديدة تنتقل إلى جسده. استدار نحو أصحابه، بقعة صغيرة من الإصرار في وسط عالمٍ شاسع وموحش. لم يقل شيئاً عن الآمال أو الأحلام، فالكلمات عند ثورفين كانت ترفاً، لكن إيماءة رأسه نحو الغابة الكثيفة كانت أمراً لا يحتمل التأجيل. بدأوا في إفراغ المؤن، وكل حركة كانت محسوبة، كل صوت مكتوم؛ كانوا يعلمون أن الأرض في هذه الأصقاع لا ترحب بالغرباء بسهولة. بينما كان إينار يجر صندوقاً خشبياً ثقيلاً، انزلقت قدمه فتعثر، ليعلو صوت ارتطام الخشب بالطين. توقف الجميع، تحول الصمت إلى حائط مسموع. التفت ثورفين بسرعة، يده اليمنى تحوم قرب خصره، لكنه لم يجد عدواً، وجد فقط الأشجار العملاقة التي تحدق فيهم بظلالها. نظر إينار إليه، كانت قطرات العرق تفر من جبينه، فابتسم ثورفين ابتسامة باهتة لا تصل إلى عينيه المنهكتين، وقال بحدة: استمر في العمل، لا وقت للتعثر. كانت هذه هي البداية، بداية حياة لا تطلب من العالم شيئاً سوى أن يتركهم وشأنهم، وسط صمت الغابات التي لم تطأها قدمُ إنسانٍ من قبل.', '', 171, '2026-07-15 15:18:08.624', '2026-07-15 15:18:08.624');
INSERT INTO public.chapters VALUES ('9e472b8f-c57d-4c5b-a43b-2f1acab43242', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 173: صدع في جدار الوعود', '— --------------------------------------- انتصبت خيام المستعمرة في فينلاند تحت سماءٍ رمادية لا ترحم. لم تكن ثمة أعذار هذه المرة. ثورفين، الذي نذر حياته لنبذ العنف، كان يقف أمام حقيقة أن أحلامه بالسلام قد اصطدمت بجدار الواقع الخشن. كانت نظرات الرجال من حوله تتأرجح بين الارتياب والترقب. صعد ثورفين على منصة خشبية مرتفعة، عيناه كانتا باردتين، لا تعكسان أي دفء، بل تركيزاً حاداً يراقب حركة الجميع. قال بصوت مقتضب، خشن كالرمل: لن نسحب سيوفنا. ليس اليوم، ولا غداً. إذا كان الثمن هو الدماء، فقد دفعنا منه الكثير في الماضي ولا حاجة للمزيد. نظر إليه هيلد من بعيد، كانت يداها مستقرتين على قوسها، ملامح وجهها قاسية ومتحجرة. لم تكن تثق بكلماته تماماً، لكنها كانت تقر بصدق النوايا في عينيه. في تلك اللحظة، اقترب منه أحد المستوطنين، كان يرتجف، ليس من البرد، بل من الخوف الصرف، وهمس بصوت متقطع: إنهم قادمون، ثورفين. أعدادهم تزداد في الأفق. لم يلتفت ثورفين بسرعة، بل أخذ نفساً عميقاً، وانقبضت عضلات كتفيه بوضوح تحت رداء الفراء. التوتر كان يلف المكان كخيط مشدود على وشك الانقطاع. تذكر ثورفين كلمات والده عن الأرض، تلك التي لا تملك لسانًا لتدافع عن نفسها، بل نحن من نحميها، لكن أي حماية هذه التي تبدأ بالقتل؟ تحرك ثورفين نحو حافة المعسكر، حيث تبدأ الغابات الكثيفة. كان يعلم أن كل خطوة يخطوها هي اختبار لقناعته. التفت إلى رجاله وقال بلهجة آمرة تخلو من التردد: اتركوا الأسلحة حيث هي. سنقابلهم عُزلاً. ساد صمت مطبق، لم يقطعه سوى صوت تحطم غصن في الأدغال البعيدة. كان هذا هو الاختبار الأكبر، ليس ضد الأعداء الخارجيين، بل ضد الوحش الذي كان يقطن في جوف كل واحد منهم، الوحش الذي يرفض أن يموت بصمت.', '', 172, '2026-07-15 15:18:08.809', '2026-07-15 15:18:08.809');
INSERT INTO public.chapters VALUES ('441babac-6105-4c95-8eaf-301a4e00cba5', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 174: صدع في جدار العزلة', '— --------------------------------------- انزلق النصل المعدني على سطح الطاولة الخشبي ليصدر صوتاً حاداً اخترق سكون الغرفة. لم يرفع إينار بصره عن كومة القمح التي يفرزها، بينما كان ثورفين يحدق في الفراغ، يداه مقيدتان خلف ظهره بحبال خشنة. دخلت غودريد الغرفة، تعثرت قليلاً عند العتبة، ونظراتها تتبدل بين قسوة الحراس المنتشرين في الخارج وتوتر ثورفين الصامت. قالت بنبرة متهدجة: لقد بدأوا في إحصاء الماشية، يا ثورفين. إنهم لا يكتفون بالأرض، يريدون إخضاع كل نبضة حياة هنا. قبض ثورفين على أسنانه، وانقبضت عضلات فكيه حتى برزت عروق عنقه. لم يجب. كان الصمت الذي يلفه ثقيلاً، مشحوناً برغبة مكبوتة في الانفجار أو البكاء، لكنه لم يفعل أياً منهما. تقدم إينار، وضع يده على كتف ثورفين، وشعر بتشنج الجسد تحت كفه. قال إينار بصوت منخفض ومباشر: لا تغامر بكل شيء الآن. نحن لسنا مقاتلين، نحن مزارعون. إذا اندلع الدم هنا، فسيحرقون المحصول ويقتلوننا جميعاً قبل أن نصل إلى حافة الحقل. حدق ثورفين في يدي إينار، ثم تنهد بعمق، ليخرج الزفير صفيراً مكتوماً من صدره. قال ثورفين بصوت أجش: إنهم لا يفهمون. السلام ليس استسلاماً، إنه قرار أصعب من حمل السيف. التفتت غودريد نحو النافذة، تراقب الجنود الذين يعبثون بأدوات الحراثة بأحذيتهم الثقيلة. قالت: إنهم لا يرون فينا سوى عبيد، لا يهم ما في رؤوسنا، ما دام الظهر منحنياً. تحرك ثورفين ببطء، محاولاً تعديل وضعية جلوسه لتخفيف ضغط الحبال على معصميه. كانت الغرفة تعبق برائحة الحبوب المخزنة والتراب، لكن التوتر جعل الهواء يبدو شحيحاً. أضاف ثورفين بنبرة حازمة ومقتضبة: لن نقاتلهم اليوم، لكننا لن نكون جزءاً من دمارهم. سنستمر في البذر، وسنحصد ما زرعناه، مهما حاولوا دهس الأرض تحت أقدامهم. نظر إليه إينار طويلاً، ثم أومأ برأسه ببطء، مدركاً أن ثورفين قد اتخذ قراره ليس بالخضوع، بل بالثبات على جحيم من الصبر.', '', 173, '2026-07-15 15:18:08.996', '2026-07-15 15:18:08.996');
INSERT INTO public.chapters VALUES ('7ec28f4e-1ec1-4d71-9039-e636a7f2b9ad', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 175: ثمن الأرض الخصبة', '— --------------------------------------- توقفت حركة الرجال فجأة حين لاحت تباشير الشاطئ أمام أعينهم المنهكة. لم تكن فينتلاند مجرد أرض، بل كانت تجسيداً لوعدٍ ثقيل يثقل كاهل ثورفين. التفت ''إينار'' نحوه، كانت ملامحه مشوبة بآثار السفر الطويل، وقال بصوت خشن: هذه هي الأرض التي أخبرتنا عنها؟ هل تبدو كافية لجميع من أحضرناهم؟ لم يجب ثورفين فوراً، بل ثبت بصره على مساحات العشب الممتدة التي تترنح تحت وقع الرياح الهادئة. كانت عيناه تقرآن التضاريس، ليس كقائد يبحث عن غنيمة، بل كمهندس يزن احتمالات البقاء والانهيار. قال ثورفين بنبرة مقتضبة: المسافة بيننا وبين النجاة تبدأ من هنا، لكن الخطر ينمو في الجوار كما ينمو العشب. كان ''هيلد'' تقف في الخلف، تلامس مقبض سلاحها بحركة آلية، نظرتها كانت تمسح خط الأفق بحثاً عن أي تهديد محتمل، صمتها كان أبلغ من أي تحذير. استمرت الرحلة في التوغل نحو اليابسة، حيث كانت الأشجار الكثيفة تخفي أسرار هذه الأصقاع. تعثر أحد الرجال في جذر شجرة بارز، مما أدى إلى تصاعد ضحكات مكتومة وشتائم خافتة قطعت حدة الترقب. وبينما كانوا يرتبون مؤنهم، اقترب ثورفين من إينار الذي كان يتفحص تربة الأرض بيده. قال إينار وهو يفرك الطين بين أصابعه: التربة تبدو غنية، لكننا سنحتاج إلى مجهود مضاعف لتهيئة المكان قبل قدوم الشتاء. أجابه ثورفين وهو يشد حزامه: لن نحتاج إلى القتال هنا يا إينار، سنحتاج فقط إلى الصبر والعمل. كان ثورفين يدرك أن كل خطوة يخطونها في هذه الأرض تضعهم في مواجهة مع المجهول، ومع سكان لم يظهروا بعد، لكنهم بلا شك يراقبون من خلف ظلال الأشجار. لم تكن هناك فلسفة أو وعظ، بل كان الخوف المكتوم والرغبة في حياة بلا دماء هما المحركان لكل نظرة متبادلة. في تلك اللحظة، شعر ثورفين بوطأة المسؤولية؛ فالمكان الذي اختاره ليكون ملاذاً آمناً قد يتحول في أي لحظة إلى ساحة معركة إذا لم يتمكنوا من كسب ثقة الأرض وأهلها. كانت الشمس تميل نحو الغروب، تاركةً خلفها ظلالاً طويلة بدت وكأنها تستعد للابتلاع. وضع ثورفين يده على كتف إينار بقوة وقال: ابدأوا بنصب الخيام، الليل هنا يختلف عن أي مكان آخر، وعلينا ألا نكون هدفاً سهلاً لمن لا نعرفهم بعد.', '', 174, '2026-07-15 15:18:09.167', '2026-07-15 15:18:09.167');
INSERT INTO public.chapters VALUES ('140294c8-c671-4026-8bd9-9e907bab796c', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 176: سديم الآمال الموعودة', '— --------------------------------------- تصاعدت أبخرة الملح والجليد من أطراف السفن الراسية في خليج فينلاند، بينما كان ثورفين يراقب الأفق، عيناه لا تغادران شريط اليابسة الممتد كأنه وعدٌ ثقيل. خلفه، كان إينار يشد الحبال بقوة، وعروق يده تبرز مع كل حركة، محاولاً استعادة توازنه على سطح السفينة المائل بفعل التيارات القوية. لم يكد ثورفين يلتفت حتى ارتطمت أقدام الرجال بالرمال، كان وقعها ثقيلاً ومكتوماً، يشي بتوترٍ لا يخفى على أحد. اقترب هيلد، بصمتها المعهود، ووقفت إلى جانبه، أصابعها تتحسس نصل خنجرها، نظرتها متفحصة للغابات الكثيفة التي تبدو وكأنها تراقبهم بدورها. قال إينار بصوتٍ متهدج: ''هل هذه هي أرض السلام التي حلمنا بها؟ تبدو ساكنة أكثر مما ينبغي''. لم يرد ثورفين، بل اكتفى بمسح وجهه بكفه الخشنة، كانت ملامحه حادة، مشدودةً نحو أفقٍ غامض. صمتُ الغابة كان خانقاً، لا طيور تغرد، ولا ريح تعبث بالأوراق؛ كان صمتاً يسبق وقوع أمرٍ جلل. وبينما بدأوا في إنزال المؤن، توقفت حركة الجميع فجأة حين انبعثت أصوات تكسر أغصان الأشجار من العمق. تراجعت يدا ثورفين نحو حزامه تلقائياً، ليس لقتالٍ، بل لتحسس خلوه من السلاح. قال ثورفين بصوتٍ منخفض، كأنه يهمس لنفسه: ''إنهم هنا''. لم تكن تلك مفاجأة، بل حقيقةً كانوا يتحاشون مواجهتها حتى هذه اللحظة. تلاقت الأنظار، وبينما ارتسمت ملامح الترقب على وجه هيلد، كان ثورفين يتقدم خطوةً نحو حافة الغابة، جسده متصلب، ونظراته تخترق الظلال الباردة للأشجار، باحثاً عن وجهٍ قد يحمل مفتاح المستقبل أو نذير الفناء.', '', 175, '2026-07-15 15:18:09.341', '2026-07-15 15:18:09.341');
INSERT INTO public.chapters VALUES ('7356199f-58d6-41a0-bd39-e66c689a9aee', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 177: بذور في أرض الغرباء', '— --------------------------------------- انحنت أغصان الأشجار تحت وطأة الرياح الغربية، بينما كانت الفؤوس تهوي على جذوع البلوط الضخمة، مخلفةً صدىً يتردد في أرجاء الغابة الموحشة. توقف ثورفين عن العمل، مسح بظهر يده العرق عن جبينه، ونظر إلى الأفق البعيد حيث تتلاشى الأشجار لتكشف عن بقعة أرض عارية، هي أملهم الوحيد في البقاء. كانت إينار يقف بجانبه، يلهث بشدة، وقد تلطخت ثيابه بطين الأرض البكر. قال إينار بصوت متقطع: لن تكتمل الحقول قبل اشتداد البرد، يا ثورفين. لم يجبه ثورفين فوراً، بل حدق في كومة الحبوب التي جلبوها معهم، تلك البذور التي تحمل وعوداً بمستقبل بعيد. أجاب بنبرة خشنة ومختصرة: سنعمل حتى تتجمد الأرض، لا خيار لنا سوى الحصاد أو الفناء. في تلك اللحظة، اقتربت هيلد، عيناها تراقب حافة الغابة بحذر، وكأنها تتوقع خروج وحش من بين الظلال. لم تعد تلك الفتاة التي تسعى للانتقام، بل أصبحت جزءاً من هذا الكيان القلق الذي يحاول بناء حياة فوق أنقاض الكراهية. توجهوا نحو مخيمهم الصغير، حيث كانت النار تلتهم بقايا الأغصان الجافة. جلسوا في صمت مطبق، وهو الصمت الذي تفرضه قسوة الطبيعة على الغرباء الذين لا يملكون وطناً. أخرج ثورفين قطعة من اللحم المجفف وناولها لإينار، ثم نظر إلى السماء التي بدأت تتلون بلون رمادي داكن. فكر في ثقل المسؤولية التي يحملها على عاتقه؛ فالجميع يعتمد عليه ليرسم لهم درباً في هذه البرية المنسية. قال إينار وهو يكسر صمته: هل تعتقد حقاً أن هؤلاء السكان المحليين سيتركوننا وشأننا؟ التفت إليه ثورفين، وبرقت عيناه بحدة، وقال: لا أبحث عن عداوتهم، ولن أسمح لأي أحد بأن يجرنا إلى دوامة الدم مرة أخرى. إذا أرادوا الأرض، سنفاوضهم، وإذا أرادوا القتال، سنرحل. لكنه لم يكمل جملته، فقد انقبضت كفه تلقائياً، ملمحاً إلى ذلك الماضي الذي لم يترك جسده تماماً. انقضى الليل ثقيلاً، ومع بزوغ الفجر، كانت أصوات الطبيعة تنذر بتغيير قادم. وقف ثورفين أمام الحقل غير المكتمل، ممسكاً بمحراثه الخشبي بقوة، مدركاً أن كل بذرة يغرسها في هذا التراب هي تحدٍ مباشر لقدره الملطخ بالدماء.', '', 176, '2026-07-15 15:18:09.546', '2026-07-15 15:18:09.546');
INSERT INTO public.chapters VALUES ('f2633524-b088-4eb2-bc19-22f9aff91ac7', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 178: صدى الأرض البكر', '— --------------------------------------- انزلق النصل الحديدي في التربة الداكنة، فمزقها بصوت خشن ومكتوم. وقف ثورفين وسط الحقل، يمسح حبات العرق التي تجمعت عند منبت شعره بظهر يده الملطخة بالطين. لم تكن الأرض التي يقفون عليها مجرد تراب؛ كانت وعاءً لآمال لم تكتمل بعد. التفت إينار نحو رفيقه، كان يلهث، وقد تعلقت بملابسه خيوط من العشب الجاف، ثم أشار بيده نحو الأفق حيث تتراءى ملامح المستوطنة الوليدة. قال إينار بصوتٍ متهدج: ألا تشعر بذلك؟ الأرض هنا لا تشبه أرضنا، إنها لا تطالب بالدماء، بل تطلب فقط أن نغرس فيها شيئاً لتعطينا الكثير. لم يرد ثورفين فوراً، بل ثبت نظره على حافة الأفق، حيث كان ثقل المسؤولية يتركز في عينيه العميقتين. أجابه بصوتٍ مبحوح: لا يهم نوع الأرض، إينار. الأهم هو ما نفعله بها. القوة التي استهلكناها في حمل السيوف، هي ذاتها التي سنحتاجها لشق هذه الأخاديد. اقترب منهما أحد المستوطنين، كان يرتجف قليلاً، ملامح وجهه مشدودة بعلامات القلق التي لا تخطئها العين، وقال بنبرة متقطعة: السلاح… هل نبقيها مخبأة؟ الشائعات عن الهجمات لا تتوقف. توقف ثورفين عن الحركة تماماً، ساد صمت ثقيل لم يقطعه سوى طنين بعيد لحشرة ما. وضع ثورفين معوله جانباً، واقترب من الرجل حتى صار يواجهه مباشرة، وقال بصوت خافت لكنه حاد كالشفرة: لن نستخدمها. لا أريد أن أرى حديداً في أيديكم ما دامت الأيدي قادرة على حمل البذور. إن بدأت الحرب هنا، فقد انتهى كل شيء قبل أن نبدأ. تحركت عضلات فك ثورفين بانقباضة خفيفة، دلالة على صراع داخلي خفي، لكنه سرعان ما استدار عائداً نحو عمله. وبينما كانت الشمس تميل نحو المغيب، صابغةً أطراف الأشجار البعيدة بلون النحاس المحروق، كان وقع أقدامهم على الأرض يتناغم مع إيقاع العمل الرتيب. لم تكن هناك فلسفات كبرى في حديثهم، فقط واقع مرير يسعون لترويضه، وعالم جديد يحاولون خلقه من تحت أنقاض ذكرياتهم المثقلة بالندم.', '', 177, '2026-07-15 15:18:09.797', '2026-07-15 15:18:09.797');
INSERT INTO public.chapters VALUES ('73145eaa-6162-405d-91f5-4e5e8a5f5a71', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 179: صدى الماضي في أروقة الذاكرة', '— --------------------------------------- توقف ثورفين عن الحركة. لم يكن الصمت في الغرفة محض غياب للأصوات، بل كان ثقلاً مادياً يضغط على أنفاسه. أمامه، جلس هيلد، عيناها تحدقان في الفراغ، بينما كانت أصابعها تعبث بحافة ثوبها باضطراب غير معتاد. لم تكن هناك رياح تهب عبر النافذة المفتوحة، لكن ورقة شجر يابسة تدحرجت على الأرضية الخشبية لتستقر عند قدمه. كسر ثورفين جمود الموقف بنبرة جافة ومباشرة: أسمعيني يا هيلد، لا يمكننا الاستمرار في تجاهل ما حدث في أراضي الماريند. قالت هيلد، وصوتها يخرج متهدجاً، كأنه قادم من خلف جدار عازل: لا تظن أن المسامحة عمل مجاني يا ثورفين. إنها ندبة، وكلما لمستها، سال الدم من جديد. اقترب ثورفين منها بضع خطوات، فارضاً حضوراً حذراً، فبؤبؤ عينه اتسع قليلاً وهو يراقب ارتعاش كتفيها. لم يعتذر، فكلمة الاعتذار في قاموسه كانت تبدو دائماً كعملة زائفة لا تشتري الغفران. قال بصوت خشن: أنا لا أطلب محواً للماضي، بل أطلب طريقاً للعبور. نظر إليها، مستذكراً وجوه من رحلوا، لكنه لم يترك الحزن يطغى على ملامحه الصلبة. إن الصراع بيننا ليس بسيف أو درع، بل هو في كيفية حمل أوزارنا دون أن نتحطم. استدارت هيلد نحوه، ووجهها، الذي كان شاحباً بفعل ضوء الغروب الشحيح، حمل تعبيراً يمزج بين الضغينة والحيرة. قالت بنبرة حادة، خالية من أي رقة: أنت تتحدث وكأن السلام هدف نبيل، لكن السلام في نظري هو مجرد مهلة لالتقاط الأنفاس قبل الطعنة التالية. ضغط ثورفين على قبضة يده، مفصلاً أصابعه تبرز تحت الجلد المشدود. صمت لحظة، كان خلالها صوت نبضات قلبه هو الوحيد المسموع في الغرفة. رد بصرامة: إذا كان هذا هو قدرنا، فليكن. لكنني لن أعيش كعدو في عالم لا يزال فيه مكان للعيش. غادر الغرفة بخطوات واسعة، تاركاً هيلد خلفه تواجه وحدتها. كانت الأرض تحت قدميه تبدو صلبة، حقيقية، لا ترحم، تماماً كالحقيقة التي يواجهها الآن؛ لم تكن الفلسفة هي ما يحميه، بل الإصرار الصامت على المضي قدماً رغم ثقل الأرواح التي تلاحقه.', '', 178, '2026-07-15 15:18:09.979', '2026-07-15 15:18:09.979');
INSERT INTO public.chapters VALUES ('00205ab1-b8ec-48ea-9dab-85f8b9534942', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 180: صدى الصمت في أرض الميعاد', '— --------------------------------------- انتصبت خيمة ثورفين وسط الأراضي الوعرة، حيث تداخلت أصوات الرياح مع همس المستوطنين الذين تجمهروا في الخارج. كان الغضب يسري في عروق الحاضرين مثل حمى لا تهدأ، صرخاتهم تطالب بالعدالة أو ربما بالدم، بعد أن تكشفت خيانة السكان الأصليين لمؤنهم القليلة. وقف ثورفين بملامح متصلبة، عيناه تتابعان حركة الأيدي المرتجفة على مقابض السيوف. قال صوته مقتضباً وخشناً يخترق الضجيج: لا قتال هنا. ساد صمت مفاجئ، لم يكن صمت اقتناع، بل صمت دهشة وتساؤل. تقدم أحد الرجال، كان وجهه محفراً بندوب قديمة، ونبرته تحمل مرارة السنين: يا ثورفين، لقد سرقوا ما نقتات عليه، هل نترك أطفالنا للجوع من أجل مثالياتك؟ لم يجب ثورفين بكلمات منمقة؛ بل خطى خطوة واحدة نحو الرجل، كانت عيناه تحملان ثقلاً حقيقياً، نظرة من خاض حروباً عرف فيها أن السيف لا يطعم جائعاً بل يصنع قبراً. هز ثورفين رأسه بنفي قاطع، عضلات فكه منقبضة. بينما في زاوية الخيمة، كان إينار يراقب المشهد، صمت إينار كان أبلغ من أي اعتراض، فهو يدرك تماماً أن ثورفين لم يعد ذلك الصبي المتعطش للانتقام، بل رجل يحمل ثقل وعود قطعها لنفسه وللأرض. كان النزاع يشتد، صرخات الفريق تزداد حدة، لكن ثورفين ظل ثابتاً، حركته بطيئة ومدروسة، يرفض الانجرار إلى هوة العنف التي تتربص بهم. قال بصوت مسموع لكنه هادئ: إذا خرجتم للقتال، فقد خسرنا الأرض قبل أن نضع جذورنا فيها. لم تكن عبارة فلسفية، بل كانت حقيقة مادية لمست تراب الأرض الذي يقفون عليه. انخفضت السيوف قليلاً، وتراجع الرجال خطوة إلى الوراء، لكن التوتر ظل معلقاً في الهواء، كثيفاً وخانقاً، ينتظر شرارة واحدة لتشعل ما تبقى من أمل في هذه الأرض الغريبة.', '', 179, '2026-07-15 15:18:10.188', '2026-07-15 15:18:10.188');
INSERT INTO public.chapters VALUES ('ec4e0120-38b3-4e48-9c27-35eea64fc393', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 181: أصداءُ التيهِ في أرضِ الغرب', '— --------------------------------------- توقف ثورفين عن الحركة. لم تكن الغابةُ صامتة، بل كانت تضجُّ بخرخشة أوراق الأشجار الجافة تحت وطأة خطواتهم المترددة. التفت نحو إينار الذي كان يتنفس بحدة، تتردد في عينيه أسئلة لم يجرؤ على نطقها، بينما ظلت ميردال صامتة، تراقب المسارات المتشعبة بأعينٍ فاحصة. قال ثورفين بصوتٍ مقتضب وجاف: «توقفوا». لم ينتظر إجابة، بل انحنى ليفحص الأرض، حيث تلاشت أثار الأقدام لتتحول إلى مسارٍ موحلٍ غامض. لم تكن هذه مجرد رحلة استكشاف؛ كان ثقل الماضي يطارد خطواته في كل لحظة. نظر إينار إلى الأفق البعيد، حيث تلوح تلال فينلاند كأنها جدارٌ لا يمكن اختراقه، وقال بنبرة متهدجة: «هل نحن نسير في الدائرة ذاتها؟». لم يجب ثورفين، بل اكتفى بمسح العرق عن جبينه بظهر يده المليئة بالندوب. كان يعلم أن كل خطوة تخطوها أقدامهم في هذه الأرض هي مجازفة. فجأة، توقفت ميردال، وأشارت بسبابتها نحو منطقة منخفضة يغطيها الضباب الخفيف. هناك، وسط الفراغ، كانت تلوح ملامح معسكرٍ مهجور، بقاياه لا تزال تتصاعد منها خيوط دخانٍ باهتة. لم يكن ثمة صراخ، لم يكن ثمة معركة، بل كان سكوناً يسبق العاصفة، سكوناً يمزق الأعصاب. اقترب ثورفين بحذر، مقبض خنجره تحت ردائه يرتجف بلمسة أصابعه المتوترة. التفت إلى رفيقه وقال بنبرةٍ حازمة: «ابق خلفي. لا تخرج سلاحك ما لم تلمح عدواً حقيقياً». كان الضباب يلتف حول أقدامهم كأفاعٍ خفية. في تلك اللحظة، ظهر ظلٌ من خلف جذع شجرة ضخم. لم يكن محارباً، بل كان فرداً من سكان الأرض الأصليين، يراقبهم بنظراتٍ تفتقر إلى الكره، لكنها تفيض بالريبة. جمد ثورفين في مكانه، ورفع يده ببطء لتكون مرئية، كاشفاً عن كفه الفارغة. كان هذا الصمت هو الحوار الأكثر ضراوة الذي خاضه منذ زمن. لم تكن السيوف هنا هي من يتحدث، بل كانت أنفاسهم المتسارعة ونظراتهم التي تتصادم في الفراغ. همس إينار وهو يشد قبضته: «ماذا لو لم يفهموا نوايانا؟»، فأجابه ثورفين بصوتٍ مبحوح: «سأجعلهم يفهمون، حتى لو اضطررت لأن أجعل صمتي يتحدث بدلاً مني». استمر الترقب، وظلت الأشجار تلوح بأغصانها كأنها شهودٌ على لحظة فارقة قد تغير مسار مستقبلهم في هذه القارة العذراء.', '', 180, '2026-07-15 15:18:10.379', '2026-07-15 15:18:10.379');
INSERT INTO public.chapters VALUES ('dbcdac0b-d45a-4898-a09b-27ca9eb4d0e4', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 182: صدى الصمت في أرض الميعاد', '— --------------------------------------- انزلق نصل النصل على حجر السن بصوت معدني حاد، يقطع رتابة الأجواء في مستوطنة فينلاند الناشئة. توقف ثورفين عن الحركة، وعيناه مسمرتان على أفقٍ لا يحده سوى ضباب الغابات الكثيفة. كان الصوت القادم من الخلف مألوفاً، وقع أقدامٍ ثقيلة، غير متزنة، تفضح إنهاكاً مزمناً. التفت ثورفين ليرى إينار يتقدم نحوه، وقد ارتسمت على ملامحه سحابة من الحيرة. لم يطل الانتظار حتى كسر إينار حاجز الصمت بسؤاله المباشر: هل تعتقد حقاً أننا نملك ترف بناء عالمٍ بلا دماء، بينما الذئاب تحيط بنا من كل جانب؟ لم يجب ثورفين فوراً، بل أعاد وضع النصل في غمده ببطء مدروس، ثم سار بضع خطوات نحو حافة الجرف المطل على البحر. كانت أمواج المحيط الأطلسي تضرب الصخور بانتظام، كأنها نبض أرضٍ ترفض الخضوع. رد ثورفين بنبرة جافة، خالية من أي تهويمات: السلاح لا يصنع السلام يا إينار، بل يؤجل الانفجار. إذا سحبنا سيوفنا الآن، أعلنا للعالم أننا مثلهم تماماً، نقتات على خوف الآخرين. كان ثورفين يتحدث وهو ينظر إلى يديه، تلك اليدان اللتان حملتا الموت لأعوام طويلة، والآن لا تجيدان سوى حراثة الأرض. اقترب إينار أكثر، وتلاقت نظراتهما تحت سماءٍ ملبدة. في تلك اللحظة، لم تكن الحاجة إلى الحكمة هي الغالبة، بل كانت الحاجة إلى اليقين. قال إينار بصوتٍ متهدج: لكن أهل القبائل يراقبوننا، ثورفين. إنهم لا يرون فينا مزارعين، بل يرون فينا غزاة بوجوهٍ مسالمة. هز ثورفين رأسه بحدة، وقبض على قبضة خنجره حتى ابيضت مفاصل أصابعه، لكنه لم يسحبه. نحن هنا لنغير القواعد، حتى لو كلفنا ذلك حياتنا. إذا كنا سنموت، فسنموت ونحن نحمل المحراث، لا الفأس. غادر إينار المكان تاركاً ثورفين وحيداً، يواجه وطأة قراره. وبينما كان الليل يهبط بظلاله الزرقاء على أرجاء المستوطنة، جلس ثورفين أمام النار المشتعلة، يراقب تراقص اللهب. لم يكن في قلبه خوف، بل كان هناك حضورٌ طاغٍ لكل من رحلوا، لكل الذين سقطوا في ظلال سيوفه. أغمض عينيه للحظة، مستحضراً طيفاً من الماضي، لا كذكرى مؤلمة، بل كدرسٍ نهائي: القوة ليست في البقاء واقفاً بينما يسقط الآخرون، بل في القدرة على إلقاء السلاح حين لا يعود هناك مبرر لحمله.', '', 181, '2026-07-15 15:18:10.577', '2026-07-15 15:18:10.577');
INSERT INTO public.chapters VALUES ('63808fa7-610d-4690-8a0a-7b3603e65748', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 183: بذور النزاع في أرض السلام', '— --------------------------------------- التفت إيفار نحو ثورفين، عيناه تضيقان خلف ظلال خوذته الصدئة، بينما كانت يده تقبض على مقبض سيفه حتى ابيضت مفاصل أصابعه. لم يكن هناك حديثٌ مطول، فقط صوت احتكاك المعدن بالجلد حين اقترب خطوة إضافية. قال إيفار بصوتٍ مشوب بخشونة الحرب: ''أنت تتحدث عن السلام، يا ابن ثورس، بينما يتربص بنا هؤلاء القوم خلف الأشجار. هل تعتقد أن النوايا الحسنة ستصد نصل فأسٍ يشق الجمجمة؟ ''. ثورفين لم يتردد، وقف ثابتاً، جسده لم يرتجف ولم يبدُ عليه أي توتر، لكنه أجاب بنبرة حادة ومقتضبة: ''العنف لا يولد إلا العنف يا إيفار. إذا بدأنا بالقتال، فلن نكون أفضل حالاً ممن هربنا منهم''. ساد صمتٌ خانق، قطعه صوت صليل متباعد قادم من الغابة المحيطة بـ ''فينلاند''. لم تكن أصوات طيور، بل كان وقع أقدامٍ ثقيلة تخترق الأدغال بعناية. هيلد، التي كانت تراقب المشهد من مسافة، رفعت قوسها ببطء، توترت أوتار القوس تحت أصابعها، ونظرة حذر صامتة ارتسمت على ملامحها الحادة. ''إنهم يقتربون''، همست هيلد دون أن تحيد بصرها عن الأشجار. في تلك اللحظة، ظهرت ملامح الترقب على وجوه المستوطنين؛ بعضهم أمسك بأدوات الزراعة كأنها أسلحة، وآخرون تراجعوا خطوة إلى الوراء، تتسارع أنفاسهم. ثورفين نظر إلى الجميع، لم يجد في أعينهم إلا الخوف الممزوج بضغينة قديمة لا تفنى. أدرك حينها أن المسافة بين حلمه بـ ''فينلاند'' وبين واقع الدم الذي يلاحقهم تتقلص إلى خيط رفيع جداً. ''لا أحد يسحب سلاحه''، أمر ثورفين بصوتٍ حازم، لكن إيفار سخر منه وهو يبصق على الأرض: ''أنت تحكم على هذا المكان بالفناء يا ثورفين، ونحن لن نموت صامتين''. انقبضت عضلات فك ثورفين، واتسعت حدقتا عينيه وهو يرى أحد الغرباء يخرج من بين الظلال، يده ملوثة بصبغة غريبة، وعيناه لا تحملان سوى نية واحدة: المواجهة. لم يكن هناك مجالٌ للتراجع؛ اللحظة التي طالما حاول تجنبها أصبحت حقيقة ماثلة أمام عينيه، والسكين التي نبذها في ماضيه كادت أن تعود لتغرز نفسها في نسيج حلمه الجديد.', '', 182, '2026-07-15 15:18:10.883', '2026-07-15 15:18:10.883');
INSERT INTO public.chapters VALUES ('212eb764-238c-4a6b-9ceb-f19456f29ab6', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 184: صدى العزلة في أنقاض الحلم', '— --------------------------------------- انزلق ثورفين نحو حافة المنحدر الصخري، حيث تتكسر الأمواج بخفوتٍ مخيبٍ للآمال. لم تكن العزلة هنا ملاذاً، بل كانت مرآةً عارية تعكس هشاشة خطواته. خلفه، وقف إينار يراقب صمته المطبق، يتأمل انحناءة ظهره التي باتت توحي بثقلٍ لا يخص جسده فحسب، بل يمتد ليطال أرواح أولئك الذين علقوا في طموحه التائه. التفت ثورفين، لم تكن عيناه تحملان لمعان التحدي المعهود، بل استقرت نظراته على بقعة باهتة في الأفق. قال بصوتٍ خشنٍ، كأنه يمزق الصمت بحدسِ جريح: لا شيء في فينلاند يتسع لهذا الغضب الذي حملته معي عبر البحار. نظر إينار إلى يد ثورفين التي كانت ترتجف بشكل غير مرئي، قبضة يده تنقبض وتنبسط فوق مقبض سيفه الذي لم يعد يشهره. لم يجد إينار في نفسه حاجةً للرد بالكلمات، فاكتفى بوضع كفه على كتف ثورفين، ضغطة كانت كفيلة بإيصال كل ما يعجز اللسان عن صياغته. في تلك اللحظة، تحولت ذكريات المعارك إلى أشباحٍ باهتة لا تقوى على مواجهة وهج الحقيقة القاسية: أن الأرض الجديدة لم تكن خالية من الخطايا، بل كانت تنتظر فقط من يجرؤ على غرس جذور النزاع فيها. تنهد ثورفين بعمق، انكمشت عضلات فكه السفلي، ثم خطى مبتعداً عن الحافة، تاركاً الريح تعبث بملابسه المهترئة، مدركاً أن المسافة بين حلمه وواقعه ليست بحراً شاسعاً، بل هي تلك المسافة القصيرة بين عقله وقلبه. كانت أصوات المستوطنين في الأسفل تتصاعد مختلطة بأصوات أدوات الحفر، إيقاع رتيب يذكرهم بأن البناء لا يكتمل دون مواجهة الأشباح التي يسكنونها في ذواتهم، دون وعظٍ أو فلسفة، كان الوجود بحد ذاته هو الامتحان الأخير.', '', 183, '2026-07-15 15:18:11.067', '2026-07-15 15:18:11.067');
INSERT INTO public.chapters VALUES ('4e32353f-53e8-4e26-a07e-0f815a0bbe07', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 185: صدى الصمت في فيرلاند', '— --------------------------------------- توقفت حركة القوارب عند ضفاف النهر. لم تكن هناك صيحات معتادة للبحارة، بل ثقلٌ في الأجواء يشي بنهاية رحلة طويلة. ترجل ثورفين، غارزاً قدميه في التربة الرطبة التي لم تطأها أقدام قومه من قبل. نظر إينار إلى الأفق، حيث تختلط خيوط الضباب الأخضر بغابات لم يمسسها فأس. قال إينار بصوت متهدج: أهذا هو المكان؟ اكتفى ثورفين بهز رأسه، كانت عيناه تمسحان المكان بحدة، لا كفاتح يبحث عن غنيمة، بل كمزارع يقرأ جودة الأرض قبل البذر. اقترب هيلد ببطء، ممسكة بقوسها، تراقب الأشجار العالية بحذر. لم تكن الغابة صامتة تماماً، بل كانت تعج بحياة بدائية لا تعرف وجود البشر. في تلك اللحظة، لم يكن هناك عدو، ولم تكن هناك دماء. جلس ثورفين على صخرة مغطاة بالطحالب، وأخرج بضع حبات من الحبوب من كيسه الجلدي. قلبها بين أصابعه الخشنة. التفت إليه إينار وسأل: هل تظن أنهم سيقبلون بنا؟ ثورفين لم يجب على الفور؛ كان ينظر إلى أبعد من الأشجار، إلى حيث ينتهي الماضي ويبدأ المجهول. أجاب بنبرة جافة ومقتضبة: الأمر لا يتعلق بالقبول. يتعلق بالبقاء دون سحق أحد. تقدم هيلد خطوة، وقالت بصوت هادئ يشوبه التوجس: السكان المحليون، إنهم يراقبوننا منذ لحظة وصولنا. انقبضت كف ثورفين على مقبض خنجره، ليس استعداداً للقتال، بل كفعل انعكاسي لمحارب لم ينسَ حذر السنين. تنفس ثورفين بعمق، وشعر بضغط الغابة المحيطة. لم تكن هناك خريطة، ولم يكن هناك قائد عسكري يملي عليهم التحركات. كانت هذه هي الأرض التي وعدوا بها أنفسهم، أرض خالية من نير العبودية والحروب. قال ثورفين بصوت خفيض: لا نستخدم السيوف إلا للضرورة القصوى. التزموا بهذا. في الأفق، بدأت حركة غريبة بين الأشجار، لم تكن حيواناً، بل ظلاً بشرياً توارى بسرعة خلف الجذوع الضخمة. أدرك الجميع أنهم دخلوا منطقة لم تُكتب في سجلات تاريخهم، وأن التحدي الحقيقي ليس في عبور المحيط، بل في الحفاظ على إنسانيتهم وسط هذا المجهول الأخضر.', '', 184, '2026-07-15 15:18:11.241', '2026-07-15 15:18:11.241');
INSERT INTO public.chapters VALUES ('e85c3982-20eb-42cf-952e-6adfe91c4c87', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 186: صدى الآفاق البعيدة', '— --------------------------------------- تثاقلت خطى ثورفين على الرمال الساحلية لجزيرة وينلاند، حيث تلاشت أصوات البحر لتفسح المجال لضجيجٍ مكتومٍ قادمٍ من معسكر المستوطنين. لم تكن المسافة الفاصلة بينه وبين وجهته سوى خطواتٍ معدودة، لكن ثقل القرار كان يضغط على كاهله كصخرةٍ صماء. توقف فجأة؛ لم يكن الصمت من حوله خاوياً، بل كان مشحوناً بتوترٍ ناتجٍ عن مواجهةٍ محتومة مع ''إيفار''. التفت ثورفين برأسه قليلاً، ورأى إيفار يتقدم نحوه، يده اليمنى تقبض على مقبض سيفه بإحكامٍ جعل مفاصل أصابعه تبرز بلونٍ شاحب. قال إيفار بصوتٍ متهدج: أظننت أننا سنقف متفرجين بينما تبيع دماءنا مقابل السلام؟ رد ثورفين ببرود، وعيناه ثابتتان في عيني خصمه دون أن يرمش: السلام ليس سلعةً للبيع، إنه بناءٌ يتطلب شجاعةً تفوق شجاعة إشهار السلاح في وجه من لا يريد قتالك. انقبض فك إيفار، واندفع خطوة للأمام، رائحة العرق والتوتر تفوح من ثيابه المتربة. صاح إيفار: أنت خائن، خذلت شعبك الذي جاء ليبحث عن وطن! حدق ثورفين في المساحات الممتدة أمامه، في الغابات التي لم تلمسها فؤوسهم بعد، وقال بلهجةٍ جافة لا تحمل تشفياً: الوطن ليس أرضاً نلطخها بالدماء، بل هو مكانٌ لا يضطر فيه المرء لقتل أخيه ليبقى حياً. خيم صمتٌ خانق، قطعه صوت صرير خطواتٍ خافتة من رجالٍ آخرين يقتربون. لم يكن ثورفين يبحث عن مواجهةٍ لفظية، فقد تجاوز تلك المرحلة. مشى متجاوزاً إيفار، كتفه يلامس كتف الآخر في احتكاكٍ قاسٍ ومباشر. لم يلتفت ثورفين خلفه، رغم أنه كان يشعر بنظراتهم المغتاظة تحرق ظهره. كان يعلم أن الطريق نحو ''فينلاند'' التي يحلم بها لا يمر عبر النصر في نزال، بل عبر الصبر على هذا الرفض المرير. وعندما وصل إلى كوخه، دخل وأغلق الباب خلفه بقوة، تاركاً إيفار ومن معه في مواجهة الفراغ الذي خلفه وراءه، فراغ لم يجرؤوا على ملئه بقرارٍ نهائي.', '', 185, '2026-07-15 15:18:11.452', '2026-07-15 15:18:11.452');
INSERT INTO public.chapters VALUES ('152f77e2-0b35-4fbf-bc3a-c1fc4d32b0cf', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 187: صدع في جدار السلام', '— --------------------------------------- تصلبت ملامح ثورفين وهو يراقب بؤر التوتر المتصاعدة في مستوطنته الناشئة، فالمناوشات البسيطة التي بدأت باحتكاكات حول الموارد قد تحولت إلى نذر صدام مسلح يهدد حلم المسالمة الذي نذر له حياته. وقف إينار بجانبه، يمسح العرق عن جبينه، وعيناه ترصدان تحركات القادمين من القبائل المحلية، وقال بصوت منخفض: هؤلاء ليسوا هنا للمقايضة يا ثورفين، إنهم يطلبون الثمن الذي لا نملكه، الأرض مقابل الولاء للدم. لم يلتفت ثورفين، بل ظل يراقب زعيم القبائل الذي تقدم بضع خطوات واضعاً يده على مقبض سيفه الصدئ، كانت نظراته مزيجاً من الريبة والعداء المكتوم. التفت ثورفين نحو إينار، انقبضت عضلات فكه قبل أن ينطق بكلمات مقتضبة: لا ترفع سلاحك، ليس اليوم، الانسحاب ليس هزيمة بل هو الخيار الوحيد لنمنع حلقة الانتقام من الدوران مجدداً. تقدم ثورفين نحو زعيم القبيلة، مشيته ثابتة لكن جسده كان متأهباً، وبصوت خفيض ونبرة خالية من التهديد، خاطبه: لا نريد دماءكم ولا نرجو أرضكم، نحن هنا لنزرع لا لنحصد الرؤوس. تجاهل الزعيم كلماته، وبصق على الأرض بين قدميهما، كانت الحركة بمثابة إعلان صامت عن فشل كل مساعي الحوار. في تلك اللحظة، شعر ثورفين بعبء القرار يثقل كاهله، فكل نبضة قلب كانت تذكره بضحايا الماضي الذين سقطوا تحت نصل سيفه، والآن، عليه أن يختار بين الصمود الذي يجر المستوطنة إلى المحرقة، أو التنازل الذي يراه الآخرون ضعفاً. التفت ثورفين إلى رفاقه، كانت نظراتهم تائهة بين الخوف والترقب، فصاح بهم بلهجة حادة: تراجعوا إلى الداخل، لا تغادروا الحصن مهما حدث، سأتكفل أنا بالأمر. كانت الساعات القادمة أشبه بجلوس على حافة بركان، حيث الحوار الهادئ لا يعدو كونه محاولة يائسة لمنع الانهيار الوشيك، بينما كانت عيون المستوطنين تراقب من الشقوق، منتظرة خيط الضوء الذي قد يجنبهم المذبحة، أو الضربة الأولى التي ستغير وجه حياتهم إلى الأبد.', '', 186, '2026-07-15 15:18:11.619', '2026-07-15 15:18:11.619');
INSERT INTO public.chapters VALUES ('ab9b329a-e0ec-4de3-800e-e7ed88c22202', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 188: صدى السيوف في فيينلاند', '— --------------------------------------- توقف ثورفين عن الجري حين تلاقت أنظاره بقائد المستوطنين المحليين. كانت الأرض تحت قدميه طينية ومرتوية بماء المطر الأخير، بينما كانت أصوات الصراخ والاشتباك قادمة من مسافة غير بعيدة، محملة بنبرة استغاثة لا تخطئها الأذن. وقف ثورفين بملامح متصلبة، يده اليمنى تتحرك لا شعورياً نحو مقبض خنجره قبل أن يثبتها بوعي. لم تكن الرغبة في القتال هي التي تحرك أعصابه، بل ذلك الشعور الثقيل بالمسؤولية تجاه الحلم الذي تعهد ببنائه. نظر ثورفين إلى الرجل الواقف أمامه؛ كان الأخير يلهث، وقد تلطخت ثيابه الجلدية بالوحل. لم تكن هناك حاجة لتبادل التحيات. قال الرجل بصوت مبحوح يتخلله ذعر مكتوم: إنهم يقتلون الماشية ويحرقون المخازن، لا يفرقون بين أحد. قبض ثورفين على ذراعه بقوة، حدق في عينيه مباشرة وقال بنبرة مقتضبة: ابقوا في الكهوف، لا تخرجوا مهما سمعتم، سأتولى الأمر. استدار ثورفين وركض نحو مصدر الضجيج، عضلات ساقيه تنقبض بقوة فوق الأرض الوعرة. لم يكن يفكر في القتل، بل كان يفكر في كيفية إيقاف هذا النزيف دون إراقة دماء إضافية. حين وصل إلى الساحة، كانت النيران قد بدأت تلتهم سقف أحد البيوت الخشبية. جنود يرتدون دروعاً معدنية متسخة كانوا يطاردون المزارعين، وسيف أحدهم كان يرتفع عالياً. صرخ ثورفين بصوت أجش ومجلجل: توقفوا! لم يلتفتوا إليه في البداية، فاندفع ثورفين كالسهم، معتمداً على سرعته الفائقة ليتفادى ضربة عشوائية، ثم ألقى بجسده ليصطدم بكتف المهاجم، معطلاً حركته. كان الصمت الذي أعقب التدخل مفاجئاً، وتوسعت بؤبؤة عين جندي كان يستعد للطعن. وقف ثورفين بين الطرفين، فارداً ذراعيه، لا يحمل سلاحاً ظاهراً، بينما كانت أنفاسه متسارعة، وصدره يعلو ويهبط. قال ثورفين ببرود حاد: إذا أردتم دماً، فابدؤوا بي، لكن لن يلمس أحد منكم هؤلاء مجدداً. كان الجنود ينظرون إليه بتشكك، بينما خيم هدوء مشحون بالتوتر على المكان، لم يكسره سوى طقطقة الخشب المحترق.', '', 187, '2026-07-15 15:18:11.84', '2026-07-15 15:18:11.84');
INSERT INTO public.chapters VALUES ('428eb7ae-d6ec-4ef2-a2c9-9b33c512744c', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 189: صدع في جدار الوعود', '— --------------------------------------- توقفت حركة القوافل فجأة حين تعثرت إحدى العربات في وحل الطريق الرطب. نظر ثورفين إلى الأفق، حيث تختفي ملامح الغابة في ضباب خفيف، ثم التفت نحو ''أينهينار'' الذي كان يمسح العرق عن جبينه. ساد صمت مطبق إلا من نَفَس الخيول المتلاحق. همس ثورفين دون أن يلتفت: ''لا يمكننا المضي بهذا الإيقاع، الموارد تنفد والمسافة التي تفصلنا عن أرض الحلم لا تزال غامضة''. لم يرد ''أينهينار''، بل اكتفى بوضع يده على مقبض فأسه، فقد كان التوتر يلف المكان كخيط مشدود على وشك الانقطاع. في تلك اللحظة، اقترب ''هيلد'' بخطوات واثقة، وعيناها تراقب حافة الغابة كأنها تستشعر خطراً دفيناً تحت أوراق الشجر المتساقطة. قالت بنبرة حادة ومقتضبة: ''هناك عيون تتبعنا، ليست عيون حيوانات، بل ترقب بشريّ يزن خطواتنا''. تجمد ثورفين في مكانه، وتقلصت عضلات فكيه. لم يلتفت للوراء، بل أطلق زفيراً بطيئاً وهو يقول: ''أخبرتكم أنني لا أريد قتالاً، لكن إذا فرضوا علينا الطريق، فلن نكون الضحايا''. كان ثورفين يصارع في داخله ضجيج ماضيه، حيث تتقاطع صور الدماء مع أحلام الأرض الجديدة. في هذه الأثناء، ظهرت أشكال بشرية ملثمة بين الجذوع. لم يصرخوا، ولم يهددوا، بل اكتفوا بالوقوف في وضعية القتال. اتسعت بؤبؤة عين ثورفين، وشعر ببرودة المعدن في يده، ليس لأنه يبتغي القتل، بل لأن غريزة البقاء طغت على إرادته في السلام. صاح ثورفين بصوت أبح ومباشر: ''تراجعوا إلى العربات، لا تسحبوا أسلحتكم ما لم يخطوا خطوة أخرى! ''. وقف أمامهم كحاجز بشري، يواجه المجهول ليس بحدة السيف، بل بصلابة الموقف، بينما كانت الغابة من حولهم تبتلع أصواتهم في صمت رهيب.', '', 188, '2026-07-15 15:18:12.022', '2026-07-15 15:18:12.022');
INSERT INTO public.chapters VALUES ('439fd2de-0357-4730-868e-4002e7fe8ce5', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 190: صدعُ التوقعات', '— --------------------------------------- توقفت حركة العربات تحت وهج الشمس التي بدأت تميل نحو المغيب. ألقى ثورفين نظرة فاحصة على الأفق، حيث تختبئ التلال خلف ضباب خفيف. لم يكن الصمت الذي يلف المكان باعثاً على الطمأنينة، بل كان صمتاً مشحوناً بتوقعات خائبة. اقترب ''إينار'' منه، تمسح يداه الغليظتان جبينه المبلل بالعرق، ثم قال بصوت متحشرج: هل نواصل المسير؟ إن الأرض هنا لا توحي بالأمان، والرجال بدأوا يتململون. هز ثورفين رأسه بالنفي، وعيناه لا تزالان معلقتين بحدود الغابة. لم يجبه، بل اكتفى بالإشارة نحو المتمردين الذين بدأت تتسارع وتيرة حركتهم في الجانب الآخر. كان التوتر يطفو فوق الوجوه؛ بعضهم كان يحدق في الأرض، وآخرون كانوا يقبضون على مقابض سيوفهم حتى ابيضت مفاصل أصابعهم. اقترب ''هيلد'' بخطوات واثقة، وجهها كان كقناع من حجر، وقالت بنبرة حادة ومقتضبة: ثورفين، إنهم ليسوا هنا للسلام. انظر إلى كيفية اصطفافهم. لاحظ ثورفين بؤبؤي عينها اللذين ضاقا فجأة، ثم التفت ليرى ''إيفار'' يندفع نحوهم، وجهه محتقن بالدم. صرخ ''إيفار'' بحدة: ما الذي ننتظره؟ إنهم يحيطون بنا! إننا نضع رقابنا تحت سكاكينهم! لم ينفعل ثورفين. زفر نفساً طويلاً، وشعر بثقل المسؤولية يضغط على كتفيه كصخرة صماء. أجابه بهدوء مريب: التراجع يعني الحرب، يا إيفار. أريد أن أرى ما إذا كان هناك مساحة للكلام، ولو لمرة واحدة. بصق إيفار على الأرض وضحك بسخرية لاذعة: الكلام؟ هل تحاول أن تغني للذئاب؟ إنهم لا يرون فينا سوى غزاة. انقبضت عضلات فك ثورفين، وخطا خطوة واحدة نحو الأمام، متجاهلاً إيفار تماماً. كانت نظراته تتبع القائد الذي بدأ يخرج من بين صفوف العدو، يده مستقرة ببرود على مقبض نصله. في تلك اللحظة، خفت حدة ضجيج الرياح، وتركّز كل شيء في ذلك الفضاء الفاصل بين الفريقين. رفع ثورفين يده، ليس للقتال، بل لفرض صمت مطبق. كان يعلم أن أي حركة متهورة الآن ستجر الجميع إلى منحدر من الدماء التي لم يكن يرغب في سفكها. قال بصوت مسموع، خاوٍ من الرعشة: لست هنا للقتال. لست هنا لأخذ أرضكم. ساد صمت مفاجئ، لم يقطعه سوى صهيل خيل بعيد. تلاقت الأنظار، واشتبكت التوقعات في هواءٍ صار ثقيلاً كأنفاس رجل يلفظ أنفاسه الأخيرة، وبدا أن الهاوية التي تفصل بين الفريقين قد بدأت تتسع، لا بالمسافة، بل بالفجوة التي لا ردم لها بين عقول متمسكة بالخوف وقلوب تحاول كسر دائرة الانتقام.', '', 189, '2026-07-15 15:18:12.217', '2026-07-15 15:18:12.217');
INSERT INTO public.chapters VALUES ('4c4ed807-996e-4f16-9191-42f10f1e6ad0', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 191: نذير العاصفة في فينلاند', '— --------------------------------------- توقف ثورفين عن التجديف، ليس لأن التعب نال من ذراعيه، بل لأن الصمت الذي خيم على الخليج كان ثقيلاً، غير طبيعي. التفت إيفار نحوه، كانت عيناه تتفحصان الأفق بضيق، ويده تتحسس مقبض سيفه القصير بعصبية. قال إيفار بصوت خشن: ثورفين، الأرواح في الغابة ساكنة أكثر من المعتاد. لم يجب ثورفين، بل اكتفى بمسح العرق عن جبينه. كانت أصوات الطبيعة التي اعتادوا عليها - زقزقة الطيور، حفيف الأشجار - قد تلاشت تماماً، تاركةً مكاناً لضجيج داخلي ينم عن شيء قادم. هيلد كانت تقف في مقدمة القارب، قوسها مشدود بوضوح رغم عدم وجود هدف مرئي، وبصرها الحاد يخترق ضباب الشاطئ. تحركت شفة ثورفين قليلاً قبل أن يهمس: هناك تجمعات. ليست حيوانات. كان يعلم أن التوسع في تلك الأرض لن يمر دون ثمن، وأن السلام الذي ينشده ليس سوى هدنة مؤقتة تسبق صراعاً دموياً يلوح في الأفق. انقبضت كف ثورفين على خشب المجداف حتى ابيضت مفاصل أصابعه. لم يكن خائفاً، بل كان يشعر بعبء القرار الذي اتخذه؛ قرار البقاء دون قتال في أرض يحكمها منطق القوة. نادى هيلد بهدوء: ضعي القوس، لسنا هنا للقتل. ردت هيلد دون أن تلتفت، وبصوت بارد كقطعة ثلج: القوس هنا ليحميك من غبائك يا ثورفين، وليس لقتلك. ساد صمت مطبق، لم يقطعه سوى صوت ارتطام الأمواج الخافت بجانب القارب. في البعيد، بدأت ملامح رجال يظهرون بين الأشجار، أجسادهم مغطاة بجلود الحيوانات، وأيديهم مشغولة برماح بدائية لا تخطئ الهدف. لم تكن نظراتهم تحمل الحقد بقدر ما كانت تحمل التحذير. أدرك ثورفين في تلك اللحظة أن حلمه لا يزال في المهد، وأن الأرض التي اختاروها للعيش بسلام قد تكون هي نفسها مقبرة هذا الحلم، إذا لم يجد الطريقة الصحيحة للحديث مع هؤلاء الذين يرون في وجود المستوطنين تعدياً لا يغتفر على نواميسهم. رمى ثورفين المجداف أرضاً، ووقف بوضوح على سطح القارب، ورفع يديه فارغتين، دلالة على سلميته، بينما كان أنفاسه منتظمة بشكل مدروس لتخفي اضطراباً بسيطاً في قلبه.', '', 190, '2026-07-15 15:18:12.476', '2026-07-15 15:18:12.476');
INSERT INTO public.chapters VALUES ('c660b5cf-7ddc-4670-a097-50c8792bd59e', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 192: صدى الرحيل في أرض الميعاد', '— --------------------------------------- ارتطمت أمواج فينلاند بجسد السفينة الخشبية كأنها ترفض هذا الغزو الصامت. ثورفين يقف على مقدمة المركب، يحدق في الأفق حيث تتلاشى الغابات الخضراء في ضباب الغسق. خلفه، كان صوت إيفار يمزق سكون المكان، صرخته المكتومة بالتوتر تتردد في أرجاء السفينة: ثورفين، هل تعي ما تقترفه؟ إنها ليست مجرد رحلة عودة، بل إعلان هزيمة. التفت ثورفين ببطء، عيناه الغائرتان لا تحملان ذرة تردد، ملامحه التي حفرها الزمن والحروب ظلت جامدة كصخرة في وجه العاصفة. لم يجب بكلمة، بل اكتفى بإيماءة خفيفة إلى رفاقه ببدء الإبحار. كان هيلد تراقب المشهد من الزاوية، يدها تتحسس نصل سلاحها بآلية باردة، وعيناها تلاحقان كل حركة لثورفين، كأنها تحاول قراءة المستقبل في تجاعيد وجهه. صمتت البحار فجأة، وانقطع لغط الرجال، وكأن الجميع أدركوا أن هذه اللحظة تضع حدًا لفصل كامل من حياتهم. اقترب إيفار منه، قبضته محكمة على مقبض سيفه، وصوته يرتجف من غيظ مكبوت: نترك أرضنا؟ نترك كل ما بنيناه لأنك قررت أن السلام هو الحل الوحيد؟ رمقه ثورفين بنظرة خاطفة، ثم عاد ببصره إلى البحر، متجاهلاً نبرة التحدي في صوت رفيقه. لم تكن فلسفة أو خطابًا أخلاقيًا، بل كانت ثقل التجربة التي تجعل الكلمات تبدو بلا جدوى. في تلك اللحظة، لم تعد فينلاند مجرد أرض للزراعة، بل تحولت إلى فكرة معلقة في الفراغ، يطاردهم ظلها في كل اتجاه. انطلقت السفينة تشق الماء بقوة، تاركة خلفها بقايا الحلم القديم، بينما وقف ثورفين، قبطان بلا وجهة سوى الفراغ الذي ينتظره في الأفق، تاركاً إيفار ورفاقه يغرقون في تساؤلاتهم التي لن تجد جواباً بين أمواج البحر المتلاطمة.', '', 191, '2026-07-15 15:18:12.664', '2026-07-15 15:18:12.664');
INSERT INTO public.chapters VALUES ('d74d64c8-50f5-46ba-b21c-d89ef48e5143', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 193: أصداء الأمس وقيد المدى', '— --------------------------------------- انغرس نصل الفأس في جذع الشجرة بضربة واحدة جافة، أحدثت رنيناً مكتوماً في صمت الغابة. لم يلتفت ثورفين، بل ظل يراقب أثر النصل في الخشب، عروقه بارزة على ظهر يده، وتواتر أنفاسه يشي بجهد ممتد. خلفه، وقف آيفار، يشد قبضتيه حول حزام سلاحه، عيناه تلاحقان تحركات ثورفين بريبة لا تخطئها العين. تحركت كف ثورفين لتلمس موضع الندبة على وجهه، حركة عفوية تسبق استدارته. قال آيفار بصوت خشن تشوبه نبرة تحدٍ مستفزة: هل تظن حقاً أن مجرد التلويح بكلمات السلام سيجعل هؤلاء المحاربين يلقون سلاحهم؟ إنهم لا يفهمون إلا لغة الحديد. لم يجب ثورفين فوراً، بل التقط قطعة خشب صغيرة، وبدأ يسنها بسكينه بحركات رتيبة. تجمدت ملامح ثورفين، واتسعت عيناه قليلاً قبل أن تستقر على آيفار. نطق ثورفين بنبرة هادئة ومقتضبة: القتال ليس خياراً، بل هو فشل في إيجاد مخرج آخر. رمق آيفار رفيقه باحتقار، وبصق على الأرض جانباً. أنت تتحدث كالحالمين، يا ثورفين، بينما نعيش في عالم يلتهم فيه القوي الضعيف. تقدم ثورفين خطوة، فجأة، وبحركة خاطفة كان قد أغلق المسافة بينهما، صوته انخفض ليصبح أشبه بهمس حاد: لم أعد ذلك الفتى الذي يسعى للموت، ولا أبحث عن المجد في ساحات الوغى. إذا كان بناء وطننا يتطلب دماءً إضافية، فقد خسرنا قبل أن نبدأ. تحركت عضلات فك آيفار بحدة، وتراجع خطوة إلى الوراء، لكنه لم ينبس ببنت شفة. في تلك اللحظة، قطعت صيحة بعيدة صمت المكان، صيحة لم تكن تحمل نذير حرب، بل نداء استغاثة أو ربما تحذيراً. التفت الاثنان نحو الأفق، حيث بدأت سحب رمادية تلوح في الأفق، تنذر بتغير في الطقس، لكن عيون ثورفين كانت ترصد شيئاً أبعد من الغيوم. لقد استشعر ثقلاً في الأجواء، شيئاً يشبه نذر المواجهة القادمة. وضع ثورفين سكينه، ومسح يديه في ثيابه، ثم سار بخطوات ثابتة نحو حافة المنحدر. قال ثورفين، وصوته يقطع الهواء كالسيف: سنلتقي بهم، وسنرى إن كانت أجسادهم قادرة على تلقي كلماتي، أو إن كان عليهم أن يختبروا صلابة قرارنا. لم تكن نبرته تحمل تهديداً، بل كانت تحمل يقيناً بارداً كالجبل. تابع ثورفين سيره، تاركاً آيفار في مكانه، يراقب ظهره المبتعد، بينما بدأت الرياح تشتد، حاملة معها نذر المجهول.', '', 192, '2026-07-15 15:18:12.838', '2026-07-15 15:18:12.838');
INSERT INTO public.chapters VALUES ('3c5ede1c-d9ec-46d2-8c48-4561a7d3cd09', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 194: ثمن العودة إلى الأرض المحرمة', '— --------------------------------------- تصاعدت أبخرة البحر المالح حين ارتطمت مقدمة السفينة بالرمال الضحلة لساحل فينلاند. قفز ثورفين إلى اليابسة، كانت قدماه تغوصان في التربة الرطبة، بينما ظلت عيناه معلقتين بظلال الأشجار الكثيفة التي تحتضن الأفق. خلفه، كان صوت تلاطم الأمواج يخفت ليحل محله حفيف أوراق الشجر، صمتٌ مريب لم يعهده في رحلاته السابقة. التفت إينار نحو ثورفين، كان وجهه شاحباً، وقد قبضت يده على مقبض فأسه بقوة جعلت مفاصل أصابعه تبرز بوضوح. قال إينار بصوت منخفض ومتقطع: لقد عادوا، ثورفين. التفت ثورفين برأسه ببطء، ليرى بضع عيون تترصد من بين الغابات، عيوناً لا تحمل الترحاب الذي كانوا يرجونه. لم تكن هناك كلمات، فقط وقع خطوات ثقيلة على الأغصان الجافة. تقدم ''هيد'' بخطوات واثقة، متجاهلاً التوتر الذي ساد المكان، ونظر مباشرة إلى القادمين. كان النزاع يلوح في الأفق، ليس كسيف يُشهر، بل كجدار من العزلة والانغلاق. حاول ثورفين رفع يديه، حركة بسيطة أراد بها إبداء حسن النوايا، لكن نظراتهم لم تلن. همس ثورفين لنفسه بينما كانت دقات قلبه تتسارع في صدره: لم آتِ للحرب. في تلك اللحظة، تعثر أحد الرجال المحليين، وسقطت خنجر خشبية من حزامه. ساد صمت مطبق. كان الهواء ثقيلاً، مشحوناً برائحة الطين والترقب. انحنى ثورفين ببطء، التقط الخنجر الخشبية، ومد يده بها إلى الرجل. لم تكن هناك فلسفة في تلك الحركة، كانت مجرد فعل بسيط من إنسان يواجه إنساناً آخر، بعيداً عن صخب السيوف وأوهام المجد. تراجع الطرفان خطوات للخلف، لكن التوتر ظل معلقاً في الهواء، خيطاً رفيعاً قد ينقطع في أي لحظة. نظر ثورفين إلى أفق فينلاند، أدرك حينها أن حلمه بإنشاء أرض بلا سلاح ليس مجرد خطوة على الرمال، بل هو مسيرة طويلة في طريق موحش، طريق يرفض فيه الانصياع لمنطق الدم الذي طالما طارده في ماضيه.', '', 193, '2026-07-15 15:18:13.018', '2026-07-15 15:18:13.018');
INSERT INTO public.chapters VALUES ('e050a0e0-b4e1-470a-81bd-a1ea436045e6', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 195: بقايا العهد في ممر الرحيل', '— --------------------------------------- توقف ثورفين عن الحركة. لم يكن الصمت في الغرفة فراغاً، بل كان ثقلاً مادياً يضغط على أنفاس الجميع. أمام عينيه، كان إيفار يقف متمسكاً بسيفه، مفاصل أصابعه بارزة تحت الجلد بفعل قبضته القاسية، وعروق رقبته نابضة بوضوح كأنها تعلن عن انفجار وشيك. التفت ثورفين ببطء، لم تكن حركته تحمل استسلاماً، بل كانت هدوءاً يسبق عاصفة من الحوار الصعب. قال ثورفين بصوت متهدج لكنه ثابت: إن طريق السيف لم يجلب لنا سوى المزيد من القبور يا إيفار. رد عليه إيفار، وصوته يخرج كحشرجة من صدره: هل تعتقد أن النوايا الطيبة ستحمينا حين نكون في مواجهة الموت؟ إنك تتحدث كمن يعيش في حلم، بينما الواقع يغرق في دماء إخوتنا. لم يتردد ثورفين في الاقتراب خطوة، مخترقاً المسافة المكهربة بينهما، وقال بكلمات تقطر مرارة: القتل ليس حلاً، بل هو دوامة تبتلع الجميع، وأنا لن أسمح بأن نكون وقوداً لنيرانها مجدداً. اتسعت عينا إيفار للحظة، وبرزت تجاعيد الغضب حول عينيه، لكنه لم يهاجم، بل تراجع خطوة إلى الوراء، تاركاً السيف يرتطم بالأرض بضجيج معدني مزق سكون الغرفة. في زاوية المكان، كانت نظرات المتابعين تترنح بين الخوف والترقب، بينما ظلت ملامح ثورفين محفورة في وجدانهم كصخرة واجهت أمواجاً عاتية ورفضت الانكسار. لم يضف ثورفين كلمة أخرى، بل استدار ليخرج، تاركاً إيفار يغلي في صمت مريب، بينما كان الحاضرون يتبادلون نظرات الحيرة، مدركين أن شيئاً ما في توازن القوى قد انكسر إلى الأبد، وأن هذه اللحظة لم تكن مجرد جدال عابر، بل كانت إعلاناً لنهاية حقبة من الدماء.', '', 194, '2026-07-15 15:18:13.203', '2026-07-15 15:18:13.203');
INSERT INTO public.chapters VALUES ('7d8b560f-f6fd-4318-a3e0-d673b5659519', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 196: صدى الرحيل في فينيسلاند', '— --------------------------------------- ارتطمت أمواج المحيط بجوانب السفينة الخشبية كأنها تحاول انتزاع اعتراف بالبقاء. وقف ثورفين على سطح السفينة، عيناه مثبتتان على الأفق حيث تذوب زرقة السماء في رمادية الماء. لم تكن الرحلة مجرد عبور بحري، بل كانت انسلاخاً من ماضٍ طاردته نيرانه لسنوات. بجانبه، كان إينار يراقب انحناءات الخشب، وجهه يحمل أثراً واضحاً لليلة من الأرق. استدار ثورفين نحوه، ملامحه جامدة كصخرة نحتتها الرياح، وقال بصوت خفيض: سنصل قريباً. رد إينار دون أن ينظر إليه، صوته مشوب بحذر دفين: الأرض التي وعدت بها، هل هي حقاً خالية من الظلال التي خلفناها؟ لم يجب ثورفين فوراً، بل نظر إلى يديه اللتين اعتادتا حمل السلاح، ثم قبض عليهما بقوة حتى برزت عروقهما. الصمت بينهما لم يكن فراغاً، بل كان ثقلاً يغلف مساحة السفينة. على الجانب الآخر من المكان، كانت هيلد تراقب المشهد من مسافة، يدها تستقر فوق قوسها، أصابعها تتحرك لا إرادياً على الوتر. كانت تدرك أن الوصول إلى فينيسلاند ليس غاية، بل بداية لصدام جديد مع الطبيعة والإنسان. فجأة، تعالت أصوات البحارة في المقدمة؛ رصدوا شيئاً وسط الضباب. لم تكن صخوراً، بل كانت ملامح يابسة بدأت تتشكل كخطوط غامضة في الأفق. تغير إيقاع السفينة، وبدأ الخشب يصدر أصواتاً أكثر حدة مع تلاطم الأمواج الضحلة. التفت ثورفين إلى طاقمه، لم يلقِ خطابات حماسية، بل أومأ برأسه فقط. كان يدرك أن كل رجل على هذه السفينة يحمل ندبة لا يراها أحد، وأن الوصول إلى هناك يعني البدء في نسيان كيف يكون المرء محارباً. تقدمت السفينة مخترقة الضباب، وانكشفت غابات شاسعة لم تلمسها أقدام الغزاة من قبل. وقف الجميع في صمت مهيب، ساد المكان هدوء غريب لم يقطعه سوى صوت ارتطام المرساة بقاع المياه الضحلة. لقد وصلوا، لكن السؤال الذي ظل معلقاً في هواء فينيسلاند البكر كان: هل يملك هؤلاء الرجال القدرة على البقاء دون أن يلوثوا الأرض بدماء جديدة؟ نزل ثورفين إلى الماء، برودة الموج اخترقت جلد ساقيه، لكنه لم يتراجع. غرس قدميه في الرمل الخشن، ونظر إلى الأشجار العالية التي تلوح كأنها تراقب الغرباء. بدأت الرحلة الآن فقط، بعيداً عن أشباح القارة القديمة.', '', 195, '2026-07-15 15:18:13.376', '2026-07-15 15:18:13.376');
INSERT INTO public.chapters VALUES ('878c88eb-3af3-417e-a46a-c8d3d1eb900a', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 197: نذير العاصفة في فينلاند', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في تربة فينلاند الرخوة، ونظره معلق بذلك الأفق الذي بدأ يضيق بفعل غبار الخيول المندفعة. لم تكن صرخات التحذير التي أطلقها المستوطنون مجرد ضجيج، بل كانت نذيراً لصدام بات لا مفر منه. التفت ثورفين نحو إيفار، الذي كان يشد قبضته على مقبض سيفه حتى ابيضت مفاصل أصابعه، وعروق عنقه بارزة كأنها ستنفجر من فرط الاحتقان. قال ثورفين بصوت منخفض، جاف، وخالٍ من أي رغبة في القتال: تراجعوا، لا ترفعوا أسلحتكم، هذا ليس طريقنا. رد إيفار وقد زفر نفساً حارقاً ينم عن غضب مكبوت: هل ننتظر ذبحنا؟ إنهم يزحفون نحونا كالجحيم ذاته. لم يجب ثورفين، بل تقدم خطوة نحو حافة الغابة، جسده مشدود كوتر قوس، وعيناه تراقب بؤر التوتر في وجوه المحاربين المندفعين نحوهم. كانت المسافة بين الفريقين تتلاشى، وصوت حوافر الخيول يقرع الأرض بعنف، مسبباً ارتجاجات خفيفة تحت أقدام المستوطنين المرعوبين. وسط هذا الصخب، بدت ملامح ثورفين صخرية، لا يكسوها خوف، بل تركيز حاد يحلل كل حركة للعدو. لمح ثورفين القائد في الجانب الآخر؛ كان وجهه مخضباً بصبغة الحرب، وعيناه لا تحملان إلا رغبة واحدة: الإبادة. لم يكن هناك وقت للخطابات أو الفلسفة، فالخطر المادي كان يزحف كالأفعى، يحيط بهم ويضيق الخناق. التفت ثورفين خلفه، ونظر في عيون رفاقه الذين تملكتهم الحيرة؛ البعض ألقى سلاحه بطلب منه، والبعض الآخر كان يرتجف، متمسكاً بحديده كأنه طوق نجاة. ببرود مفاجئ، وبحركة خاطفة، نزع ثورفين رداءه وألقاه جانباً، فاتحاً ذراعيه في تحدٍ صامت. لم تكن هذه حركة استسلام، بل كانت إعلاناً أن جسده سيكون هو الجدار الذي سيوصد الباب أمام حمام الدم القادم، مهما كان الثمن. حين وصلت طليعة الخيول إلى مسافة قريبة جداً، بحيث صار بوسعهم رؤية ذرات الغبار العالقة على ملابسهم، رفع ثورفين يده، ليست للقتال، بل لفرض صمت مطبق خيم على المكان، صمت تخلله فقط أنفاس الخيول اللاهثة وصليل الدروع المرتجف.', '', 196, '2026-07-15 15:18:13.562', '2026-07-15 15:18:13.562');
INSERT INTO public.chapters VALUES ('f15f688f-93fc-4a2b-8e2d-ade7d5299468', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 198: حين تصمت الأسلحة', '— --------------------------------------- انتصبت خيام المستوطنين في فينلاند تحت سماء رمادية ثقيلة، لم يكن ثورفين ينظر إلى الأفق، بل كان يحدق في يديه الخشنتين، عروقهما بارزة كجذور شجر عتيق. صوته خرج أجشاً حين خاطب الرجال الذين تحلقوا حوله، لم تكن هناك خطب رنانة، بل كلمات مقتضبة كأنها حجارة تُلقى في بئر: لن نقاتل. نظر إليه أحد المستوطنين، وجهه محتقن بالدماء، وصدره يعلو ويهبط بوتيرة متسارعة، صرخ بنبرة مشروخة: هل نترك أرضنا للغزاة؟ أجابه ثورفين دون أن يرمش، ملامحه جامدة كتمثال منحوت من صخر، لم يقل إنها جريمة أو خطيئة، بل قال جملة واحدة: القتال يعني نهاية كل شيء. كان الهدوء في المكان مريباً، لا صوت سوى تكتكة خشب يتمدد بفعل البرودة ونباح كلب بعيد. التفت إينار إلى رفاقه، ملامحه تعكس مزيجاً من الحيرة والاعتراف بمرارة الواقع، لم يكن هناك مفر من خيار ثورفين المر. اقترب المحاربون من حدود المستوطنة، وقع أقدامهم على الأرض الرطبة كان صدىً لشيء قديم لا يريدون العودة إليه. ثورفين لم يستل سيفاً، ولم يتخذ وضعية دفاع، بل تقدم نحو صفوف الرجال المسلحين بصدور عارية من الحديد. ساد صمت مطبق، لم يعد يُسمع سوى خفقان القلوب المذعورة. حين وصلت نصل الحربة إلى قرب عنقه، توقف المهاجم، ارتعشت يده التي كانت تقبض على المقبض بوضوح، تلاقت النظرات؛ عينان ثاقبتان كأنهما تبحثان عن انعكاس لجنون الحرب في عيني ثورفين، لكنهما لم تجدا سوى فراغٍ عميق لا قاع له. لم يصرخ ثورفين، ولم يطلب الرحمة، اكتفى بالوقوف منتصباً، كتفاه مفرودتان كأنه يغرس جذوراً في هذه الأرض التي اختارها وطناً. ارتبك المهاجمون، بدأت صفوفهم بالاضطراب، فالعدو الذي لا يقاوم لا يمنحهم متعة النصر التي يشتهونها. تراجع أحدهم خطوة إلى الوراء، ثم تبعه الآخر، بينما ظل ثورفين واقفاً، ثابتاً كالجبل الذي لا يبالي بمرور العواصف.', '', 197, '2026-07-15 15:18:13.789', '2026-07-15 15:18:13.789');
INSERT INTO public.chapters VALUES ('26c865b1-f227-40e2-bcd1-74252beda422', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 199: أصداءُ الأرض البعيدة', '— --------------------------------------- انزاح الغبار عن وجوه المستوطنين، مخلفاً خطوطاً داكنة على بشرة شحبها طول الطريق. ثورفين وقف في طليعة الجماعة، عيناه تمسحان الأفق الأخضر الممتد خلف شاطئ فينلاند. كان الصمت ثقيلاً، مشحوناً بتوقعات الرجال الذين وضعوا حياتهم بين يدي وعوده. نظر إلى إينار الذي كان يتفحص تربة الأرض بيدين خشنين؛ لم تكن تلك مجرد تربة، بل كانت وعداً بالبقاء. اقترب منه هيلد، ظلت يدها قريبة من سلاحها، ملامحها الصلبة لا توحي بالاطمئنان. التفت ثورفين نحو إينار قائلاً بصوت خافت لم يكسر حدة الهدوء: هذه ليست أرض الملوك، ولا ساحة للسيوف. هنا، الصراع الوحيد الذي ينتظرنا هو صراع الجذور مع الحجارة. لم يلتفت إينار، بل قبض على حفنة من التراب ورفعها لتمتزج بريح المساء، ثم أجاب بنبرة تشوبها ريبة مكتومة: الأرض لا تفرق بين دم الملك ودم الفلاح، لكنها ستطالبنا بضريبتها يا ثورفين. الوعود التي قطعتها لهم ليست مجانية. وقف ثورفين جامداً، أصابعه تفرك شحمة أذنه، حركة لا إرادية رافقته منذ سنوات الشتات. لم يعقب، فالحوارات حول المصير أصبحت تنهكه. على بعد أمتار، كان الرجال يبدأون بإنزال الأخشاب والمؤن. الأصوات كانت مكتومة، تتصاعد مع صرخات الطيور البحرية التي كانت تراقب المشهد من علٍ. هيلد تقدمت خطوة، حدقت في ثورفين، ونبرة التشكيك لا تزال تكسو كلماتها: أنت تبحث عن مكان لا يصله سيفك القديم، لكنك تحمل ندوب الماضي في مشيتك. هل تظن حقاً أن النسيان يبدأ من هنا؟ توقف ثورفين عن الحركة. دار بجسده ببطء ليواجهها، بؤبؤا عينيه اتسعتا قليلاً قبل أن تستقرا على حدة باردة. لم يبتسم، ولم يحاول تلطيف العبارة. قال مقتضباً: أنا لا أبحث عن النسيان، بل عن المسافة التي تجعل الألم غير ذي صلة. إذا كان السيف هو رفيقي القديم، فالمعول هو رفيقي الجديد. لا تعبثي بظلال الماضي، فالشمس هنا كافية لإحراقنا جميعاً. ساد صمت مطبق إلا من صوت ارتطام الخشب بالرمال. كان الجو ينبئ بتغير في الطقس، الغيوم بدأت تتكدس فوق التلال البعيدة كجيوش صامتة. إينار وقف أخيراً، نفض يديه من الغبار وقال بصوت أجش: ستبدأ العمل غداً. لا يهم ماضينا، بل المهم أن ينام هؤلاء الرجال الليلة ببطء دون أن يرتجفوا من صوت الرياح. أومأ ثورفين برأسه. في تلك اللحظة، لم يكن هناك أبطال أو محاربون، كان هناك فقط رجال متعبون يقفون على حافة عالم جديد، يحاولون بجهد جهيد أن لا يتركوا ذواتهم القديمة تتبعهم إلى هذا الشاطئ.', '', 198, '2026-07-15 15:18:13.969', '2026-07-15 15:18:13.969');
INSERT INTO public.chapters VALUES ('1b1ec86d-7866-4bc0-8002-60ab1eaa5676', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 200: صدى الرحيل في فينلاند', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في تربة فينلاند الرطبة، بينما ظلت عيناه مثبتتين على الأفق حيث تلاشت ملامح السفينة المبحرة بعيداً. لم يكن الصمت الذي يحيط به هدوءاً، بل كان ثقلاً يضغط على صدره، مشبعاً بصوت تلاطم أمواج المحيط التي تبعده الآن عن كل ما كان يعرفه. التفت إيفار نحوه، كانت ملامح وجهه مشدودة، وعيناه تعكسان ارتياباً لا يخفيه. قال إيفار بصوت خشن: ''لقد رحلوا، والآن نحن هنا، وحدنا مع هذه الأرض التي لا نعرف كيف تروضنا''. لم يجب ثورفين فوراً، بل نظر إلى يده التي كانت تضغط على مقبض سيفه قبل أن يتركها ببطء، وكأنما يتخلص من عبء ثقيل. قال ثورفين بصوت مقتضب وحاد: ''نحن لا نحتاج لترويض الأرض، بل نحتاج لأن نتعلم كيف نعيش معها دون أن نكسرها''. ضحك إيفار بسخرية، وهي ضحكة جافة لم تصل إلى عينيه، ثم بصق على الأرض وقال: ''فلسفاتك لن تطعمنا في الشتاء القادم يا ثورفين. القوة هي اللغة الوحيدة التي يفهمها هذا العالم''. استدار ثورفين بعيداً عن إيفار، كانت خطواته موزونة، ثابتة رغم الإرهاق الذي بدأ يتسرب إلى مفاصله. لم يلتفت للرد، بل اكتفى بقول: ''القوة تجلب الدم، والدم يجلب المزيد من الدم. لقد انتهى عهدي بهذا المسار''. كان هيلد تقف على مقربة، تراقب المشهد بصمت مطبق، عيناها تتابعان كل حركة بحذر صياد. لم تتحدث، لكن يدها تحركت تلقائياً نحو قوسها، وكأن غريزتها ترفض الاسترخاء في هذا المكان الجديد. كان الهواء يحمل رائحة الرطوبة والأوراق المتساقطة، وهي روائح لم تكن مألوفة تماماً لثورفين، لكنها بدت له كبداية لشيء غامض وموحش في آن واحد. استمرت الأيام التالية في بناء المستوطنة، حيث كانت أصوات الفؤوس تقطع سكون الغابة. لم يكن العمل سهلاً، وكان الجهد البدني كفيلاً بجعل الجميع ينسون الفلسفة والانشغال بالبقاء. في المساء، حينما كان الظلام يلف المكان، كان ثورفين يجلس بمفرده أمام نيران مخمدة، يراقب تراقص الشرر. لم تكن في ذهنه صوراً للماضي، بل كان يرى فقط التحديات التي تنتظرهم في الغد. لقد أدرك أن العزلة عن العالم لا تعني بالضرورة العزلة عن الصراعات، وأن فينلاند ليست جنة موعودة، بل هي ساحة أخرى لاختبار قدرته على التمسك بمبدئه الذي نذر حياته له.', '', 199, '2026-07-15 15:18:14.324', '2026-07-15 15:18:14.324');
INSERT INTO public.chapters VALUES ('8d8d7a06-9425-4a7c-9d90-3ffff45fb1b3', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 201: أصداء الرماد في فينلاند', '— --------------------------------------- توقف ثورفين عن الحركة. لم تكن الغابة صامتة، بل كانت تعج بحفيف لم يعهده من قبل، صوتٌ يشي بأن المكان الذي لطالما اعتبره ملاذاً بات الآن مسرحاً لتمزق الهدوء. تطلعت عيناه نحو الأفق حيث تلوح طلائع الفوضى، لم تكن مجرد نذير خطر، بل حقيقة دامغة تقتحم بساطة حياته الجديدة. بجانبه، وقف إينار، قبضتاه مقبوضتان بقوة حتى تلونت مفاصل أصابعه بالبياض، وعيناه لا تغادران مسار الدخان المتصاعد من جهة المستوطنة. قال ثورفين بنبرة جافة لا تحمل تأثراً بل ترقباً حاداً: ''لا تتراجع يا إينار. المسافة بيننا وبينهم بدأت تتقلص''. لم يجب إينار، بل أطلق زفيراً محتقناً، وتحركت عضلات رقبته بتوتر واضح. لم يكن ثورفين بحاجة إلى خطابات مطولة ليقيس حجم الكارثة؛ فرائحة الأخشاب المحترقة التي بدأت تتسلل إلى أنوفهم حطمت كل وهم بالسلام. التفت ثورفين نحو رجاله، كانت ملامحه حجرية، لا تعتريها ذرة من التردد الذي يغشى الضعفاء، بل تركيزاً صلبًا كشفرة سيف لم يصدأ. صاح بكلمات مقتضبة، صريحة، وخالية من أي زخرفة خطابية: ''احموا النساء، ولا تقتربوا من خط النار إلا إذا جاءكم أمري''. تحرك الرجال في صمت مطبق، مطيعين لبروده القاتل. في تلك اللحظة، لم يعد ثورفين ذلك الحالم الذي يطارد سراب السلام، بل صار رجلاً يدرك أن الحقيقة الوحيدة المتبقية هي الحفاظ على ما تبقى من أطلال حلمه. وعندما برز المهاجمون من بين الأشجار، لم يرتجف ثورفين، بل انحنى قليلاً إلى الأمام، متخذاً وضعية الاستعداد التي صقلتها سنون من القتال الضاري، وعيناه تلاحقان تحركات الخصم بدقة جراح لا يخطئ. التقت نظراته بقائد الغزاة، لم يكن هناك حوار، بل تواصل صامت مشحون بالعداء البدائي. رفع ثورفين يده إشارةً للثبات، بينما كان نبضُه يقرع في صدره كطبول حرب لا ترحم. الزمن الذي توقف للحظةٍ خاطفة، سرعان ما استعاد زخمه مع أول صرخة اخترقت سكون المكان، معلنةً أن فينلاند لم تعد أرض الأحلام الموعودة، بل ساحة اختبارٍ لقدرة المرء على الحفاظ على مبادئه وسط جحيم الواقع.', '', 200, '2026-07-15 15:18:14.515', '2026-07-15 15:18:14.515');
INSERT INTO public.chapters VALUES ('ba60c3d9-136e-47e0-b56e-704f2006ee24', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 202: ثمن العودة إلى الديار', '— --------------------------------------- توقفت حركة العربات في القافلة لبرهة، وانعكس صمت المكان على وجوه المستوطنين الذين أنهكهم طول المسير. نظر ثورفين إلى الأفق، حيث كانت الغابات الكثيفة في فينلاند تلوح كحائط أخضر لا نهاية له، تبتلع ضوء النهار. اقترب هيلد منه، وقد كانت عيناها تراقبان حركة الظلال بين الأشجار بحدة، ثم قالت بصوت منخفض: «الجميع متعب، ثورفين. لم نتوقف منذ مطلع الفجر». التفت ثورفين إليها، ولمعت في عينيه بقايا إرهاق خفي، لكنه هز رأسه بالنفي. لم يكن الوقت مناسباً للراحة، ليس هنا، حيث التربة لا تزال غريبة والمسارات مجهولة. على الجانب الآخر، كان إينار يحاول تثبيت إحدى العجلات التي تضررت من جراء الاصطدام بجدع شجرة. كان يتصبب عرقاً، وقد اتسخت ملابسه بدمج الطين بالأرض العذراء. نظر إينار نحوهما قائلاً بلهجة جافة: «هذه الأرض لا ترحب بنا، ثورفين. كلما تقدمنا، زادت العقبات التي تبتلع قوانا». لم يدم الصمت طويلاً؛ فمن بين الأشجار المتشابكة، ظهرت حركة غير طبيعية، انقبضت كف ثورفين على قبضة خنجره دون أن يسحب نصله. لم يكن الخوف هو الدافع، بل التأهب الفطري الذي اكتسبه من سنوات الحرب الطويلة. قال ثورفين بصوت حازم موجه لرجاله: «أبقوا السلاح قريباً، لكن لا ترفعوه إلا إذا طُلب منكم ذلك». في تلك اللحظة، برز أحد سكان المنطقة الأصليين من بين أوراق الشجر، متوقفاً على مسافة آمنة. تبادل ثورفين والنظرات مع الرجل، كانت نظراتهما تحمل حذراً متبادلاً، لغة صامتة لا تحتاج إلى ترجمة. اقترب ثورفين خطوة واحدة، باسطاً كفيه أمام صدره ليؤكد خلوهما من السلاح، وقال بنبرة هادئة ومباشرة: «نحن هنا للعيش بسلام، لا لنبني أسواراً حول أطماعنا». لم تكن هناك كلمات منمقة، فثورفين لم يعد ذلك الفتى الذي يهذي بالشعارات، بل أصبح رجلاً يدرك أن الحقيقة تكمن في الحفاظ على هذا السلام الهش. انحنى الرجل الغريب برأسه قليلاً، ثم أشار إلى مسار جانبي، في إيماءة فهم ثورفين أنها طريق آمن لتجنب المستنقعات التي تعيق حركتهم. التفت ثورفين إلى إينار الذي وقف يمسح جبينه، وقال له: «اربط العجلة جيداً، الطريق لا يزال طويلاً، لكننا لن نلتفت للوراء». تابعوا السير تحت غطاء الشفق، حيث لم يعد الهدف مجرد الوصول، بل الحفاظ على جوهر إنسانيتهم وسط برية لا تعرف الرحمة.', '', 201, '2026-07-15 15:18:14.726', '2026-07-15 15:18:14.726');
INSERT INTO public.chapters VALUES ('5212cd9a-cb35-4e3c-be0d-c8e79303cf58', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 203: ثمن العودة إلى الديار', '— --------------------------------------- توقفت حركة العربات فجأة وسط الغبار المتصاعد، لتكشف عن وجه ثورفين المكتسي بملامح الإجهاد. لم يكن الطريق إلى فينلاند طريقاً معبداً بالوعود، بل كان صراعاً يومياً مع التضاريس والشكوك التي تنهش عزيمة الرجال. نظر ثورفين إلى الأفق، حيث تلوح أشجار الغابة كأنها جدار صامت يراقب تحركاتهم المتواضعة. اقترب منه إينار، مسحت يده العرق عن جبينه، وقال بصوت خافت يملؤه الترقب: هل نحن حقاً في المكان الصحيح؟ لم يجب ثورفين فوراً، بل اكتفى بمسح بصره للأرض، ثم قال بحدة: الأرض لا تكذب، لكننا قد نكذب على أنفسنا إذا ظننا أن السلام مجاني. تحركت المجموعة ببطء، محاولين تجاوز الصخور العالقة في الوحل. كان التوتر سيد الموقف؛ فكل خطوة كانت تزيد من حدة الأسئلة المكتومة في أعين المهاجرين الذين لم يعتادوا هذا الصمت الموحش. ثورفين لم يتوقف عن مراقبة محيطه، كانت يداه تقبضان على مقبض عربته بقوة حتى ابيضت مفاصل أصابعه. تذكر ثورفين كلمات والده القديمة، لكنه لم يجد في قلبه مكاناً للحكمة الآن؛ كان يرى فقط أرواحاً تنتظر منه القيادة، وواقعاً يضيق عليهم الخناق. وعندما تعثر أحد الثيران وسقط متخبلاً تحت ثقل الحمل، تعالت صرخات الرجال بالسباب واللعنات. اقترب ثورفين من الحيوان الساقط، وضع يده على رأسه المرتجف، وهدأ من روعه بحركة خبيرة، ثم التفت نحو رجاله وقال بنبرة مقتضبة: الصراخ لن يرفع الحمل، توقفوا عن الضجيج وأفرغوا بعض المتاع. انصاع الجميع لصوته؛ فلم يعد الرجل الذي يعرفونه من قصص الانتقام، بل قائداً يستمد هيبته من هدوئه اللافت في أشد لحظات الضياع. استأنفت القافلة مسيرها، وبينما كانت الشمس تميل نحو الغروب، تاركة ظلالاً طويلة تمتد خلفهم، تساءل ثورفين في قرارة نفسه عما إذا كان هذا ''الوطن'' سيقبلهم كما هم، أم أنهم سيظلون غرباء حتى في الأرض التي اختاروها بأيديهم.', '', 202, '2026-07-15 15:18:15.015', '2026-07-15 15:18:15.015');
INSERT INTO public.chapters VALUES ('120f96ef-eea1-41d5-8f4e-60f66cb286b4', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 204: صدى الصمت في أرض الميعاد', '— --------------------------------------- توقف ثورفين عن الحركة. كانت الأرض تحت قدميه في فينلاند تختلف عن أي تربة وطئها من قبل؛ رطبة، غنية، وتنبض بحياة لم يعكر صفوها صليل السيوف. إلى جانبه، وقفت غودريد تنظر إلى الأفق، أنفاسها منتظمة، بينما كان هيلد تتفحص المسافة بعينين لا تفوتان حركة طائر في الأغصان. لم يكن هناك أعداء هنا، لكن القلق كان خيطاً غير مرئي يربطهم جميعاً. التفت ثورفين نحو أتباعه، كانت يده ترتجف قليلاً وهو يمسح العرق عن جبينه. قال بنبرة مقتضبة: لا تتركوا السلاح بعيداً، لكن لا تستلوه إلا بأمري. كانت كلماته حادة، تخلو من الزينة البلاغية، تماماً كخشونة يديه. رد عليه أحد المهاجرين، رجل ذو ملامح متصلبة وشعر أشعث: نحن هنا لنزرع لا لنحصد الرؤوس يا ثورفين، لكن الغابة تبدو وكأنها تراقبنا. لم يجب ثورفين، بل اكتفى بإيماءة سريعة من رأسه. في تلك اللحظة، قطعت سكون الغابة حركة مباغتة في الأعشاب الكثيفة. تجمدت أعضاء المجموعة، وتحولت عيون هيلد إلى سهام موجهة نحو مصدر الصوت. خرجت شخصية من بين الأشجار، لم تكن تحمل سلاحاً، بل كانت ملامحها تحمل إرهاقاً يشبه إرهاقهم. الصمت الذي ساد المكان كان أثقل من أي صرخة حرب. حدق ثورفين في الغريب، لم تكن عيناه تعكسان رغبة في القتال، بل محاولة للفهم. اقترب الغريب خطوة واحدة، فرفع ثورفين يده ليوقف أي حركة دفاعية من رجاله. كانت الفلسفة هنا ليست كلمات مرصوصة في كتب، بل كانت هذا التردد العنيف في المبادرة بالهجوم، وهذا الضغط في الصدر الذي يفرضه قرار العيش بسلام وسط عالم لا يعرف سوى قانون الغاب. لم يسأل الغريب شيئاً، ولم يطلب ثورفين تبريراً؛ كانت نظراتهما كافية لرسم حدود اللقاء. انحنى ثورفين قليلاً، ليس خضوعاً، بل اعترافاً بوجود طرف آخر يشاركهم هذا المكان. عندما عاد المهاجرون إلى معسكرهم، كانت الشمس تميل نحو المغيب، تصبغ الأرض بلون دموي خافت، لكن ثورفين لم يلتفت للخلف. كان يعلم أن البناء في هذه الأرض يتطلب دماءً من نوع آخر، دماءً تبذل في العمل والانتظار، لا في الموت. جلس ثورفين على جذع شجرة سقطت بفعل الزمن، متأملاً في الأفق البعيد، حيث كانت آماله في تأسيس أرض خالية من الحرب تصطدم بواقع الطبيعة القاسي. لم يقل شيئاً، لكن انقباض فكه كان يشي بحجم المسؤولية التي يحملها بين كتفيه، مسؤولية الحلم الذي لا يزال يقاوم الانكسار.', '', 203, '2026-07-15 15:18:15.216', '2026-07-15 15:18:15.216');
INSERT INTO public.chapters VALUES ('0e23b809-c537-4d72-9fc6-698413feef94', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 205: صدى الرحيل في فينيكلاند', '— --------------------------------------- انزاح الغطاء عن وجه هيلد، كانت عيناها تحدقان في السقف الخشبي بكوخٍ لا يصله ضجيج الخارج. استقامت ببطء، مفاصلها تئن تحت وطأة الإجهاد المتراكم. تحركت يداها بآلية معتادة لتفقد تجهيزات القوس، أصابعها تتحسس نتوءات الخشب ببرود. ثورفين لم يكن هناك، كان صوته بالخارج يمتزج بضوضاء الرجال الذين ينصبون الخيام، نبرةٌ خافتة توحي بالثقل الذي يحمله في صدره. خرجت هيلد إلى الساحة؛ الأرض موحلة تحت أقدام المستوطنين، وأعينهم تحيد عن النظر المباشر. لم تكن المسافة بينها وبين ثورفين تتطلب أكثر من بضع خطوات، لكنها بدت كأنها تفصل بين عالمين. توقفت، راقبت تقاسيم وجهه الجانبية وهو يوجه الرجال حول إمدادات الطعام. لم تكن ثمة فلسفة في اللحظة، فقط جردٌ للأدوات المتبقية وخوفٌ صامت من الشتاء القادم. استدار ثورفين، التقت أعينهما؛ لم يبتسم، ولم تكن الحاجة تستدعي ذلك. قال بصوت مقتضب جاف: «لقد تحركت المجموعة الأولى نحو التلال الغربية. إذا لم نصل إلى هناك قبل الغروب، ستضيع المؤن في الوحل». أومأت هيلد برأسها، وانقبضت عضلات فكها. كان الرجل القادم من الشمال يدرك أن الكلام ترفٌ لا يملكه من يحاول بناء مستقبل من لا شيء. التفتت لتلحق بركبه، بينما كانت رياح خفيفة تداعب أطراف معطفها المهترئ، معلنةً عن تحول في الطقس سيجعل المهمة أصعب مما توقعوا. لم يكن هناك أعداء في الأفق، لكن الغابة كانت تمتد أمامهم كوحشٍ مترقب يرفض الترويض. مشيا جنباً إلى جنب دون حديث، الصمت بينهما لم يكن فراغاً، بل كان شاهداً على رحلة بدأت بالدماء وانتهت ببحثٍ مضنٍ عن الخبز والأمان.', '', 204, '2026-07-15 15:18:15.434', '2026-07-15 15:18:15.434');
INSERT INTO public.chapters VALUES ('b86a8d0a-2bbd-4103-9198-8bc8906fed6d', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 206: بذرة في أرض الشتات', '— --------------------------------------- انحنى ثورفين على تربة فينلاند، أصابعه القاسية تتغلغل في الأديم الرطب، يقلبها بحثاً عن إشارة حياة. كانت يداه، اللتان اعتادتا قبض مقبض الخنجر، الآن ملطختين بطين الأرض التي وعد نفسه بأن تكون ملاذاً لا حرب فيه. خلفه، وقف إينار يراقب بصمت، أنفاسه متلاحقة تحت وطأة العمل الشاق. لم يكن الصمت فراغاً، بل كان ثقيلاً بآمال معلقة على محصول لم يكتمل نموه بعد. ''ثورفين، إنهم قادمون''، نبس إينار بصوت أجش، دون أن يلتفت نحو الأفق حيث تلوح ظلال غير مرحب بها. لم يرتجف ثورفين، بل استقام ببطء، ممسحاً يديه في ثيابه الخشنة. استدار ليواجه الحقيقة التي لا مفر منها: الغرباء على حدود أرضهم لا يحملون في جعبتهم بذوراً للزراعة، بل حديداً للصدأ. تقدم رجل من بين الواصلين، ملامحه تعكس غطرسة المستعمر الذي يرى في كل أرض مفتوحة حقاً مكتسباً. حدق ثورفين في عينيه مباشرة، لم يكن في نظرة ثورفين غضب مقاتل قديم، بل صمود من لا يملك غير خيار واحد: حماية حلمه. قال الغريب بلهجة استعلائية: ''هذه الأرض لم تعد تكفيكم''. رد ثورفين بكلمات مقتضبة، نبرته خالية من التهديد ولكنها مشحونة بصلابة لا تلين: ''نحن لا نطلب قتالاً، لكننا لن نتخلى عن شبر واحد زرعناه بعرقنا''. كان الهواء في الساحة يتكثف، وتوترت عضلات الرجال الواقفين خلف ثورفين. لم يكن هناك حديث عن الفلسفة أو قيم السلام، بل كان كل شيء حاضراً في وقفة الجسد، في قبضة اليد التي ارتخت عن سلاح كانت لتمسك به لولا العهد الذي قطعه على نفسه. انحسر الضوء خلف الأشجار العالية، وأدرك الجميع أن ليلة الحسم قد بدأت دون صرخة حرب واحدة، بل بهدوء مرعب يسبق العاصفة، حيث الصراع لم يعد مجرد مسألة بقاء، بل مسألة إثبات أن الإنسان قادر على أن يكون شيئاً آخر غير وحش.', '', 205, '2026-07-15 15:18:15.62', '2026-07-15 15:18:15.62');
INSERT INTO public.chapters VALUES ('7be2f810-c154-47b8-8522-dfb3a4bb9a46', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 207: بذرة في أرض غريبة', '— --------------------------------------- انحنى ثورفين على التربة الداكنة، مغمساً أصابعه في ثراها المبلل بمياه الأمطار التي لم تكف عن الهطول منذ أيام. كانت الأراضي في فينلاند لا تشبه تلك القسوة الجليدية التي ألفها في موطنه، لكنها كانت تفرض شروطها الخاصة. إلى جانبه، وقف كارلي يراقب حركته بصمت، عيناه الصغيرتان تلاحقان بذور الشعير وهي تتوارى تحت طبقات الطين. التفت ثورفين، ماسحاً وجهه بكم قميصه الخشن، وقال بنبرة مقتضبة: هذا كل ما لدينا. إذا لم ينبت، فلن نملك ما نقتات عليه حين يشتد عزم الشتاء. لم يجب كارلي، لكن حركة كتفيه المترددة عكست قلقاً مكتوماً. في البعيد، كان صوت الفؤوس يرتطم بجذوع الأشجار يتردد كإيقاع منتظم، يعلن توسع المستوطنة المنهك. اقترب إيفار، ملامحه محتقنة بالغضب الذي بات يرافقه كظله، وألقى نظرة ازدراء على البذور الموزعة. تحدث إيفار بنبرة حادة ومتهكمة: نحن ننتظر المعجزات من حفنة بذور في أرض لا نعرف طبيعتها، بينما نترك أسلحتنا تصدأ في مخازنها. هل تعتقد أن النوايا الحسنة ستمتلئ بها بطوننا يا ثورفين؟ انتصب ثورفين واقفاً، كانت حركته هادئة وثقيلة، وتجاهل نبرة التحدي في صوت إيفار. نظر إلى أفق الغابة الكثيفة قبل أن يجيب ببرود: القتال لا يطعم أحداً يا إيفار، بل يورثنا القبور. هذه البذور هي رهاننا الوحيد على البقاء بعيداً عن حلقة الدماء التي فررنا منها. لم يتزحزح إيفار، بل ضيق عينيه وخطا خطوة أقرب: أنت تحلم بعالم لا وجود له، ونحن هنا لنحمي مكتسباتنا بالقوة التي نعرفها. لم يزد ثورفين على أن أدار ظهره، عائداً إلى عمله في غرس البذور، بينما بقي إيفار متسمراً في مكانه، يراقب الرجل الذي اختار المحراث على السيف، في صمت مشحون بتوتر لم يعد بالإمكان احتواؤه. الغيوم فوقهم كانت تتجمع ككتل رصاصية، تنذر بعاصفة قادمة، وفي تلك اللحظة، بدا أن المسافة بين رؤية ثورفين للسلام وبين واقع المستوطنة العنيف تتسع لتصبح هوة سحيقة لا قاع لها.', '', 206, '2026-07-15 15:18:15.8', '2026-07-15 15:18:15.8');
INSERT INTO public.chapters VALUES ('6b26caaa-1a13-474f-9691-81e70d42bf35', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 208: صدى السيوف في أفق فينلاند', '— --------------------------------------- توقف ثورفين عن الحركة. لم تكن الغابة صامتة كما يظن العابرون، بل كانت تعج بضجيج الحياة المتسارع تحت أقدامهم. نظر إلى غودريد التي تجمعت على وجهها علامات القلق، ثم التفت إلى الوراء حيث كانت الأطياف المتوهمة للماضي تطارده في كل زاوية. قال ثورفين بصوت مقتضب، خشن النبرة: ''ابق خلفي. لا تتقدمي خطوة واحدة''. كانت يده لا تزال معلقة في الهواء، لم يلمس مقبض سيفه، ولم يشعر برغبة في ذلك، رغم أن الأجواء كانت توحي بوقوع صدام وشيك. كان ثورفين يراقب تحركات المتربصين خلف الأشجار؛ ليسوا مقاتلين محترفين، بل أفراد يملؤهم الخوف والتردد. تنهد بعمق، ثم قال موجهًا كلامه للمجهول المختبئ: ''نحن لا نبحث عن قتال. لا نملك ما يغريكم، ولا نريد سلبكم ما تملكون''. لم يأتِ رد، بل تعمق الصمت حتى بات مسموعاً. وبينما كان ثورفين يقيس المسافات بعينيه، تذكر للحظة برود أسكلاد وتهكمه في مواقف مشابهة، لكنه طرد الفكرة. هو ليس أسكلاد، وهو لا يريد أن يكون. ''أريد التحدث مع زعيمكم''، أضاف ثورفين بلهجة حادة، متجاهلاً ارتعاش أصابع غودريد التي تمسكت بكتفه. خرج رجل من بين الظلال، ملامحه محفورة بندوب الزمن والحروب، يده تقبض على فأسه بقوة جعلت عروق ذراعه تبرز كأوتار مشدودة. لم ينبس الرجل ببنت شفة، بل اكتفى بتبادل نظرات حادة مع ثورفين. في تلك اللحظة، لم تكن هناك كلمات تعبر عن حقيقة الوضع؛ كان الأمر برمته يتلخص في تلك المسافة الضئيلة بين السلام والحرب. أمال ثورفين رأسه قليلاً، متخلياً عن وضعية الهجوم، وبدأ يخطو ببطء شديد نحو الرجل. قال ثورفين بصوت هادئ ومسموع: ''الحياة في هذه الأرض صعبة بما يكفي، لماذا نجعلها جحيماً لبعضنا؟ ''. تجمد الرجل في مكانه، متفاجئاً بقلة مبالاة ثورفين بوجود السلاح الموجه نحو صدره. انقبضت عضلات فك الرجل، لكن الفأس انخفضت سنتيمترات قليلة عن مستوى الهجوم. كانت تلك حركة صغيرة، لكنها في عرف المحاربين تعني الكثير. استدار ثورفين قليلاً ليؤكد لغودريد أن الوضع تحت السيطرة، بينما كان عقله يحلل كل احتمال ممكن. لم تكن فلسفة مثالية، بل كانت ضرورة بقاء. في فينلاند، الأرض التي حلم بها، لا مكان للدماء التي أريقت في الشمال. صمت الجميع، بانتظار الكلمة التي قد تشعل نيران الصراع أو تطفئها إلى الأبد.', '', 207, '2026-07-15 15:18:16.008', '2026-07-15 15:18:16.008');
INSERT INTO public.chapters VALUES ('c92923b3-f2f8-4857-b51b-61b9a81bd1b0', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 209: صدى النزوح في فينا', '— --------------------------------------- توقفت حركة العربات فجأة عند مشارف فينا، حيث بدا الأفق ملبداً بغبار العجلات الخشبية التي أنهكها طول الطريق. ترجل ثورفين، ماسحاً عن وجهه طبقة رقيقة من الأتربة العالقة، وعيناه لا تغادران المشهد المضطرب أمامه؛ تدفق من البشر يزحف ببطء، وجوه شاحبة يحفرها القلق، وأجساد تئن تحت ثقل ما تبقى من متاعهم. لم تكن فينا تلك المدينة التي تغنوا بها في أساطير الاستقرار، بل كانت ملاذاً مكتظاً يضيق بأهله. اقترب منه إينار، ممسكاً بزمام دابة هزيلة، وقال بصوت خافت متهدج: أهذا هو المكان الذي عقدنا العزم على الوصول إليه؟ لم يجب ثورفين فوراً، بل اكتفى بمراقبة جندي من حرس المدينة يلوح برمحه في وجه رجل عجوز حاول اختراق الصفوف، قبل أن يدفعه بقسوة أدت إلى سقوط الرجل أرضاً. انقبضت كف ثورفين على مقبض سيفه المعتاد، لكنه زفر بقوة، مرخياً أصابعه ببطء متعمد. التفت إلى إينار وقال بنبرة مقتضبة: لا أحد هنا يملك ترف التساؤل. نحن هنا للنجاة، ليس للبحث عن عدالة ضاعت في الطريق. اقتربت غودهيد، تنظر إلى الجموع بوجوم، وقالت بصوت مسموع: المكان يغص بالخوف، يا ثورفين. الخوف معدٍ أكثر من الأوبئة. نظر ثورفين إلى الأفق مرة أخرى، حيث تتصاعد أعمدة الدخان من مخيمات المهاجرين على الأطراف، وأجاب بحدة: الخوف هو الثمن الذي ندفعه مقابل خطوة أخرى نحو الأمام. لا تنظري إلى وجوههم، انظري إلى الطريق الذي سيخرجنا من هذا الزحام. تحركت المجموعة مجدداً، وسط ضجيج التوسلات والأوامر العسكرية المتضاربة، وكل خطوة كانت تثقل كاهلهم باليقين بأن فينا ليست نهاية الرحلة، بل مجرد فوهة بركان يستعد للانفجار. كان الصمت بين الثلاثة سيد الموقف، صمتٌ يشي بأن كل واحد منهم قد أدرك للتو أن الحرب التي هربوا منها، قد سبقتهم إلى هنا.', '', 208, '2026-07-15 15:18:16.183', '2026-07-15 15:18:16.183');
INSERT INTO public.chapters VALUES ('ed6e50d0-44d7-41fe-8bde-8746daaedb1d', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 210: حين تصمت السيوف في فينلاند', '— --------------------------------------- ارتطم نعل ثورفين بالأرض الطينية، ليترك خلفه أثراً غائراً في تراب المستعمرة. لم يكن هناك صراخ، بل ثقل غير مرئي يطبق على الصدور. وقف أمام حشد من المستوطنين والوافدين الجدد، وجوههم شاحبة، تائهة بين الرغبة في البقاء والخوف من النزاع المسلح الذي يلوح في الأفق. نظر إليهم ثورفين، لم يخطب فيهم بكلمات منمقة، بل مسح وجهه بكفه الخشنة وقال بصوت مبحوح: لا قتال. تنفس بحدة، وعيناه لا تغادران الأرض، ثم أضاف: من أراد رحيلاً فليذهب، ومن أراد أرضاً فليحفر. صمت الرجل الماثل أمامه، ''إيفار''، وانقبضت أصابعه على مقبض سيفه حتى ابيضت مفاصل يده. كان الغضب يغلي في عروق إيفار، نبض عنقه يتسارع، لكنه لم يجد صدىً في عيني ثورفين سوى برود غريب. تقدم ثورفين خطوة، متجاهلاً النصل المشهر، واقترب حتى التقت أنفاسهما. قال بصوت منخفض لا يسمعه إلا خصمه: السيف الذي ترفعه يقطع رقبتك قبل أن يلمس عدوك. لم يرتجف ثورفين، بل استرخى كتفاه تماماً في حركة استفزت إيفار أكثر. في الجانب الآخر من الساحة، بدأت الأصوات تهمس، تشتت بين مؤيد لنهج السلام ومتحفز لصد الغزاة. التفت ثورفين نحو الأفق حيث تتمايل الأشجار، ولم يلتفت خلفه عندما بدأ بعض الرجال بوضع سلاحهم أرضاً. كان الصمت الذي أعقب ذلك هو أقوى ما شهده المكان؛ صمت لا ينم عن ضعف، بل عن إرادة صلبة ترفض الانجرار إلى دوامة الدماء التي لا تنتهي. انحنى ثورفين ليلتقط فأساً كانت ملقاة قرب قدميه، وناولها لرجل عجوز يقف قريباً، ثم أشار بيده نحو الحقل. لم يعد هناك خطاب، بل عمل شاق ينتظرهم، وعالم يحاولون بناءه على أنقاض رغبتهم الجامحة في الانتقام.', '', 209, '2026-07-15 15:18:16.356', '2026-07-15 15:18:16.356');
INSERT INTO public.chapters VALUES ('fa00251f-6612-4f19-89de-3433bccd24db', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 211: بين مِطرقة السعي ومِنجل القدر', '— --------------------------------------- توقفت حركة ثورفين فجأة، يده لمست مقبض خنجره المعلق عند خصره، ليس بدافع الهجوم، بل بحركة عصبية لا إرادية ترافق توتره الصامت. أمامه، كانت الأراضي القاسية في فينلاند تمتد كبساطٍ شاسعٍ من الوعود المحفوفة بالمخاطر. التفت ثورفين نحو أتباعه، لم تكن عيناه تحملان لمعان المحارب التواق للدماء، بل ضيقاً غائراً يعكس ثقلاً نفسياً يزداد يوماً بعد يوم. قال بصوت متهدج وخشن: توقفوا هنا. لا خطوة إضافية نحو حدود المستوطنة الأصلية. بدا ''أينار'' مرتبكاً، اقترب منه بخطوات مترددة، ممسكاً بساعده: نحن بحاجة إلى الموارد، ثورفين. التأخير يعني الجوع في الشتاء القادم. زفر ثورفين هواءً بارداً، ثم أجابه باقتضاب: الجوع أهون من إراقة الدماء التي لا تلتئم. كان التوتر يمزق الهواء؛ فالمستوطنون الذين وصلوا قبلهم ليسوا في حالة تفاهم، والصدام بات مسألة وقت. نظر ثورفين إلى الأفق، حيث بدأت غيوم رمادية تغطي وجه الشمس. كان الصمت الذي يلف المكان ثقيلاً، يقاطعه فقط صوت اصطكاك الدروع المعدنية المتهالكة لجنودٍ لم يغادرهم طبع الغزو. حاول ثورفين جاهداً كبح غريزته القديمة، تلك التي تهمس له بأن السيف هو الحل الوحيد لكل معضلة. قبض على قبضتيه حتى ابيضت مفاصل أصابعه، وشعر بعروق رقبته تنبض بقوة. لم يكن يبحث عن المجد، بل كان يبحث عن ثقب إبرة يمر منه للنجاة بحلمه في أرض السلام. اقترب منه رجلٌ عجوز من المجموعة، متمتماً بكلمات غير مفهومة تشبه النحيب، فأشاح ثورفين بوجهه عنه. لم يكن يطيق الشفقة أو التحذير. في تلك اللحظة، ظهرت مجموعة من الرجال الغرباء على التلة المقابلة، يلوحون برماحهم بوضوحٍ لا يقبل التأويل. تبادل ثورفين نظرة سريعة مع أينار؛ نظرة كانت كافية لتلخص كل ما لا يقال: الحرب تحاصرهم من كل جانب، ليس كخيار، بل كقدرٍ يحاولون بكل ما أوتوا من قوة صده. صرخ ثورفين موجهاً كلامه للجميع: تراجعوا للخلف! لا تشهروا الأسلحة! كانت كلماته تبدو غريبة وسط هذا الجمع المحارب، لكن سلطته الصامتة أجبرتهم على الطاعة المترددة. سحب ثورفين نفساً عميقاً، محاولاً ترتيب أفكاره المبعثرة، مدركاً أن طريقه نحو السلام قد يكون الأكثر دموية على الإطلاق.', '', 210, '2026-07-15 15:18:16.536', '2026-07-15 15:18:16.536');
INSERT INTO public.chapters VALUES ('da00051d-50bb-4c46-a0af-c558358e6982', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 212: بذرة في أرض غريبة', '— --------------------------------------- انحنى ثورفين فوق التربة الداكنة، غارزاً أصابعه في الطين الذي لم يمسسه محراث منذ قرون. كان الحقل في فينلاند يحمل رائحة الرطوبة الخام والنمو البكر، رائحة تختلف تماماً عن دموع البحار وجثث الشمال. نظر كارلي إلى وجه ثورفين بتركيز صامت، بينما كانت يد الصبي الصغيرة تمسك بطرف عباءته الخشنة. التفت ثورفين نحوه، لم تكن عيناه تحملان بريق الفاتحين، بل ثقل المسؤولية التي لا يراها أحد. قال ثورفين بصوت خفيض ونبرة خالية من التزلف: انظر يا كارلي، هذه الأرض لا تطلب تضحية من دماء الرجال، بل تطلب صبراً لا ينفد. انثنى ثورفين ليضع بذور الشعير في الشقوق المحفورة بمهارة، حركاته كانت اقتصادية، خالية من العبث الحركي. في الطرف الآخر من الحقل، كان إيفار يراقب المشهد من بعيد، يده تتحسس مقبض سيفه بوضوح، عضلات فكه تنقبض وتنبسط بإيقاع متوتر. اقترب إيفار، مشيته كانت ثقيلة وتنم عن ضيق مستمر. قال إيفار والشرر يقدح من عينيه: هل تظن أن هذه الحفنة من الحبوب ستحمينا حينما يأتي الغرباء؟ نحن نزرع القوت بينما تتجمع السحب في الأفق. لم يلتفت ثورفين في البداية، استمر في عمله حتى غطى البذور بطبقة رقيقة من التراب، ثم انتصب واقفاً ببطء، مفاصل ظهره تطلق أزيزاً خفيفاً. مسح كفيه بالرمل وقال دون أن يواجه إيفار مباشرة: القوة التي نحتاجها ليست في حديد السيوف يا إيفار، بل في ثباتنا هنا حينما يقرر الآخرون الرحيل. القتال هو قمة الفشل، وليس ذروة المجد. ضيق إيفار عينيه، وبدا وكأنه يبتلع كلمات قاسية، لكنه اكتفى بالبصق على الأرض والابتعاد بخطوات سريعة متصلبة. كانت شمس فينلاند تميل نحو المغيب، تصبغ الأفق بلون نحاسي يوحي بالهدوء، لكن الصمت الذي خيم على المكان كان محملًا بنذر التغيير. لم يعد ثورفين ذلك المحارب الذي يقتات على الندم، لقد أصبح جذراً يضرب في هذه الأرض، مدركاً أن البناء يستغرق دهوراً، بينما يمكن للهدم أن يحدث في رمشة عين. التقط كارلي حفنة من التربة ورفعها لثورفين، ابتسم الصبي ببراءة. مسح ثورفين على رأس كارلي، وشعر للحظة ببرد المساء يتسرب إلى عظام كتفه، لكن قلبه كان دافئاً بما يكفي ليتحمل ما هو قادم. في تلك اللحظة، لم تكن هناك حروب في ذهنه، فقط صوت الريح التي تعزف بين الأشجار البعيدة، ووعد خفي بوطن لا يعرف طعم الحديد.', '', 211, '2026-07-15 15:18:16.712', '2026-07-15 15:18:16.712');
INSERT INTO public.chapters VALUES ('79569070-fd0a-4602-aee5-538bb03fb72b', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 213: صدى في أرض الغرباء', '— --------------------------------------- انتصبت خيام المهاجرين في فينلاند كبقعٍ داكنة فوق العشب اللامع، بينما خيم صمت مريب على أطراف المستعمرة، صمت لم يقطعه سوى أنين الخشب تحت ثقل الخطوات المترددة. وقف ثورفين وسط الساحة الترابية، تحدق عيناه في الأفق حيث تتوارى الغابات الموحشة. لم يكن هناك أثر للحياة البرية، فقط ثقل الهواء الذي ينذر بقدوم تغيير لا يملك أحد رده. اقترب إينار من ثورفين، كانت ملامحه مشدودة، وعيناه لا تكفان عن مسح المنطقة المظلمة خلف الأشجار. قال إينار بصوت خفيض لم يكد يسمعه ثورفين: إنهم يراقبوننا، أشعر ببرودة أعينهم في ظهري، لا يمكن أن نستمر في تجاهل هذا التربص. التفت ثورفين ببطء، لم تكن في عينيه نيران الانتقام التي اعتادتها الحروب، بل كان فيهما اتساع غريب، حيرة تلمع خلف حاجبيه. أجاب ثورفين بصوت خشن: لا يهم ما يراقبون، المهم هو ما نفعله نحن. نحن هنا لنعيش، لا لنحارب. ولكن إينار قبض على مقبض فأسه بقوة حتى ابيضت مفاصل أصابعه. إنهم لا يريدون العيش يا ثورفين، يريدون أرضنا، يريدون إخراجنا من هنا. نحن لسنا في أيسلندا، هنا القانون هو من يملك القوة الأكبر. اتجه ثورفين نحو حافة المخيم، حيث تنتهي حدود مستعمرتهم ويبدأ المجهول. كانت خطواته واثقة، لكن كتفيه كانتا محملتين بعبء ثقيل، عبء وعوده بعدم إراقة الدماء مجدداً. توقف عند حافة الغابة، مد يده نحو لحاء شجرة قديمة، كان اللحاء خشناً ومغطى بالندوب، تماماً كأصابع المحاربين. همس ثورفين لنفسه: لا أعداء… لا أعداء لأي أحد. كان صوته يتردد في الفراغ كأنه صرخة استغاثة لا يسمعها غير الأشجار الصامتة. فجأة، انبعث صوت حفيف من بين الأغصان العالية، لم يكن حفيف ريح، بل وقع حركة سريعة ومتعمدة. تجمد ثورفين في مكانه، انقبضت عضلات رقبته، وأطبق شفتيه على بعضهما في خط مستقيم. لم يلتفت للخلف، بل ظل يراقب انعكاس الحركة على وجه إينار الذي شحب لونه واقترب منه خطوتين. همس إينار: هل رأيت ذلك؟ تحرك شيء ما هناك. هز ثورفين رأسه إيجابياً دون أن ينطق، فقد أدرك في تلك اللحظة أن حلمه في السلام ليس سوى مساحة ضيقة تحيط بها سيوف الجميع، وأن قدره المحتوم ليس في الهروب من ساحات المعارك، بل في الصمود أمامها دون أن يسحب سيفه، وهو التحدي الذي لا يغفر له، ولا يرحم.', '', 212, '2026-07-15 15:18:16.909', '2026-07-15 15:18:16.909');
INSERT INTO public.chapters VALUES ('e6674de8-ab0c-4129-bacf-c8846c987205', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 214: صدى السيوف في أذني الصمت', '— --------------------------------------- انغرس نصل الفأس في جذع الشجرة بقوة أحدثت اهتزازاً في أغصانها العارية، استقرت الرأس المعدنية بعمق، بينما ظل ثورفين واقفاً، يراقب تذبذب مقبضها الخشبي. الصمت في غابة فينلاند ليس خواءً، بل هو وزنٌ ثقيل يضغط على الأنفاس. التفت ثورفين نحو إينار الذي كان يمسح العرق عن جبينه بظهر كفه، ملامحه تنطق بإنهاك جسدي تجاوز الحدود. قال ثورفين بصوتٍ خافت، كأنه يزن الكلمات قبل إطلاقها: لن نتوقف حتى نبلغ نقطة التوازن. لم يلتفت إليه إينار، بل استمر في حفر الأرض، مجيباً بنبرة متهدجة: هذه الأرض لا تمنحنا السلام مجاناً يا ثورفين، إنها تأخذ من أجسادنا بقدر ما تعطينا من قمح. في تلك اللحظة، تحركت ظلال الأشجار الطويلة بفعل الريح، وبدت وكأنها كائنات تراقب جهدهم المضني. لم تكن هناك وحوش أو جيوش، كان الصراع أزلياً بين الإنسان والتربة القاسية. اقتربت هيلد، خفتت خطواتها على الأعشاب الجافة، وضعت يدها على قوسها، نظراتها حادة كأنها ترصد عدواً غير مرئي. قالت بنبرة قاسية لا تقبل الجدل: الهدوء هنا مريب، القادم ليس صديقاً، والمسافة تتقلص بسرعة أكبر مما توقعنا. التقط ثورفين فأسه، انتزعها بضربة واحدة من الجذع، وبرزت عروق ذراعه مع شدة القبضة. لم يغرق في التفكير، بل اتخذ وضعية الاستعداد. تلاشت الحوارات السطحية، وحل محلها صرير احتكاك الجلد بالمعادن. أدرك الجميع أن الملاذ الذي بنوه لم يعد مجرد حلم، بل صار قلعة يجب الدفاع عنها ضد قسوة الخارج. انقبضت عضلات فك ثورفين، ونظر في الأفق البعيد، حيث بدأت غبار خيول الغرباء تتصاعد، معلنة نهاية عهد العزلة. لم يقل شيئاً، فالحركة هي لغته الوحيدة الآن، والقرار قد اتُخذ قبل أن تظهر السنابك في الأفق. كان الاختبار الحقيقي لفلسفته، ليس في ساحات القتال القديمة، بل في الحفاظ على هذا المكان الذي يرفض فيه إراقة قطرة دم واحدة، حتى لو كان الثمن حياته ذاتها.', '', 213, '2026-07-15 15:18:17.079', '2026-07-15 15:18:17.079');
INSERT INTO public.chapters VALUES ('c83532ca-d327-4f44-a93b-c374b13ca07f', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 215: حين تصمت الأسلحة على أرض فينلاند', '— --------------------------------------- انتصبت الجرافات الخشبية كأنها وحوش صامتة أمام حشود المستوطنين المتجمهرين. ثورفين يقف في المقدمة، يداه مرتخيتان بجانبه، لا أثر لسيف أو خنجر في حزامه. العرق يتصبب على جبينه، ليس خوفاً، بل تركيزاً محضا على كل حركة تصدر من الطرف الآخر. إيفار يغلي دمه، قبضته التي تشد مقبض سيفه تبيّض مفاصلها، وصوته يخرج مبحوحاً كفحيح أفعى: «إنهم يتقدمون يا ثورفين، إذا لم نرفع السلاح الآن، فسنكون جثثاً قبل الغروب». التفت ثورفين إليه بنظرة حادة، لم يجب بكلمة، بل اكتفى بضغط فكه الأسفل. في الجانب المقابل، كان المحاربون المحليون يشدون على رماحهم، عيونهم تترصد ثغرة في صفوف المستوطنين. أحدهم، يرتدي فرواً خشناً، خطى خطوة للأمام وصرخ بكلمات غير مفهومة، كان صوته يتردد في الفضاء المفتوح كإنذار أخير. ثورفين خطا خطوة واحدة للأمام، بعيداً عن حماية رفاقه، كاشفاً صدره العاري. لم يرتجف، بل زفر نفساً طويلاً ومستقراً. كانت اللحظة تبدو وكأن الزمن قد توقف، لا حركة في الحقول، لا طيور تحلق في الأفق. همس ثورفين لنفسه بصوت خافت لم يسمعه إلا القريبون: «العدو ليس هنا». ارتفعت أصوات الجلبة بين المستوطنين، البعض تراجع للخلف، والبعض الآخر استعد للهجوم بدافع الغريزة. إيفار اندفع خطوة، لكن يد ثورفين القوية قبضت على كتفه، مانعة إياه من إكمال حركته. كان ضغط أصابع ثورفين كأنها طوق حديدي، أجبر إيفار على التوقف. دارت بينهما نظرات سريعة، صمت ثورفين كان أبلغ من أي خطبة، صمت يحمل ثقل السنين التي قضاها في الحروب وما تلاها من ندم. بدأت الحشود بالتأرجح، التردد بدا واضحاً على وجوه المهاجمين. سقط رمح من يد أحد المحاربين فجأة، فصاح الصدى في الأرجاء. كانت تلك اللحظة الفاصلة؛ حيث تلاشت الرغبة في الدماء أمام ثبات رجل قرر ألا يقتل، ليضع الجميع أمام حقيقة أن القوة الحقيقية تكمن في البقاء صامدين دون سيل من الدماء يلطخ التربة التي جاؤوا ليزرعوها.', '', 214, '2026-07-15 15:18:17.391', '2026-07-15 15:18:17.391');
INSERT INTO public.chapters VALUES ('a42013dc-9d34-41c5-a96e-35081eba918f', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 216: أصداءُ الأرضِ الموعودة', '— --------------------------------------- انزاح الغبار عن وجه ثورفين، لتكشف عيناه عن أفقٍ لا ينتهي من التلال الخضراء التي لم تطأها أقدام الغزاة بعد. سكنت حركته، وتصلبت قامته وسط السهول التي بدت وكأنها تتنفس حياةً جديدة، بعيداً عن صخب النصال. التفت إلى أتباعه، كانت نظراتهم لا تزال تحمل ثقل الرحلة الطويلة، تتقاذفهم الحيرة بين رغبة الاستقرار وخوف الغريب. اقترب منه ''هيلدار'' بخطوات موزونة، لم تكن عيناها تفارقان الأفق المتسع. همس ثورفين بنبرة مقتضبة، خالية من أي تهويش: لن نضع سيوفنا هنا، الأرض التي تنبت لنا خبزنا لا تستحق أن تُروى بدمائنا. كان صوته أجشاً، يحمل إرهاق السنين، لكنه كان قاطعاً كحد السيف. اندلعت بين المهاجرين نقاشات حادة، ارتفعت أصواتهم في محاولة لفك طلاسم العزلة التي فرضتها الطبيعة عليهم. أحدهم، رجل ضخم البنيان يدعى إريك، صرخ بحدة بينما كانت يده تقبض على مقبض فأسه: نحن لا نملك سوى قوتنا، يا ثورفين. إذا لم نحمِ أنفسنا بحديدنا، فمن سيصد عنا أطماع الجوعى؟ لم يلتفت ثورفين، بل ظل مسمراً ينظر إلى مساحات الأرض البكر. لم يكن في نظرته ضعف، بل كان في صمتها ثقل يقيد أفواه المعترضين. تحركت كفوفه لتلامس التربة، خشنة، باردة، لكنها حقيقية. أدرك الجميع في تلك اللحظة أن القتال لم يعد وسيلة للبقاء، بل صار عبئاً يمنعهم من العيش. اقترب ''ييف'' منه، كان وجهه شاحباً من التعب، وهمس له: السكينة التي تنشدها يا ثورفين تكلف أكثر من الحرب. أجابه ثورفين بصوت بالكاد يُسمع، بينما اتسعت حدقتا عينيه وهو يتأمل طائراً يحلق بحرية فوق الحقول: الحرب لا تكلفنا حياتنا فحسب، بل تكلفنا حقنا في أن نكون بشراً. ساد صمت مطبق، لم يقطعه سوى خرير جدول صغير ينساب قريباً. لم تكن هناك فلسفة، بل كان هناك واقع يفرض نفسه؛ الأرض لا تكترث لمن يملك السيف، بل لمن يزرع البذرة. توارى الأفق في ضباب المساء، وبدأ الرجال، واحداً تلو الآخر، يغمدون أسلحتهم، ليس استسلاماً، بل إعلاناً عن بداية حقبة لم يعهدوها من قبل.', '', 215, '2026-07-15 15:18:17.598', '2026-07-15 15:18:17.598');
INSERT INTO public.chapters VALUES ('f07f467d-685c-4505-991e-89f642d30f2f', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 217: حيث تغدو الأرض وعراً', '— --------------------------------------- توقف ثورفين عن المشي، مثبتاً قدميه على التربة الصلبة. كان صمت الغابة يلف المكان، غير أن أنفاسه المتقطعة كانت تخرق هذا السكون. إلى جواره، وقف المهاجرون، وجوههم محفورة بتعب السفر، يرقبون أفقاً لا يمنح وعوداً سهلة. التفت ثورفين نحو إينار، الذي كان يمسح العرق عن جبينه بيده الملوثة بالطين. قال إينار بصوت مبحوح: الأرض هنا لا تشبه مروجنا، إنها توشك أن تبتلع كل ما نغرسه فيها. لم يجب ثورفين فوراً، بل انحنى ليمسك حفنة من التراب، يفركها بين أصابعه الخشنة. تلك ليست أرضاً للرخاء، بل هي ساحة صراع من نوع آخر، صراعٌ لا يسفك دماً، لكنه يستنزف العزيمة. اقترب هيلد ببطء، ظله يمتد طويلاً على العشب الضامر، عيناها تراقب حركات ثورفين بدقة. همست هيلد: إذا استمر الجفاف، لن ننجو من الشتاء القادم. ارتفع صوت ثورفين، حاداً ومباشراً: سنشق القنوات، وسنحفر الآبار حتى نصل إلى جوف الصخر، لا بديل عن ذلك. لم تكن نبرته تحمل وعداً بالراحة، بل كانت أمراً قسرياً للواقع. في الخلفية، كان الأطفال يراقبون من بعيد، عيونهم الواسعة تلاحق حركة الرجال. أدرك الجميع أن الاستقرار في فينلاند ليس هدية، بل ضريبة تُدفع من عظامهم. وقف ثورفين شامخاً، ينظر إلى التلال البعيدة؛ كان يعلم أن كل شجرة يقتلعونها وكل حجر يزيحونه هو انتصار على الفناء الذي طارده طوال حياته. لم يعد يبحث عن معارك السيوف، لكنه اليوم يواجه معركة البقاء في أرضٍ بكر لا تأبه لنواياه الطيبة. استدار نحو رفاقه، كانت ملامحه صلبة، خالية من التردد: ابدأوا بالعمل، الشمس لن تنتظرنا، والليل هنا يسرق الدفء بسرعة.', '', 216, '2026-07-15 15:18:17.805', '2026-07-15 15:18:17.805');
INSERT INTO public.chapters VALUES ('25a074b5-0a01-4bf1-8b1d-81d0493d56bb', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 218: صدى الرحيل في فينيسلاند', '— --------------------------------------- توقفت حركة المجاذيف فجأة، وانزلق القارب الخشبي فوق سطح الماء الساكن كأنه يمزق صمتاً أبدياً. كان إينار يراقب ثورفين، الذي لم يرفع بصره عن الأفق، يداه الخشنة تقبضان على حافة القارب حتى ابيضت مفاصلهما. قال إينار بصوت منخفض، مشوباً بحذر لم يعتد عليه: ثورفين، الأرض التي حلمنا بها ليست كما تخيلناها. لم يلتفت ثورفين، بل اكتفى بضغط شفتيه على بعضهما، وعيناه غائرتان تعكسان اضطراباً دفيناً لا يجد له مخرجاً في الكلمات. خلفهما، بدأت جلبة المهاجرين تتعالى، أصوات الأطفال الذين لا يدركون ثقل القرار، وضجيج الرجال الذين يبحثون عن أمل في أرض بكر. سأل ثورفين دون أن يغير وضعيته: هل تعتقد أنهم سيتبعوننا إلى الموت؟ التفت إينار ونظر إلى الوجوه المنهكة حولهما، ثم أجاب بمرارة: هم يتبعون القائد، لا الأرض. في تلك اللحظة، هبت ريح باردة حملت معها رائحة تراب غريب، لم يألفوه من قبل، تراب ينذر بعهد جديد لا مكان فيه للضعف. وضع ثورفين يده على مقبض سيفه الذي لم يسل منذ سنين، ثم أبعدها بسرعة كما لو أنه تذكر وعداً قطعه على نفسه. قال بصوت مقتضب وحاد: لا سيف، لا دماء، هذا هو العهد. لكن نظرات الرجال من حوله، تلك النظرات المتعطشة للأمن والخبز، كانت تخبره بشيء آخر. كان ثورفين يدرك، بحدسه الذي صقلته الحروب، أن السلام ليس مجرد غياب للقتال، بل هو معركة يومية أشد وطأة من طعنات السيوف. انحنى ثورفين نحو الماء، غسل وجهه ببرودة الأمواج، ثم وقف بشموخ هزيل، جسده الذي أنهكته الرحلة كان لا يزال يحمل ثقل الآلاف الذين وضعوا مصيرهم بين يديه. اتجه نحو مقدمة القارب، تاركاً إينار خلفه في حيرة صامتة، بينما بدأت ملامح الشاطئ تتبدى بوضوح؛ غابات كثيفة، أرض بكر، ومستقبل مجهول لا يرحم. لم تكن فينيسلاند مجرد حلم، كانت امتحانهم الأخير، وامتحاناً لإنسانية ثورفين التي باتت على المحك تحت سماء جديدة.', '', 217, '2026-07-15 15:18:18.002', '2026-07-15 15:18:18.002');
INSERT INTO public.chapters VALUES ('629a0c35-4d60-408b-8767-abf8bebb3aaf', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 219: صدى الصمت في أراضي فينلاند', '— --------------------------------------- توقف ثورفين عن الحركة. كانت قدماه تغوصان في تربة فينلاند الرطبة، بينما تتصاعد أنفاسه في هواء الصباح البارد كخيوط من ضباب واهن. لم تكن هناك أصوات سوى وقع أقدام المستوطنين على العشب. نظر ثورفين إلى الأفق؛ لم يعد يبحث عن ساحات المعارك، بل كان يراقب امتداد الأرض التي يسعى لبناء حياته عليها. كان التوتر يلف المكان، ليس كخطر داهم، بل كقلق مبهم يتسرب من وجوه رفاقه. تقدم إينار نحوه، كانت قبضتاه مضمومتين إلى جانبيه، وتجاعيد جبينه تكشف عن تساؤلات لم يجرؤ على نطقها بعد. التفت ثورفين، فغارت عيناه في ملامح إينار، ولم يحتج لقول كلمة. الصمت بينهما كان أبلغ من أي حوار. كان ثورفين يدرك أن الحفاظ على السلام في هذا العالم الجديد يتطلب صلابة تفوق صلابة السيف. وسط الحقول التي بدأت تكتسي بملامح العمل الشاق، وقف ثورفين شامخاً، يراقب بعينين حادتين تفاصيل الخيام المتناثرة، مدركاً أن الاختبار الحقيقي ليس في صد غزو خارجي، بل في حماية هذا العهد الذي قطعه على نفسه من التآكل بفعل الضغينة. تناهى إلى مسامعه صوت ضحكات أطفال من بعيد، فاسترخى كتفاه قليلاً. لم تكن الغاية يوماً سهلة، لكنها الآن تجسدت في حبات القمح التي تتهيأ للنمو. التفت ثورفين مجدداً نحو قريته، وبدأ بالسير بخطوات وئيدة، تاركاً خلفه ثقل الماضي ليتفرغ لبناء حجر الأساس التالي في عالم لا مكان فيه للأعداء.', '', 218, '2026-07-15 15:18:18.194', '2026-07-15 15:18:18.194');
INSERT INTO public.chapters VALUES ('b59d4350-3e74-4ae3-bc6d-07db8e11d079', '4513ff04-2773-4afa-b168-f740a40810ac', 'الفصل 220: أصداءُ الأرضِ الموعودةِ', '— --------------------------------------- توقف ثورفين عن المسير، مغرسًا قدميه في التربة الندية التي لم تكن تشبه تربة أيسلندا القاسية. كان الهواء هنا ثقيلًا برطوبة الغابات، صمتٌ يقطعه فقط حفيف الأوراق البعيد. التفت «آيفار» نحوه، ملامحه متشنجة، يده تقبض على مقبض سيفه بضغطٍ أبيض المفاصل. صاح آيفار بنبرة مشحونة بالريبة: «إنهم يراقبوننا يا ثورفين، هل تسمع؟ هذا الصمت ليس خلوًا، إنه كمين!». لم يلتفت ثورفين إليه، بل ظل يحدق في كثافة الأشجار الملتفة أمامهم. كان عقله يزن احتمالات المواجهة، لا بأسلحة الحديد

، بل بثقل العواقب التي ستلحق بمستعمرتهم الوليدة. قال ثورفين بصوتٍ منخفض، مقتضب النبرات: «أخفض يدك عن السيف. السلاح هنا يعني الحرب، والحرب هنا تعني فناءنا جميعًا». تردد آيفار، ارتجفت عضلات فكه السفلي قبل أن يتراجع خطوة للخلف، باصقًا على الأرض دلالةً على سخريته. في هذه الأثناء، بدأت أشباح الساكنين الأصليين تظهر بين الجذوع. لم تكن حركتهم تشبه دبيب المقاتلين؛ كانت أقرب لانسلال الضباب. توترت أجساد الرجال المهاجرين، وارتفعت وتيرة أنفاسهم، لكن ثورفين تقدم خطوة واحدة، خالي الوفاض، باسطًا كفيه أمام صدره. كان الصمت الذي ساد اللحظة أثقل من صليل السيوف. لم تكن هناك فلسفة في تلك الحركة، بل كان قرارًا صلبًا لا يلين، مغامرةً بحياة الجميع في سبيل أرض بلا أعداء. نظر ثورفين إلى أعين الرجال الذين واجهوه؛ كانت أعينًا تقطر غضبًا وحذرًا، لا تختلف عن أعين القراصنة في سالف العهد، لكنها هنا كانت تدافع عن ديارها. أطبق ثورفين شفتيه بإحكام، مدركًا أن الكلمات لن تكون كافية هذه المرة، وأن عليه أن يفتح صدره للقدر دون درع، ليثبت أن الوصول إلى فينلاند ليس رحلة جغرافية، بل اختبارًا لبقاء إنسانيته في وجه الوحشية المتربصة.', '', 219, '2026-07-15 15:18:18.42', '2026-07-15 15:18:18.42');


