INSERT INTO public.novels VALUES ('4513ff04-2773-4afa-b168-f740a40810ac', 'user_3GN1M7kJdxV54AziRNZJsRqXSGH', 'MangA | NoneL', '', 'ملحمة فينلاند', 'drama', '— --------------------------------------- تصاعد صليل السيوف في الساحة المفتوحة، صوت معدن يرتطم بمعدن، رتيب وموحش. ثورفين، الطفل ذو السنوات الست، كان يتنقل بين أقدام المحاربين كقطة ضالة، عيناه تلاحقان والده ثورس. ثورس لم يكن يقاتل كبقية رجال القرية؛ لم تكن حركاته صاخبة أو مبهرجة، بل كان يتفادى الضربا...', 'data:image/jpeg;base64,', 'draft', 0, 0, 0, 'ar', 'none', 'neutral', 'var(--font-serif)', '1.125rem', 'right', '1.75', NULL, '', '2026-07-15 15:17:33.781', '2026-07-15 15:47:15.362');


